fn fake_vm_api() -> FakeVmApi {
    let listener = TcpListener::bind(("127.0.0.1", 0)).expect("bind fake VM API");
    listener
        .set_nonblocking(true)
        .expect("make fake VM API nonblocking");
    let address = listener.local_addr().expect("fake VM API address");
    let base_url = format!("http://{address}");
    let stop = Arc::new(AtomicBool::new(false));
    let thread_stop = Arc::clone(&stop);
    let thread = thread::spawn(move || {
        let mut vms = HashMap::<String, Value>::new();
        let mut idempotency_keys = HashMap::<String, String>::new();
        while !thread_stop.load(Ordering::Relaxed) {
            let (mut stream, _) = match listener.accept() {
                Ok(connection) => connection,
                Err(err) if err.kind() == std::io::ErrorKind::WouldBlock => {
                    thread::sleep(Duration::from_millis(5));
                    continue;
                }
                Err(_) => break,
            };
            let _ = stream.set_read_timeout(Some(Duration::from_secs(2)));
            let Some(request) = read_fake_http_request(&mut stream) else {
                continue;
            };
            let authorized = request.headers.get("authorization").map(String::as_str)
                == Some("Bearer vm-access")
                && request
                    .headers
                    .get("x-stack-refresh-token")
                    .map(String::as_str)
                    == Some("vm-refresh")
                && request.headers.get("x-cmux-team-id").map(String::as_str) == Some("team-stack");
            let (status, body) = if !authorized {
                (
                    "401 Unauthorized",
                    json!({"error": "unauthorized", "message": "missing VM auth headers"}),
                )
            } else {
                fake_vm_response(&request, &mut vms, &mut idempotency_keys)
            };
            write_fake_http_json(&mut stream, status, &body);
        }
    });
    FakeVmApi {
        base_url,
        stop,
        thread: Some(thread),
    }
}

#[derive(Clone, Debug)]
struct FakeHttpRequest {
    method: String,
    path: String,
    headers: HashMap<String, String>,
    body: Value,
    raw_body: String,
}

fn read_fake_http_request(stream: &mut TcpStream) -> Option<FakeHttpRequest> {
    const MAX_REQUEST_BYTES: usize = 1024 * 1024;
    let mut bytes = Vec::new();
    let mut chunk = [0_u8; 4096];
    let header_end = loop {
        if let Some(index) = bytes.windows(4).position(|window| window == b"\r\n\r\n") {
            break index + 4;
        }
        if bytes.len() >= MAX_REQUEST_BYTES {
            return None;
        }
        match stream.read(&mut chunk) {
            Ok(0) => return None,
            Ok(count) => bytes.extend_from_slice(&chunk[..count]),
            Err(_) => return None,
        }
    };
    let header_text = std::str::from_utf8(&bytes[..header_end]).ok()?;
    let mut lines = header_text.split("\r\n");
    let mut request_line = lines.next()?.split_whitespace();
    let method = request_line.next()?.to_string();
    let path = request_line.next()?.to_string();
    let headers = lines
        .filter_map(|line| line.split_once(':'))
        .map(|(name, value)| (name.trim().to_ascii_lowercase(), value.trim().to_string()))
        .collect::<HashMap<_, _>>();
    let content_length = headers
        .get("content-length")
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(0);
    if header_end.saturating_add(content_length) > MAX_REQUEST_BYTES {
        return None;
    }
    while bytes.len() < header_end + content_length {
        match stream.read(&mut chunk) {
            Ok(0) => return None,
            Ok(count) => bytes.extend_from_slice(&chunk[..count]),
            Err(_) => return None,
        }
    }
    let raw_body = String::from_utf8_lossy(&bytes[header_end..header_end + content_length]).into();
    let body = serde_json::from_slice(&bytes[header_end..header_end + content_length])
        .unwrap_or(Value::Null);
    Some(FakeHttpRequest {
        method,
        path,
        headers,
        body,
        raw_body,
    })
}

fn fake_vm_response(
    request: &FakeHttpRequest,
    vms: &mut HashMap<String, Value>,
    idempotency_keys: &mut HashMap<String, String>,
) -> (&'static str, Value) {
    if request.method == "GET" && request.path == "/api/vm" {
        let mut items = vms.values().cloned().collect::<Vec<_>>();
        items.sort_by(|left, right| left["id"].as_str().cmp(&right["id"].as_str()));
        return ("200 OK", json!({"vms": items}));
    }
    if request.method == "POST" && request.path == "/api/vm" {
        let Some(key) = request.headers.get("idempotency-key") else {
            return (
                "400 Bad Request",
                json!({"error": "missing_idempotency_key", "message": "Idempotency-Key is required"}),
            );
        };
        if let Some(vm_id) = idempotency_keys.get(key) {
            return ("200 OK", vms.get(vm_id).cloned().expect("idempotent VM"));
        }
        let vm_id = format!("vm-backend-{}", vms.len() + 1);
        let vm = json!({
            "id": vm_id,
            "provider": request.body.get("provider").and_then(Value::as_str).unwrap_or("modal"),
            "image": request.body.get("image").and_then(Value::as_str).unwrap_or("ubuntu"),
            "createdAt": 1_700_000_000_000_i64
        });
        idempotency_keys.insert(key.clone(), vm_id.clone());
        vms.insert(vm_id, vm.clone());
        return ("200 OK", vm);
    }

    let Some(relative_path) = request.path.strip_prefix("/api/vm/") else {
        return ("404 Not Found", json!({"message": "not found"}));
    };
    let parts = relative_path.split('/').collect::<Vec<_>>();
    let vm_id = parts.first().copied().unwrap_or_default();
    if !vms.contains_key(vm_id) {
        return (
            "404 Not Found",
            json!({"error": "vm_not_found", "message": "VM not found"}),
        );
    }
    match (request.method.as_str(), parts.as_slice()) {
        ("DELETE", [_]) => {
            vms.remove(vm_id);
            ("200 OK", json!({}))
        }
        ("POST", [_, "exec"]) => {
            let command = request
                .body
                .get("command")
                .and_then(Value::as_str)
                .unwrap_or_default();
            (
                "200 OK",
                json!({"exitCode": 0, "stdout": format!("backend: {command}\n"), "stderr": ""}),
            )
        }
        ("POST", [_, "ssh-endpoint"]) => (
            "200 OK",
            json!({
                "host": "127.0.0.1",
                "port": 22,
                "username": "cmux",
                "credential": {"kind": "password", "value": format!("password-{vm_id}")},
                "publicKeyFingerprint": null
            }),
        ),
        ("POST", [_, "attach-endpoint"]) => {
            let require_daemon = request
                .body
                .get("requireDaemon")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if !require_daemon {
                return (
                    "200 OK",
                    json!({
                        "transport": "ssh",
                        "host": "ssh.vm.example",
                        "port": 2222,
                        "username": "root",
                        "credential": {
                            "kind": "authorizedKey",
                            "privateKeyPem": format!("private-key-{vm_id}")
                        },
                        "publicKeyFingerprint": "SHA256:test"
                    }),
                );
            }
            let daemon = require_daemon.then(|| {
                json!({
                    "url": format!("wss://vm.example/{vm_id}/daemon"),
                    "headers": {"x-cmux-vm-id": vm_id, "ignored-number": 42},
                    "token": format!("daemon-token-{vm_id}"),
                    "sessionId": format!("daemon-session-{vm_id}"),
                    "expiresAtUnix": 1_700_000_600_i64
                })
            });
            (
                "200 OK",
                json!({
                    "transport": "websocket",
                    "url": format!("wss://vm.example/{vm_id}/pty"),
                    "headers": {"x-cmux-vm-id": vm_id, "ignored-number": 42},
                    "token": format!("pty-token-{vm_id}"),
                    "sessionId": format!("pty-session-{vm_id}"),
                    "expiresAtUnix": 1_700_000_600_i64,
                    "daemon": daemon
                }),
            )
        }
        _ => ("404 Not Found", json!({"message": "not found"})),
    }
}

fn write_fake_http_json(stream: &mut TcpStream, status: &str, body: &Value) {
    let body = serde_json::to_string(body).expect("fake HTTP JSON");
    let response = format!(
        "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    );
    let _ = stream.write_all(response.as_bytes());
}

