fn fake_stack_auth(email: &str) -> FakeStackAuth {
    let listener = TcpListener::bind(("127.0.0.1", 0)).expect("bind fake Stack Auth");
    listener
        .set_nonblocking(true)
        .expect("make fake Stack Auth nonblocking");
    let address = listener.local_addr().expect("fake Stack Auth address");
    let base_url = format!("http://{address}");
    let stop = Arc::new(AtomicBool::new(false));
    let thread_stop = Arc::clone(&stop);
    let revocations = Arc::new(AtomicUsize::new(0));
    let thread_revocations = Arc::clone(&revocations);
    let refreshes = Arc::new(AtomicUsize::new(0));
    let thread_refreshes = Arc::clone(&refreshes);
    let email = email.to_string();
    let thread = thread::spawn(move || {
        while !thread_stop.load(Ordering::Relaxed) {
            let (mut stream, _) = match listener.accept() {
                Ok(connection) => connection,
                Err(err) if err.kind() == std::io::ErrorKind::WouldBlock => {
                    thread::sleep(Duration::from_millis(5));
                    continue;
                }
                Err(_) => break,
            };
            let _ = stream.set_read_timeout(Some(Duration::from_secs(2)));
            let Some(request) = read_fake_http_request(&mut stream) else {
                continue;
            };
            let has_project_headers = request.headers.contains_key("x-stack-project-id")
                && request
                    .headers
                    .contains_key("x-stack-publishable-client-key");
            let has_access_headers =
                has_project_headers && request.headers.contains_key("x-stack-access-token");
            let has_auth_headers =
                has_access_headers && request.headers.contains_key("x-stack-refresh-token");
            let (status, body) = if request.method == "POST"
                && request.path == "/api/v1/auth/oauth/token"
                && !has_project_headers
            {
                (
                    "401 Unauthorized",
                    json!({"message": "missing Stack project headers"}),
                )
            } else if request.method == "POST"
                && request.path == "/api/v1/auth/oauth/token"
                && request.raw_body.contains("refresh_token=definitive-reject")
            {
                thread_refreshes.fetch_add(1, Ordering::Relaxed);
                (
                    "400 Bad Request",
                    json!({"error": "invalid_grant", "message": "refresh rejected"}),
                )
            } else if request.method == "POST"
                && request.path == "/api/v1/auth/oauth/token"
                && request.raw_body.contains("refresh_token=transient-fail")
            {
                thread_refreshes.fetch_add(1, Ordering::Relaxed);
                (
                    "503 Service Unavailable",
                    json!({"message": "temporary outage"}),
                )
            } else if request.method == "POST" && request.path == "/api/v1/auth/oauth/token" {
                thread_refreshes.fetch_add(1, Ordering::Relaxed);
                let access_token = if request.raw_body.contains("refresh_token=vm-refresh") {
                    "vm-access"
                } else {
                    "refreshed-access"
                };
                ("200 OK", json!({"access_token": access_token}))
            } else if request.method == "DELETE"
                && request.path == "/api/v1/auth/sessions/current"
                && has_auth_headers
            {
                thread_revocations.fetch_add(1, Ordering::Relaxed);
                ("200 OK", json!({}))
            } else if request.path == "/api/v1/users/me" && !has_access_headers {
                (
                    "401 Unauthorized",
                    json!({"message": "missing access token"}),
                )
            } else if request.path == "/api/v1/users/me" && email.is_empty() {
                ("401 Unauthorized", json!({"message": "invalid session"}))
            } else if request.path == "/api/v1/users/me" {
                let user_id = if request
                    .headers
                    .get("x-stack-access-token")
                    .map(String::as_str)
                    == Some("different-user-access")
                {
                    "different-stack-user"
                } else {
                    "stack-user"
                };
                (
                    "200 OK",
                    json!({
                        "id": user_id,
                        "primary_email": email,
                        "display_name": "Stack User",
                        "selected_team_id": "team-stack",
                        "is_anonymous": false,
                        "is_restricted": false
                    }),
                )
            } else if request.path == "/api/v1/teams?user_id=me" && has_auth_headers {
                (
                    "200 OK",
                    json!({"items": [
                        {
                            "id": "team-stack",
                            "display_name": "Stack Team",
                            "slug": "stack-team"
                        },
                        {
                            "id": "team-alt",
                            "display_name": "Alternate Team",
                            "slug": "alternate-team"
                        }
                    ]}),
                )
            } else if !has_auth_headers {
                (
                    "401 Unauthorized",
                    json!({"message": "missing auth headers"}),
                )
            } else {
                ("404 Not Found", json!({"message": "not found"}))
            };
            write_fake_http_json(&mut stream, status, &body);
        }
    });
    FakeStackAuth {
        base_url,
        refreshes,
        revocations,
        stop,
        thread: Some(thread),
    }
}

fn fake_secret_tool() -> FakeSecretTool {
    let root = tempfile::tempdir().expect("fake secret-tool root");
    let program = root.path().join("secret-tool");
    let secret_path = root.path().join("stored-secret");
    let log_path = root.path().join("secret-tool.log");
    std::fs::write(
        &program,
        r#"#!/bin/sh
set -eu
operation=$1
shift
printf '%s %s\n' "$operation" "$*" >> "$CMUX_FAKE_SECRET_TOOL_LOG"
case "$operation" in
  lookup)
    [ -f "$CMUX_FAKE_SECRET_TOOL_SECRET" ] || exit 1
    cat "$CMUX_FAKE_SECRET_TOOL_SECRET"
    ;;
  store)
    cat > "$CMUX_FAKE_SECRET_TOOL_SECRET"
    ;;
  clear)
    if [ "${CMUX_FAKE_SECRET_TOOL_CLEAR_FAIL:-}" = "1" ]; then
      printf '%s\n' 'temporary Secret Service failure' >&2
      exit 2
    fi
    rm -f "$CMUX_FAKE_SECRET_TOOL_SECRET"
    ;;
  *)
    exit 2
    ;;
esac
"#,
    )
    .expect("write fake secret-tool");
    let mut permissions = std::fs::metadata(&program)
        .expect("fake secret-tool metadata")
        .permissions();
    permissions.set_mode(0o755);
    std::fs::set_permissions(&program, permissions).expect("chmod fake secret-tool");
    FakeSecretTool {
        _root: root,
        program: program.display().to_string(),
        secret_path: secret_path.display().to_string(),
        log_path: log_path.display().to_string(),
    }
}

impl Drop for Server {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn start_server() -> Server {
    start_server_with_env(&[])
}

fn start_server_with_beta_features(envs: &[(&str, &str)]) -> Server {
    let config_root = tempfile::tempdir().expect("beta config root");
    let config_home = config_root.path().join("config");
    let config_path = config_home.join("cmux/cmux.json");
    std::fs::create_dir_all(config_path.parent().unwrap()).expect("create beta config directory");
    std::fs::write(
        &config_path,
        serde_json::to_vec_pretty(&json!({
            "rightSidebar.beta.feed.enabled": true,
            "rightSidebar.beta.dock.enabled": true,
            "customSidebars.beta.enabled": true,
            "remoteTmux.beta.enabled": true
        }))
        .expect("serialize beta config"),
    )
    .expect("write beta config");

    let mut owned_envs = vec![(
        "XDG_CONFIG_HOME".to_string(),
        config_home.display().to_string(),
    )];
    owned_envs.extend(
        envs.iter()
            .map(|(key, value)| ((*key).to_string(), (*value).to_string())),
    );
    let env_refs = owned_envs
        .iter()
        .map(|(key, value)| (key.as_str(), value.as_str()))
        .collect::<Vec<_>>();
    let mut server = start_server_with_env(&env_refs);
    server._extra_tmp.push(config_root);
    server
}

fn fake_ssh() -> FakeSsh {
    let root = tempfile::tempdir().expect("fake ssh root");
    let fake_bin = root.path().join("bin");
    std::fs::create_dir_all(&fake_bin).expect("create fake bin");
    let ssh = fake_bin.join("ssh");
    let log_path = root.path().join("ssh.log");
    let remote_home = root.path().join("remote-home");
    std::fs::write(
        &ssh,
        r#"#!/bin/sh
printf '%s\n' "$*" >> "$CMUX_FAKE_SSH_LOG"
remote_cmd=""
for arg in "$@"; do
  remote_cmd="$arg"
done
destination=""
prev=""
for arg in "$@"; do
  if [ "$prev" = "--" ]; then
    destination="$arg"
    break
  fi
  prev="$arg"
done
target=""
prev=""
for arg in "$@"; do
  if [ "$prev" = "-W" ]; then
    target="$arg"
    break
  fi
  prev="$arg"
done
if [ -n "$target" ]; then
  CMUX_FAKE_SSH_TARGET="$target" python3 -c '
import os, socket, sys, threading

host, port_text = os.environ["CMUX_FAKE_SSH_TARGET"].rsplit(":", 1)
sock = socket.create_connection((host, int(port_text)), timeout=5)

def pump_stdin():
    fd = sys.stdin.fileno()
    try:
        while True:
            data = os.read(fd, 16384)
            if not data:
                break
            sock.sendall(data)
    finally:
        try:
            sock.shutdown(socket.SHUT_WR)
        except Exception:
            pass

threading.Thread(target=pump_stdin, daemon=True).start()
try:
    while True:
        data = sock.recv(16384)
        if not data:
            break
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
finally:
    sock.close()
'
  exit $?
fi
if printf '%s' "$remote_cmd" | grep -F 'tmux -CC' >/dev/null; then
  CMUX_FAKE_REMOTE_CMD="$remote_cmd" CMUX_FAKE_DESTINATION="$destination" python3 -c '
import os, re, sys

remote_cmd = os.environ.get("CMUX_FAKE_REMOTE_CMD", "")
destination = os.environ.get("CMUX_FAKE_DESTINATION", "")
log_path = os.environ["CMUX_FAKE_SSH_LOG"]
remote_home = os.environ["CMUX_FAKE_REMOTE_HOME"]
reconnect_marker = os.path.join(remote_home, "tmux-control-reconnected")
drop_after_list = destination == "reconnect-control.example" and not os.path.exists(reconnect_marker)
command_number = 1

def write(value):
    sys.stdout.buffer.write(value.encode("utf-8"))
    sys.stdout.buffer.flush()

def result(lines=(), error=False):
    global command_number
    write(f"%begin 1 {command_number} 0\r\n")
    for line in lines:
        write(line + "\r\n")
    marker = "error" if error else "end"
    write(f"%{marker} 1 {command_number} 0\r\n")
    command_number += 1

write("\x1bP1000p")
result()
for raw in sys.stdin:
    command = raw.rstrip("\r\n")
    with open(log_path, "a", encoding="utf-8") as handle:
        handle.write("control: " + command + "\n")
    if command.startswith("list-windows "):
        if "work" in remote_cmd:
            result([
                "@0\t0\tmain\t1\t80x24,0,0{39x24,0,0,0,40x24,40,0,3}\t%3",
                "@1\t1\tlogs\t0\t80x24,0,0,1\t%1",
            ])
        else:
            result([
                "@0\t0\tmain\t1\t80x24,0,0{39x24,0,0,0,40x24,40,0,2}\t%2"
            ])
        if drop_after_list:
            os.makedirs(remote_home, exist_ok=True)
            open(reconnect_marker, "w").close()
            sys.exit(255)
    elif command.startswith("capture-pane "):
        match = re.search(r"-t %(\d+)", command)
        pane = match.group(1) if match else "0"
        result([f"seed-pane-{pane}"])
    elif command.startswith("send-keys "):
        match = re.search(r"-t %(\d+)", command)
        pane = match.group(1) if match else "0"
        result()
        write(f"%output %{pane} remote-live-output\\015\\012\r\n")
    else:
        result()
'
  exit $?
fi
if printf '%s' "$remote_cmd" | grep -F 'tmux list-sessions' >/dev/null; then
  if [ "$destination" = "auth-required.example" ]; then
    printf '%s\n' 'Permission denied (publickey,password).' >&2
    exit 255
  fi
  if [ "$destination" = "empty-live.example" ] && [ ! -f "$CMUX_FAKE_REMOTE_HOME/tmux-created" ]; then
    printf '%s\n' 'no server running on /tmp/tmux-1000/default' >&2
    exit 1
  fi
  if [ "$destination" = "empty-live.example" ]; then
    printf '$0\tdefault\t1\t1700000200\t0\n'
    exit 0
  fi
  printf '$0\twork\t2\t1700000000\t0\n'
  printf '$1\tops\t1\t1700000100\t1\n'
  exit 0
fi
if printf '%s' "$remote_cmd" | grep -F 'tmux new-session' >/dev/null; then
  mkdir -p "$CMUX_FAKE_REMOTE_HOME"
  : > "$CMUX_FAKE_REMOTE_HOME/tmux-created"
  exit 0
fi
if printf '%s' "$remote_cmd" | grep -F 'printf %s "$HOME"' >/dev/null; then
  printf '%s\n' "$CMUX_FAKE_REMOTE_HOME"
  exit 0
fi
if printf '%s' "$remote_cmd" | grep -F 'cat >' >/dev/null; then
  CMUX_FAKE_REMOTE_CMD="$remote_cmd" python3 -c '
import os, re, stat, sys

cmd = os.environ.get("CMUX_FAKE_REMOTE_CMD", "")
match = re.search(r"cat > (?:'\''([^'\'']+)'\''|\"([^\"]+)\"|([^; ]+))", cmd)
if not match:
    sys.stdin.buffer.read()
    sys.exit(0)
path = next(group for group in match.groups() if group)
path = path.replace("$HOME", os.environ.get("CMUX_FAKE_REMOTE_HOME", ""))
data = sys.stdin.buffer.read()
os.makedirs(os.path.dirname(path), exist_ok=True)
with open(path, "wb") as handle:
    handle.write(data)
if "chmod +x" in cmd:
    os.chmod(path, os.stat(path).st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
'
  exit $?
fi
cat >/dev/null 2>/dev/null || true
exit 0
"#,
    )
    .expect("write fake ssh");
    let mut permissions = std::fs::metadata(&ssh)
        .expect("fake ssh metadata")
        .permissions();
    permissions.set_mode(0o755);
    std::fs::set_permissions(&ssh, permissions).expect("chmod fake ssh");
    FakeSsh {
        path: format!(
            "{}:{}",
            fake_bin.display(),
            std::env::var("PATH").unwrap_or_default()
        ),
        log_path: log_path.display().to_string(),
        remote_home: remote_home.display().to_string(),
        _root: root,
    }
}

fn start_server_with_env(envs: &[(&str, &str)]) -> Server {
    let tmp = tempfile::tempdir().expect("tempdir");
    let socket = tmp.path().join("cmux.sock").display().to_string();
    let browser_settings_path = tmp
        .path()
        .join("browser-availability.json")
        .display()
        .to_string();
    let agent_hibernation_settings_path = tmp
        .path()
        .join("agent-hibernation.json")
        .display()
        .to_string();
    let feed_log_path = tmp.path().join("workstream.jsonl").display().to_string();
    let session_snapshot_path = tmp.path().join("session-linux.json").display().to_string();
    let browser_profiles_path = tmp
        .path()
        .join("browser-profiles.json")
        .display()
        .to_string();
    let browser_webkit_data_dir = tmp.path().join("webkit-data").display().to_string();
    let browser_webkit_cache_dir = tmp.path().join("webkit-cache").display().to_string();
    let auth_state_path = tmp.path().join("auth.json").display().to_string();
    let custom_sidebar_state_path = tmp
        .path()
        .join("custom-sidebar-state.json")
        .display()
        .to_string();
    let mut command = Command::new(env!("CARGO_BIN_EXE_cmux"));
    command
        .arg("serve")
        .arg("--socket")
        .arg(&socket)
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    if !envs.iter().any(|(key, _)| *key == "XDG_STATE_HOME") {
        command.env("XDG_STATE_HOME", tmp.path().join("state"));
    }
    if !envs
        .iter()
        .any(|(key, _)| *key == "CMUX_BROWSER_SETTINGS_PATH")
    {
        command.env("CMUX_BROWSER_SETTINGS_PATH", &browser_settings_path);
    }
    if !envs
        .iter()
        .any(|(key, _)| *key == "CMUX_AGENT_HIBERNATION_SETTINGS_PATH")
    {
        command.env(
            "CMUX_AGENT_HIBERNATION_SETTINGS_PATH",
            &agent_hibernation_settings_path,
        );
    }
    if !envs.iter().any(|(key, _)| *key == "CMUX_FEED_LOG_PATH") {
        command.env("CMUX_FEED_LOG_PATH", &feed_log_path);
    }
    if !envs
        .iter()
        .any(|(key, _)| *key == "CMUX_SESSION_SNAPSHOT_PATH")
    {
        command.env("CMUX_SESSION_SNAPSHOT_PATH", &session_snapshot_path);
    }
    if !envs
        .iter()
        .any(|(key, _)| *key == "CMUX_BROWSER_PROFILES_PATH")
    {
        command.env("CMUX_BROWSER_PROFILES_PATH", &browser_profiles_path);
    }
    if !envs
        .iter()
        .any(|(key, _)| *key == "CMUX_BROWSER_WEBKIT_DATA_DIR")
    {
        command.env("CMUX_BROWSER_WEBKIT_DATA_DIR", &browser_webkit_data_dir);
    }
    if !envs
        .iter()
        .any(|(key, _)| *key == "CMUX_BROWSER_WEBKIT_CACHE_DIR")
    {
        command.env("CMUX_BROWSER_WEBKIT_CACHE_DIR", &browser_webkit_cache_dir);
    }
    if !envs.iter().any(|(key, _)| *key == "CMUX_AUTH_STATE_PATH") {
        command.env("CMUX_AUTH_STATE_PATH", &auth_state_path);
    }
    if !envs
        .iter()
        .any(|(key, _)| *key == "CMUX_CUSTOM_SIDEBAR_STATE_PATH")
    {
        command.env("CMUX_CUSTOM_SIDEBAR_STATE_PATH", &custom_sidebar_state_path);
    }
    for (key, value) in envs {
        command.env(key, value);
    }
    let child = command.spawn().expect("spawn server");

    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        if UnixStream::connect(&socket).is_ok() {
            return Server {
                child,
                socket,
                agent_hibernation_settings_path,
                browser_settings_path,
                _tmp: tmp,
                _extra_tmp: Vec::new(),
            };
        }
        thread::sleep(Duration::from_millis(50));
    }
    panic!("server did not create socket");
}

#[test]
fn server_writes_xdg_socket_marker_and_cli_discovers_it() {
    let state_root = tempfile::tempdir().expect("xdg state tempdir");
    let xdg_state_home = state_root.path().join("state");
    let xdg_state_home_text = xdg_state_home.display().to_string();
    let server = start_server_with_env(&[("XDG_STATE_HOME", xdg_state_home_text.as_str())]);

    let marker = xdg_state_home.join("cmux/last-socket-path");
    let marker_text = std::fs::read_to_string(&marker)
        .unwrap_or_else(|err| panic!("failed to read marker {}: {err}", marker.display()));
    assert_eq!(marker_text.trim(), server.socket);

    let debug_log = xdg_state_home.join("cmux/logs/cmux-debug.log");
    assert!(
        debug_log.exists(),
        "debug log was not created at {}",
        debug_log.display()
    );

    let output = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("ping")
        .env("XDG_STATE_HOME", &xdg_state_home_text)
        .env_remove("CMUX_SOCKET_PATH")
        .env_remove("CMUX_SOCKET")
        .output()
        .expect("run marker-discovered ping");
    assert!(
        output.status.success(),
        "marker-discovered ping failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(String::from_utf8(output.stdout).unwrap(), "pong\n");
}

fn rpc_response(socket: &str, method: &str, params: Value) -> Value {
    let mut stream = UnixStream::connect(socket).expect("connect socket");
    let request = json!({"id": 1, "method": method, "params": params});
    serde_json::to_writer(&mut stream, &request).expect("write json");
    stream.write_all(b"\n").expect("write newline");
    stream.flush().expect("flush");

    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    reader.read_line(&mut line).expect("read line");
    serde_json::from_str(&line).expect("response json")
}

fn rpc(socket: &str, method: &str, params: Value) -> Value {
    let response = rpc_response(socket, method, params);
    assert_eq!(response["ok"], true, "response was {response}");
    response["result"].clone()
}

fn free_tcp_port() -> u16 {
    TcpListener::bind(("127.0.0.1", 0))
        .expect("reserve free TCP port")
        .local_addr()
        .expect("reserved TCP address")
        .port()
}

fn write_mobile_frame(stream: &mut TcpStream, value: &Value) {
    let payload = serde_json::to_vec(value).expect("encode mobile frame");
    stream
        .write_all(&(payload.len() as u32).to_be_bytes())
        .expect("write mobile frame header");
    stream
        .write_all(&payload)
        .expect("write mobile frame payload");
    stream.flush().expect("flush mobile frame");
}

fn read_mobile_frame(stream: &mut TcpStream) -> Value {
    let mut header = [0_u8; 4];
    stream
        .read_exact(&mut header)
        .expect("read mobile frame header");
    let length = u32::from_be_bytes(header) as usize;
    assert!(length <= 8 * 1024 * 1024, "mobile frame was oversized");
    let mut payload = vec![0_u8; length];
    stream
        .read_exact(&mut payload)
        .expect("read mobile frame payload");
    serde_json::from_slice(&payload).expect("decode mobile frame")
}

fn mobile_rpc(
    stream: &mut TcpStream,
    id: &str,
    method: &str,
    params: Value,
    auth: Option<Value>,
) -> Value {
    let mut request = json!({"id": id, "method": method, "params": params});
    if let Some(auth) = auth {
        request["auth"] = auth;
    }
    write_mobile_frame(stream, &request);
    loop {
        let response = read_mobile_frame(stream);
        if response.get("id").and_then(Value::as_str) == Some(id) {
            return response;
        }
    }
}

#[test]
fn linux_update_check_is_available_through_socket_and_standalone_cli() {
    fn append_file(
        archive: &mut Builder<GzEncoder<Vec<u8>>>,
        path: &str,
        contents: &[u8],
        mode: u32,
    ) {
        let mut header = Header::new_gnu();
        header.set_size(contents.len() as u64);
        header.set_mode(mode);
        header.set_mtime(1_700_000_000);
        header.set_cksum();
        archive
            .append_data(&mut header, path, contents)
            .expect("append update archive file");
    }

    fn update_archive(version: &str) -> Vec<u8> {
        let encoder = GzEncoder::new(Vec::new(), Compression::default());
        let mut archive = Builder::new(encoder);
        append_file(
            &mut archive,
            "cmux-linux-x86_64/install.sh",
            br#"#!/bin/sh
set -eu
root=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
install -d "$PREFIX/bin" "$PREFIX/share/cmux"
install -m 0755 "$root/bin/cmux" "$PREFIX/bin/cmux"
install -m 0644 "$root/share/cmux/bundle-version" "$PREFIX/share/cmux/bundle-version"
install -m 0644 "$root/share/cmux/build-provenance.txt" "$PREFIX/share/cmux/build-provenance.txt"
"#,
            0o755,
        );
        append_file(
            &mut archive,
            "cmux-linux-x86_64/bin/cmux",
            format!("#!/bin/sh\nprintf 'cmux-linux {version}\\n'\n").as_bytes(),
            0o755,
        );
        append_file(
            &mut archive,
            "cmux-linux-x86_64/share/cmux/bundle-version",
            format!("{version}\n").as_bytes(),
            0o644,
        );
        append_file(
            &mut archive,
            "cmux-linux-x86_64/share/cmux/build-provenance.txt",
            format!("schema=cmux.linux-bundle.provenance.v1\nversion={version}\n").as_bytes(),
            0o644,
        );
        let encoder = archive.into_inner().expect("finish update archive tar");
        encoder.finish().expect("finish update archive gzip")
    }

    let listener = TcpListener::bind(("127.0.0.1", 0)).expect("bind update API");
    let address = listener.local_addr().expect("update API address");
    let endpoint = format!("http://{address}/latest");
    let archive = update_archive("v1.2.0");
    let hash = format!("{:x}", Sha256::digest(&archive));
    let expected_hash = hash.clone();
    let release = json!({
        "tag_name": "v1.2.0",
        "html_url": format!("http://{address}/release"),
        "assets": [
            {
                "name": "cmux-linux-x86_64.tar.gz",
                "browser_download_url": format!("http://{address}/archive")
            },
            {
                "name": "cmux-linux-x86_64.tar.gz.sha256",
                "browser_download_url": format!("http://{address}/checksum")
            }
        ]
    });
    let update_api = thread::spawn(move || {
        for _ in 0..7 {
            let (mut stream, _) = listener.accept().expect("accept update request");
            let request = read_fake_http_request(&mut stream).expect("read update request");
            match request.path.as_str() {
                "/latest" => write_fake_http_json(&mut stream, "200 OK", &release),
                "/checksum" => {
                    let body = format!("{hash}  cmux-linux-x86_64.tar.gz\n");
                    let response = format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                        body.len()
                    );
                    stream
                        .write_all(response.as_bytes())
                        .expect("write checksum response");
                }
                "/archive" => {
                    let response = format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: application/gzip\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                        archive.len()
                    );
                    stream
                        .write_all(response.as_bytes())
                        .expect("write archive response headers");
                    stream
                        .write_all(&archive)
                        .expect("write archive response body");
                }
                path => panic!("unexpected update request path: {path}"),
            }
        }
    });
    let server = start_server_with_env(&[
        ("CMUX_LINUX_UPDATE_API_URL", endpoint.as_str()),
        ("CMUX_LINUX_BUNDLE_VERSION", "v1.1.0"),
    ]);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert_eq!(capabilities["features"]["linux_update_check"], true);
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "app.update.check"));
    let socket_status = rpc(&server.socket, "app.update.check", json!({}));
    assert_eq!(socket_status["current_version"], "v1.1.0");
    assert_eq!(socket_status["latest_version"], "v1.2.0");
    assert_eq!(socket_status["update_available"], true);
    assert_eq!(socket_status["archive_sha256"], expected_hash);

    let output = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .args(["update", "--json"])
        .env("CMUX_LINUX_UPDATE_API_URL", &endpoint)
        .env("CMUX_LINUX_BUNDLE_VERSION", "v1.1.0")
        .output()
        .expect("run update CLI");
    assert!(
        output.status.success(),
        "update CLI failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let cli_status: Value = serde_json::from_slice(&output.stdout).expect("update CLI JSON");
    assert_eq!(cli_status["status"], "update_available");
    assert_eq!(cli_status["archive_sha256"], expected_hash);

    let install_root = tempfile::tempdir().expect("update install root");
    let prefix = install_root.path().join("prefix");
    let cache = install_root.path().join("cache");
    let install_output = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .args([
            "update",
            "install",
            "--yes",
            "--prefix",
            prefix.to_str().unwrap(),
            "--json",
        ])
        .env("CMUX_LINUX_UPDATE_API_URL", &endpoint)
        .env("CMUX_LINUX_BUNDLE_VERSION", "v1.1.0")
        .env("XDG_CACHE_HOME", &cache)
        .output()
        .expect("run update install CLI");
    assert!(
        install_output.status.success(),
        "update install CLI failed: stdout={} stderr={}",
        String::from_utf8_lossy(&install_output.stdout),
        String::from_utf8_lossy(&install_output.stderr)
    );
    let install_status: Value =
        serde_json::from_slice(&install_output.stdout).expect("update install JSON");
    assert_eq!(install_status["installed"], true);
    assert_eq!(install_status["latest_version"], "v1.2.0");
    assert_eq!(
        fs::read_to_string(prefix.join("share/cmux/bundle-version"))
            .unwrap()
            .trim(),
        "v1.2.0"
    );
    update_api.join().expect("update API thread");
}

fn start_tcp_socket_bridge(socket: &str) -> u16 {
    let listener = TcpListener::bind(("127.0.0.1", 0)).expect("bind tcp socket bridge");
    let port = listener
        .local_addr()
        .expect("tcp socket bridge addr")
        .port();
    let socket_path = socket.to_string();
    thread::spawn(move || {
        for incoming in listener.incoming().flatten() {
            let socket_path = socket_path.clone();
            thread::spawn(move || {
                let Ok(mut unix) = UnixStream::connect(socket_path) else {
                    return;
                };
                let Ok(mut tcp_write) = incoming.try_clone() else {
                    return;
                };
                let Ok(mut unix_write) = unix.try_clone() else {
                    return;
                };
                let mut tcp_read = incoming;
                let upload = thread::spawn(move || {
                    let _ = std::io::copy(&mut tcp_read, &mut unix_write);
                });
                let _ = std::io::copy(&mut unix, &mut tcp_write);
                let _ = upload.join();
            });
        }
    });
    port
}

fn legacy_rpc(socket: &str, command: &str) -> String {
    let mut stream = UnixStream::connect(socket).expect("connect socket");
    stream
        .write_all(command.as_bytes())
        .expect("write legacy command");
    stream.write_all(b"\n").expect("write legacy newline");
    stream.flush().expect("flush legacy command");
    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    reader.read_line(&mut line).expect("read legacy line");
    line.trim_end().to_string()
}

fn daemon_rpc(
    stdin: &mut std::process::ChildStdin,
    frames: &mpsc::Receiver<Value>,
    id: u64,
    method: &str,
    params: Value,
) -> Value {
    serde_json::to_writer(
        &mut *stdin,
        &json!({"id": id, "method": method, "params": params}),
    )
    .expect("write daemon request");
    stdin.write_all(b"\n").expect("write daemon newline");
    stdin.flush().expect("flush daemon request");
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        let frame = match frames.recv_timeout(remaining.min(Duration::from_millis(250))) {
            Ok(frame) => frame,
            Err(RecvTimeoutError::Timeout) => continue,
            Err(RecvTimeoutError::Disconnected) => panic!("daemon stdout closed"),
        };
        if frame["id"].as_u64() == Some(id) {
            assert_eq!(frame["ok"], true, "daemon response was {frame}");
            return frame["result"].clone();
        }
    }
    panic!("timed out waiting for daemon response id={id} method={method}");
}

fn daemon_event(frames: &mpsc::Receiver<Value>, event_name: &str, stream_id: &str) -> Value {
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        let frame = match frames.recv_timeout(remaining.min(Duration::from_millis(250))) {
            Ok(frame) => frame,
            Err(RecvTimeoutError::Timeout) => continue,
            Err(RecvTimeoutError::Disconnected) => panic!("daemon stdout closed"),
        };
        if frame["event"] == event_name && frame["stream_id"] == stream_id {
            return frame;
        }
    }
    panic!("timed out waiting for daemon event {event_name} stream={stream_id}");
}

fn start_proxy_probe_server(expected_connections: usize) -> (u16, mpsc::Receiver<()>) {
    let listener = TcpListener::bind(("127.0.0.1", 0)).expect("bind proxy probe server");
    let port = listener.local_addr().expect("proxy probe addr").port();
    let (done_tx, done_rx) = mpsc::channel();
    thread::spawn(move || {
        for _ in 0..expected_connections {
            let Ok((mut conn, peer)) = listener.accept() else {
                break;
            };
            let peer_ip = peer.ip().to_string();
            handle_proxy_probe_connection(&mut conn, &peer_ip);
        }
        let _ = done_tx.send(());
    });
    (port, done_rx)
}

fn handle_proxy_probe_connection(conn: &mut TcpStream, peer_ip: &str) {
    conn.set_read_timeout(Some(Duration::from_secs(5)))
        .expect("set read timeout");
    let request = read_http_headers(conn);
    let body = read_http_body(conn, &request);
    if request.to_ascii_lowercase().contains("upgrade: websocket") {
        conn.write_all(
            b"HTTP/1.1 101 Switching Protocols\r\n\
Upgrade: websocket\r\n\
Connection: Upgrade\r\n\
Sec-WebSocket-Accept: cmux-test\r\n\r\n",
        )
        .expect("write websocket handshake");
        let payload = read_websocket_text(conn);
        write_websocket_text(conn, &payload);
        return;
    }

    let path = request
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .unwrap_or("/");
    let body = format!("egress_ip={peer_ip}\npath={path}\nrequest_body={body}\n");
    let response = format!(
        "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\nX-Cmux-Probe: observed\r\n\r\n{}",
        body.len(),
        body
    );
    conn.write_all(response.as_bytes())
        .expect("write probe response");
}

fn read_http_headers(stream: &mut TcpStream) -> String {
    let mut bytes = Vec::new();
    while bytes.len() < 8192 && !bytes.ends_with(b"\r\n\r\n") {
        let mut byte = [0_u8; 1];
        stream.read_exact(&mut byte).expect("read http header byte");
        bytes.push(byte[0]);
    }
    String::from_utf8(bytes).expect("http headers utf8")
}

fn read_http_body(stream: &mut TcpStream, headers: &str) -> String {
    let length = headers
        .lines()
        .find_map(|line| {
            let (name, value) = line.split_once(':')?;
            name.eq_ignore_ascii_case("content-length")
                .then(|| value.trim().parse::<usize>().ok())
                .flatten()
        })
        .unwrap_or(0);
    if length == 0 {
        return String::new();
    }
    let mut body = vec![0_u8; length];
    stream.read_exact(&mut body).expect("read http body");
    String::from_utf8(body).expect("http body utf8")
}

fn socks_connect(proxy_port: u64, target_host: &str, target_port: u16) -> TcpStream {
    let mut stream =
        TcpStream::connect(("127.0.0.1", proxy_port as u16)).expect("connect socks proxy");
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .expect("set socks read timeout");
    stream.write_all(&[0x05, 0x01, 0x00]).expect("socks hello");
    let mut greeting = [0_u8; 2];
    stream
        .read_exact(&mut greeting)
        .expect("read socks greeting");
    assert_eq!(greeting, [0x05, 0x00]);

    let mut request = vec![0x05, 0x01, 0x00];
    if let Ok(addr) = target_host.parse::<std::net::Ipv4Addr>() {
        request.push(0x01);
        request.extend_from_slice(&addr.octets());
    } else {
        request.push(0x03);
        request.push(target_host.len() as u8);
        request.extend_from_slice(target_host.as_bytes());
    }
    request.extend_from_slice(&target_port.to_be_bytes());
    stream.write_all(&request).expect("socks connect");
    let mut reply = [0_u8; 10];
    stream.read_exact(&mut reply).expect("read socks reply");
    assert_eq!(reply[0], 0x05);
    assert_eq!(reply[1], 0x00, "socks connect failed: {reply:?}");
    stream
}

fn http_get_via_socks(proxy_port: u64, target_host: &str, target_port: u16, path: &str) -> String {
    let mut stream = socks_connect(proxy_port, target_host, target_port);
    let request = format!(
        "GET {path} HTTP/1.1\r\nHost: {target_host}:{target_port}\r\nConnection: close\r\n\r\n"
    );
    stream
        .write_all(request.as_bytes())
        .expect("write socks http request");
    read_http_response(&mut stream)
}

fn http_post_via_socks(
    proxy_port: u64,
    target_host: &str,
    target_port: u16,
    path: &str,
    body: &str,
) -> String {
    let mut stream = socks_connect(proxy_port, target_host, target_port);
    let request = format!(
        "POST {path} HTTP/1.1\r\nHost: {target_host}:{target_port}\r\nConnection: close\r\nX-Cmux-Trace: proxy-observed\r\nContent-Length: {}\r\n\r\n{body}",
        body.len()
    );
    stream
        .write_all(request.as_bytes())
        .expect("write socks http post");
    read_http_response(&mut stream)
}

fn connect_via_http_connect(proxy_port: u64, target_host: &str, target_port: u16) -> TcpStream {
    let mut stream =
        TcpStream::connect(("127.0.0.1", proxy_port as u16)).expect("connect http proxy");
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .expect("set connect read timeout");
    let request = format!(
        "CONNECT {target_host}:{target_port} HTTP/1.1\r\nHost: {target_host}:{target_port}\r\n\r\n"
    );
    stream
        .write_all(request.as_bytes())
        .expect("write CONNECT request");
    let response = read_http_headers(&mut stream);
    assert!(
        response.starts_with("HTTP/1.1 200"),
        "CONNECT failed: {response:?}"
    );
    stream
}

fn websocket_echo_via_connect(
    proxy_port: u64,
    target_host: &str,
    target_port: u16,
    message: &str,
) -> String {
    let mut stream = connect_via_http_connect(proxy_port, target_host, target_port);
    let request = format!(
        "GET /ws HTTP/1.1\r\n\
Host: {target_host}:{target_port}\r\n\
Upgrade: websocket\r\n\
Connection: Upgrade\r\n\
Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\
Sec-WebSocket-Version: 13\r\n\r\n"
    );
    stream
        .write_all(request.as_bytes())
        .expect("write websocket handshake");
    let response = read_http_headers(&mut stream);
    assert!(
        response.starts_with("HTTP/1.1 101"),
        "websocket handshake failed: {response:?}"
    );
    write_masked_websocket_text(&mut stream, message);
    read_websocket_text(&mut stream)
}

fn write_masked_websocket_text(stream: &mut TcpStream, message: &str) {
    let payload = message.as_bytes();
    assert!(payload.len() < 126, "test websocket payload too large");
    let mask = [0x11_u8, 0x22, 0x33, 0x44];
    let mut frame = vec![0x81, 0x80 | payload.len() as u8];
    frame.extend_from_slice(&mask);
    for (index, byte) in payload.iter().enumerate() {
        frame.push(byte ^ mask[index % mask.len()]);
    }
    stream.write_all(&frame).expect("write websocket frame");
}

fn write_websocket_text(stream: &mut TcpStream, message: &str) {
    let payload = message.as_bytes();
    assert!(payload.len() < 126, "test websocket payload too large");
    let mut frame = vec![0x81, payload.len() as u8];
    frame.extend_from_slice(payload);
    stream.write_all(&frame).expect("write websocket echo");
}

fn read_websocket_text(stream: &mut TcpStream) -> String {
    let mut head = [0_u8; 2];
    stream.read_exact(&mut head).expect("read websocket header");
    assert_eq!(head[0] & 0x0f, 0x01, "expected text frame: {head:?}");
    let masked = head[1] & 0x80 != 0;
    let len = (head[1] & 0x7f) as usize;
    assert!(
        len < 126,
        "extended websocket lengths are not used in tests"
    );
    let mut mask = [0_u8; 4];
    if masked {
        stream.read_exact(&mut mask).expect("read websocket mask");
    }
    let mut payload = vec![0_u8; len];
    stream
        .read_exact(&mut payload)
        .expect("read websocket payload");
    if masked {
        for (index, byte) in payload.iter_mut().enumerate() {
            *byte ^= mask[index % mask.len()];
        }
    }
    String::from_utf8(payload).expect("websocket payload utf8")
}

fn read_http_response(stream: &mut TcpStream) -> String {
    let headers = read_http_headers(stream);
    let content_length = headers
        .lines()
        .find_map(|line| {
            let (name, value) = line.split_once(':')?;
            name.eq_ignore_ascii_case("content-length")
                .then(|| value.trim().parse::<usize>().ok())
                .flatten()
        })
        .unwrap_or(0);
    let mut body = vec![0_u8; content_length];
    stream.read_exact(&mut body).expect("read http body");
    format!(
        "{}{}",
        headers,
        String::from_utf8(body).expect("http body utf8")
    )
}

fn cli(socket: &str, args: &[&str]) -> String {
    cli_with_env(socket, args, &[])
}

fn cli_with_env(socket: &str, args: &[&str], envs: &[(&str, &str)]) -> String {
    let mut command = Command::new(env!("CARGO_BIN_EXE_cmux"));
    command.arg("--socket").arg(socket).args(args);
    for (key, value) in envs {
        command.env(key, value);
    }
    let output = command.output().expect("run cli");
    assert!(
        output.status.success(),
        "cli failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).expect("stdout utf8")
}

fn cli_with_input(socket: &str, args: &[&str], input: &str) -> String {
    let mut command = Command::new(env!("CARGO_BIN_EXE_cmux"));
    command
        .arg("--socket")
        .arg(socket)
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = command.spawn().expect("spawn cli with input");
    if let Some(mut stdin) = child.stdin.take() {
        stdin.write_all(input.as_bytes()).expect("write stdin");
    }
    let output = child.wait_with_output().expect("wait cli with input");
    assert!(
        output.status.success(),
        "cli failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).expect("stdout utf8")
}

fn cli_json_with_env(socket: &str, args: &[&str], envs: &[(&str, &str)]) -> Value {
    serde_json::from_str(&cli_with_env(socket, args, envs)).expect("cli json")
}

fn cli_json_with_input(socket: &str, args: &[&str], input: &str) -> Value {
    serde_json::from_str(&cli_with_input(socket, args, input)).expect("cli json")
}

fn cli_json_with_input_env_cwd(
    socket: &str,
    args: &[&str],
    input: &str,
    envs: &[(&str, &str)],
    cwd: &std::path::Path,
) -> Value {
    let mut command = Command::new(env!("CARGO_BIN_EXE_cmux"));
    command
        .arg("--socket")
        .arg(socket)
        .args(args)
        .envs(envs.iter().copied())
        .current_dir(cwd)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = command.spawn().expect("spawn cli with input");
    if let Some(mut stdin) = child.stdin.take() {
        stdin.write_all(input.as_bytes()).expect("write stdin");
    }
    let output = child.wait_with_output().expect("wait cli with input");
    assert!(
        output.status.success(),
        "cli failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).expect("cli json")
}

fn cli_failure(socket: &str, args: &[&str]) -> String {
    cli_failure_with_env(socket, args, &[])
}

fn cli_failure_with_env(socket: &str, args: &[&str], envs: &[(&str, &str)]) -> String {
    let output = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("--socket")
        .arg(socket)
        .args(args)
        .envs(envs.iter().copied())
        .output()
        .expect("run cli");
    assert!(
        !output.status.success(),
        "cli unexpectedly succeeded: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    )
}

fn cmux_command_with_input(args: &[&str], envs: &[(&str, &str)], input: &str) -> String {
    let mut command = Command::new(env!("CARGO_BIN_EXE_cmux"));
    command
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for (key, value) in envs {
        command.env(key, value);
    }
    let mut child = command.spawn().expect("spawn cmux command");
    if let Some(mut stdin) = child.stdin.take() {
        stdin.write_all(input.as_bytes()).expect("write stdin");
    }
    let output = child.wait_with_output().expect("wait cmux command");
    assert!(
        output.status.success(),
        "cmux command failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    )
}

fn write_executable(path: &std::path::Path, script: &str) {
    std::fs::write(path, script).expect("write executable");
    let mut permissions = std::fs::metadata(path)
        .expect("executable metadata")
        .permissions();
    permissions.set_mode(0o755);
    std::fs::set_permissions(path, permissions).expect("chmod executable");
}

#[test]
fn linux_app_launcher_exports_sourced_ghostty_environment() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let data_home = tmp.path().join("share");
    let state_home = tmp.path().join("state");
    let home = tmp.path().join("home");
    let config_dir = data_home.join("cmux");
    std::fs::create_dir_all(&config_dir).expect("create launcher config dir");
    std::fs::create_dir_all(&state_home).expect("create launcher state dir");
    std::fs::create_dir_all(&home).expect("create launcher home");
    let socket_path = state_home.join("manual.sock");
    std::fs::write(
        config_dir.join("linux-app.env"),
        format!(
            "CMUX_LINUX_RENDERER=ghostty-vt\n\
             CMUX_GHOSTTY_LIBRARY=/manual/libghostty-internal.so\n\
             CMUX_GHOSTTY_VT_LIBRARY=/manual/libghostty-vt.so\n\
             CMUX_GHOSTTY_ROOT=/manual/ghostty-root\n\
             CMUX_SOCKET_PATH={}\n",
            socket_path.display()
        ),
    )
    .expect("write launcher env");

    let capture = tmp.path().join("cmux-child.log");
    let fake_cmux = tmp.path().join("cmux");
    write_executable(
        &fake_cmux,
        r#"#!/bin/sh
{
  printf 'CALL\n'
  printf 'ARGS=%s\n' "$*"
  printf 'CMUX_LINUX_RENDERER=%s\n' "${CMUX_LINUX_RENDERER-unset}"
  printf 'CMUX_GHOSTTY_LIBRARY=%s\n' "${CMUX_GHOSTTY_LIBRARY-unset}"
  printf 'CMUX_GHOSTTY_VT_LIBRARY=%s\n' "${CMUX_GHOSTTY_VT_LIBRARY-unset}"
  printf 'CMUX_GHOSTTY_ROOT=%s\n' "${CMUX_GHOSTTY_ROOT-unset}"
  printf 'CMUX_SOCKET_PATH=%s\n' "${CMUX_SOCKET_PATH-unset}"
  printf 'CMUX_LINUX_GTK_SINGLE_INSTANCE=%s\n' "${CMUX_LINUX_GTK_SINGLE_INSTANCE-unset}"
} >> "$CMUX_FAKE_CAPTURE"
if [ "${3:-}" = "ping" ]; then
  exit 1
fi
exit 0
"#,
    );

    let launcher = Path::new(env!("CARGO_MANIFEST_DIR")).join("dist/cmux-linux-app");
    let output = Command::new(&launcher)
        .arg("/tmp/cmux-launch-target")
        .env("CMUX_BIN", &fake_cmux)
        .env("CMUX_FAKE_CAPTURE", &capture)
        .env("XDG_DATA_HOME", &data_home)
        .env("XDG_STATE_HOME", &state_home)
        .env("HOME", &home)
        .output()
        .expect("run linux app launcher");
    assert!(
        output.status.success(),
        "launcher failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );

    let log = std::fs::read_to_string(&capture).expect("read fake cmux log");
    assert!(
        log.contains("ARGS=app --renderer ghostty-vt --socket "),
        "launcher did not start app with sourced renderer: {log}"
    );
    assert!(
        log.contains("CMUX_GHOSTTY_LIBRARY=/manual/libghostty-internal.so"),
        "sourced full Ghostty library was not exported: {log}"
    );
    assert!(
        log.contains("CMUX_GHOSTTY_VT_LIBRARY=/manual/libghostty-vt.so"),
        "sourced Ghostty VT library was not exported: {log}"
    );
    assert!(
        log.contains("CMUX_GHOSTTY_ROOT=/manual/ghostty-root"),
        "sourced Ghostty root was not exported: {log}"
    );
    assert!(
        log.contains(&format!("CMUX_SOCKET_PATH={}", socket_path.display())),
        "sourced socket path was not exported: {log}"
    );
    assert!(
        log.contains("CMUX_LINUX_GTK_SINGLE_INSTANCE=1"),
        "configured launcher socket should retain GTK application ownership: {log}"
    );
}

