#[test]
fn linux_desktop_entry_registers_file_and_url_launch_contract() {
    let desktop = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("dist/ai.manaflow.cmux.desktop.in"),
    )
    .expect("read desktop template");

    assert!(
        desktop.contains("Exec=@CMUX_APP_WRAPPER@ %U"),
        "desktop launcher should accept URLs and files through the wrapper: {desktop}"
    );
    for mime in [
        "inode/directory",
        "text/plain",
        "text/markdown",
        "text/x-patch",
        "text/x-diff",
        "x-scheme-handler/cmux",
        "x-scheme-handler/http",
        "x-scheme-handler/https",
    ] {
        assert!(
            desktop.contains(mime),
            "desktop template missing MIME/scheme handler {mime}: {desktop}"
        );
    }
}

#[test]
fn linux_app_launcher_routes_files_to_existing_app() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let data_home = tmp.path().join("share");
    let state_home = tmp.path().join("state");
    let home = tmp.path().join("home");
    std::fs::create_dir_all(&data_home).expect("create launcher data dir");
    std::fs::create_dir_all(&state_home).expect("create launcher state dir");
    std::fs::create_dir_all(&home).expect("create launcher home");

    let capture = tmp.path().join("cmux-child.log");
    let fake_cmux = tmp.path().join("cmux");
    write_executable(
        &fake_cmux,
        r#"#!/bin/sh
printf 'ARGS=%s\n' "$*" >> "$CMUX_FAKE_CAPTURE"
if [ "${3:-}" = "ping" ]; then
  exit 0
fi
exit 0
"#,
    );

    let launcher = Path::new(env!("CARGO_MANIFEST_DIR")).join("dist/cmux-linux-app");
    let output = Command::new(&launcher)
        .arg("/tmp/cmux-open-one")
        .arg("/tmp/cmux-open-two")
        .env("CMUX_BIN", &fake_cmux)
        .env("CMUX_FAKE_CAPTURE", &capture)
        .env("CMUX_LINUX_RENDERER", "core")
        .env("XDG_DATA_HOME", &data_home)
        .env("XDG_STATE_HOME", &state_home)
        .env("HOME", &home)
        .output()
        .expect("run linux app launcher");
    assert!(
        output.status.success(),
        "launcher failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );

    let log = std::fs::read_to_string(&capture).expect("read fake cmux log");
    assert!(
        log.contains("ARGS=--socket ") && log.contains(" ping"),
        "launcher did not probe the existing app socket: {log}"
    );
    assert!(
        log.contains(" open /tmp/cmux-open-one /tmp/cmux-open-two"),
        "launcher did not route desktop file handoff to open: {log}"
    );
    assert!(
        !log.contains(" app --renderer "),
        "launcher should not start a second app when ping succeeds: {log}"
    );
}

