#[test]
fn cli_workspace_env_targets_background_workspace() {
    let server = start_server();
    let active = rpc(&server.socket, "workspace.current", json!({}));
    let active_workspace_id = active["workspace_id"].as_str().unwrap().to_string();
    let background = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "background-agent", "focus": false}),
    );
    let background_workspace_id = background["workspace_id"].as_str().unwrap().to_string();
    assert_ne!(active_workspace_id, background_workspace_id);

    let env = [("CMUX_WORKSPACE_ID", background_workspace_id.as_str())];
    let listed = cli_json_with_env(
        &server.socket,
        &["--json", "--id-format", "both", "list-panels"],
        &env,
    );
    assert_eq!(listed["workspace_id"], background_workspace_id);
    let background_count = listed["surfaces"].as_array().unwrap().len();
    let active_count = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": active_workspace_id}),
    )["surfaces"]
        .as_array()
        .unwrap()
        .len();

    let token = "workspace-env-background-token";
    let send_output = cli_with_env(&server.socket, &["send", token], &env);
    assert!(
        send_output.contains("surface") || send_output.contains("OK") || send_output.contains('{'),
        "send output was {send_output}"
    );
    let background_text = rpc(
        &server.socket,
        "surface.read_text",
        json!({"workspace_id": background_workspace_id}),
    );
    assert!(
        background_text["text"]
            .as_str()
            .unwrap_or_default()
            .contains(token),
        "background text was {background_text}"
    );
    let active_text = rpc(
        &server.socket,
        "surface.read_text",
        json!({"workspace_id": active_workspace_id}),
    );
    assert!(
        !active_text["text"]
            .as_str()
            .unwrap_or_default()
            .contains(token),
        "active workspace should not receive background send: {active_text}"
    );

    let created = cli_with_env(&server.socket, &["new-surface", "--type", "terminal"], &env);
    assert!(
        created.contains("surface:"),
        "new-surface output was {created}"
    );
    let after_create = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": background_workspace_id}),
    );
    assert_eq!(
        after_create["surfaces"].as_array().unwrap().len(),
        background_count + 1
    );
    let active_after_create = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": active_workspace_id}),
    );
    assert_eq!(
        active_after_create["surfaces"].as_array().unwrap().len(),
        active_count
    );

    let pane_surfaces = cli_json_with_env(
        &server.socket,
        &["--json", "--id-format", "both", "list-pane-surfaces"],
        &env,
    );
    assert_eq!(
        pane_surfaces["surfaces"].as_array().unwrap().len(),
        background_count + 1
    );

    let close_output = cli_with_env(
        &server.socket,
        &["close-surface", "--surface", "surface:1"],
        &env,
    );
    assert!(
        close_output.contains('{') || close_output.contains("OK"),
        "close-surface output was {close_output}"
    );
    let after_close = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": background_workspace_id}),
    );
    assert_eq!(
        after_close["surfaces"].as_array().unwrap().len(),
        background_count
    );
    let active_after_close = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": active_workspace_id}),
    );
    assert_eq!(
        active_after_close["surfaces"].as_array().unwrap().len(),
        active_count
    );

    let current = rpc(&server.socket, "workspace.current", json!({}));
    assert_eq!(current["workspace_id"], active_workspace_id);
}

#[test]
fn workspace_env_returns_configured_env_and_applies_to_terminals() {
    let server = start_server();
    let workspace = rpc(
        &server.socket,
        "workspace.create",
        json!({
            "title": "env workspace",
            "working_directory": "/tmp",
            "focus": true,
            "command": "printf 'env:%s:%s:%s\\n' \"$PROJECT_TOKEN\" \"$SURFACE_ONLY\" \"$CMUX_WORKSPACE_ID\"",
            "initial_env": {
                "SURFACE_ONLY": "surface-value",
                "PROJECT_TOKEN": "surface-overrides-workspace"
            },
            "workspace_env": {
                " PROJECT_TOKEN ": "workspace-secret",
                "CMUX_WORKSPACE_ID": "spoofed-workspace",
                "BLANK": "",
                "BAD=KEY": "bad",
                "NUL_VALUE": "bad\u{0}value",
                "NUMBER": 42
            }
        }),
    );
    let workspace_id = workspace["workspace_id"].as_str().unwrap().to_string();
    let workspace_ref = workspace["workspace_ref"].as_str().unwrap().to_string();
    let listed = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    );
    let surface = &listed["surfaces"].as_array().unwrap()[0];
    let surface_id = surface["surface_id"].as_str().unwrap().to_string();
    let pane_id = surface["pane_id"].as_str().unwrap().to_string();

    let by_workspace = rpc(
        &server.socket,
        "workspace.env",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(by_workspace["workspace_id"], workspace_id);
    assert_eq!(by_workspace["workspace_ref"], workspace_ref);
    assert_eq!(by_workspace["env"]["PROJECT_TOKEN"], "workspace-secret");
    assert_eq!(
        by_workspace["env"]["CMUX_WORKSPACE_ID"],
        "spoofed-workspace"
    );
    assert_eq!(by_workspace["count"], 2);
    assert!(by_workspace["env"].get("BLANK").is_none());
    assert!(by_workspace["env"].get("BAD=KEY").is_none());
    assert!(by_workspace["env"].get("NUL_VALUE").is_none());
    assert!(by_workspace["env"].get("NUMBER").is_none());

    let by_surface = rpc(
        &server.socket,
        "workspace.env",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(by_surface["workspace_id"], workspace_id);
    let by_pane = rpc(&server.socket, "workspace.env", json!({"pane_id": pane_id}));
    assert_eq!(by_pane["workspace_id"], workspace_id);

    let workspace_list = rpc(&server.socket, "workspace.list", json!({}));
    let row = workspace_list["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == workspace_id)
        .expect("workspace row");
    assert!(
        row.get("env").is_none() && row.get("workspace_env").is_none(),
        "workspace list should not expose workspace env: {row}"
    );

    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let read = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": surface_id}),
        );
        let text = read["text"].as_str().unwrap_or_default();
        if text.contains(&format!(
            "env:surface-overrides-workspace:surface-value:{workspace_id}"
        )) {
            let invalid = rpc_response(
                &server.socket,
                "workspace.env",
                json!({"workspace_id": "missing-workspace"}),
            );
            assert_eq!(invalid["ok"], false, "response was {invalid}");
            assert_eq!(invalid["error"]["code"], "not_found");

            let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
            assert!(capabilities["methods"]
                .as_array()
                .unwrap()
                .iter()
                .any(|method| method == "workspace.env"));
            assert_eq!(capabilities["features"]["workspace_env"], true);
            return;
        }
        thread::sleep(Duration::from_millis(100));
    }
    let read = rpc(
        &server.socket,
        "surface.read_text",
        json!({"surface_id": surface_id}),
    );
    panic!("workspace env did not reach terminal: {read}");
}

#[test]
fn cli_workspace_namespace_create_env_and_aliases() {
    let server = start_server();
    let env_dir = tempfile::tempdir().expect("workspace env tempdir");
    let env_path = env_dir.path().join("workspace.env");
    std::fs::write(
        &env_path,
        "FROM_FILE=file-value\nOVERRIDE=from-file\n# ignored\nexport EXPORTED=from-export\n",
    )
    .expect("write env file");
    let env_path = env_path.display().to_string();

    let created = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace",
            "create",
            "--name",
            "namespace env",
            "--env-file",
            &env_path,
            "--env",
            "OVERRIDE=from-cli",
            "--env",
            "CLI_ONLY=cli-value",
        ],
        &[],
    );
    let workspace_id = created["workspace_id"].as_str().unwrap().to_string();

    let env = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace",
            "env",
            &workspace_id,
        ],
        &[],
    );
    assert_eq!(env["workspace_id"], workspace_id);
    assert_eq!(env["env"]["FROM_FILE"], "file-value");
    assert_eq!(env["env"]["EXPORTED"], "from-export");
    assert_eq!(env["env"]["OVERRIDE"], "from-cli");
    assert_eq!(env["env"]["CLI_ONLY"], "cli-value");
    assert_eq!(env["count"], 4);

    let masked = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace",
            "env",
            "--mask",
            &workspace_id,
        ],
        &[],
    );
    assert_eq!(masked["env"]["OVERRIDE"], "***");
    assert_eq!(masked["env"]["CLI_ONLY"], "***");
    assert_eq!(masked["count"], 4);

    let selected = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace",
            "select",
            &workspace_id,
        ],
        &[],
    );
    assert_eq!(selected["workspace_id"], workspace_id);

    let renamed = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace",
            "rename",
            &workspace_id,
            "Namespace Renamed",
        ],
        &[],
    );
    assert_eq!(renamed["workspace_id"], workspace_id);

    let listed = cli_json_with_env(
        &server.socket,
        &["--json", "--id-format", "both", "workspace", "list"],
        &[],
    );
    let row = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == workspace_id)
        .expect("renamed workspace row");
    assert_eq!(row["title"], "Namespace Renamed");
    assert!(row.get("env").is_none());
    assert!(row.get("workspace_env").is_none());

    let groups = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace",
            "group",
            "list",
        ],
        &[],
    );
    assert!(groups["groups"].as_array().is_some());

    let closed = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace",
            "close",
            &workspace_id,
        ],
        &[],
    );
    assert!(closed.as_object().is_some());
    let after_close = rpc(&server.socket, "workspace.list", json!({}));
    assert!(after_close["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .all(|row| row["workspace_id"].as_str() != Some(workspace_id.as_str())));
}

#[test]
fn cli_workspace_namespace_remote_disconnect_reconnect_uses_caller_workspace() {
    let fake = fake_ssh();
    let server = start_server_with_env(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);
    let remote = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "namespace remote",
            "destination": "namespace.example",
            "identity_file": "/tmp/cmux-fake-key"
        }),
    );
    let workspace_id = remote["workspace_id"].as_str().unwrap().to_string();
    let env = [("CMUX_WORKSPACE_ID", workspace_id.as_str())];

    let disconnected = cli_json_with_env(
        &server.socket,
        &["--json", "--id-format", "both", "workspace", "disconnect"],
        &env,
    );
    assert_eq!(disconnected["workspace_id"], workspace_id);
    assert_eq!(disconnected["remote"]["state"], "disconnected");

    let reconnected = cli_json_with_env(
        &server.socket,
        &["--json", "--id-format", "both", "workspace", "reconnect"],
        &env,
    );
    assert_eq!(reconnected["workspace_id"], workspace_id);
    assert_eq!(reconnected["remote"]["state"], "connecting");
    assert_eq!(reconnected["remote"]["proxy"]["state"], "connecting");
}

#[test]
fn system_tree_snapshots_window_workspace_pane_surface_hierarchy() {
    let server = start_server();
    let ident = rpc(&server.socket, "system.identify", json!({}));
    let window_id = ident["focused"]["window_id"].as_str().unwrap().to_string();
    let window_ref = ident["focused"]["window_ref"].as_str().unwrap().to_string();
    let workspace_id = ident["focused"]["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let workspace_ref = ident["focused"]["workspace_ref"]
        .as_str()
        .unwrap()
        .to_string();
    let original_surface = ident["focused"]["surface_id"].as_str().unwrap().to_string();

    let split = rpc(
        &server.socket,
        "surface.split",
        json!({"direction": "right", "title": "Tree Split"}),
    );
    let split_pane_id = split["pane_id"].as_str().unwrap().to_string();
    let split_surface_id = split["surface_id"].as_str().unwrap().to_string();

    let tree = rpc(&server.socket, "system.tree", json!({}));
    assert_eq!(tree["active"]["window_id"], window_id);
    assert_eq!(tree["active"]["workspace_id"], workspace_id);
    assert_eq!(tree["caller"], Value::Null);
    assert_eq!(tree["windows"].as_array().unwrap().len(), 1);
    let window = &tree["windows"][0];
    assert_eq!(window["id"], window_id);
    assert_eq!(window["ref"], window_ref);
    assert_eq!(window["key"], true);
    assert_eq!(window["visible"], true);
    assert_eq!(window["selected_workspace_id"], workspace_id);
    assert_eq!(window["selected_workspace_ref"], workspace_ref);

    let workspace = window["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == workspace_id)
        .expect("workspace row");
    assert_eq!(workspace["ref"], workspace_ref);
    assert_eq!(workspace["selected"], true);
    assert_eq!(workspace["pinned"], false);
    assert_eq!(workspace["panes"].as_array().unwrap().len(), 2);

    let split_pane = workspace["panes"]
        .as_array()
        .unwrap()
        .iter()
        .find(|pane| pane["id"] == split_pane_id)
        .expect("split pane");
    assert_eq!(split_pane["focused"], true);
    assert_eq!(split_pane["selected_surface_id"], split_surface_id);
    assert_eq!(split_pane["surface_count"], 1);
    assert_eq!(split_pane["surface_ids"], json!([split_surface_id]));
    assert_eq!(split_pane["surface_refs"].as_array().unwrap().len(), 1);

    let split_surface = &split_pane["surfaces"][0];
    assert_eq!(split_surface["id"], split_surface_id);
    assert_eq!(split_surface["type"], "terminal");
    assert_eq!(split_surface["title"], "Tree Split");
    assert_eq!(split_surface["focused"], true);
    assert_eq!(split_surface["selected"], true);
    assert_eq!(split_surface["selected_in_pane"], true);
    assert_eq!(split_surface["pane_id"], split_pane_id);
    assert_eq!(split_surface["index_in_pane"], 0);
    assert_eq!(split_surface["url"], Value::Null);

    let original_pane = workspace["panes"]
        .as_array()
        .unwrap()
        .iter()
        .find(|pane| {
            pane["surface_ids"]
                .as_array()
                .unwrap()
                .iter()
                .any(|id| id == &original_surface)
        })
        .expect("original pane");
    assert_eq!(original_pane["focused"], false);

    let second_window = rpc(
        &server.socket,
        "window.create",
        json!({"title": "Tree Second"}),
    );
    let second_window_id = second_window["window_id"].as_str().unwrap();
    let all = rpc(&server.socket, "system.tree", json!({"all_windows": true}));
    assert!(
        all["windows"]
            .as_array()
            .unwrap()
            .iter()
            .any(|window| window["id"] == window_id),
        "all-windows tree missing original window: {all}"
    );
    assert!(
        all["windows"]
            .as_array()
            .unwrap()
            .iter()
            .any(|window| window["id"] == second_window_id),
        "all-windows tree missing second window: {all}"
    );

    let filtered = rpc(
        &server.socket,
        "system.tree",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(filtered["windows"].as_array().unwrap().len(), 1);
    assert_eq!(filtered["windows"][0]["id"], window_id);
    assert_eq!(
        filtered["windows"][0]["workspaces"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert_eq!(filtered["windows"][0]["workspaces"][0]["id"], workspace_id);

    let invalid = rpc_response(
        &server.socket,
        "system.tree",
        json!({"all_windows": "maybe"}),
    );
    assert_eq!(invalid["ok"], false, "response was {invalid}");
    assert_eq!(invalid["error"]["code"], "invalid_params");

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "system.tree"));
    assert_eq!(capabilities["features"]["system_tree"], true);
}

#[test]
fn cli_tree_debug_and_app_focus_commands_match_socket_contract() {
    let server = start_server();
    let ident = rpc(&server.socket, "system.identify", json!({}));
    let window_id = ident["focused"]["window_id"].as_str().unwrap().to_string();
    let workspace_id = ident["focused"]["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    let tree = cli_json_with_env(
        &server.socket,
        &["--json", "--id-format", "both", "tree"],
        &[],
    );
    assert_eq!(tree["active"]["window_id"], window_id);
    assert_eq!(tree["active"]["workspace_id"], workspace_id);
    assert_eq!(tree["windows"].as_array().unwrap().len(), 1);

    let filtered = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "tree",
            "--workspace",
            workspace_id.as_str(),
        ],
        &[],
    );
    assert_eq!(filtered["windows"].as_array().unwrap().len(), 1);
    assert_eq!(filtered["windows"][0]["workspaces"][0]["id"], workspace_id);

    rpc(
        &server.socket,
        "window.create",
        json!({"title": "CLI Tree"}),
    );
    let all = cli_json_with_env(
        &server.socket,
        &["--json", "--id-format", "both", "tree", "--all-windows"],
        &[],
    );
    assert!(
        all["windows"]
            .as_array()
            .unwrap()
            .iter()
            .any(|window| window["id"] == window_id),
        "all-windows tree missing original window: {all}"
    );

    let terminals = cli_json_with_env(&server.socket, &["--json", "debug-terminals"], &[]);
    assert!(
        !terminals["terminals"].as_array().unwrap().is_empty(),
        "debug-terminals returned no terminal rows: {terminals}"
    );

    let inactive = cli_json_with_env(
        &server.socket,
        &["--json", "set-app-focus", "inactive"],
        &[],
    );
    assert_eq!(inactive["active"], false);
    let cleared = cli_json_with_env(
        &server.socket,
        &["--json", "set-app-focus", "--state", "clear"],
        &[],
    );
    assert_eq!(cleared["active"], Value::Null);
    let active = cli_json_with_env(&server.socket, &["--json", "simulate-app-active"], &[]);
    assert_eq!(active["active"], true);
}

#[test]
fn system_identify_includes_browser_metadata_for_focused_and_caller_contexts() {
    let server = start_server();
    let initial = rpc(&server.socket, "system.identify", json!({}));
    assert_eq!(initial["focused"]["surface_type"], "terminal");

    let url = "data:text/html,<title>Identify Context</title><main>ready</main>";
    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": url, "focus": false}),
    );
    let surface_id = opened["surface_id"].as_str().unwrap();
    let surface_ref = opened["surface_ref"].as_str().unwrap();

    let caller_ident = rpc(
        &server.socket,
        "system.identify",
        json!({"caller": {"surface_id": surface_id}}),
    );
    assert_eq!(caller_ident["focused"]["surface_type"], "terminal");
    assert_eq!(caller_ident["caller"]["surface_id"], surface_id);
    assert_eq!(caller_ident["caller"]["surface_ref"], surface_ref);
    assert_eq!(caller_ident["caller"]["surface_type"], "browser");
    assert_eq!(caller_ident["caller"]["browser"]["url"], url);
    assert_eq!(
        caller_ident["caller"]["browser"]["title"],
        "Identify Context"
    );
    assert_eq!(caller_ident["caller"]["browser"]["loading"], false);
    assert_eq!(caller_ident["caller"]["browser"]["focused"], false);

    rpc(
        &server.socket,
        "browser.bringtofront",
        json!({"surface_id": surface_id}),
    );
    let focused_ident = rpc(&server.socket, "system.identify", json!({}));
    assert_eq!(focused_ident["surface_id"], surface_id);
    assert_eq!(focused_ident["surface_ref"], surface_ref);
    assert_eq!(focused_ident["surface_type"], "browser");
    assert_eq!(focused_ident["browser"]["url"], url);
    assert_eq!(focused_ident["browser"]["title"], "Identify Context");
    assert_eq!(focused_ident["browser"]["loading"], false);
    assert_eq!(focused_ident["browser"]["focused"], true);
    assert_eq!(focused_ident["focused"]["surface_id"], surface_id);
    assert_eq!(focused_ident["focused"]["surface_type"], "browser");
    assert_eq!(focused_ident["focused"]["browser"]["url"], url);
    assert_eq!(
        focused_ident["focused"]["browser"]["title"],
        "Identify Context"
    );
}

#[test]
fn system_top_and_memory_report_linux_process_resources() {
    let server = start_server();
    let ident = rpc(&server.socket, "system.identify", json!({}));
    let workspace_id = ident["focused"]["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let surface_id = ident["focused"]["surface_id"].as_str().unwrap().to_string();

    let top = rpc(
        &server.socket,
        "system.top",
        json!({"include_processes": true}),
    );
    assert_eq!(top["active"]["workspace_id"], workspace_id);
    assert_eq!(top["sample"]["source"], "linux.procfs");
    assert_eq!(top["sample"]["process_details"], true);
    assert!(
        top["totals"]["process_count"].as_i64().unwrap_or(0) >= 1,
        "system.top should account at least the app process: {top}"
    );
    assert!(top["program_totals"].is_array());
    assert!(top["coding_agents"].is_array());
    assert!(top["memory_diagnostic"]["app"]["pid"].as_i64().unwrap_or(0) > 0);

    let window = &top["windows"][0];
    assert_eq!(window["kind"], "window");
    assert!(window["resources"]["resident_bytes"].as_i64().unwrap_or(-1) >= 0);
    assert!(!window["app_process_pids"].as_array().unwrap().is_empty());

    let workspace = window["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == workspace_id)
        .expect("workspace row");
    assert_eq!(workspace["kind"], "workspace");
    assert!(workspace["tags"].is_array());
    assert!(
        workspace["resources"]["process_count"]
            .as_i64()
            .unwrap_or(0)
            >= 1
    );

    let surface = workspace["panes"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|pane| pane["surfaces"].as_array().unwrap().iter())
        .find(|surface| surface["id"] == surface_id)
        .expect("focused surface");
    assert_eq!(surface["kind"], "surface");
    assert_eq!(surface["type"], "terminal");
    assert!(
        !surface["root_pids"].as_array().unwrap().is_empty(),
        "terminal surface should expose a root shell pid: {surface}"
    );
    assert!(
        surface["resources"]["process_count"].as_i64().unwrap_or(0) >= 1,
        "terminal surface should have a process summary: {surface}"
    );
    assert!(
        !surface["processes"].as_array().unwrap().is_empty(),
        "include_processes should include a process tree: {surface}"
    );
    assert_eq!(surface["processes"][0]["kind"], "process");

    let summarized = rpc(&server.socket, "system.top", json!({}));
    let summarized_surface = summarized["windows"][0]["workspaces"][0]["panes"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|pane| pane["surfaces"].as_array().unwrap().iter())
        .find(|surface| surface["id"] == surface_id)
        .expect("summarized focused surface");
    assert!(
        summarized_surface["processes"]
            .as_array()
            .unwrap()
            .is_empty(),
        "system.top should omit process trees unless include_processes is true"
    );

    let memory = rpc(
        &server.socket,
        "system.memory",
        json!({"top_group_limit": 3}),
    );
    assert_eq!(memory["sample"]["source"], "linux.procfs");
    assert_eq!(memory["sample"]["process_details"], true);
    assert!(memory["memory_diagnostic"]["summary"].as_str().is_some());
    assert!(
        memory["memory_diagnostic"]["children"]["groups"]
            .as_array()
            .unwrap()
            .len()
            <= 3
    );

    let filtered = rpc(
        &server.socket,
        "system.top",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(filtered["windows"].as_array().unwrap().len(), 1);
    assert_eq!(
        filtered["windows"][0]["workspaces"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert!(
        filtered["windows"][0]["app_process_pids"]
            .as_array()
            .unwrap()
            .is_empty(),
        "workspace-scoped top should not attach the app process to the window"
    );

    let invalid_include = rpc_response(
        &server.socket,
        "system.top",
        json!({"include_processes": "maybe"}),
    );
    assert_eq!(
        invalid_include["ok"], false,
        "response was {invalid_include}"
    );
    assert_eq!(invalid_include["error"]["code"], "invalid_params");

    let invalid_limit = rpc_response(&server.socket, "system.memory", json!({"group_limit": 0}));
    assert_eq!(invalid_limit["ok"], false, "response was {invalid_limit}");
    assert_eq!(invalid_limit["error"]["code"], "invalid_params");

    let cli_top: Value =
        serde_json::from_str(&cli(&server.socket, &["top", "--include-processes"]))
            .expect("cmux top json");
    assert_eq!(cli_top["sample"]["source"], "linux.procfs");
    assert_eq!(cli_top["sample"]["process_details"], true);

    let cli_memory: Value =
        serde_json::from_str(&cli(&server.socket, &["memory", "--top-group-limit", "2"]))
            .expect("cmux memory json");
    assert!(
        cli_memory["memory_diagnostic"]["children"]["groups"]
            .as_array()
            .unwrap()
            .len()
            <= 2
    );

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    assert!(methods.iter().any(|method| method == "system.top"));
    assert!(methods.iter().any(|method| method == "system.memory"));
    assert_eq!(capabilities["features"]["system_top"], true);
    assert_eq!(capabilities["features"]["system_memory"], true);
}

#[test]
fn window_display_lists_and_assigns_linux_displays() {
    let displays_json = r#"[
        {"name":"Built-in","index":0,"display_id":11,"main":true,"frame":{"x":0,"y":0,"width":1920,"height":1080}},
        {"name":"LG HDR 4K","index":1,"display_id":42,"main":false,"frame":{"x":1920,"y":0,"width":3840,"height":2160}}
    ]"#;
    let server = start_server_with_env(&[("CMUX_LINUX_DISPLAYS_JSON", displays_json)]);

    let displays = rpc(&server.socket, "window.displays", json!({}));
    assert_eq!(displays["displays"].as_array().unwrap().len(), 2);
    assert_eq!(displays["displays"][0]["name"], "Built-in");
    assert_eq!(displays["displays"][0]["display_id"], 11);
    assert_eq!(displays["displays"][0]["main"], true);
    assert_eq!(displays["displays"][1]["frame"]["width"], 3840);

    let current = rpc(&server.socket, "window.current", json!({}));
    let window_id = current["window_id"].as_str().unwrap().to_string();
    let moved = rpc(
        &server.socket,
        "window.display",
        json!({"window_id": &window_id, "display": "LG"}),
    );
    assert_eq!(moved["display"], "LG HDR 4K");
    assert_eq!(moved["window_id"], window_id);
    assert_eq!(moved["moved"], json!([&window_id]));

    let listed = rpc(&server.socket, "window.list", json!({}));
    let row = listed["windows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == window_id)
        .expect("window row");
    assert_eq!(row["display"], "LG HDR 4K");

    let second = rpc(
        &server.socket,
        "window.create",
        json!({"title": "display two"}),
    );
    let second_window = second["window_id"].as_str().unwrap().to_string();
    let all = rpc(&server.socket, "window.display", json!({"display": "0"}));
    assert_eq!(all["display"], "Built-in");
    let moved_ids = all["moved"].as_array().unwrap();
    assert!(moved_ids.iter().any(|id| id == &window_id));
    assert!(moved_ids.iter().any(|id| id == &second_window));

    let cli_displays: Value =
        serde_json::from_str(&cli(&server.socket, &["--json", "window", "displays"]))
            .expect("window displays json");
    assert_eq!(cli_displays["displays"][1]["name"], "LG HDR 4K");

    let cli_moved: Value = serde_json::from_str(&cli(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "window",
            "display",
            "LG",
            "--window",
            &second_window,
        ],
    ))
    .expect("window display json");
    assert_eq!(cli_moved["display"], "LG HDR 4K");
    assert_eq!(cli_moved["window_id"], second_window);

    let invalid = rpc_response(&server.socket, "window.display", json!({}));
    assert_eq!(invalid["ok"], false, "response was {invalid}");
    assert_eq!(invalid["error"]["code"], "invalid_params");

    let missing = rpc_response(&server.socket, "window.display", json!({"display": "Nope"}));
    assert_eq!(missing["ok"], false, "response was {missing}");
    assert_eq!(missing["error"]["code"], "not_found");
    assert!(missing["error"]["message"]
        .as_str()
        .unwrap()
        .contains("Built-in"));

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    assert!(methods.iter().any(|method| method == "window.displays"));
    assert!(methods.iter().any(|method| method == "window.display"));
    assert_eq!(capabilities["features"]["window_display"], true);
}

#[test]
fn window_create_uses_configured_default_display() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let home = tmp.path();
    let xdg_config = home.join(".config");
    let xdg_cache = home.join(".cache");
    let cmux_json = xdg_config.join("cmux/cmux.json");
    std::fs::create_dir_all(cmux_json.parent().unwrap()).expect("cmux config dir");
    std::fs::write(
        &cmux_json,
        r#"{
  "app": {
    "devWindowDisplay": "LG"
  }
}
"#,
    )
    .expect("write cmux json");
    let home_s = home.display().to_string();
    let xdg_config_s = xdg_config.display().to_string();
    let xdg_cache_s = xdg_cache.display().to_string();
    let displays_json = r#"[
        {"name":"Built-in","index":0,"display_id":11,"main":true,"frame":{"x":0,"y":0,"width":1920,"height":1080}},
        {"name":"LG HDR 4K","index":1,"display_id":42,"main":false,"frame":{"x":1920,"y":0,"width":3840,"height":2160}}
    ]"#;
    let server = start_server_with_env(&[
        ("HOME", home_s.as_str()),
        ("XDG_CONFIG_HOME", xdg_config_s.as_str()),
        ("XDG_CACHE_HOME", xdg_cache_s.as_str()),
        ("CMUX_LINUX_DISPLAYS_JSON", displays_json),
    ]);

    let current = rpc(&server.socket, "window.current", json!({}));
    let initial_window = current["window_id"].as_str().unwrap().to_string();
    let listed = rpc(&server.socket, "window.list", json!({}));
    let initial_row = listed["windows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == initial_window)
        .expect("initial window row");
    assert_eq!(initial_row["display"], "LG HDR 4K");

    let created = rpc(
        &server.socket,
        "window.create",
        json!({"title": "default display"}),
    );
    let new_window = created["window_id"].as_str().unwrap().to_string();
    let listed = rpc(&server.socket, "window.list", json!({}));
    let new_row = listed["windows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == new_window)
        .expect("new window row");
    assert_eq!(new_row["display"], "LG HDR 4K");
}

#[test]
fn cli_close_workspace_requires_explicit_target() {
    let server = start_server();
    let before = rpc(&server.socket, "workspace.list", json!({}));
    let before_count = before["workspaces"].as_array().unwrap().len();

    let error = cli_failure(&server.socket, &["close-workspace"]);
    assert!(
        error.contains("close-workspace requires an explicit workspace ref or UUID"),
        "unexpected error: {error}"
    );
    let after_error = rpc(&server.socket, "workspace.list", json!({}));
    assert_eq!(
        after_error["workspaces"].as_array().unwrap().len(),
        before_count
    );

    let by_ref = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "close-by-ref", "focus": false}),
    );
    let by_ref_id = by_ref["workspace_id"].as_str().unwrap().to_string();
    let by_ref_ref = by_ref["workspace_ref"].as_str().unwrap().to_string();
    cli(&server.socket, &["close-workspace", &by_ref_ref]);
    let after_ref = rpc(&server.socket, "workspace.list", json!({}));
    assert!(
        after_ref["workspaces"]
            .as_array()
            .unwrap()
            .iter()
            .all(|row| { row["workspace_id"].as_str() != Some(by_ref_id.as_str()) }),
        "workspace closed by ref should be gone: {after_ref}"
    );

    let by_uuid = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "close-by-uuid", "focus": false}),
    );
    let by_uuid_id = by_uuid["workspace_id"].as_str().unwrap().to_string();
    cli(&server.socket, &["close-workspace", &by_uuid_id]);
    let after_uuid = rpc(&server.socket, "workspace.list", json!({}));
    assert!(
        after_uuid["workspaces"]
            .as_array()
            .unwrap()
            .iter()
            .all(|row| { row["workspace_id"].as_str() != Some(by_uuid_id.as_str()) }),
        "workspace closed by UUID should be gone: {after_uuid}"
    );
}

#[test]
fn workspace_reorder_many_plans_and_applies_partial_order() {
    let server = start_server();
    let initial = rpc(&server.socket, "workspace.current", json!({}));
    let ws0 = initial["workspace_id"].as_str().unwrap().to_string();
    let ws1 = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Bulk A", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let ws2 = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Bulk B", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    let dry_run = rpc(
        &server.socket,
        "workspace.reorder_many",
        json!({"workspace_ids": [ws2.clone(), ws0.clone()], "dry_run": true}),
    );
    assert_eq!(dry_run["dry_run"], true);
    assert_eq!(dry_run["plan"].as_array().unwrap().len(), 2);
    assert_eq!(dry_run["events"].as_array().unwrap().len(), 0);
    let after_dry_run = rpc(&server.socket, "workspace.list", json!({}));
    let dry_order = after_dry_run["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(dry_order[..3], [ws0.clone(), ws1.clone(), ws2.clone()]);

    let applied = rpc(
        &server.socket,
        "workspace.reorder_many",
        json!({"order": format!("{ws2},{ws0}")}),
    );
    assert_eq!(applied["dry_run"], false);
    assert!(
        !applied["events"].as_array().unwrap().is_empty(),
        "applied reorder was {applied}"
    );
    let listed = rpc(&server.socket, "workspace.list", json!({}));
    let order = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(order[..3], [ws2.clone(), ws0.clone(), ws1.clone()]);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    assert!(methods
        .iter()
        .any(|method| method == "workspace.reorder_many"));
    assert_eq!(capabilities["features"]["workspace_reorder_many"], true);
}

#[test]
fn workspace_reorder_many_stays_inside_pinned_and_group_partitions() {
    let server = start_server();
    let ws0 = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let pinned = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Pinned", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let child_a = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Group Child A", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let child_b = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Group Child B", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let outside = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Outside", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": pinned, "action": "pin"}),
    );
    let created_group = rpc(
        &server.socket,
        "workspace.group.create",
        json!({
            "name": "Reorder Group",
            "child_workspace_ids": [child_a.clone(), child_b.clone()]
        }),
    );
    let anchor = created_group["group"]["anchor_workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    let before = rpc(&server.socket, "workspace.list", json!({}));
    let before_order = before["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(
        before_order,
        [
            pinned.clone(),
            ws0.clone(),
            anchor.clone(),
            child_a.clone(),
            child_b.clone(),
            outside.clone()
        ]
    );

    let requested = format!("{outside},{child_b},{child_a},{pinned}");
    let dry_run = rpc(
        &server.socket,
        "workspace.reorder_many",
        json!({"order": requested, "dry_run": true}),
    );
    assert_eq!(dry_run["dry_run"], true);
    assert_eq!(dry_run["events"].as_array().unwrap().len(), 0);
    let after_dry_run = rpc(&server.socket, "workspace.list", json!({}));
    let dry_order = after_dry_run["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(dry_order, before_order);

    let requested = format!("{outside},{child_b},{child_a},{pinned}");
    let applied = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "reorder-workspaces",
            "--order",
            &requested,
        ],
        &[],
    );
    assert_eq!(applied["dry_run"], false);
    assert_eq!(applied["plan"].as_array().unwrap().len(), 4);

    let listed = rpc(&server.socket, "workspace.list", json!({}));
    let order = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(
        order,
        [
            pinned.clone(),
            outside.clone(),
            anchor.clone(),
            child_b.clone(),
            child_a.clone(),
            ws0.clone()
        ]
    );
    let anchor_row = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == anchor)
        .expect("anchor row");
    assert_eq!(anchor_row["is_group_anchor"], true);
}

#[test]
fn workspace_group_move_targets_ungrouped_workspaces_without_splitting_group() {
    let server = start_server();
    let outside_a = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let outside_b = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Outside B", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let child = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Grouped Child", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let created = rpc(
        &server.socket,
        "workspace.group.create",
        json!({"name": "Movable", "child_workspace_ids": [child.clone()]}),
    );
    let group_id = created["group"]["group_id"].as_str().unwrap().to_string();
    let anchor = created["group"]["anchor_workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    rpc(
        &server.socket,
        "workspace.group.move",
        json!({"group_id": group_id, "before_workspace_id": outside_a}),
    );
    let listed = rpc(&server.socket, "workspace.list", json!({}));
    let order = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(
        order,
        [
            anchor.clone(),
            child.clone(),
            outside_a.clone(),
            outside_b.clone()
        ]
    );

    rpc(
        &server.socket,
        "workspace.group.move",
        json!({"group_id": group_id, "after_workspace_id": outside_b}),
    );
    let listed = rpc(&server.socket, "workspace.list", json!({}));
    let order = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(order, [outside_a, outside_b, anchor.clone(), child]);

    let error = rpc_response(
        &server.socket,
        "workspace.group.move",
        json!({"group_id": group_id, "before_workspace_id": anchor}),
    );
    assert_eq!(error["ok"], false);
    assert_eq!(error["error"]["code"], "invalid_params");
}

#[test]
fn workspace_action_updates_metadata_and_reorders() {
    let server = start_server();
    let window_id = rpc(&server.socket, "window.current", json!({}))["window_id"]
        .as_str()
        .unwrap()
        .to_string();
    let ws0 = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let ws1 = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Action One", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let ws2 = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Action Two", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    let renamed = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace-action",
            "--workspace",
            &ws1,
            "rename",
            "Infra Work",
        ],
        &[],
    );
    assert_eq!(renamed["title"], "Infra Work");
    assert_eq!(renamed["workspace_id"], ws1);

    let described = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace-action",
            "--workspace",
            &ws1,
            "set-description",
            "Ship checklist",
        ],
        &[],
    );
    assert_eq!(described["description"], "Ship checklist");

    let colored = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace-action",
            "--workspace",
            &ws1,
            "set-color",
            "blue",
        ],
        &[],
    );
    assert_eq!(colored["custom_color"], "#3498DB");

    let pinned = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws1, "action": "pin"}),
    );
    assert_eq!(pinned["pinned"], true);
    let unread = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws1, "action": "mark-unread"}),
    );
    assert_eq!(unread["unread"], true);

    let listed = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": window_id.clone()}),
    );
    let row = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == ws1)
        .expect("workspace action row");
    assert_eq!(row["title"], "Infra Work");
    assert_eq!(row["description"], "Ship checklist");
    assert_eq!(row["custom_color"], "#3498DB");
    assert_eq!(row["pinned"], true);
    assert_eq!(row["unread"], true);
    assert_eq!(row["unread_count"], 1);

    let read = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace-action",
            "--workspace",
            &ws1,
            "--action",
            "mark-read",
        ],
        &[],
    );
    assert_eq!(read["unread"], false);
    let unpinned = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws1, "action": "unpin"}),
    );
    assert_eq!(unpinned["pinned"], false);
    let clear_description = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws1, "action": "clear-description"}),
    );
    assert!(clear_description["description"].is_null());
    let clear_color = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws1, "action": "clear-color"}),
    );
    assert!(clear_color["custom_color"].is_null());

    let moved_up = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws2, "action": "move-up"}),
    );
    assert_eq!(moved_up["index"], 1);
    let moved_down = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws2, "action": "move-down"}),
    );
    assert_eq!(moved_down["index"], 2);
    let moved_top = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace-action",
            "--window",
            &window_id,
            "--workspace",
            "workspace:3",
            "--action",
            "move-top",
        ],
        &[],
    );
    assert_eq!(moved_top["workspace_id"], ws2);
    assert_eq!(moved_top["index"], 0);

    let final_list = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": window_id}),
    );
    let order = final_list["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(order[..3], [ws2.clone(), ws1.clone(), ws0.clone()]);

    let clear_name = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws1, "action": "clear-name"}),
    );
    assert_eq!(clear_name["title"], "Workspace");
}

#[test]
fn workspace_action_close_neighbors_skips_pinned_and_preserves_anchor() {
    let server = start_server();
    let window_id = rpc(&server.socket, "window.current", json!({}))["window_id"]
        .as_str()
        .unwrap()
        .to_string();
    let ws0 = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let ws1 = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Close pinned left", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let anchor = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Close anchor", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let ws3 = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Close pinned right", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let ws4 = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Close tail", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws1, "action": "pin"}),
    );
    rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws3, "action": "pin"}),
    );

    let close_above = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": anchor, "action": "close-above"}),
    );
    assert_eq!(close_above["closed"], 1);
    assert_eq!(close_above["skipped_pinned"], 2);
    assert_eq!(close_above["closed_workspace_ids"], json!([ws0.clone()]));
    let current = rpc(&server.socket, "workspace.current", json!({}));
    assert_eq!(current["workspace_id"], anchor);

    let close_below = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace-action",
            "--workspace",
            &anchor,
            "--action",
            "close-below",
        ],
        &[],
    );
    assert_eq!(close_below["closed"], 1);
    assert_eq!(close_below["skipped_pinned"], 0);
    assert_eq!(close_below["closed_workspace_ids"], json!([ws4.clone()]));

    let listed = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": window_id.clone()}),
    );
    let ids = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(ids, [ws1.clone(), ws3.clone(), anchor.clone()]);

    rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws1, "action": "unpin"}),
    );
    let close_others = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": anchor, "action": "close-others"}),
    );
    assert_eq!(close_others["closed"], 1);
    assert_eq!(close_others["skipped_pinned"], 1);
    assert_eq!(close_others["closed_workspace_ids"], json!([ws1.clone()]));

    rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": ws3, "action": "unpin"}),
    );
    let close_last_other = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": anchor, "action": "close-others"}),
    );
    assert_eq!(close_last_other["closed"], 1);
    assert_eq!(close_last_other["skipped_pinned"], 0);
    assert_eq!(
        close_last_other["closed_workspace_ids"],
        json!([ws3.clone()])
    );

    let noop = rpc(
        &server.socket,
        "workspace.action",
        json!({"workspace_id": anchor, "action": "close-others"}),
    );
    assert_eq!(noop["closed"], 0);
    assert_eq!(noop["skipped_pinned"], 0);
    let final_list = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": window_id}),
    );
    let final_ids = final_list["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(final_ids, [anchor.clone()]);
}

#[test]
fn workspace_prompt_submit_records_preview_and_redacts_event() {
    let server = start_server();
    let current = rpc(&server.socket, "workspace.current", json!({}));
    let workspace_id = current["workspace_id"].as_str().unwrap().to_string();
    let prompt = "  ship\nsecret\tprompt  ";

    let submitted = rpc(
        &server.socket,
        "workspace.prompt_submit",
        json!({"workspace_id": workspace_id, "message": prompt}),
    );
    assert_eq!(submitted["workspace_id"], workspace_id);
    assert_eq!(submitted["i_message_mode_enabled"], false);
    assert_eq!(submitted["message_recorded"], true);
    assert_eq!(submitted["message_preview"], "ship secret prompt");
    assert_eq!(submitted["reordered"], false);
    assert_eq!(submitted["index"], 0);

    let listed = rpc(&server.socket, "workspace.list", json!({}));
    let row = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == workspace_id)
        .expect("workspace row");
    assert_eq!(row["latest_submitted_message"], "ship secret prompt");
    assert!(row["latest_submitted_at"].as_u64().is_some());

    let invalid = rpc_response(
        &server.socket,
        "workspace.prompt_submit",
        json!({"workspace_id": workspace_id, "message": 42}),
    );
    assert_eq!(invalid["ok"], false, "response was {invalid}");
    assert_eq!(invalid["error"]["code"], "invalid_params");

    let output = cli(
        &server.socket,
        &[
            "events",
            "--after",
            "0",
            "--name",
            "workspace.prompt.submitted",
            "--limit",
            "1",
            "--no-ack",
            "--no-heartbeat",
        ],
    );
    let line = output
        .lines()
        .find(|line| !line.trim().is_empty())
        .expect("prompt event");
    let event: Value = serde_json::from_str(line).expect("event json");
    assert_eq!(event["name"], "workspace.prompt.submitted");
    assert_eq!(event["category"], "workspace");
    assert_eq!(event["workspace_id"], workspace_id);
    assert_eq!(event["payload"]["method"], "workspace.prompt_submit");
    assert_eq!(event["payload"]["params"]["message"], Value::Null);
    assert_eq!(
        event["payload"]["params"]["message_length"],
        prompt.chars().count()
    );
    assert_eq!(
        event["payload"]["params"]["redacted_fields"],
        json!(["message"])
    );
    assert_eq!(
        event["payload"]["result"]["message_preview"],
        "ship secret prompt"
    );

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    assert!(methods
        .iter()
        .any(|method| method == "workspace.prompt_submit"));
    assert_eq!(capabilities["features"]["workspace_prompt_submit"], true);
}

#[test]
fn workspace_set_auto_title_preserves_user_owned_titles() {
    let server = start_server();
    let current = rpc(&server.socket, "workspace.current", json!({}));
    let workspace_id = current["workspace_id"].as_str().unwrap().to_string();
    let surface = rpc(&server.socket, "surface.current", json!({}));
    let surface_id = surface["surface_id"].as_str().unwrap().to_string();

    let probe = rpc(
        &server.socket,
        "workspace.set_auto_title",
        json!({"probe": true, "workspace_id": workspace_id}),
    );
    assert_eq!(probe["enabled"], true);
    assert_eq!(probe["summarizer_agent"], Value::Null);
    assert_eq!(probe["workspace_user_owned"], false);

    let applied = rpc(
        &server.socket,
        "workspace.set_auto_title",
        json!({
            "workspace_id": workspace_id,
            "panel_id": surface_id,
            "title": "Auto Title"
        }),
    );
    assert_eq!(applied["workspace_applied"], true);
    assert_eq!(applied["panel_applied"], true);
    assert_eq!(applied["title"], "Auto Title");

    let listed = rpc(&server.socket, "workspace.list", json!({}));
    let row = listed["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == workspace_id)
        .expect("workspace row");
    assert_eq!(row["title"], "Auto Title");
    assert_eq!(row["auto_title"], "Auto Title");
    assert_eq!(row["custom_title"], false);

    let surfaces = rpc(&server.socket, "surface.list", json!({}));
    let surface_row = surfaces["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["surface_id"] == surface_id)
        .expect("surface row");
    assert_eq!(surface_row["title"], "Auto Title");
    assert_eq!(surface_row["auto_title"], "Auto Title");

    rpc(
        &server.socket,
        "workspace.rename",
        json!({"workspace_id": workspace_id, "title": "Manual Title"}),
    );
    let skipped = rpc(
        &server.socket,
        "workspace.set_auto_title",
        json!({"workspace_id": workspace_id, "title": "Ignored Auto Title"}),
    );
    assert_eq!(skipped["workspace_applied"], false);
    let after_skip = rpc(&server.socket, "workspace.list", json!({}));
    let row = after_skip["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == workspace_id)
        .expect("workspace row");
    assert_eq!(row["title"], "Manual Title");
    assert_eq!(row["auto_title"], Value::Null);
    assert_eq!(row["custom_title"], true);

    let user_owned_probe = rpc(
        &server.socket,
        "workspace.set_auto_title",
        json!({"probe": true, "workspace_id": workspace_id}),
    );
    assert_eq!(user_owned_probe["workspace_user_owned"], true);

    let failure = rpc(
        &server.socket,
        "workspace.set_auto_title",
        json!({"failure": "rate_limited", "agent": "codex"}),
    );
    assert_eq!(failure["recorded"], true);
    assert_eq!(failure["enabled"], true);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    assert!(methods
        .iter()
        .any(|method| method == "workspace.set_auto_title"));
    assert_eq!(capabilities["features"]["workspace_auto_title"], true);
}

#[test]
fn extension_sidebar_snapshot_exposes_workspace_feed_contract() {
    fn git(repo: &std::path::Path, args: &[&str]) {
        let status = Command::new("git")
            .args(args)
            .current_dir(repo)
            .status()
            .expect("run git");
        assert!(status.success(), "git {args:?} failed with {status}");
    }

    let server = start_server();
    let repo = tempfile::tempdir().expect("git repo");
    git(repo.path(), &["init", "-q"]);
    git(repo.path(), &["config", "user.email", "cmux@example.test"]);
    git(repo.path(), &["config", "user.name", "cmux tests"]);
    std::fs::write(repo.path().join("README.md"), "initial\n").expect("write readme");
    git(repo.path(), &["add", "README.md"]);
    git(repo.path(), &["commit", "-qm", "initial"]);
    git(repo.path(), &["checkout", "-qb", "sidebar-test"]);
    std::fs::write(repo.path().join("README.md"), "dirty\n").expect("dirty readme");
    let nested = repo.path().join("nested");
    std::fs::create_dir_all(&nested).expect("nested cwd");
    let cwd = nested.display().to_string();

    rpc(
        &server.socket,
        "app.focus_override.set",
        json!({"state": "inactive"}),
    );
    let workspace = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Snapshot Workspace", "cwd": cwd, "focus": true}),
    );
    let workspace_id = workspace["workspace_id"].as_str().unwrap().to_string();
    let workspace_ref = workspace["workspace_ref"].as_str().unwrap().to_string();
    rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Background Snapshot", "focus": false}),
    );
    rpc(
        &server.socket,
        "workspace.prompt_submit",
        json!({"workspace_id": workspace_id, "message": "snapshot prompt"}),
    );
    rpc(
        &server.socket,
        "notification.create",
        json!({
            "workspace_id": workspace_id,
            "title": "Snapshot title",
            "body": "Snapshot body"
        }),
    );

    let snapshot = rpc(&server.socket, "extension.sidebar.snapshot", json!({}));
    assert_eq!(snapshot["seq"], snapshot["sequence"]);
    assert!(snapshot["sequence"].as_i64().unwrap() >= 2);
    assert_eq!(snapshot["selected_workspace_id"], workspace_id);
    assert_eq!(snapshot["selected_workspace_ref"], workspace_ref);
    assert!(
        snapshot["workspaces"].as_array().unwrap().len() >= 3,
        "snapshot was {snapshot}"
    );
    let row = snapshot["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == workspace_id)
        .expect("workspace row");
    assert_eq!(row["ref"], workspace_ref);
    assert_eq!(row["title"], "Snapshot Workspace");
    assert_eq!(row["selected"], true);
    assert_eq!(row["pinned"], false);
    assert_eq!(row["root_path"], cwd);
    assert_eq!(row["current_directory"], cwd);
    assert_eq!(row["project_root_path"], repo.path().display().to_string());
    assert_eq!(row["branch_summary"], "sidebar-test");
    assert_eq!(row["git_branches"][0]["branch"], "sidebar-test");
    assert_eq!(row["git_branches"][0]["dirty"], true);
    assert_eq!(row["remote_connection_state"], "disconnected");
    assert_eq!(row["remote"]["enabled"], false);
    assert_eq!(row["unread_count"], 1);
    assert_eq!(row["latest_notification_text"], "Snapshot body");
    assert_eq!(row["latest_conversation_message"], "snapshot prompt");
    assert_eq!(row["latest_submitted_message"], "snapshot prompt");
    assert!(row["latest_submitted_at"]
        .as_str()
        .is_some_and(|value| value.contains('T') && value.ends_with('Z')));
    assert_eq!(row["panel_directories"], json!([cwd]));
    assert_eq!(row["pull_request_urls"], json!([]));

    let routed = rpc(
        &server.socket,
        "extension.sidebar.snapshot",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(routed["window_id"], snapshot["window_id"]);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "extension.sidebar.snapshot"));
    assert_eq!(capabilities["features"]["extension_sidebar_snapshot"], true);
}

#[test]
fn custom_sidebar_runtime_validates_selects_renders_live_swift_and_keeps_last_good() {
    let root = tempfile::tempdir().expect("custom sidebar root");
    let sidebars = root.path().join("sidebars");
    std::fs::create_dir_all(&sidebars).expect("create custom sidebar directory");
    let selection = root.path().join("custom-sidebar-selection.json");
    let status = sidebars.join("status.json");
    std::fs::write(
        &status,
        r##"{
          "version": 1,
          "root": {
            "type": "vstack",
            "spacing": 8,
            "children": [
              {"type": "text", "text": "Linux status", "font": "headline", "color": "#ff8800"},
              {"type": "button", "title": "Next workspace", "action": {"type": "workspace.next"}}
            ]
          }
        }"##,
    )
    .expect("write valid custom sidebar");
    std::fs::write(
        sidebars.join("broken.json"),
        r#"{"version":1,"root":{"type":"unknown"}}"#,
    )
    .expect("write broken custom sidebar");
    std::fs::write(
        sidebars.join("finder.swift"),
        r#"
VStack(spacing: 4) {
  Text("Swift workspaces: \(workspaceCount)")
  ForEach(workspaces.prefix(1)) { w in
    Button(action: { cmux("workspace.select", workspace_id: w.id) }) {
      Text(w.title)
    }
  }
}
"#,
    )
    .expect("write Swift custom sidebar");
    std::fs::write(
        sidebars.join("finder.json"),
        r#"{"version":1,"root":{"type":"text","text":"JSON loses"}}"#,
    )
    .expect("write shadowed JSON custom sidebar");

    let sidebars_path = sidebars.display().to_string();
    let selection_path = selection.display().to_string();
    let server = start_server_with_env(&[
        ("CMUX_CUSTOM_SIDEBARS_DIR", sidebars_path.as_str()),
        (
            "CMUX_CUSTOM_SIDEBAR_SELECTION_PATH",
            selection_path.as_str(),
        ),
    ]);

    let validation = rpc(&server.socket, "sidebar.custom.validate", json!({}));
    assert_eq!(validation["directory"], sidebars_path);
    assert_eq!(validation["valid_count"], 2);
    assert_eq!(validation["error_count"], 1);
    let entries = validation["sidebars"].as_array().unwrap();
    assert_eq!(
        entries
            .iter()
            .map(|entry| entry["name"].as_str().unwrap())
            .collect::<Vec<_>>(),
        vec!["broken", "finder", "status"]
    );
    let finder = entries
        .iter()
        .find(|entry| entry["name"] == "finder")
        .expect("finder validation");
    assert_eq!(finder["kind"], "swift");
    assert_eq!(finder["ok"], true);
    assert_eq!(finder["error"], Value::Null);

    let cli_validation = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("--socket")
        .arg(&server.socket)
        .arg("sidebar")
        .arg("validate")
        .arg("--json")
        .output()
        .expect("run custom sidebar CLI validation");
    assert!(
        cli_validation.status.success(),
        "custom sidebar CLI validation failed: stdout={} stderr={}",
        String::from_utf8_lossy(&cli_validation.stdout),
        String::from_utf8_lossy(&cli_validation.stderr)
    );
    let cli_validation: Value =
        serde_json::from_slice(&cli_validation.stdout).expect("custom sidebar CLI JSON");
    assert_eq!(cli_validation["valid_count"], 2);
    assert_eq!(cli_validation["error_count"], 1);

    let missing = rpc(
        &server.socket,
        "sidebar.custom.validate",
        json!({"name": "missing"}),
    );
    assert_eq!(missing["error_count"], 1);
    assert_eq!(missing["sidebars"][0]["error"], "Sidebar file is missing.");

    let selected = rpc(
        &server.socket,
        "sidebar.custom.select",
        json!({"name": "status"}),
    );
    assert_eq!(selected["error_count"], 0);
    assert_eq!(selected["selected_name"], "status");
    assert_eq!(
        selected["selected_provider_id"],
        "cmux.sidebar.custom.status"
    );
    let selection_mode = std::fs::metadata(&selection)
        .expect("selection metadata")
        .permissions()
        .mode()
        & 0o777;
    assert_eq!(selection_mode, 0o600);

    let snapshot = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(
        snapshot["custom_sidebar"]["selected_provider_id"],
        "cmux.sidebar.custom.status"
    );
    assert_eq!(snapshot["custom_sidebar"]["state"], "ready");
    assert_eq!(
        snapshot["custom_sidebar"]["document"]["root"]["children"][0]["text"],
        "Linux status"
    );
    assert_eq!(
        snapshot["custom_sidebar"]["document"]["root"]["children"][1]["action"]["type"],
        "workspace.next"
    );

    std::fs::write(&status, r#"{"version":1,"root":{"type":"text""#)
        .expect("break selected custom sidebar");
    let stale = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(stale["custom_sidebar"]["state"], "stale");
    assert_eq!(stale["custom_sidebar"]["using_last_good"], true);
    assert_eq!(
        stale["custom_sidebar"]["document"]["root"]["children"][0]["text"],
        "Linux status"
    );
    assert!(stale["custom_sidebar"]["error"]
        .as_str()
        .unwrap()
        .contains("Invalid sidebar JSON"));

    let reload = rpc(
        &server.socket,
        "sidebar.custom.reload",
        json!({"name": "status"}),
    );
    assert_eq!(reload["error_count"], 1);
    assert_eq!(reload["reloaded_count"], 0);
    assert!(reload["reload_generation"].as_u64().unwrap() >= 2);

    let swift_selected = rpc(
        &server.socket,
        "sidebar.custom.select",
        json!({"name": "finder"}),
    );
    assert_eq!(swift_selected["error_count"], 0);
    assert_eq!(swift_selected["selected_name"], "finder");
    let swift_snapshot = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(swift_snapshot["custom_sidebar"]["kind"], "swift");
    assert_eq!(swift_snapshot["custom_sidebar"]["state"], "ready");
    assert_eq!(
        swift_snapshot["custom_sidebar"]["document"]["root"]["children"][0]["text"],
        "Swift workspaces: 1"
    );
    let live_workspace_id = swift_snapshot["workspaces"][0]["workspace_id"]
        .as_str()
        .unwrap();
    assert_eq!(
        swift_snapshot["custom_sidebar"]["document"]["root"]["children"][1]["action"]["commands"]
            [0]["method"],
        "workspace.select"
    );
    assert_eq!(
        swift_snapshot["custom_sidebar"]["document"]["root"]["children"][1]["action"]["commands"]
            [0]["params"]["workspace_id"],
        live_workspace_id
    );
    assert_ne!(
        swift_snapshot["custom_sidebar"]["document"]["root"]["children"][0]["text"],
        "JSON loses"
    );

    let restored = rpc(
        &server.socket,
        "sidebar.custom.select",
        json!({"provider_id": "cmux.sidebar.workspaces"}),
    );
    assert_eq!(restored["selected_provider_id"], "cmux.sidebar.workspaces");
    let default_snapshot = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(default_snapshot["custom_sidebar"]["state"], "default");
    assert_eq!(default_snapshot["custom_sidebar"]["document"], Value::Null);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    for method in [
        "sidebar.custom.action",
        "sidebar.custom.event.submit",
        "sidebar.custom.reload",
        "sidebar.custom.select",
        "sidebar.custom.state.clear",
        "sidebar.custom.state.set",
        "sidebar.custom.validate",
    ] {
        assert!(capabilities["methods"]
            .as_array()
            .unwrap()
            .iter()
            .any(|candidate| candidate == method));
    }
    assert_eq!(capabilities["features"]["custom_sidebars_json"], true);
    assert_eq!(capabilities["features"]["custom_sidebars_state"], true);
    assert_eq!(capabilities["features"]["custom_sidebars_events"], true);
    assert_eq!(capabilities["features"]["custom_sidebars_swift"], true);
}

#[test]
fn custom_sidebar_remote_worker_is_configurable_and_failure_keeps_last_good() {
    let root = tempfile::tempdir().expect("custom sidebar worker root");
    let sidebars = root.path().join("sidebars");
    let xdg_config = root.path().join("config");
    let selection = root.path().join("selection.json");
    let fail_marker = root.path().join("fail-worker");
    let worker = root.path().join("sidebar-worker");
    std::fs::create_dir_all(&sidebars).expect("create sidebars");
    std::fs::write(
        sidebars.join("remote.swift"),
        r#"
@State private var count = 0
@State private var observed = 0
VStack {
  Text("Remote \(workspaceCount) count \(count)")
  Button("Increment") { count += 1 }
  Text("Observed \(observed)")
}
.onChange(of: count) { _, newValue in
  observed = newValue
}
"#,
    )
    .expect("write remote sidebar");
    std::fs::write(
        &worker,
        format!(
            "#!/bin/sh\nif [ -f '{}' ]; then exec sleep 5; fi\nexec '{}' \"$@\"\n",
            fail_marker.display(),
            env!("CARGO_BIN_EXE_cmux")
        ),
    )
    .expect("write worker wrapper");
    let mut permissions = std::fs::metadata(&worker)
        .expect("worker metadata")
        .permissions();
    permissions.set_mode(0o755);
    std::fs::set_permissions(&worker, permissions).expect("chmod worker");

    let sidebars = sidebars.display().to_string();
    let selection = selection.display().to_string();
    let xdg_config = xdg_config.display().to_string();
    let worker = worker.display().to_string();
    let server = start_server_with_env(&[
        ("CMUX_CUSTOM_SIDEBARS_DIR", sidebars.as_str()),
        ("CMUX_CUSTOM_SIDEBAR_SELECTION_PATH", selection.as_str()),
        ("CMUX_CUSTOM_SIDEBAR_WORKER", worker.as_str()),
        ("CMUX_CUSTOM_SIDEBAR_WORKER_TIMEOUT_MS", "100"),
        ("XDG_CONFIG_HOME", xdg_config.as_str()),
    ]);

    let selected = rpc(
        &server.socket,
        "sidebar.custom.select",
        json!({"name": "remote"}),
    );
    assert_eq!(selected["error_count"], 0);
    let in_process = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(in_process["custom_sidebar"]["renderer"], "inProcess");
    assert_eq!(
        in_process["custom_sidebar"]["document"]["root"]["children"][0]["text"],
        "Remote 1 count 0"
    );

    let changed = rpc(
        &server.socket,
        "settings.custom_sidebars.set_renderer",
        json!({"renderer": "remote"}),
    );
    assert_eq!(changed["renderer"], "remote");
    assert_eq!(changed["ok"], true);
    let status = rpc(&server.socket, "settings.custom_sidebars.status", json!({}));
    assert_eq!(status["renderer"], "remote");
    assert_eq!(
        std::fs::read_to_string(root.path().join("config/cmux/cmux.json"))
            .expect("read renderer config")
            .contains("\"renderer\": \"remote\""),
        true
    );

    let remote = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(remote["custom_sidebar"]["renderer"], "remote");
    assert_eq!(remote["custom_sidebar"]["state"], "ready");
    assert_eq!(
        remote["custom_sidebar"]["document"]["root"]["children"][0]["text"],
        "Remote 1 count 0"
    );
    let increment = remote["custom_sidebar"]["document"]["root"]["children"][1]["action"]
        ["commands"][0]
        .clone();
    let mutated = rpc(
        &server.socket,
        "sidebar.custom.action",
        json!({
            "provider_id": "cmux.sidebar.custom.remote",
            "action": increment
        }),
    );
    assert_eq!(mutated["value"], 1);
    let rerendered = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(
        rerendered["custom_sidebar"]["document"]["root"]["children"][0]["text"],
        "Remote 1 count 1"
    );
    assert_eq!(
        rerendered["custom_sidebar"]["document"]["root"]["children"][2]["text"],
        "Observed 1"
    );

    std::fs::write(&fail_marker, b"fail").expect("enable worker failure");
    let stale = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(stale["custom_sidebar"]["renderer"], "remote");
    assert_eq!(stale["custom_sidebar"]["state"], "stale");
    assert_eq!(stale["custom_sidebar"]["using_last_good"], true);
    assert_eq!(
        stale["custom_sidebar"]["document"]["root"]["children"][0]["text"],
        "Remote 1 count 1"
    );
    assert_eq!(
        stale["custom_sidebar"]["document"]["root"]["children"][2]["text"],
        "Observed 1"
    );
    assert!(stale["custom_sidebar"]["error"]
        .as_str()
        .is_some_and(|error| error.contains("timed out after 100 milliseconds")));

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    for method in [
        "settings.custom_sidebars.set_renderer",
        "settings.custom_sidebars.status",
    ] {
        assert!(capabilities["methods"]
            .as_array()
            .unwrap()
            .iter()
            .any(|candidate| candidate == method));
    }
}

#[test]
fn custom_sidebar_state_mutates_isolates_and_persists_across_restart() {
    let root = tempfile::tempdir().expect("custom sidebar state root");
    let sidebars = root.path().join("sidebars");
    let selection = root.path().join("selection.json");
    let state_store = root.path().join("state.json");
    std::fs::create_dir_all(&sidebars).expect("create sidebars");
    let source = r#"
@State private var count = 0
@State private var enabled = true
@State private var name = "cmux"
@State private var volume = 0.5
@State private var mode = "balanced"
@State private var retries = 2
@State private var transition = ""
@State private var changeCount = 0
@State private var submitted = ""
VStack {
  Text("Count \(count)")
  Button("Increment") { count += 1 }
  Toggle("Enabled", isOn: $enabled)
  TextField("Name", text: $name)
    .onChange(of: name) { oldValue, newValue in
      transition = "\(oldValue)->\(newValue)"
      changeCount += 1
    }
    .onSubmit {
      submitted = name
      cmux("workspace.rename", workspace_id: selectedId, title: name)
    }
  Slider(value: $volume, in: 0.0...1.0, step: 0.1)
  Picker("Mode", selection: $mode) {
    Text("Fast").tag("fast")
    Text("Balanced").tag("balanced")
  }
  Stepper("Retries \(retries)", value: $retries, in: 0...10, step: 2)
  Text("Events \(transition) \(changeCount) \(submitted)")
}
"#;
    std::fs::write(sidebars.join("alpha.swift"), source).expect("write alpha sidebar");
    std::fs::write(sidebars.join("beta.swift"), source).expect("write beta sidebar");
    let sidebars_path = sidebars.display().to_string();
    let selection_path = selection.display().to_string();
    let state_path = state_store.display().to_string();
    let envs = [
        ("CMUX_CUSTOM_SIDEBARS_DIR", sidebars_path.as_str()),
        (
            "CMUX_CUSTOM_SIDEBAR_SELECTION_PATH",
            selection_path.as_str(),
        ),
        ("CMUX_CUSTOM_SIDEBAR_STATE_PATH", state_path.as_str()),
    ];

    {
        let server = start_server_with_env(&envs);
        let selected = rpc(
            &server.socket,
            "sidebar.custom.select",
            json!({"name": "alpha"}),
        );
        assert_eq!(selected["selected_name"], "alpha");
        let initial = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        let alpha = &initial["custom_sidebar"];
        assert_eq!(alpha["document"]["root"]["children"][0]["text"], "Count 0");
        assert_eq!(
            alpha["document"]["root"]["children"][2]["binding"],
            json!({"key": "enabled", "value": true})
        );
        assert_eq!(
            alpha["document"]["root"]["children"][3]["binding"],
            json!({"key": "name", "value": "cmux"})
        );
        assert_eq!(
            alpha["document"]["root"]["children"][4]["binding"],
            json!({"key": "volume", "value": 0.5})
        );
        assert_eq!(
            alpha["document"]["root"]["children"][5]["options"],
            json!([
                {"label": "Fast", "value": "fast"},
                {"label": "Balanced", "value": "balanced"}
            ])
        );
        assert_eq!(
            alpha["document"]["root"]["children"][6]["binding"],
            json!({"key": "retries", "value": 2})
        );

        let increment = alpha["document"]["root"]["children"][1]["action"]["commands"][0].clone();
        let mutated = rpc(
            &server.socket,
            "sidebar.custom.action",
            json!({
                "provider_id": "cmux.sidebar.custom.alpha",
                "action": increment
            }),
        );
        assert_eq!(mutated["changed"], true);
        assert_eq!(mutated["value"], 1);
        let set_toggle = rpc(
            &server.socket,
            "sidebar.custom.state.set",
            json!({
                "provider_id": "cmux.sidebar.custom.alpha",
                "key": "enabled",
                "value": false
            }),
        );
        assert_eq!(set_toggle["changed"], true);
        let set_name = rpc(
            &server.socket,
            "sidebar.custom.state.set",
            json!({
                "provider_id": "cmux.sidebar.custom.alpha",
                "key": "name",
                "value": "linux"
            }),
        );
        assert_eq!(set_name["changed"], true);
        let set_volume = rpc(
            &server.socket,
            "sidebar.custom.state.set",
            json!({
                "provider_id": "cmux.sidebar.custom.alpha",
                "key": "volume",
                "value": 0.8
            }),
        );
        assert_eq!(set_volume["changed"], true);
        let set_mode = rpc(
            &server.socket,
            "sidebar.custom.state.set",
            json!({
                "provider_id": "cmux.sidebar.custom.alpha",
                "key": "mode",
                "value": "fast"
            }),
        );
        assert_eq!(set_mode["changed"], true);
        let set_retries = rpc(
            &server.socket,
            "sidebar.custom.state.set",
            json!({
                "provider_id": "cmux.sidebar.custom.alpha",
                "key": "retries",
                "value": 4
            }),
        );
        assert_eq!(set_retries["changed"], true);
        let updated = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][0]["text"],
            "Count 1"
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][2]["binding"]["value"],
            false
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][3]["binding"]["value"],
            "linux"
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][4]["binding"]["value"],
            0.8
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][5]["binding"]["value"],
            "fast"
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][6]["binding"]["value"],
            4
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][7]["text"],
            "Events cmux->linux 1 "
        );
        let submit_event_id = updated["custom_sidebar"]["document"]["root"]["children"][3]
            ["onSubmit"][0]["id"]
            .as_str()
            .expect("submit event id")
            .to_string();
        let submitted = rpc(
            &server.socket,
            "sidebar.custom.event.submit",
            json!({
                "provider_id": "cmux.sidebar.custom.alpha",
                "event_id": submit_event_id,
                "key": "name",
                "value": "linux"
            }),
        );
        assert_eq!(submitted["accepted"], true);
        let after_submit = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        assert_eq!(
            after_submit["custom_sidebar"]["document"]["root"]["children"][7]["text"],
            "Events cmux->linux 1 linux"
        );
        let renamed = rpc(&server.socket, "workspace.list", json!({}));
        assert_eq!(renamed["workspaces"][0]["title"], "linux");

        rpc(
            &server.socket,
            "sidebar.custom.select",
            json!({"name": "beta"}),
        );
        let beta = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        assert_eq!(
            beta["custom_sidebar"]["document"]["root"]["children"][0]["text"],
            "Count 0"
        );
        assert_eq!(
            beta["custom_sidebar"]["document"]["root"]["children"][2]["binding"]["value"],
            true
        );
        assert_eq!(
            beta["custom_sidebar"]["document"]["root"]["children"][4]["binding"]["value"],
            0.5
        );
        assert_eq!(
            beta["custom_sidebar"]["document"]["root"]["children"][5]["binding"]["value"],
            "balanced"
        );
        assert_eq!(
            beta["custom_sidebar"]["document"]["root"]["children"][6]["binding"]["value"],
            2
        );
        rpc(
            &server.socket,
            "sidebar.custom.select",
            json!({"name": "alpha"}),
        );
    }

    assert_eq!(
        std::fs::metadata(&state_store)
            .expect("state store metadata")
            .permissions()
            .mode()
            & 0o777,
        0o600
    );

    {
        let server = start_server_with_env(&envs);
        let restored = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        assert_eq!(
            restored["custom_sidebar"]["selected_provider_id"],
            "cmux.sidebar.custom.alpha"
        );
        assert_eq!(
            restored["custom_sidebar"]["document"]["root"]["children"][0]["text"],
            "Count 1"
        );
        assert_eq!(
            restored["custom_sidebar"]["document"]["root"]["children"][2]["binding"]["value"],
            false
        );
        assert_eq!(
            restored["custom_sidebar"]["document"]["root"]["children"][3]["binding"]["value"],
            "linux"
        );
        assert_eq!(
            restored["custom_sidebar"]["document"]["root"]["children"][4]["binding"]["value"],
            0.8
        );
        assert_eq!(
            restored["custom_sidebar"]["document"]["root"]["children"][5]["binding"]["value"],
            "fast"
        );
        assert_eq!(
            restored["custom_sidebar"]["document"]["root"]["children"][6]["binding"]["value"],
            4
        );
        assert_eq!(
            restored["custom_sidebar"]["document"]["root"]["children"][7]["text"],
            "Events cmux->linux 1 linux"
        );
        let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
        assert_eq!(capabilities["features"]["custom_sidebars_state"], true);
        for method in [
            "sidebar.custom.event.submit",
            "sidebar.custom.state.clear",
            "sidebar.custom.state.set",
        ] {
            assert!(capabilities["methods"]
                .as_array()
                .unwrap()
                .iter()
                .any(|candidate| candidate == method));
        }

        let cleared = Command::new(env!("CARGO_BIN_EXE_cmux"))
            .arg("--socket")
            .arg(&server.socket)
            .arg("--json")
            .args(["sidebar", "clear-state", "alpha"])
            .output()
            .expect("clear custom sidebar state");
        assert!(
            cleared.status.success(),
            "clear state failed: stdout={} stderr={}",
            String::from_utf8_lossy(&cleared.stdout),
            String::from_utf8_lossy(&cleared.stderr)
        );
        let cleared: Value = serde_json::from_slice(&cleared.stdout).expect("clear state response");
        assert_eq!(cleared["changed"], true);
        let reset = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        assert_eq!(
            reset["custom_sidebar"]["document"]["root"]["children"][0]["text"],
            "Count 0"
        );
    }
}

#[test]
fn declarative_json_sidebar_controls_seed_writable_provider_state() {
    let root = tempfile::tempdir().expect("JSON sidebar controls root");
    let sidebars = root.path().join("sidebars");
    let selection = root.path().join("selection.json");
    let state_store = root.path().join("state.json");
    std::fs::create_dir_all(&sidebars).expect("create sidebars");
    std::fs::write(
        sidebars.join("controls.json"),
        r#"{
            "version": 1,
            "root": {
                "type": "vstack",
                "children": [
                    {
                        "type": "slider",
                        "minimum": 0,
                        "maximum": 1,
                        "step": 0.1,
                        "binding": {"key": "volume", "value": 0.5}
                    },
                    {
                        "type": "picker",
                        "title": "Mode",
                        "binding": {"key": "mode", "value": "balanced"},
                        "options": [
                            {"label": "Fast", "value": "fast"},
                            {"label": "Balanced", "value": "balanced"}
                        ]
                    }
                ]
            }
        }"#,
    )
    .expect("write JSON controls");
    let sidebars_path = sidebars.display().to_string();
    let selection_path = selection.display().to_string();
    let state_path = state_store.display().to_string();
    let server = start_server_with_env(&[
        ("CMUX_CUSTOM_SIDEBARS_DIR", sidebars_path.as_str()),
        (
            "CMUX_CUSTOM_SIDEBAR_SELECTION_PATH",
            selection_path.as_str(),
        ),
        ("CMUX_CUSTOM_SIDEBAR_STATE_PATH", state_path.as_str()),
    ]);

    rpc(
        &server.socket,
        "sidebar.custom.select",
        json!({"name": "controls"}),
    );
    let initial = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(
        initial["custom_sidebar"]["document"]["root"]["children"][0]["binding"]["value"],
        0.5
    );
    assert_eq!(
        initial["custom_sidebar"]["document"]["root"]["children"][1]["binding"]["value"],
        "balanced"
    );

    let volume = rpc(
        &server.socket,
        "sidebar.custom.state.set",
        json!({
            "provider_id": "cmux.sidebar.custom.controls",
            "key": "volume",
            "value": 0.9
        }),
    );
    assert_eq!(volume["changed"], true);
    let mode = rpc(
        &server.socket,
        "sidebar.custom.state.set",
        json!({
            "provider_id": "cmux.sidebar.custom.controls",
            "key": "mode",
            "value": "fast"
        }),
    );
    assert_eq!(mode["changed"], true);

    let updated = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    assert_eq!(
        updated["custom_sidebar"]["document"]["root"]["children"][0]["binding"]["value"],
        0.9
    );
    assert_eq!(
        updated["custom_sidebar"]["document"]["root"]["children"][1]["binding"]["value"],
        "fast"
    );
}

#[test]
fn custom_sidebar_row_state_isolated_and_persistent_in_remote_worker() {
    let root = tempfile::tempdir().expect("row state root");
    let sidebars = root.path().join("sidebars");
    let selection = root.path().join("selection.json");
    let state_store = root.path().join("state.json");
    let config_home = root.path().join("config");
    std::fs::create_dir_all(&sidebars).expect("create sidebars");
    std::fs::create_dir_all(config_home.join("cmux")).expect("create config");
    std::fs::write(
        config_home.join("cmux/cmux.json"),
        r#"{"customSidebars":{"renderer":"remote"}}"#,
    )
    .expect("write remote renderer config");
    std::fs::write(
        sidebars.join("rows.swift"),
        r#"
struct Row: View {
  let index: Int
  @State private var enabled = false

  var body: some View {
    Toggle("Row \(index)", isOn: $enabled)
  }
}

ForEach(0..<2, id: \.self) { index in
  Row(index: index)
}
"#,
    )
    .expect("write row state sidebar");
    let sidebars_path = sidebars.display().to_string();
    let selection_path = selection.display().to_string();
    let state_path = state_store.display().to_string();
    let config_path = config_home.display().to_string();
    let envs = [
        ("CMUX_CUSTOM_SIDEBARS_DIR", sidebars_path.as_str()),
        (
            "CMUX_CUSTOM_SIDEBAR_SELECTION_PATH",
            selection_path.as_str(),
        ),
        ("CMUX_CUSTOM_SIDEBAR_STATE_PATH", state_path.as_str()),
        ("XDG_CONFIG_HOME", config_path.as_str()),
    ];

    let first_key;
    let second_key;
    {
        let server = start_server_with_env(&envs);
        rpc(
            &server.socket,
            "sidebar.custom.select",
            json!({"name": "rows"}),
        );
        let initial = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        assert_eq!(initial["custom_sidebar"]["renderer"], "remote");
        let rows = initial["custom_sidebar"]["document"]["root"]["children"]
            .as_array()
            .expect("row controls");
        assert_eq!(rows.len(), 2);
        first_key = rows[0]["binding"]["key"]
            .as_str()
            .expect("first row key")
            .to_string();
        second_key = rows[1]["binding"]["key"]
            .as_str()
            .expect("second row key")
            .to_string();
        assert_ne!(first_key, second_key);
        assert!(first_key.starts_with("__cmux_instance_"));
        assert_eq!(rows[0]["binding"]["value"], false);
        assert_eq!(rows[1]["binding"]["value"], false);

        let changed = rpc(
            &server.socket,
            "sidebar.custom.state.set",
            json!({
                "provider_id": "cmux.sidebar.custom.rows",
                "key": first_key,
                "value": true
            }),
        );
        assert_eq!(changed["changed"], true);
        let updated = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][0]["binding"]["value"],
            true
        );
        assert_eq!(
            updated["custom_sidebar"]["document"]["root"]["children"][1]["binding"]["value"],
            false
        );
    }

    {
        let server = start_server_with_env(&envs);
        let restored = rpc(
            &server.socket,
            "renderer.snapshot",
            json!({"backend": "core"}),
        );
        let rows = restored["custom_sidebar"]["document"]["root"]["children"]
            .as_array()
            .expect("restored row controls");
        assert_eq!(rows[0]["binding"]["key"], first_key);
        assert_eq!(rows[1]["binding"]["key"], second_key);
        assert_eq!(rows[0]["binding"]["value"], true);
        assert_eq!(rows[1]["binding"]["value"], false);
    }
}

