#[test]
fn cli_workspace_group_commands_match_socket_contract() {
    let server = start_server();
    let current = rpc(&server.socket, "workspace.current", json!({}));
    let ws0 = current["workspace_id"].as_str().unwrap().to_string();
    let ws1 = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "CLI Group Child", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    let from = format!("{ws0},{ws1}");
    let created = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "workspace-group",
            "create",
            "--name",
            "CLI Group",
            "--from",
            &from,
        ],
        &[],
    );
    let group_id = created["group"]["group_id"].as_str().unwrap();
    let group_ref = created["group"]["group_ref"].as_str().unwrap();
    assert_eq!(created["group"]["name"], "CLI Group");
    assert_eq!(created["group"]["member_count"], 3);

    let listed = cli_json_with_env(
        &server.socket,
        &["--json", "--id-format", "both", "workspace-group", "list"],
        &[],
    );
    assert_eq!(listed["groups"].as_array().unwrap().len(), 1);
    assert_eq!(listed["groups"][0]["group_id"], group_id);

    let renamed = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "workspace-group",
            "rename",
            group_ref,
            "--name",
            "CLI Renamed",
        ],
        &[],
    );
    assert_eq!(renamed["name"], "CLI Renamed");
    let new_workspace = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "workspace-group",
            "new-workspace",
            group_ref,
            "--placement",
            "end",
        ],
        &[],
    );
    assert_eq!(new_workspace["group_id"], group_id);
    let deleted = cli_json_with_env(
        &server.socket,
        &["--json", "workspace-group", "delete", group_ref],
        &[],
    );
    assert_eq!(deleted["closed_workspace_count"], 4);
}

#[test]
fn socket_ids_reject_bare_numeric_indexes_but_accept_refs() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "ref-only-target", "focus": false}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap().to_string();
    let workspace_ref = created["workspace_ref"].as_str().unwrap().to_string();

    for (method, params) in [
        ("window.focus", json!({"window_id": "1"})),
        ("workspace.select", json!({"workspace_id": "1"})),
        ("pane.focus", json!({"pane_id": "1"})),
        ("surface.focus", json!({"surface_id": "1"})),
        ("surface.focus", json!({"surface_id": 1})),
    ] {
        let response = rpc_response(&server.socket, method, params);
        assert_eq!(response["ok"], false, "response was {response}");
        assert_eq!(
            response["error"]["code"], "not_found",
            "response was {response}"
        );
    }

    rpc(
        &server.socket,
        "window.focus",
        json!({"window_id": "window:1"}),
    );
    let selected = rpc(
        &server.socket,
        "workspace.select",
        json!({"workspace_id": workspace_ref}),
    );
    assert_eq!(selected["workspace_id"], workspace_id);

    let pane = rpc(&server.socket, "pane.focus", json!({"pane_id": "pane:1"}));
    assert!(
        pane["pane_ref"]
            .as_str()
            .unwrap_or_default()
            .starts_with("pane:"),
        "pane focus response was {pane}"
    );
    let surface = rpc(
        &server.socket,
        "surface.focus",
        json!({"surface_id": "surface:1"}),
    );
    assert!(
        surface["surface_ref"]
            .as_str()
            .unwrap_or_default()
            .starts_with("surface:"),
        "surface focus response was {surface}"
    );
}

#[test]
fn notification_mark_unread_promotes_row_to_top() {
    let server = start_server();
    rpc(
        &server.socket,
        "app.focus_override.set",
        json!({"state": "inactive"}),
    );
    let current_workspace = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let background_workspace = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "background", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let first = rpc(
        &server.socket,
        "notification.create",
        json!({"workspace_id": current_workspace, "title": "first"}),
    )["notification_id"]
        .as_str()
        .unwrap()
        .to_string();
    let second = rpc(
        &server.socket,
        "notification.create",
        json!({"workspace_id": background_workspace, "title": "second"}),
    )["notification_id"]
        .as_str()
        .unwrap()
        .to_string();

    let initial = rpc(&server.socket, "notification.list", json!({}));
    let initial_rows = initial["notifications"].as_array().unwrap();
    assert_eq!(initial_rows[0]["id"], second);
    assert_eq!(initial_rows[1]["id"], first);

    rpc(
        &server.socket,
        "notification.mark_read",
        json!({"notification_id": first}),
    );
    let after_read = rpc(&server.socket, "notification.list", json!({}));
    let after_read_rows = after_read["notifications"].as_array().unwrap();
    assert_eq!(after_read_rows[0]["id"], second);
    assert_eq!(after_read_rows[0]["is_read"], false);
    assert_eq!(after_read_rows[1]["id"], first);
    assert_eq!(after_read_rows[1]["is_read"], true);

    rpc(
        &server.socket,
        "notification.mark_unread",
        json!({"notification_id": first}),
    );
    let after_unread = rpc(&server.socket, "notification.list", json!({}));
    let after_unread_rows = after_unread["notifications"].as_array().unwrap();
    assert_eq!(after_unread_rows[0]["id"], first);
    assert_eq!(after_unread_rows[0]["is_read"], false);
    assert_eq!(after_unread_rows[1]["id"], second);
    assert_eq!(after_unread_rows[1]["is_read"], false);
}

#[test]
fn notification_reconcile_reports_handled_ids_and_unread_count() {
    let server = start_server();
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "notification.reconcile"));
    assert_eq!(capabilities["features"]["notification_reconcile"], true);

    let workspace_id = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let background_workspace_id = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "notification reconcile background", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let read_id = rpc(
        &server.socket,
        "notification.create",
        json!({"workspace_id": workspace_id, "title": "read notification"}),
    )["notification_id"]
        .as_str()
        .unwrap()
        .to_string();
    let unread_id = rpc(
        &server.socket,
        "notification.create",
        json!({"workspace_id": background_workspace_id, "title": "unread notification"}),
    )["notification_id"]
        .as_str()
        .unwrap()
        .to_string();
    rpc(
        &server.socket,
        "notification.mark_read",
        json!({"notification_id": read_id}),
    );

    let reconciled = rpc(
        &server.socket,
        "notification.reconcile",
        json!({"delivered_ids": [read_id, unread_id, "bad-id", read_id]}),
    );
    assert_eq!(reconciled["handled_ids"].as_array().unwrap().len(), 1);
    assert_eq!(reconciled["handled_ids"][0], read_id);
    assert_eq!(reconciled["unread_count"], 1);

    let badge_only = rpc(
        &server.socket,
        "notification.reconcile",
        json!({"delivered_ids": []}),
    );
    assert_eq!(badge_only["handled_ids"].as_array().unwrap().len(), 0);
    assert_eq!(badge_only["unread_count"], 1);
}

#[test]
fn notification_create_for_target_matches_macos_contract() {
    let server = start_server();
    rpc(
        &server.socket,
        "app.focus_override.set",
        json!({"state": "inactive"}),
    );
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    assert!(methods
        .iter()
        .any(|method| method.as_str() == Some("notification.create_for_target")));
    assert_eq!(capabilities["features"]["notification_targets"], true);

    let current = rpc(&server.socket, "surface.current", json!({}));
    let workspace_id = current["workspace_id"].as_str().unwrap();
    let workspace_ref = current["workspace_ref"].as_str().unwrap();
    let split = rpc(
        &server.socket,
        "surface.split",
        json!({"workspace_id": workspace_id, "type": "terminal", "focus": false}),
    );
    let surface_id = split["surface_id"].as_str().unwrap();
    let surface_ref = split["surface_ref"].as_str().unwrap();

    let delivered = rpc(
        &server.socket,
        "notification.create_for_target",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "title": "targeted",
            "subtitle": "sub",
            "body": "body"
        }),
    );
    assert_eq!(delivered["workspace_id"], workspace_id);
    assert_eq!(delivered["workspace_ref"], workspace_ref);
    assert_eq!(delivered["surface_id"], surface_id);
    assert_eq!(delivered["surface_ref"], surface_ref);
    assert!(delivered["window_id"].as_str().is_some());
    assert!(delivered["window_ref"].as_str().is_some());

    let listed = rpc(&server.socket, "notification.list", json!({}));
    let row = listed["notifications"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["title"] == "targeted")
        .expect("targeted notification");
    assert_eq!(row["workspace_id"], workspace_id);
    assert_eq!(row["surface_id"], surface_id);
    assert_eq!(row["subtitle"], "sub");
    assert_eq!(row["body"], "body");
    assert_eq!(row["is_read"], false);

    let surface_delivered = rpc(
        &server.socket,
        "notification.create_for_surface",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "title": "surface-targeted"
        }),
    );
    assert_eq!(surface_delivered["workspace_id"], workspace_id);
    assert_eq!(surface_delivered["workspace_ref"], workspace_ref);
    assert_eq!(surface_delivered["surface_id"], surface_id);
    assert_eq!(surface_delivered["surface_ref"], surface_ref);

    let missing_workspace = rpc_response(
        &server.socket,
        "notification.create_for_target",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(
        missing_workspace["ok"], false,
        "response was {missing_workspace}"
    );
    assert_eq!(missing_workspace["error"]["code"], "invalid_params");
    assert_eq!(
        missing_workspace["error"]["message"],
        "Missing or invalid workspace_id"
    );

    let missing_surface = rpc_response(
        &server.socket,
        "notification.create_for_target",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(
        missing_surface["ok"], false,
        "response was {missing_surface}"
    );
    assert_eq!(missing_surface["error"]["code"], "invalid_params");
    assert_eq!(
        missing_surface["error"]["message"],
        "Missing or invalid surface_id"
    );

    let background_workspace = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "notification mismatch", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let mismatched_surface = rpc_response(
        &server.socket,
        "notification.create_for_target",
        json!({"workspace_id": background_workspace, "surface_id": surface_id}),
    );
    assert_eq!(
        mismatched_surface["ok"], false,
        "response was {mismatched_surface}"
    );
    assert_eq!(mismatched_surface["error"]["code"], "not_found");
    assert_eq!(mismatched_surface["error"]["message"], "Surface not found");
}

#[test]
fn notification_create_for_caller_matches_macos_resolution_contract() {
    let server = start_server();
    rpc(
        &server.socket,
        "app.focus_override.set",
        json!({"state": "inactive"}),
    );
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "notification.create_for_caller"));
    assert_eq!(
        capabilities["features"]["notification_create_for_caller"],
        true
    );

    let current = rpc(&server.socket, "surface.current", json!({}));
    let current_workspace_id = current["workspace_id"].as_str().unwrap();
    let current_workspace_ref = current["workspace_ref"].as_str().unwrap();
    let current_surface_id = current["surface_id"].as_str().unwrap();
    let current_surface_ref = current["surface_ref"].as_str().unwrap();
    rpc(
        &server.socket,
        "surface.report_tty",
        json!({
            "workspace_id": current_workspace_id,
            "surface_id": current_surface_id,
            "tty": "/dev/pts/caller-notify"
        }),
    );

    let direct = rpc(
        &server.socket,
        "notification.create_for_caller",
        json!({
            "preferred_workspace_id": current_workspace_ref,
            "preferred_surface_id": current_surface_ref,
            "title": "caller-direct",
            "subtitle": "preferred",
            "body": "Body"
        }),
    );
    assert_eq!(direct["workspace_id"], current_workspace_id);
    assert_eq!(direct["workspace_ref"], current_workspace_ref);
    assert_eq!(direct["surface_id"], current_surface_id);
    assert_eq!(direct["surface_ref"], current_surface_ref);
    assert!(direct["notification_id"].as_str().is_some());
    let listed_direct = rpc(&server.socket, "notification.list", json!({}));
    assert!(listed_direct["notifications"]
        .as_array()
        .unwrap()
        .iter()
        .any(|row| row["title"] == "caller-direct"
            && row["workspace_id"] == current_workspace_id
            && row["surface_id"] == current_surface_id));

    let background = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "notification caller background", "focus": false}),
    );
    let background_workspace_id = background["workspace_id"].as_str().unwrap();
    let background_surface = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": background_workspace_id}),
    );
    let background_surface_id = background_surface["surface_id"].as_str().unwrap();
    let stale_workspace = "00000000-0000-4000-8000-000000000000";
    let stale_surface_target = rpc(
        &server.socket,
        "notification.create_for_caller",
        json!({
            "preferred_workspace_id": stale_workspace,
            "preferred_surface_id": background_surface_id,
            "title": "caller-stale-surface"
        }),
    );
    assert_eq!(
        stale_surface_target["workspace_id"],
        background_workspace_id
    );
    assert_eq!(stale_surface_target["surface_id"], background_surface_id);

    let tty_target = rpc(
        &server.socket,
        "notification.create_for_caller",
        json!({
            "preferred_workspace_id": background_workspace_id,
            "preferred_surface_id": background_surface_id,
            "caller_tty": "/dev/pts/caller-notify",
            "prefer_tty": true,
            "title": "caller-tty"
        }),
    );
    assert_eq!(tty_target["workspace_id"], current_workspace_id);
    assert_eq!(tty_target["surface_id"], current_surface_id);

    let listed = rpc(&server.socket, "notification.list", json!({}));
    let rows = listed["notifications"].as_array().unwrap();
    assert!(rows.iter().any(|row| row["title"] == "caller-stale-surface"
        && row["workspace_id"] == background_workspace_id
        && row["surface_id"] == background_surface_id));
    assert!(rows.iter().any(|row| row["title"] == "caller-tty"
        && row["workspace_id"] == current_workspace_id
        && row["surface_id"] == current_surface_id));
}

