#[test]
fn agent_session_permission_modes_validate_provider_and_value() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "surface.create",
        json!({
            "type": "agent-session",
            "provider": "codex",
            "auto_start": false
        }),
    );
    let surface_id = created["surface_id"].as_str().expect("surface id");

    let selected = rpc(
        &server.socket,
        "agent_session.set_permission_mode",
        json!({
            "surface_id": surface_id,
            "permissionMode": "auto_review"
        }),
    );
    assert_eq!(selected["agent_session"]["permission_mode"], "auto-review");

    let invalid = rpc_response(
        &server.socket,
        "agent_session.set_permission_mode",
        json!({
            "surface_id": surface_id,
            "permission_mode": "unrestricted"
        }),
    );
    assert_eq!(invalid["ok"], false);
    assert_eq!(invalid["error"]["code"], "invalid_params");

    let claude = rpc(
        &server.socket,
        "agent_session.set_provider",
        json!({
            "surface_id": surface_id,
            "provider": "claude"
        }),
    );
    assert_eq!(claude["agent_session"]["permission_mode"], "default");
    let unsupported = rpc_response(
        &server.socket,
        "agent_session.set_permission_mode",
        json!({
            "surface_id": surface_id,
            "permission_mode": "full-access"
        }),
    );
    assert_eq!(unsupported["ok"], false);
    assert_eq!(unsupported["error"]["code"], "invalid_state");

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert_eq!(
        capabilities["features"]["native_agent_session_permission_modes"],
        true
    );
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "agent_session.set_permission_mode"));
}

#[test]
fn mobile_attach_ticket_create_reports_unavailable_and_mints_route_ticket() {
    let no_route_server = start_server();
    let no_route_capabilities = rpc(&no_route_server.socket, "system.capabilities", json!({}));
    assert!(
        no_route_capabilities["methods"]
            .as_array()
            .unwrap()
            .iter()
            .any(|method| method == "mobile.attach_ticket.create"),
        "mobile.attach_ticket.create was not advertised: {no_route_capabilities}"
    );
    assert_eq!(
        no_route_capabilities["features"]["mobile_attach_ticket"],
        true
    );
    let no_route = rpc_response(
        &no_route_server.socket,
        "mobile.attach_ticket.create",
        json!({}),
    );
    assert_eq!(no_route["ok"], false, "response was {no_route}");
    assert_eq!(no_route["error"]["code"], "unavailable");

    let tmp = tempfile::tempdir().expect("tempdir");
    let device_id_path = tmp.path().join("mobile-host-device-id");
    let device_id_path_text = device_id_path.display().to_string();
    let route_server = start_server_with_env(&[
        (
            "CMUX_MOBILE_HOST_DEVICE_ID_PATH",
            device_id_path_text.as_str(),
        ),
        ("CMUX_MOBILE_HOST_DISPLAY_NAME", "Linux Ticket Host"),
        ("CMUX_MOBILE_HOST_PORT", "59001"),
        ("CMUX_MOBILE_HOST_ROUTE_HOST", "100.64.1.2"),
        ("CMUX_MOBILE_HOST_ROUTE_PORT", "59001"),
        ("CMUX_MOBILE_HOST_ROUTE_KIND", "tailscale"),
        ("CMUX_MOBILE_HOST_ROUTE_ID", "tailscale"),
    ]);

    let status = rpc(&route_server.socket, "mobile.host.status", json!({}));
    let device_id = status["mac_device_id"].as_str().unwrap();
    assert_eq!(status["device_id"], device_id);
    assert_eq!(status["host_platform"], "linux");
    assert_eq!(status["display_name"], "Linux Ticket Host");
    assert_eq!(status["mac_display_name"], "Linux Ticket Host");
    assert_eq!(status["host_service"]["is_running"], true);
    assert_eq!(status["host_service"]["port"], 59001);
    assert_eq!(status["host_service"]["routes"][0]["id"], "tailscale");
    assert_eq!(status["host_service"]["routes"][0]["kind"], "tailscale");
    assert_eq!(
        status["host_service"]["routes"][0]["endpoint"],
        json!({"type": "host_port", "host": "100.64.1.2", "port": 59001})
    );
    assert_eq!(status["host_service"]["routes"][0]["priority"], 10);

    let ticket = rpc(
        &route_server.socket,
        "mobile.attach_ticket.create",
        json!({"scope": "mac", "ttl_seconds": 5, "route_kind": "tailscale"}),
    );
    assert_eq!(
        ticket["attach_url"],
        "cmux-ios://attach?v=2&r=100.64.1.2:59001"
    );
    assert_eq!(ticket["routes"], status["host_service"]["routes"]);
    assert!(ticket["expires_at"]
        .as_str()
        .unwrap_or_default()
        .ends_with('Z'));
    assert_eq!(ticket["device_id"], device_id);
    assert_eq!(ticket["display_name"], "Linux Ticket Host");
    assert_eq!(ticket["host_platform"], "linux");
    assert_eq!(ticket["app_version"], env!("CARGO_PKG_VERSION"));
    assert_eq!(ticket["ticket"]["version"], 1);
    assert_eq!(ticket["ticket"]["workspaceID"], "");
    assert_eq!(ticket["ticket"]["terminalID"], Value::Null);
    assert_eq!(ticket["ticket"]["hostPlatform"], "linux");
    assert_eq!(ticket["ticket"]["hostDeviceID"], device_id);
    assert_eq!(ticket["ticket"]["hostDisplayName"], "Linux Ticket Host");
    assert_eq!(
        ticket["ticket"]["hostAppVersion"],
        env!("CARGO_PKG_VERSION")
    );
    assert_eq!(ticket["ticket"]["macDeviceID"], device_id);
    assert_eq!(ticket["ticket"]["macDisplayName"], "Linux Ticket Host");
    assert_eq!(ticket["ticket"]["macPairingCompatibilityVersion"], 1);
    assert_eq!(ticket["ticket"]["macAppVersion"], env!("CARGO_PKG_VERSION"));
    assert_eq!(ticket["ticket"]["routes"], status["host_service"]["routes"]);
    assert!(
        ticket["ticket"]["auth_token"]
            .as_str()
            .unwrap_or_default()
            .len()
            >= 32
    );

    let linux_scope_ticket = rpc(
        &route_server.socket,
        "mobile.attach_ticket.create",
        json!({"scope": "linux", "route_id": "tailscale"}),
    );
    assert_eq!(linux_scope_ticket["host_platform"], "linux");
    assert_eq!(linux_scope_ticket["ticket"]["workspaceID"], "");
    assert_eq!(linux_scope_ticket["ticket"]["terminalID"], Value::Null);
    assert_eq!(linux_scope_ticket["ticket"]["hostPlatform"], "linux");
    assert_eq!(
        linux_scope_ticket["ticket"]["hostAppVersion"],
        env!("CARGO_PKG_VERSION")
    );
    assert_eq!(linux_scope_ticket["ticket"]["macDeviceID"], device_id);

    let cli_ticket = cli_json_with_env(
        &route_server.socket,
        &[
            "mobile",
            "attach-ticket",
            "create",
            "--scope",
            "linux",
            "--route-id",
            "tailscale",
            "--ttl-seconds",
            "30",
        ],
        &[],
    );
    assert_eq!(
        cli_ticket["attach_url"],
        "cmux-ios://attach?v=2&r=100.64.1.2:59001"
    );
    assert_eq!(cli_ticket["host_platform"], "linux");
    assert_eq!(cli_ticket["ticket"]["workspaceID"], "");
    assert_eq!(cli_ticket["ticket"]["terminalID"], Value::Null);
    assert_eq!(
        cli_ticket["ticket"]["routes"],
        status["host_service"]["routes"]
    );
    assert_eq!(cli_ticket["routes"], status["host_service"]["routes"]);

    let current = rpc(&route_server.socket, "workspace.current", json!({}));
    let current_surface = rpc(&route_server.socket, "surface.current", json!({}));
    let scoped = rpc(
        &route_server.socket,
        "mobile.attach_ticket.create",
        json!({
            "workspace_id": current["workspace_id"],
            "terminal_id": current_surface["surface_id"],
            "ttl_seconds": 3601
        }),
    );
    assert_eq!(scoped["ticket"]["workspaceID"], current["workspace_id"]);
    assert_eq!(
        scoped["ticket"]["terminalID"],
        current_surface["surface_id"]
    );
    let current_workspace_id = current["workspace_id"].as_str().unwrap();
    let current_surface_id = current_surface["surface_id"].as_str().unwrap();
    let cli_scoped = cli_json_with_env(
        &route_server.socket,
        &[
            "mobile",
            "host",
            "attach-ticket",
            "create",
            "--workspace",
            current_workspace_id,
            "--surface",
            current_surface_id,
            "--route-kind",
            "tailscale",
        ],
        &[],
    );
    assert_eq!(cli_scoped["ticket"]["workspaceID"], current["workspace_id"]);
    assert_eq!(
        cli_scoped["ticket"]["terminalID"],
        current_surface["surface_id"]
    );

    let missing_route = rpc_response(
        &route_server.socket,
        "mobile.attach_ticket.create",
        json!({"route_id": "missing-route"}),
    );
    assert_eq!(missing_route["ok"], false, "response was {missing_route}");
    assert_eq!(missing_route["error"]["code"], "unavailable");
    assert!(missing_route["error"]["message"]
        .as_str()
        .unwrap_or_default()
        .contains("Requested mobile host route"));
    let cli_missing_route = cli_failure(
        &route_server.socket,
        &[
            "mobile",
            "attach-ticket",
            "create",
            "--route-id",
            "missing-route",
        ],
    );
    assert!(
        cli_missing_route.contains("Requested mobile host route is not available"),
        "unexpected mobile attach-ticket CLI error: {cli_missing_route}"
    );
}

#[test]
fn mobile_attach_ticket_create_supports_debug_loopback_route() {
    let server = start_server_with_env(&[
        ("CMUX_MOBILE_HOST_PORT", "59002"),
        ("CMUX_MOBILE_HOST_ROUTE_HOST", "100.64.1.2"),
        ("CMUX_MOBILE_HOST_ROUTE_PORT", "59002"),
        ("CMUX_MOBILE_HOST_ROUTE_KIND", "tailscale"),
        ("CMUX_MOBILE_HOST_DEBUG_LOOPBACK", "1"),
        ("CMUX_MOBILE_HOST_DEBUG_ROUTE_PORT", "59003"),
    ]);

    let status = rpc(&server.socket, "mobile.host.status", json!({}));
    let routes = status["host_service"]["routes"]
        .as_array()
        .expect("host routes");
    assert_eq!(routes.len(), 2, "status was {status}");
    assert_eq!(routes[0]["id"], "tailscale");
    assert_eq!(routes[0]["kind"], "tailscale");
    assert_eq!(routes[0]["priority"], 10);
    assert_eq!(routes[1]["id"], "debug-loopback");
    assert_eq!(routes[1]["kind"], "debug_loopback");
    assert_eq!(
        routes[1]["endpoint"],
        json!({"type": "host_port", "host": "127.0.0.1", "port": 59003})
    );
    assert_eq!(routes[1]["priority"], 1000);

    let ticket = rpc(
        &server.socket,
        "mobile.attach_ticket.create",
        json!({"scope": "linux", "route_kind": "loopback"}),
    );
    assert_eq!(
        ticket["attach_url"],
        "cmux-ios://attach?v=2&r=127.0.0.1:59003"
    );
    assert_eq!(ticket["routes"].as_array().unwrap().len(), 1);
    assert_eq!(ticket["routes"][0]["id"], "debug-loopback");
    assert_eq!(ticket["ticket"]["routes"], ticket["routes"]);
    assert_eq!(ticket["ticket"]["workspaceID"], "");
    assert_eq!(ticket["ticket"]["terminalID"], Value::Null);
}

#[test]
fn mobile_host_tcp_listener_authenticates_frames_streams_terminal_and_reconnects() {
    let port = free_tcp_port();
    let port_text = port.to_string();
    let tmp = tempfile::tempdir().expect("mobile host tempdir");
    let device_id_path = tmp.path().join("mobile-device-id");
    let device_id_path_text = device_id_path.display().to_string();
    let server = start_server_with_env(&[
        (
            "CMUX_MOBILE_HOST_DEVICE_ID_PATH",
            device_id_path_text.as_str(),
        ),
        ("CMUX_MOBILE_HOST_DISPLAY_NAME", "Linux TCP Host"),
        ("CMUX_MOBILE_HOST_PORT", port_text.as_str()),
        ("CMUX_MOBILE_HOST_DEBUG_LOOPBACK", "1"),
        ("CMUX_MOBILE_HOST_DEBUG_ROUTE_PORT", port_text.as_str()),
    ]);
    let dev_token = "linux-mobile-tcp-token";
    rpc(
        &server.socket,
        "mobile.dev_stack_auth.configure",
        json!({"token": dev_token}),
    );

    let status = rpc(&server.socket, "mobile.host.status", json!({}));
    assert_eq!(status["host_service"]["is_running"], true);
    assert_eq!(status["host_service"]["port"], port);
    assert_eq!(status["host_service"]["active_connection_count"], 0);
    assert_eq!(
        status["host_service"]["routes"][0]["endpoint"],
        json!({"type": "host_port", "host": "127.0.0.1", "port": port})
    );

    let address = ("127.0.0.1", port);
    let mut fragmented = TcpStream::connect(address).expect("connect fragmented mobile client");
    fragmented
        .set_read_timeout(Some(Duration::from_secs(3)))
        .expect("set fragmented client timeout");
    let request = serde_json::to_vec(&json!({
        "id": "fragmented-status",
        "method": "mobile.host.status",
        "params": {}
    }))
    .expect("encode fragmented request");
    let header = (request.len() as u32).to_be_bytes();
    fragmented
        .write_all(&header[..2])
        .expect("write partial frame header");
    fragmented
        .write_all(&header[2..])
        .expect("write remaining frame header");
    for chunk in request.chunks(3) {
        fragmented
            .write_all(chunk)
            .expect("write fragmented frame payload");
    }
    let public_status = read_mobile_frame(&mut fragmented);
    assert_eq!(public_status["ok"], true);
    assert_eq!(public_status["result"]["terminal_fidelity"], "render_grid");
    assert_eq!(public_status["result"]["mac_device_id"], Value::Null);
    drop(fragmented);

    let mut stream = TcpStream::connect(address).expect("connect mobile client");
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .expect("set mobile client timeout");
    let unauthorized = mobile_rpc(
        &mut stream,
        "unauthorized",
        "workspace.list",
        json!({}),
        None,
    );
    assert_eq!(unauthorized["ok"], false);
    assert_eq!(unauthorized["error"]["code"], "unauthorized");

    let auth = json!({"stack_access_token": dev_token});
    let identity_status = mobile_rpc(
        &mut stream,
        "identity-status",
        "mobile.host.status",
        json!({}),
        Some(auth.clone()),
    );
    assert_eq!(identity_status["ok"], true);
    assert_eq!(
        identity_status["result"]["mac_display_name"],
        "Linux TCP Host"
    );
    assert!(identity_status["result"]["mac_device_id"]
        .as_str()
        .is_some_and(|id| !id.is_empty()));

    let workspaces = mobile_rpc(
        &mut stream,
        "workspace-list",
        "workspace.list",
        json!({}),
        Some(auth.clone()),
    );
    assert_eq!(workspaces["ok"], true);
    assert_eq!(workspaces["result"]["groups"], json!([]));
    let workspace = &workspaces["result"]["workspaces"][0];
    let workspace_id = workspace["id"].as_str().expect("workspace id");
    let terminal_id = workspace["terminals"][0]["id"]
        .as_str()
        .expect("terminal id");

    let scoped_ticket = rpc(
        &server.socket,
        "mobile.attach_ticket.create",
        json!({
            "workspace_id": workspace_id,
            "terminal_id": terminal_id,
            "route_kind": "debug_loopback"
        }),
    );
    let attach_token = scoped_ticket["ticket"]["auth_token"]
        .as_str()
        .expect("attach token");
    let second = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Ticket scope target", "focus": false}),
    );
    let second_workspace_id = second["workspace_id"]
        .as_str()
        .expect("second workspace id");
    let second_list = rpc(
        &server.socket,
        "mobile.workspace.list",
        json!({"workspace_id": second_workspace_id}),
    );
    let second_terminal_id = second_list["workspaces"][0]["terminals"][0]["id"]
        .as_str()
        .expect("second terminal id");
    let scoped_auth = json!({
        "stack_access_token": dev_token,
        "attach_token": attach_token
    });
    let forbidden = mobile_rpc(
        &mut stream,
        "scope-forbidden",
        "mobile.terminal.replay",
        json!({
            "workspace_id": second_workspace_id,
            "terminal_id": second_terminal_id
        }),
        Some(scoped_auth.clone()),
    );
    assert_eq!(forbidden["ok"], false);
    assert_eq!(forbidden["error"]["code"], "forbidden");

    let allowed = mobile_rpc(
        &mut stream,
        "scope-allowed",
        "mobile.terminal.replay",
        json!({"workspace_id": workspace_id, "terminal_id": terminal_id}),
        Some(scoped_auth.clone()),
    );
    assert_eq!(allowed["ok"], true);
    assert!(allowed["result"]["render_grid"].is_object());

    let created = mobile_rpc(
        &mut stream,
        "workspace-create",
        "workspace.create",
        json!({"title": "Created from iOS"}),
        Some(scoped_auth.clone()),
    );
    assert_eq!(created["ok"], true);
    assert!(created["result"]["created_workspace_id"]
        .as_str()
        .is_some_and(|id| !id.is_empty()));
    assert_eq!(created["result"]["workspaces"].as_array().unwrap().len(), 1);

    rpc(
        &server.socket,
        "terminal.create",
        json!({"workspace_id": workspace_id, "title": "Codex mobile chat"}),
    );
    let subscribed = mobile_rpc(
        &mut stream,
        "subscribe",
        "mobile.events.subscribe",
        json!({
            "stream_id": "terminal-live",
            "topics": [
                "workspace.updated",
                "terminal.render_grid",
                "notification.dismissed",
                "notification.badge",
                "chat.message"
            ]
        }),
        Some(scoped_auth.clone()),
    );
    assert_eq!(subscribed["ok"], true);
    assert_eq!(subscribed["result"]["already_subscribed"], false);

    let mut topics = HashSet::new();
    let mut chat_event_names = HashSet::new();
    let mut chat_payloads = Vec::new();
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline
        && (![
            "workspace.updated",
            "terminal.render_grid",
            "notification.badge",
            "chat.message",
        ]
        .iter()
        .all(|topic| topics.contains(*topic))
            || !["state_changed", "descriptor_changed", "terminal_blocks"]
                .iter()
                .all(|event| chat_event_names.contains(*event)))
    {
        let event = read_mobile_frame(&mut stream);
        if event["kind"] == "event" {
            let topic = event["topic"].as_str().unwrap().to_string();
            topics.insert(topic.clone());
            if topic == "chat.message" {
                if let Some(name) = event["payload"]["event"]["event"].as_str() {
                    chat_event_names.insert(name.to_string());
                }
                chat_payloads.push(event["payload"].clone());
            }
        }
    }
    assert!(
        topics.contains("workspace.updated"),
        "topics were {topics:?}"
    );
    assert!(
        topics.contains("terminal.render_grid"),
        "topics were {topics:?}"
    );
    assert!(
        topics.contains("notification.badge"),
        "topics were {topics:?}"
    );
    assert!(topics.contains("chat.message"), "topics were {topics:?}");
    assert!(
        ["state_changed", "descriptor_changed", "terminal_blocks"]
            .iter()
            .all(|event| chat_event_names.contains(*event)),
        "chat events were {chat_event_names:?}"
    );
    let descriptor = chat_payloads
        .iter()
        .find(|payload| payload["event"]["event"] == "descriptor_changed")
        .expect("chat descriptor event");
    let chat_session_id = descriptor["session_id"]
        .as_str()
        .expect("chat event session id");
    assert!(chat_session_id.starts_with("linux-chat-"));
    assert_eq!(descriptor["event"]["descriptor"]["agent_kind"], "codex");
    assert_eq!(descriptor["event"]["descriptor"]["kind"], "terminal");
    assert_eq!(
        descriptor["event"]["descriptor"]["workspace_id"],
        workspace_id
    );
    assert!(descriptor["event"]["descriptor"]["terminal_id"]
        .as_str()
        .is_some_and(|id| !id.is_empty()));
    assert!(descriptor["event"]["descriptor"]["state"]["state"]
        .as_str()
        .is_some_and(|state| matches!(state, "idle" | "working" | "needs_input" | "ended")));
    let state_changed = chat_payloads
        .iter()
        .find(|payload| payload["event"]["event"] == "state_changed")
        .expect("chat state event");
    assert_eq!(state_changed["session_id"], chat_session_id);
    assert!(state_changed["event"]["state"]["state"].is_string());
    let terminal_blocks = chat_payloads
        .iter()
        .find(|payload| payload["event"]["event"] == "terminal_blocks")
        .expect("chat terminal blocks event");
    assert_eq!(terminal_blocks["session_id"], chat_session_id);
    assert!(terminal_blocks["event"]["blocks"].is_array());

    let notification = rpc(
        &server.socket,
        "notification.create",
        json!({"workspace_id": workspace_id, "title": "Mobile badge"}),
    );
    let notification_id = notification["notification_id"]
        .as_str()
        .expect("notification id");
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let event = read_mobile_frame(&mut stream);
        if event["topic"] == "notification.badge"
            && event["payload"]["unread_count"].as_u64() == Some(1)
        {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "notification badge event did not arrive: {event}"
        );
    }
    rpc(
        &server.socket,
        "notification.dismiss",
        json!({"notification_id": notification_id}),
    );
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let event = read_mobile_frame(&mut stream);
        if event["topic"] == "notification.dismissed"
            && event["payload"]["ids"]
                .as_array()
                .is_some_and(|ids| ids.iter().any(|id| id == notification_id))
        {
            assert_eq!(event["payload"]["unread_count"], 0);
            break;
        }
        assert!(
            Instant::now() < deadline,
            "notification dismissed event did not arrive: {event}"
        );
    }

    drop(stream);
    let deadline = Instant::now() + Duration::from_secs(3);
    loop {
        let status = rpc(&server.socket, "mobile.host.status", json!({}));
        if status["host_service"]["active_connection_count"] == 0 {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "mobile connection did not leave the registry: {status}"
        );
        thread::sleep(Duration::from_millis(20));
    }

    let mut reconnected = TcpStream::connect(address).expect("reconnect mobile client");
    reconnected
        .set_read_timeout(Some(Duration::from_secs(3)))
        .expect("set reconnect timeout");
    let replay = mobile_rpc(
        &mut reconnected,
        "reconnect-replay",
        "mobile.terminal.replay",
        json!({"workspace_id": workspace_id, "terminal_id": terminal_id}),
        Some(scoped_auth),
    );
    assert_eq!(replay["ok"], true);
    drop(reconnected);

    let mut oversized = TcpStream::connect(address).expect("connect oversized client");
    oversized
        .set_read_timeout(Some(Duration::from_secs(3)))
        .expect("set oversized timeout");
    oversized
        .write_all(&((8 * 1024 * 1024 + 1) as u32).to_be_bytes())
        .expect("write oversized header");
    let rejected = read_mobile_frame(&mut oversized);
    assert_eq!(rejected["ok"], false);
    assert_eq!(rejected["error"]["code"], "frame_decode_error");
}

#[test]
fn mobile_host_tcp_workspace_mutations_match_mobile_contract() {
    let port = free_tcp_port();
    let port_text = port.to_string();
    let server = start_server_with_env(&[
        ("CMUX_MOBILE_HOST_PORT", port_text.as_str()),
        ("CMUX_MOBILE_HOST_DEBUG_LOOPBACK", "1"),
        ("CMUX_MOBILE_HOST_DEBUG_ROUTE_PORT", port_text.as_str()),
    ]);
    let dev_token = "linux-mobile-workspace-token";
    rpc(
        &server.socket,
        "mobile.dev_stack_auth.configure",
        json!({"token": dev_token}),
    );

    let initial_workspace_id = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .expect("initial workspace id")
        .to_string();
    let grouped_workspace_id = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Mobile grouped", "focus": false}),
    )["workspace_id"]
        .as_str()
        .expect("grouped workspace id")
        .to_string();
    let close_workspace_id = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Mobile close target", "focus": false}),
    )["workspace_id"]
        .as_str()
        .expect("close workspace id")
        .to_string();
    let group = rpc(
        &server.socket,
        "workspace.group.create",
        json!({
            "name": "Mobile Group",
            "child_workspace_ids": [
                initial_workspace_id.clone(),
                grouped_workspace_id.clone()
            ]
        }),
    );
    let group_id = group["group"]["group_id"]
        .as_str()
        .expect("mobile group id")
        .to_string();
    let lone_window = rpc(
        &server.socket,
        "window.create",
        json!({"title": "Mobile protected window"}),
    );
    let lone_workspace_id = lone_window["workspace_id"]
        .as_str()
        .expect("lone workspace id")
        .to_string();
    rpc(
        &server.socket,
        "notification.create",
        json!({
            "workspace_id": close_workspace_id,
            "title": "Mobile activity",
            "body": "\u{1b}[31mAgent needs input\u{1b}[0m\nnow"
        }),
    );

    let mut stream =
        TcpStream::connect(("127.0.0.1", port)).expect("connect mobile workspace client");
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .expect("set mobile workspace timeout");
    let auth = json!({"stack_access_token": dev_token});

    let listed = mobile_rpc(
        &mut stream,
        "workspace-list-before",
        "workspace.list",
        json!({}),
        Some(auth.clone()),
    );
    assert_eq!(listed["ok"], true);
    let rows = listed["result"]["workspaces"]
        .as_array()
        .expect("mobile workspace rows");
    let close_row = rows
        .iter()
        .find(|row| row["id"] == close_workspace_id)
        .expect("close target mobile row");
    assert_eq!(close_row["is_pinned"], false);
    assert_eq!(close_row["has_unread"], true);
    assert_eq!(close_row["preview"], "Agent needs input now");
    assert!(close_row["preview_at"].is_number());
    assert!(close_row["last_activity_at"].is_number());
    assert!(
        close_row["last_activity_at"].as_f64().unwrap()
            >= close_row["preview_at"].as_f64().unwrap()
    );
    assert_eq!(close_row["terminals"][0]["is_focused"], true);
    let workspace_count_before = rows.len();

    let marked_read = mobile_rpc(
        &mut stream,
        "workspace-mark-read",
        "workspace.action",
        json!({
            "workspace_id": close_workspace_id,
            "action": "mark-read"
        }),
        Some(auth.clone()),
    );
    assert_eq!(marked_read["ok"], true);
    assert_eq!(marked_read["result"]["unread"], false);
    let read_list = mobile_rpc(
        &mut stream,
        "workspace-list-read",
        "workspace.list",
        json!({"workspace_id": close_workspace_id}),
        Some(auth.clone()),
    );
    assert_eq!(read_list["result"]["workspaces"][0]["has_unread"], false);

    let missing_target = mobile_rpc(
        &mut stream,
        "workspace-action-missing-target",
        "workspace.action",
        json!({"action": "pin"}),
        Some(auth.clone()),
    );
    assert_eq!(missing_target["ok"], false);
    assert_eq!(missing_target["error"]["code"], "invalid_params");

    let ref_target = mobile_rpc(
        &mut stream,
        "workspace-action-ref-target",
        "workspace.action",
        json!({"workspace_id": "workspace:1", "action": "pin"}),
        Some(auth.clone()),
    );
    assert_eq!(ref_target["ok"], false);
    assert_eq!(ref_target["error"]["code"], "invalid_params");

    let destructive = mobile_rpc(
        &mut stream,
        "workspace-action-destructive",
        "workspace.action",
        json!({
            "workspace_id": initial_workspace_id,
            "action": "close-others"
        }),
        Some(auth.clone()),
    );
    assert_eq!(destructive["ok"], false);
    assert_eq!(destructive["error"]["code"], "method_not_found");
    assert_eq!(
        destructive["error"]["message"],
        "Unsupported workspace action for mobile"
    );
    let after_destructive = mobile_rpc(
        &mut stream,
        "workspace-list-after-destructive",
        "workspace.list",
        json!({}),
        Some(auth.clone()),
    );
    assert_eq!(
        after_destructive["result"]["workspaces"]
            .as_array()
            .unwrap()
            .len(),
        workspace_count_before
    );

    let pinned = mobile_rpc(
        &mut stream,
        "workspace-pin",
        "workspace.action",
        json!({
            "workspace_id": close_workspace_id,
            "action": "PIN"
        }),
        Some(auth.clone()),
    );
    assert_eq!(pinned["ok"], true);
    assert_eq!(pinned["result"]["action"], "pin");
    assert_eq!(pinned["result"]["pinned"], true);

    let protected_pinned = mobile_rpc(
        &mut stream,
        "workspace-close-pinned",
        "workspace.close",
        json!({"workspace_id": close_workspace_id}),
        Some(auth.clone()),
    );
    assert_eq!(protected_pinned["ok"], false);
    assert_eq!(protected_pinned["error"]["code"], "protected");

    let renamed = mobile_rpc(
        &mut stream,
        "workspace-rename",
        "workspace.action",
        json!({
            "workspace_id": close_workspace_id,
            "action": "rename",
            "title": "Renamed from mobile"
        }),
        Some(auth.clone()),
    );
    assert_eq!(renamed["ok"], true);
    assert_eq!(renamed["result"]["title"], "Renamed from mobile");

    let unpinned = mobile_rpc(
        &mut stream,
        "workspace-unpin",
        "workspace.action",
        json!({
            "workspace_id": close_workspace_id,
            "action": "unpin"
        }),
        Some(auth.clone()),
    );
    assert_eq!(unpinned["ok"], true);
    assert_eq!(unpinned["result"]["pinned"], false);

    let missing_group = mobile_rpc(
        &mut stream,
        "workspace-group-missing",
        "workspace.group.collapse",
        json!({}),
        Some(auth.clone()),
    );
    assert_eq!(missing_group["ok"], false);
    assert_eq!(missing_group["error"]["code"], "invalid_params");
    let collapsed = mobile_rpc(
        &mut stream,
        "workspace-group-collapse",
        "workspace.group.collapse",
        json!({"group_id": group_id}),
        Some(auth.clone()),
    );
    assert_eq!(collapsed["ok"], true);
    assert_eq!(collapsed["result"]["group_id"], group_id);
    assert_eq!(collapsed["result"]["is_collapsed"], true);
    let expanded = mobile_rpc(
        &mut stream,
        "workspace-group-expand",
        "workspace.group.expand",
        json!({"group_id": group_id}),
        Some(auth.clone()),
    );
    assert_eq!(expanded["ok"], true);
    assert_eq!(expanded["result"]["is_collapsed"], false);

    let protected_last = mobile_rpc(
        &mut stream,
        "workspace-close-last",
        "workspace.close",
        json!({"workspace_id": lone_workspace_id}),
        Some(auth.clone()),
    );
    assert_eq!(protected_last["ok"], false);
    assert_eq!(protected_last["error"]["code"], "protected");

    let closed = mobile_rpc(
        &mut stream,
        "workspace-close",
        "workspace.close",
        json!({"workspace_id": close_workspace_id}),
        Some(auth),
    );
    assert_eq!(closed["ok"], true);
    assert_eq!(closed["result"]["closed"], true);
    assert_eq!(closed["result"]["workspace_id"], close_workspace_id);
    assert!(closed["result"]["workspace_ref"]
        .as_str()
        .is_some_and(|value| value.starts_with("workspace:")));
    assert!(closed["result"]["window_id"]
        .as_str()
        .is_some_and(|value| !value.is_empty()));
    assert!(closed["result"]["window_ref"]
        .as_str()
        .is_some_and(|value| value.starts_with("window:")));
}

#[test]
fn mobile_host_tcp_stack_auth_enforces_same_account_and_hides_identity_on_bad_status_token() {
    let port = free_tcp_port();
    let port_text = port.to_string();
    let tmp = tempfile::tempdir().expect("mobile Stack auth tempdir");
    let stack = fake_stack_auth("mobile@example.com");
    let (auth_path, credentials_path) =
        write_cached_auth_session(tmp.path(), "mobile-refresh-token");
    let server = start_server_with_env(&[
        ("CMUX_AUTH_STATE_PATH", auth_path.as_str()),
        ("CMUX_AUTH_CREDENTIALS_PATH", credentials_path.as_str()),
        ("CMUX_STACK_BASE_URL", stack.base_url.as_str()),
        ("CMUX_MOBILE_HOST_PORT", port_text.as_str()),
        ("CMUX_MOBILE_HOST_DEBUG_LOOPBACK", "1"),
        ("CMUX_MOBILE_HOST_DEBUG_ROUTE_PORT", port_text.as_str()),
    ]);
    let auth_status = rpc(&server.socket, "auth.status", json!({}));
    assert_eq!(auth_status["signed_in"], true);
    assert_eq!(auth_status["user"]["id"], "stack-user");

    let mut stream = TcpStream::connect(("127.0.0.1", port)).expect("connect Stack mobile client");
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .expect("set Stack mobile timeout");
    let same_account = mobile_rpc(
        &mut stream,
        "same-account",
        "workspace.list",
        json!({}),
        Some(json!({"stack_access_token": "same-user-access"})),
    );
    assert_eq!(same_account["ok"], true, "response was {same_account}");

    let account_mismatch = mobile_rpc(
        &mut stream,
        "account-mismatch",
        "workspace.list",
        json!({}),
        Some(json!({"stack_access_token": "different-user-access"})),
    );
    assert_eq!(account_mismatch["ok"], false);
    assert_eq!(account_mismatch["error"]["code"], "account_mismatch");

    let public_status = mobile_rpc(
        &mut stream,
        "bad-status-token",
        "mobile.host.status",
        json!({}),
        Some(json!({"stack_access_token": "different-user-access"})),
    );
    assert_eq!(public_status["ok"], true);
    assert_eq!(public_status["result"]["mac_device_id"], Value::Null);
    assert_eq!(public_status["result"]["terminal_fidelity"], "render_grid");
}

#[test]
fn mobile_host_tcp_falls_back_to_ephemeral_port_and_updates_attach_routes() {
    let blocker = TcpListener::bind(("127.0.0.1", 0)).expect("bind mobile port blocker");
    let requested_port = blocker.local_addr().expect("mobile blocker address").port();
    let requested_port_text = requested_port.to_string();
    let server = start_server_with_env(&[
        ("CMUX_MOBILE_HOST_PORT", requested_port_text.as_str()),
        ("CMUX_MOBILE_HOST_DEBUG_LOOPBACK", "1"),
        (
            "CMUX_MOBILE_HOST_DEBUG_ROUTE_PORT",
            requested_port_text.as_str(),
        ),
    ]);
    rpc(
        &server.socket,
        "mobile.dev_stack_auth.configure",
        json!({"token": "ephemeral-mobile-token"}),
    );

    let status = rpc(&server.socket, "mobile.host.status", json!({}));
    let actual_port = status["host_service"]["port"]
        .as_u64()
        .expect("ephemeral mobile port") as u16;
    assert_ne!(actual_port, requested_port);
    assert_eq!(status["host_service"]["configured_port"], requested_port);
    assert_eq!(status["host_service"]["is_running"], true);
    assert_eq!(status["host_service"]["uses_ephemeral_fallback"], true);
    assert!(status["host_service"]["last_error"]
        .as_str()
        .is_some_and(|error| error.contains("using ephemeral port")));
    assert_eq!(
        status["host_service"]["routes"][0]["endpoint"]["port"],
        actual_port
    );

    let ticket = rpc(
        &server.socket,
        "mobile.attach_ticket.create",
        json!({"scope": "linux", "route_kind": "debug_loopback"}),
    );
    assert_eq!(ticket["routes"][0]["endpoint"]["port"], actual_port);
    assert!(ticket["attach_url"]
        .as_str()
        .is_some_and(|url| url.ends_with(&format!("127.0.0.1:{actual_port}"))));

    let mut stream =
        TcpStream::connect(("127.0.0.1", actual_port)).expect("connect ephemeral mobile listener");
    stream
        .set_read_timeout(Some(Duration::from_secs(3)))
        .expect("set ephemeral client timeout");
    let response = mobile_rpc(
        &mut stream,
        "ephemeral-status",
        "mobile.host.status",
        json!({}),
        Some(json!({"stack_access_token": "ephemeral-mobile-token"})),
    );
    assert_eq!(response["ok"], true);
    assert!(response["result"]["mac_device_id"].as_str().is_some());
}

#[test]
fn mobile_paste_image_defaults_to_xdg_cache_home() {
    let cache_tmp = tempfile::tempdir().expect("cache tempdir");
    let cache_home = cache_tmp.path().join("cache");
    let cache_home_text = cache_home.display().to_string();
    let server = start_server_with_env(&[("XDG_CACHE_HOME", cache_home_text.as_str())]);
    let current = rpc(&server.socket, "workspace.current", json!({}));
    let workspace_id = current["workspace_id"].as_str().unwrap();
    let created = rpc(
        &server.socket,
        "terminal.create",
        json!({"workspace_id": workspace_id, "title": "Cache image paste"}),
    );
    let terminal_id = created["created_terminal_id"]
        .as_str()
        .expect("created terminal id");

    let image_bytes = b"xdg cache png bytes";
    let paste = rpc(
        &server.socket,
        "terminal.paste_image",
        json!({
            "workspace_id": workspace_id,
            "terminal_id": terminal_id,
            "image_base64": base64::engine::general_purpose::STANDARD.encode(image_bytes),
            "image_format": "png"
        }),
    );
    let image_path = paste["image_path"].as_str().expect("image path");
    assert!(
        Path::new(image_path).starts_with(cache_home.join("cmux/mobile-images")),
        "mobile image path did not use XDG cache home: {image_path}"
    );
    assert_eq!(
        std::fs::read(image_path).expect("stored mobile paste image"),
        image_bytes
    );
}

#[test]
fn mobile_terminal_rpc_creates_drives_and_replays_terminal() {
    let server = start_server();
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    for method in [
        "mobile.terminal.create",
        "mobile.terminal.input",
        "mobile.terminal.paste",
        "mobile.terminal.replay",
        "mobile.terminal.viewport",
        "mobile.terminal.scroll",
        "mobile.terminal.mouse",
        "mobile.terminal.paste_image",
        "terminal.create",
        "terminal.input",
        "terminal.paste",
        "terminal.paste_image",
        "terminal.replay",
    ] {
        assert!(
            methods.iter().any(|advertised| advertised == method),
            "{method} was not advertised: {capabilities}"
        );
    }
    assert_eq!(capabilities["features"]["mobile_terminal_rpc"], true);
    assert_eq!(
        capabilities["features"]["mobile_terminal_paste_image"],
        true
    );

    let current = rpc(&server.socket, "workspace.current", json!({}));
    let workspace_id = current["workspace_id"].as_str().unwrap();
    let initial_list = rpc(
        &server.socket,
        "mobile.workspace.list",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(
        initial_list["workspaces"][0]["terminals"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    let cli_initial_list = cli_json_with_env(
        &server.socket,
        &["mobile", "workspace", "list", "--workspace", workspace_id],
        &[],
    );
    assert_eq!(
        cli_initial_list["workspaces"][0]["terminals"]
            .as_array()
            .unwrap()
            .len(),
        1
    );

    let cli_created = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "mobile",
            "terminal",
            "create",
            "--workspace",
            workspace_id,
            "--title",
            "CLI Mobile terminal",
        ],
        &[],
    );
    let cli_terminal_id = cli_created["created_terminal_id"]
        .as_str()
        .expect("CLI created terminal id");
    assert_eq!(cli_created["surface_id"], cli_terminal_id);
    assert!(cli_created["workspaces"][0]["terminals"]
        .as_array()
        .unwrap()
        .iter()
        .any(|terminal| terminal["id"] == cli_terminal_id));
    let cli_input = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "mobile",
            "terminal",
            "input",
            "--workspace",
            workspace_id,
            "--terminal",
            cli_terminal_id,
            "--",
            "printf 'CMUX_MOBILE_CLI_INPUT\\n'\n",
        ],
        &[],
    );
    assert_eq!(cli_input["workspace_id"], workspace_id);
    assert_eq!(cli_input["surface_id"], cli_terminal_id);
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let read = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": cli_terminal_id}),
        );
        if read["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_MOBILE_CLI_INPUT")
        {
            break;
        }
        thread::sleep(Duration::from_millis(100));
    }
    let cli_replay = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "mobile",
            "terminal",
            "replay",
            "--workspace",
            workspace_id,
            "--terminal",
            cli_terminal_id,
        ],
        &[],
    );
    assert_eq!(cli_replay["workspace_id"], workspace_id);
    assert_eq!(cli_replay["surface_id"], cli_terminal_id);
    assert!(cli_replay["render_grid"]["row_spans"]
        .as_array()
        .unwrap()
        .iter()
        .any(|span| span["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_MOBILE_CLI_INPUT")));
    let cli_viewport = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "mobile",
            "terminal",
            "viewport",
            "--workspace",
            workspace_id,
            "--terminal",
            cli_terminal_id,
        ],
        &[],
    );
    assert_eq!(cli_viewport["surface_id"], cli_terminal_id);
    assert!(cli_viewport["columns"].as_u64().unwrap_or(0) > 0);
    let cli_scroll = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "mobile",
            "terminal",
            "scroll",
            "--workspace",
            workspace_id,
            "--terminal",
            cli_terminal_id,
            "-2",
        ],
        &[],
    );
    assert_eq!(cli_scroll["surface_id"], cli_terminal_id);
    assert_eq!(cli_scroll["delta_lines"], -2.0);
    let cli_mouse = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "mobile",
            "terminal",
            "mouse",
            "--workspace",
            workspace_id,
            "--terminal",
            cli_terminal_id,
            "7",
            "3",
        ],
        &[],
    );
    assert_eq!(cli_mouse["surface_id"], cli_terminal_id);
    assert_eq!(cli_mouse["col"], 7);
    assert_eq!(cli_mouse["row"], 3);
    let cli_paste = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "mobile",
            "terminal",
            "paste",
            "--workspace",
            workspace_id,
            "--terminal",
            cli_terminal_id,
            "--submit-key",
            "none",
            "--text",
            "CMUX_MOBILE_CLI_PASTE",
        ],
        &[],
    );
    assert_eq!(cli_paste["surface_id"], cli_terminal_id);
    assert_eq!(cli_paste["submitted"], false);
    let cli_image_bytes = b"cli fake png bytes";
    let cli_image_path = server._tmp.path().join("cli-mobile.png");
    std::fs::write(&cli_image_path, cli_image_bytes).expect("write CLI mobile image");
    let cli_image_path_text = cli_image_path.display().to_string();
    let cli_paste_image = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "mobile",
            "terminal",
            "paste-image",
            "--workspace",
            workspace_id,
            "--terminal",
            cli_terminal_id,
            "--file",
            cli_image_path_text.as_str(),
        ],
        &[],
    );
    assert_eq!(cli_paste_image["workspace_id"], workspace_id);
    assert_eq!(cli_paste_image["surface_id"], cli_terminal_id);
    assert_eq!(cli_paste_image["bytes"], cli_image_bytes.len());
    assert_eq!(cli_paste_image["format"], "png");
    let cli_stored_image = cli_paste_image["image_path"]
        .as_str()
        .expect("CLI image path");
    assert_eq!(
        std::fs::read(cli_stored_image).expect("stored CLI mobile image"),
        cli_image_bytes
    );

    let created = rpc(
        &server.socket,
        "terminal.create",
        json!({"workspace_id": workspace_id, "title": "Mobile terminal"}),
    );
    let terminal_id = created["created_terminal_id"]
        .as_str()
        .expect("created terminal id");
    assert_eq!(created["surface_id"], terminal_id);
    let terminals = created["workspaces"][0]["terminals"].as_array().unwrap();
    assert!(
        terminals
            .iter()
            .any(|terminal| terminal["id"] == terminal_id),
        "created terminal missing from mobile workspace payload: {created}"
    );

    let input = rpc(
        &server.socket,
        "terminal.input",
        json!({
            "workspace_id": workspace_id,
            "terminal_id": terminal_id,
            "text": "printf 'CMUX_MOBILE_TERMINAL_INPUT\\n'\n"
        }),
    );
    assert_eq!(input["workspace_id"], workspace_id);
    assert_eq!(input["surface_id"], terminal_id);
    assert_eq!(input["queued"], false);
    assert!(input["terminal_seq"].as_u64().unwrap_or(0) > 0);

    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let read = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": terminal_id}),
        );
        if read["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_MOBILE_TERMINAL_INPUT")
        {
            break;
        }
        thread::sleep(Duration::from_millis(100));
    }
    let read = rpc(
        &server.socket,
        "surface.read_text",
        json!({"surface_id": terminal_id}),
    );
    assert!(
        read["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_MOBILE_TERMINAL_INPUT"),
        "terminal text was {read}"
    );

    let replay = rpc(
        &server.socket,
        "terminal.replay",
        json!({"workspace_id": workspace_id, "terminal_id": terminal_id}),
    );
    assert_eq!(replay["workspace_id"], workspace_id);
    assert_eq!(replay["surface_id"], terminal_id);
    assert_eq!(replay["render_grid"]["format"], "cmux.render-grid.v1");
    assert_eq!(replay["render_grid"]["surface_id"], terminal_id);
    assert_eq!(replay["render_grid"]["cursor"]["visible"], true);
    let cursor_row = replay["render_grid"]["cursor"]["row"]
        .as_u64()
        .expect("cursor row");
    let cursor_column = replay["render_grid"]["cursor"]["column"]
        .as_u64()
        .expect("cursor column");
    assert!(
        cursor_row < replay["render_grid"]["rows"].as_u64().unwrap(),
        "cursor row was out of bounds: {replay}"
    );
    assert!(
        cursor_column < replay["render_grid"]["columns"].as_u64().unwrap(),
        "cursor column was out of bounds: {replay}"
    );
    assert!(replay["render_grid"]["row_spans"]
        .as_array()
        .unwrap()
        .iter()
        .any(|span| span["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_MOBILE_TERMINAL_INPUT")));
    assert_eq!(replay["snapshot_format"], "ghostty.active.vt");
    assert!(
        replay["snapshot_data_b64"]
            .as_str()
            .unwrap_or_default()
            .len()
            > 4
    );

    let scroll_seed = rpc(
        &server.socket,
        "terminal.input",
        json!({
            "workspace_id": workspace_id,
            "terminal_id": terminal_id,
            "text": "i=1; while [ $i -le 35 ]; do printf 'CMUX_SCROLL_%02d\\n' \"$i\"; i=$((i + 1)); done\n"
        }),
    );
    assert_eq!(scroll_seed["workspace_id"], workspace_id);
    assert_eq!(scroll_seed["surface_id"], terminal_id);
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let read = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": terminal_id}),
        );
        if read["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_SCROLL_35")
        {
            break;
        }
        thread::sleep(Duration::from_millis(100));
    }
    let scroll_read = rpc(
        &server.socket,
        "surface.read_text",
        json!({"surface_id": terminal_id}),
    );
    assert!(
        scroll_read["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_SCROLL_35"),
        "terminal text after scroll seed was {scroll_read}"
    );
    let scroll_prefetch = rpc(
        &server.socket,
        "terminal.scroll",
        json!({
            "workspace_id": workspace_id,
            "terminal_id": terminal_id,
            "delta_lines": -5,
            "max_scrollback_rows": 5
        }),
    );
    assert_eq!(scroll_prefetch["workspace_id"], workspace_id);
    assert_eq!(scroll_prefetch["surface_id"], terminal_id);
    assert_eq!(
        scroll_prefetch["render_grid"]["format"],
        "cmux.render-grid.v1"
    );
    let scrollback_rows = scroll_prefetch["render_grid"]["scrollback_rows"]
        .as_u64()
        .expect("scrollback rows");
    assert!(
        (1..=5).contains(&scrollback_rows),
        "scrollback rows were not bounded: {scroll_prefetch}"
    );
    assert!(
        scroll_prefetch["render_grid"]["scrollback_spans"]
            .as_array()
            .unwrap()
            .iter()
            .any(|span| span["text"]
                .as_str()
                .unwrap_or_default()
                .contains("CMUX_SCROLL_")),
        "scrollback spans did not include seeded output: {scroll_prefetch}"
    );

    let paste = rpc(
        &server.socket,
        "terminal.paste",
        json!({
            "workspace_id": workspace_id,
            "terminal_id": terminal_id,
            "text": "CMUX_MOBILE_PASTE_DRAFT",
            "submit_key": "none"
        }),
    );
    assert_eq!(paste["submitted"], false);
    let read_after_paste = rpc(
        &server.socket,
        "surface.read_text",
        json!({"surface_id": terminal_id}),
    );
    assert!(
        read_after_paste["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_MOBILE_PASTE_DRAFT"),
        "terminal text after paste was {read_after_paste}"
    );

    let image_bytes = b"fake png bytes";
    let paste_image = rpc(
        &server.socket,
        "terminal.paste_image",
        json!({
            "workspace_id": workspace_id,
            "terminal_id": terminal_id,
            "image_base64": base64::engine::general_purpose::STANDARD.encode(image_bytes),
            "image_format": "png"
        }),
    );
    assert_eq!(paste_image["workspace_id"], workspace_id);
    assert_eq!(paste_image["surface_id"], terminal_id);
    assert_eq!(paste_image["queued"], false);
    assert_eq!(paste_image["bytes"], image_bytes.len());
    assert_eq!(paste_image["format"], "png");
    let image_path = paste_image["image_path"].as_str().expect("image path");
    assert_eq!(
        std::fs::read(image_path).expect("stored mobile paste image"),
        image_bytes
    );
    let read_after_image = rpc(
        &server.socket,
        "surface.read_text",
        json!({"surface_id": terminal_id}),
    );
    assert!(
        read_after_image["text"]
            .as_str()
            .unwrap_or_default()
            .contains(image_path),
        "terminal text after image paste was {read_after_image}"
    );
    let invalid_image = rpc_response(
        &server.socket,
        "mobile.terminal.paste_image",
        json!({
            "workspace_id": workspace_id,
            "terminal_id": terminal_id,
            "image_base64": "not base64"
        }),
    );
    assert_eq!(invalid_image["ok"], false, "response was {invalid_image}");
    assert_eq!(invalid_image["error"]["code"], "invalid_params");

    let viewport = rpc(
        &server.socket,
        "terminal.viewport",
        json!({"workspace_id": workspace_id, "terminal_id": terminal_id}),
    );
    assert_eq!(viewport["surface_id"], terminal_id);
    assert!(viewport["columns"].as_u64().unwrap_or(0) > 0);
    assert!(viewport["rows"].as_u64().unwrap_or(0) > 0);

    let scroll = rpc(
        &server.socket,
        "terminal.scroll",
        json!({"workspace_id": workspace_id, "terminal_id": terminal_id, "delta_lines": 3}),
    );
    assert_eq!(scroll["surface_id"], terminal_id);
    assert_eq!(scroll["delta_lines"], 3.0);

    let mouse = rpc(
        &server.socket,
        "terminal.mouse",
        json!({"workspace_id": workspace_id, "terminal_id": terminal_id, "col": 4, "row": 2}),
    );
    assert_eq!(mouse["surface_id"], terminal_id);
    assert_eq!(mouse["col"], 4);
    assert_eq!(mouse["row"], 2);
}

#[test]
fn mobile_terminal_replay_uses_renderer_fallback_styles_and_modes() {
    let server = start_server();
    let workspace = rpc(&server.socket, "workspace.current", json!({}));
    let workspace_id = workspace["workspace_id"].as_str().unwrap();
    let marker = "CMUX_MOBILE_STYLE_FRAME";
    let command =
        format!("printf '\\033[38;2;7;8;9m{marker}\\033[0m\\033[5 q\\033[?2004h\\n'; sleep 1");
    let created = rpc(
        &server.socket,
        "terminal.create",
        json!({
            "workspace_id": workspace_id,
            "title": "mobile styled replay",
            "command": command
        }),
    );
    let terminal_id = created["surface_id"].as_str().expect("terminal id");
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let text = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": terminal_id}),
        );
        if text["text"].as_str().unwrap_or_default().contains(marker) {
            break;
        }
        thread::sleep(Duration::from_millis(50));
    }

    let replay = rpc(
        &server.socket,
        "terminal.replay",
        json!({"workspace_id": workspace_id, "terminal_id": terminal_id}),
    );
    let grid = &replay["render_grid"];
    let span = grid["row_spans"]
        .as_array()
        .unwrap()
        .iter()
        .find(|span| {
            span["style_id"].as_u64().unwrap_or(0) != 0
                && span["text"]
                    .as_str()
                    .is_some_and(|text| text.contains(marker))
        })
        .unwrap_or_else(|| panic!("styled marker span missing from replay: {replay}"));
    let style_id = span["style_id"].as_u64().expect("style id");
    let style = grid["styles"]
        .as_array()
        .unwrap()
        .iter()
        .find(|style| style["id"].as_u64() == Some(style_id))
        .unwrap_or_else(|| panic!("style missing from replay: {replay}"));
    assert_eq!(style["fg"], json!({"r": 7, "g": 8, "b": 9}));
    assert_eq!(grid["cursor"]["style"], "bar");
    assert!(grid["modes"]
        .as_array()
        .unwrap()
        .iter()
        .any(|mode| mode == "bracketed_paste"));
}

#[test]
fn cli_notification_help_matches_contract_without_socket() {
    for (command, expected) in [
        ("list-notifications", "Usage: cmux list-notifications"),
        ("dismiss-notification", "Usage: cmux dismiss-notification"),
        (
            "mark-notification-read",
            "Usage: cmux mark-notification-read",
        ),
        ("open-notification", "Usage: cmux open-notification"),
        ("jump-to-unread", "Usage: cmux jump-to-unread"),
        ("clear-notifications", "Usage: cmux clear-notifications"),
        (
            "right-sidebar",
            "Usage: cmux right-sidebar <command> [flags]",
        ),
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_cmux"))
            .arg(command)
            .arg("--help")
            .output()
            .expect("run notification help");
        assert!(
            output.status.success(),
            "{command} help failed: stdout={} stderr={}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        let stdout = String::from_utf8(output.stdout).expect("help utf8");
        assert!(
            stdout.contains(expected),
            "{command} help did not contain {expected:?}: {stdout}"
        );
    }
}

#[test]
fn needs_input_notification_includes_custom_terminal_title() {
    let server = start_server();
    rpc(
        &server.socket,
        "app.focus_override.set",
        json!({"state": "inactive"}),
    );
    let workspace_id = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let surface_id = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": workspace_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let custom_title = "custom agent terminal";
    rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "action": "rename",
            "title": custom_title
        }),
    );

    let lifecycle = rpc(
        &server.socket,
        "sidebar.agent_lifecycle.set",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "key": "codex",
            "lifecycle": "needsInput"
        }),
    );
    assert_eq!(lifecycle["lifecycle"], "needsInput");

    let stdout = cli(
        &server.socket,
        &[
            "set-agent-lifecycle",
            "codex",
            "needsInput",
            "--workspace",
            &workspace_id,
            "--panel",
            &surface_id,
        ],
    );
    assert_eq!(stdout.trim(), "OK");

    let notifications = rpc(&server.socket, "notification.list", json!({}));
    let row = notifications["notifications"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["surface_id"].as_str() == Some(surface_id.as_str()))
        .expect("expected targeted waiting-input notification");
    assert!(
        row["title"]
            .as_str()
            .unwrap_or_default()
            .contains(custom_title),
        "notification title should include renamed terminal title: {row}"
    );
    assert_eq!(row["body"], "Agent needs input");
}

#[test]
fn background_terminal_title_updates_sidebar_without_focus() {
    let server = start_server();
    let active_workspace = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let background_workspace = rpc(&server.socket, "workspace.create", json!({"focus": false}))
        ["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let background_surface = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": background_workspace}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let title = "Claude Code loading";

    rpc(
        &server.socket,
        "surface.send_text",
        json!({
            "workspace_id": background_workspace,
            "surface_id": background_surface,
            "text": format!("printf '\\033]0;{title}\\007'\n")
        }),
    );

    let current = rpc(&server.socket, "workspace.current", json!({}));
    assert_eq!(current["workspace_id"], active_workspace);

    let surfaces = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": background_workspace}),
    );
    let surface_rows = surfaces["surfaces"].as_array().unwrap();
    assert_eq!(surface_rows[0]["title"], title);

    let workspaces = rpc(&server.socket, "workspace.list", json!({}));
    let workspace_row = workspaces["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == background_workspace)
        .expect("background workspace row");
    assert_eq!(workspace_row["title"], title);

    let manual_workspace_title = "manual workspace title";
    let manual_workspace = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": manual_workspace_title, "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let manual_surface = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": manual_workspace}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    rpc(
        &server.socket,
        "surface.send_text",
        json!({
            "workspace_id": manual_workspace,
            "surface_id": manual_surface,
            "text": "printf '\\033]0;terminal should not win\\007'\n"
        }),
    );
    let workspaces = rpc(&server.socket, "workspace.list", json!({}));
    let workspace_row = workspaces["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == manual_workspace)
        .expect("manual workspace row");
    assert_eq!(workspace_row["title"], manual_workspace_title);
}

#[test]
fn background_initial_command_title_updates_sidebar_without_focus() {
    let server = start_server();
    let active_workspace = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let title = "Background PTY title";
    let background_workspace = rpc(
        &server.socket,
        "workspace.create",
        json!({
            "focus": false,
            "initial_command": format!("printf '\\033]2;{title}\\007'")
        }),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    let deadline = Instant::now() + Duration::from_secs(3);
    let mut latest = Value::Null;
    while Instant::now() < deadline {
        let workspaces = rpc(&server.socket, "workspace.list", json!({}));
        latest = workspaces["workspaces"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["workspace_id"] == background_workspace)
            .cloned()
            .unwrap_or(Value::Null);
        if latest["title"] == title {
            break;
        }
        thread::sleep(Duration::from_millis(50));
    }

    assert_eq!(latest["title"], title, "workspace row was {latest}");
    let current = rpc(&server.socket, "workspace.current", json!({}));
    assert_eq!(current["workspace_id"], active_workspace);
}

#[test]
fn app_shell_script_manages_core_workspace_and_split_state() {
    let script = [
        "status",
        "new-workspace scripted",
        "new-workspace nexted",
        "previous-workspace",
        "next-workspace",
        "last-workspace",
        "split right",
        "last-pane",
        "current-workspace",
        "current-surface",
        "panes",
        "surfaces",
        "quit",
    ]
    .join("\n");
    let output = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("app")
        .arg("--script")
        .arg(script)
        .env("CMUX_SESSION_SNAPSHOT_DISABLE", "1")
        .output()
        .expect("run app shell");
    assert!(
        output.status.success(),
        "app shell failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8(output.stdout).expect("stdout utf8");
    assert!(stdout.contains("window=window:"));
    assert!(stdout.contains("workspace=workspace:"));
    assert!(stdout.contains("workspace=workspace:2 selected"));
    assert!(stdout.contains("workspace=workspace:3 selected"));
    assert!(stdout.contains("focused pane=pane:1"));
    assert!(stdout.contains("surface=surface:1 workspace=workspace:2 pane=pane:1"));
    assert!(stdout.contains("pane:0"));
    assert!(stdout.contains("pane:1"));
    assert!(stdout.contains("surface:0"));
    assert!(stdout.contains("surface:1"));
    assert!(stdout.contains("bye"));
}

#[test]
fn app_shell_script_exposes_workspace_and_tab_actions() {
    let script = [
        "rename-workspace shell workspace",
        "workspace-action pin",
        "workspace-action mark-unread",
        "workspace-action mark-read",
        "workspace-action unpin",
        "workspaces",
        "rename-tab shell root tab",
        "tab-action pin",
        "tab-action mark-unread",
        "tab-action mark-read",
        "tab-action unpin",
        "terminal",
        "rename-tab --surface surface:2 shell right tab",
        "tab-action --surface surface:1 pin",
        "tab-action --surface surface:2 close-left",
        "surfaces",
        "quit",
    ]
    .join("\n");
    let output = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("app")
        .arg("--script")
        .arg(script)
        .env("CMUX_SESSION_SNAPSHOT_DISABLE", "1")
        .output()
        .expect("run app shell");
    assert!(
        output.status.success(),
        "app shell failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8(output.stdout).expect("stdout utf8");
    assert!(
        stdout.contains("OK workspace=workspace:1 title=shell workspace"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("OK action=pin workspace=workspace:1"),
        "stdout was {stdout}"
    );
    assert!(stdout.contains("pinned=true"), "stdout was {stdout}");
    assert!(stdout.contains("unread=true"), "stdout was {stdout}");
    assert!(stdout.contains("unread=false"), "stdout was {stdout}");
    assert!(stdout.contains("pinned=false"), "stdout was {stdout}");
    assert!(stdout.contains("shell workspace"), "stdout was {stdout}");
    assert!(
        stdout.contains("OK action=rename tab=tab:1 title=shell root tab"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("OK action=rename tab=tab:2 title=shell right tab"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("OK action=close_left tab=tab:2"),
        "stdout was {stdout}"
    );
    assert!(stdout.contains("closed=0"), "stdout was {stdout}");
    assert!(stdout.contains("skipped_pinned=1"), "stdout was {stdout}");
    assert!(stdout.contains("shell root tab"), "stdout was {stdout}");
    assert!(stdout.contains("shell right tab"), "stdout was {stdout}");
    assert!(stdout.contains("bye"), "stdout was {stdout}");
}

