#[test]
fn app_shell_exposes_control_socket_over_shared_state() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let socket = tmp.path().join("cmux-app.sock").display().to_string();
    let script = ["status", "sleep 2000", "workspaces", "quit"].join("\n");
    let child = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("app")
        .arg("--socket")
        .arg(&socket)
        .arg("--script")
        .arg(script)
        .env("CMUX_SESSION_SNAPSHOT_DISABLE", "1")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn app shell");

    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        if UnixStream::connect(&socket).is_ok() {
            break;
        }
        thread::sleep(Duration::from_millis(25));
    }
    assert!(
        UnixStream::connect(&socket).is_ok(),
        "app socket was not created"
    );

    let created = cli(
        &socket,
        &[
            "new-workspace",
            "--focus",
            "true",
            "--name",
            "from external cli",
        ],
    );
    assert!(
        created.starts_with("OK workspace:"),
        "unexpected create output: {created}"
    );
    let ident: Value = serde_json::from_str(&cli(&socket, &["--json", "identify"])).unwrap();
    assert_eq!(ident["workspace_ref"], "workspace:2");

    let output = child.wait_with_output().expect("wait app shell");
    assert!(
        output.status.success(),
        "app shell failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8(output.stdout).expect("stdout utf8");
    assert!(stdout.contains("from external cli"), "stdout was {stdout}");
    assert!(stdout.contains("workspace:2"), "stdout was {stdout}");
}

#[test]
fn app_shell_script_exposes_feed_and_notification_commands() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let socket = tmp.path().join("cmux-app-feed.sock").display().to_string();
    let script = [
        "sleep 2000",
        "feed pending",
        "notify app-shell-notification",
        "notifications",
        "jump-unread",
        "clear-notifications",
        "notifications",
        "quit",
    ]
    .join("\n");
    let child = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("app")
        .arg("--socket")
        .arg(&socket)
        .arg("--script")
        .arg(script)
        .env("CMUX_SESSION_SNAPSHOT_DISABLE", "1")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn app shell");

    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        if UnixStream::connect(&socket).is_ok() {
            break;
        }
        thread::sleep(Duration::from_millis(25));
    }
    assert!(
        UnixStream::connect(&socket).is_ok(),
        "app socket was not created"
    );

    rpc(
        &socket,
        "feed.push",
        json!({
            "event": {
                "session_id": "codex-app-shell-session",
                "hook_event_name": "PermissionRequest",
                "_source": "codex",
                "_opencode_request_id": "req-app-shell",
                "tool_name": "Shell",
                "tool_input": {"command": "cargo test"}
            }
        }),
    );

    let output = child.wait_with_output().expect("wait app shell");
    assert!(
        output.status.success(),
        "app shell failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8(output.stdout).expect("stdout utf8");
    assert!(
        stdout.contains("pending\tcodex\tpermissionRequest\treq-app-shell\tShell"),
        "stdout was {stdout}"
    );
    assert!(stdout.contains("notification="), "stdout was {stdout}");
    assert!(
        stdout.contains("app-shell-notification"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("jumped notification") && stdout.contains("opened=true"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("cleared 1 notification"),
        "stdout was {stdout}"
    );
    assert!(stdout.contains("No notifications."), "stdout was {stdout}");
}

#[test]
fn app_shell_script_exposes_sidebar_palette_and_shortcut_chrome() {
    let config_root = tempfile::tempdir().expect("app shell config root");
    let config_home = config_root.path().join("config");
    let config_path = config_home.join("cmux/cmux.json");
    std::fs::create_dir_all(config_path.parent().unwrap()).expect("create config directory");
    std::fs::write(&config_path, r#"{"rightSidebar.beta.feed.enabled":true}"#)
        .expect("write app shell config");
    let script = [
        "right-sidebar set feed",
        "right-sidebar mode",
        "palette commands",
        "palette type toggle sidebar",
        "palette results",
        "shortcuts show",
        "shortcuts state",
        "quit",
    ]
    .join("\n");
    let output = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("app")
        .arg("--script")
        .arg(script)
        .env("CMUX_SESSION_SNAPSHOT_DISABLE", "1")
        .env("XDG_CONFIG_HOME", config_home)
        .output()
        .expect("run app shell");
    assert!(
        output.status.success(),
        "app shell failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8(output.stdout).expect("stdout utf8");
    assert!(
        stdout.contains("right-sidebar action=set visible=true mode=feed focused=true"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("right-sidebar action=mode visible=true mode=feed focused=false"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("palette visible=true mode=commands"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("palette.toggleSidebar\tToggle Sidebar"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("palette.toggleSidebar\tToggle Sidebar\tSuper+B"),
        "palette results should include Linux shortcut labels: {stdout}"
    );
    assert!(
        stdout.contains("shortcuts visible=true"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("new_terminal\tNew Terminal\tSuper+T\tCreate a terminal"),
        "shortcuts output should include Linux shortcut rows: {stdout}"
    );
    assert!(stdout.contains("bye"), "stdout was {stdout}");
}

#[test]
fn browser_find_and_snapshot_refs_drive_actions() {
    let server = start_server();
    let html = r#"<!doctype html>
<html>
  <head><title>cmux-browser-ref-contract</title></head>
  <body>
    <label for="name">Agent Name</label>
    <input id="name" placeholder="Type name" title="name-title" data-testid="name-field" />
    <button id="action-btn">Submit Action</button>
    <div id="status">ready</div>
    <ul><li class="row">row-1</li><li class="row">row-2</li><li class="row">row-3</li></ul>
  </body>
</html>"#;
    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": format!("data:text/html,{html}")}),
    );
    let surface_id = opened["surface_id"].as_str().expect("surface id");

    rpc(
        &server.socket,
        "browser.wait",
        json!({
            "surface_id": surface_id,
            "text_contains": "row-2",
            "url_contains": "data:text/html",
            "function": "document.querySelector('#action-btn') !== null",
            "load_state": "complete"
        }),
    );
    rpc(
        &server.socket,
        "browser.wait",
        json!({
            "surface_id": surface_id,
            "load_state": "interactive"
        }),
    );
    assert_eq!(
        cli(
            &server.socket,
            &["browser", surface_id, "wait", "#action-btn"]
        )
        .trim(),
        "OK"
    );
    assert_eq!(
        cli(
            &server.socket,
            &[
                "browser",
                surface_id,
                "wait",
                "--text",
                "row-2",
                "--url-contains",
                "data:text/html",
                "--function",
                "document.querySelector('#action-btn') !== null",
                "--load-state",
                "complete",
            ],
        )
        .trim(),
        "OK"
    );
    let wait_failure = cli_failure(
        &server.socket,
        &["browser", surface_id, "wait", "--text", "missing-row"],
    );
    assert!(
        wait_failure.contains("timed out waiting for text missing-row"),
        "unexpected wait failure: {wait_failure}"
    );

    let role = rpc(
        &server.socket,
        "browser.find.role",
        json!({"surface_id": surface_id, "role": "button", "name": "submit"}),
    );
    assert_eq!(role["selector"], "#action-btn");
    let button_ref = role["element_ref"].as_str().expect("button ref");
    assert!(button_ref.starts_with("@e"), "role payload was {role}");

    let placeholder = rpc(
        &server.socket,
        "browser.find.placeholder",
        json!({"surface_id": surface_id, "placeholder": "Type name"}),
    );
    assert_eq!(placeholder["selector"], "#name");
    let input_ref = placeholder["element_ref"].as_str().expect("input ref");

    rpc(
        &server.socket,
        "browser.fill",
        json!({"surface_id": surface_id, "selector": input_ref, "text": "agent-ref"}),
    );
    rpc(
        &server.socket,
        "browser.click",
        json!({"surface_id": surface_id, "selector": button_ref}),
    );
    let status = rpc(
        &server.socket,
        "browser.get.text",
        json!({"surface_id": surface_id, "selector": "#status"}),
    );
    assert_eq!(status["value"], "agent-ref");

    let snapshot = rpc(
        &server.socket,
        "browser.snapshot",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(snapshot["refs"]["e2"], "#name");
    rpc(
        &server.socket,
        "browser.fill",
        json!({"surface_id": surface_id, "selector": "e2", "text": "snapshot-ref"}),
    );
    let value = rpc(
        &server.socket,
        "browser.get.value",
        json!({"surface_id": surface_id, "selector": "#name"}),
    );
    assert_eq!(value["value"], "snapshot-ref");

    let count = rpc(
        &server.socket,
        "browser.get.count",
        json!({"surface_id": surface_id, "selector": "li.row"}),
    );
    assert_eq!(count["count"], 3);
}

#[test]
fn browser_open_split_preserves_terminal_focus_by_default() {
    let server = start_server();
    let before = rpc(&server.socket, "surface.current", json!({}));
    let terminal_surface = before["surface_id"].as_str().unwrap().to_string();

    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "about:blank"}),
    );
    let browser_surface = opened["surface_id"].as_str().unwrap().to_string();
    assert_ne!(browser_surface, terminal_surface);

    let after_default_open = rpc(&server.socket, "surface.current", json!({}));
    assert_eq!(after_default_open["surface_id"], terminal_surface);

    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "up"}),
    );
    let after_key = rpc(&server.socket, "surface.current", json!({}));
    assert_eq!(after_key["surface_id"], terminal_surface);

    let focused = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "about:blank", "focus": true}),
    );
    let focused_browser = focused["surface_id"].as_str().unwrap().to_string();
    let after_explicit_focus = rpc(&server.socket, "surface.current", json!({}));
    assert_eq!(after_explicit_focus["surface_id"], focused_browser);
}

#[test]
fn browser_window_new_creates_browser_surface_in_new_window() {
    let server = start_server();
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().expect("methods");
    for expected in ["browser.window.new", "browser.window.create"] {
        assert!(
            methods.iter().any(|method| method == expected),
            "missing {expected} in capabilities: {capabilities}"
        );
    }
    assert_eq!(capabilities["features"]["browser_window_new"], true);

    let before_count = rpc(&server.socket, "window.list", json!({}))["windows"]
        .as_array()
        .unwrap()
        .len();
    let created = rpc(
        &server.socket,
        "browser.window.new",
        json!({
            "url": "data:text/html,<title>RPC Window</title>",
            "title": "Agent Browser",
            "workspace_title": "Browser Workspace"
        }),
    );
    assert_eq!(created["created_window"], true);
    assert_eq!(created["created_split"], false);
    assert_eq!(created["focused"], true);
    let window_id = created["window_id"].as_str().unwrap();
    let workspace_id = created["workspace_id"].as_str().unwrap();
    let surface_id = created["surface_id"].as_str().unwrap();

    let windows = rpc(&server.socket, "window.list", json!({}));
    let rows = windows["windows"].as_array().unwrap();
    assert_eq!(rows.len(), before_count + 1);
    let row = rows
        .iter()
        .find(|row| row["id"] == window_id)
        .expect("new browser window row");
    assert_eq!(row["title"], "Agent Browser");
    assert_eq!(row["workspace_count"], 1);
    assert_eq!(row["selected"], true);

    let surfaces = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    );
    let browser_surface = surfaces["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|surface| surface["surface_id"] == surface_id)
        .expect("browser surface row");
    assert_eq!(browser_surface["type"], "browser");
    assert_eq!(
        browser_surface["url"],
        "data:text/html,<title>RPC Window</title>"
    );
    let title = rpc(
        &server.socket,
        "browser.get.title",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(title["title"], "RPC Window");

    let cli_created = cli_json_with_env(
        &server.socket,
        &[
            "browser",
            "window",
            "new",
            "data:text/html,<title>CLI Window</title>",
            "--title",
            "CLI Browser",
        ],
        &[],
    );
    let cli_surface_ref = cli_created["surface_ref"].as_str().unwrap();
    assert!(cli_surface_ref.starts_with("surface:"));
    assert!(cli_created["window_ref"]
        .as_str()
        .unwrap()
        .starts_with("window:"));
    assert!(cli_created.get("surface_id").is_none());
    assert_eq!(
        cli_created["url"],
        "data:text/html,<title>CLI Window</title>"
    );
    let cli_title = rpc(
        &server.socket,
        "browser.get.title",
        json!({"surface_id": cli_surface_ref}),
    );
    assert_eq!(cli_title["title"], "CLI Window");
}

#[test]
fn browser_profiles_and_cookie_import_match_macos_contract() {
    let server = start_server();
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    for method in [
        "browser.profiles.list",
        "browser.profiles.create",
        "browser.profiles.select",
        "browser.profiles.rename",
        "browser.profiles.clear",
        "browser.profiles.delete",
        "browser.import.cookies",
        "browser.import.data",
        "browser.import.sources",
        "browser.history.list",
        "browser.history.clear",
        "browser.bookmarks.list",
        "browser.bookmarks.clear",
    ] {
        assert!(
            methods.iter().any(|advertised| advertised == method),
            "{method} was not advertised: {capabilities}"
        );
    }
    assert_eq!(capabilities["features"]["browser_profiles"], true);
    assert_eq!(capabilities["features"]["browser_profile_isolation"], true);
    assert_eq!(capabilities["features"]["browser_import_cookies"], true);
    assert_eq!(capabilities["features"]["browser_import_history"], true);
    assert_eq!(capabilities["features"]["browser_import_bookmarks"], true);
    assert_eq!(capabilities["features"]["browser_import_settings"], true);
    assert_eq!(capabilities["features"]["browser_history"], true);
    assert_eq!(capabilities["features"]["browser_bookmarks"], true);

    let default_profile_id = "52B43C05-4A1D-45D3-8FD5-9EF94952E445";
    let initial = rpc(&server.socket, "browser.profiles.list", json!({}));
    assert_eq!(initial["current_profile_id"], default_profile_id);
    assert_eq!(initial["profiles"].as_array().unwrap().len(), 1);
    assert_eq!(initial["profiles"][0]["id"], default_profile_id);
    assert_eq!(initial["profiles"][0]["slug"], "default");
    assert_eq!(initial["profiles"][0]["built_in_default"], true);
    assert_eq!(initial["profiles"][0]["current"], true);
    assert_eq!(initial["profiles"][0]["history_entry_count"], 0);
    assert_eq!(initial["profiles"][0]["bookmark_entry_count"], 0);

    let cli_initial = cli_json_with_env(&server.socket, &["browser", "profiles", "list"], &[]);
    assert_eq!(cli_initial["current_profile_id"], default_profile_id);
    assert_eq!(cli_initial["profiles"].as_array().unwrap().len(), 1);
    assert_eq!(cli_initial["profiles"][0]["slug"], "default");

    let cli_created = cli_json_with_env(
        &server.socket,
        &["browser", "profiles", "create", "CLI Profile"],
        &[],
    );
    assert_eq!(cli_created["created"], true);
    assert_eq!(cli_created["profile"]["name"], "CLI Profile");
    assert_eq!(cli_created["profile"]["slug"], "cli-profile");
    let cli_profile_id = cli_created["profile"]["id"].as_str().unwrap().to_string();

    let cli_renamed = cli_json_with_env(
        &server.socket,
        &[
            "browser",
            "profiles",
            "rename",
            "cli-profile",
            "CLI Renamed",
        ],
        &[],
    );
    assert_eq!(cli_renamed["renamed"], true);
    assert_eq!(cli_renamed["profile"]["id"], cli_profile_id);
    assert_eq!(cli_renamed["profile"]["name"], "CLI Renamed");
    assert_eq!(cli_renamed["profile"]["slug"], "cli-renamed");

    let cli_cleared = cli_json_with_env(
        &server.socket,
        &["browser", "profiles", "clear", "default", "--force"],
        &[],
    );
    assert_eq!(cli_cleared["cleared"], true);
    assert_eq!(cli_cleared["profiles"][0]["slug"], "default");

    let cli_deleted = cli_json_with_env(
        &server.socket,
        &["browser", "profiles", "delete", "cli-renamed"],
        &[],
    );
    assert_eq!(cli_deleted["deleted"], true);
    assert_eq!(cli_deleted["profile"]["id"], cli_profile_id);

    let cli_alias = cli_json_with_env(&server.socket, &["browser", "profile", "ls"], &[]);
    assert_eq!(cli_alias["current_profile_id"], default_profile_id);
    assert_eq!(cli_alias["profiles"].as_array().unwrap().len(), 1);

    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "about:blank"}),
    );
    let browser_surface = opened["surface_id"].as_str().unwrap();
    let _ = rpc(
        &server.socket,
        "browser.navigate",
        json!({"surface_id": browser_surface, "url": "https://example.test/one"}),
    );
    let _ = rpc(
        &server.socket,
        "browser.navigate",
        json!({"surface_id": browser_surface, "url": "https://example.test/two"}),
    );

    let created = rpc(
        &server.socket,
        "browser.profiles.create",
        json!({"name": "  QA Profile  "}),
    );
    assert_eq!(created["created"], true);
    let created_id = created["profile"]["id"].as_str().unwrap().to_string();
    uuid::Uuid::parse_str(&created_id).expect("profile id should be uuid");
    assert_eq!(created["profile"]["name"], "QA Profile");
    assert_eq!(created["profile"]["slug"], "qa-profile");
    assert_eq!(created["profile"]["built_in_default"], false);
    assert_eq!(created["profile"]["current"], true);

    let renamed = rpc(
        &server.socket,
        "browser.profiles.rename",
        json!({"profile": "qa-profile", "new_name": "Renamed Profile"}),
    );
    assert_eq!(renamed["renamed"], true);
    assert_eq!(renamed["old_name"], "QA Profile");
    assert_eq!(renamed["profile"]["id"], created_id);
    assert_eq!(renamed["profile"]["name"], "Renamed Profile");
    assert_eq!(renamed["profile"]["slug"], "renamed-profile");

    let selected = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "browser",
            "profiles",
            "select",
            "renamed-profile",
            "--surface",
            browser_surface,
        ],
        &[],
    );
    assert_eq!(selected["selected"], true);
    assert_eq!(selected["current_profile_id"], created_id);
    assert_eq!(selected["surface_id"], browser_surface);
    assert_eq!(selected["surface_changed"], true);
    assert_eq!(selected["previous_surface_profile_id"], default_profile_id);
    let selected_identity = rpc(
        &server.socket,
        "browser.identify",
        json!({"surface_id": browser_surface}),
    );
    assert_eq!(selected_identity["profile_id"], created_id);
    assert_eq!(selected_identity["url"], "https://example.test/two");
    let _ = rpc(
        &server.socket,
        "browser.back",
        json!({"surface_id": browser_surface}),
    );
    let selected_back_identity = rpc(
        &server.socket,
        "browser.identify",
        json!({"surface_id": browser_surface}),
    );
    assert_eq!(selected_back_identity["url"], "https://example.test/one");
    let _ = rpc(
        &server.socket,
        "browser.forward",
        json!({"surface_id": browser_surface}),
    );
    let selected_forward_identity = rpc(
        &server.socket,
        "browser.identify",
        json!({"surface_id": browser_surface}),
    );
    assert_eq!(selected_forward_identity["url"], "https://example.test/two");
    let _ = rpc(
        &server.socket,
        "browser.cookies.set",
        json!({
            "surface_id": browser_surface,
            "name": "profile_only",
            "value": "created"
        }),
    );

    let selected_default = rpc(
        &server.socket,
        "browser.profiles.select",
        json!({"profile": "default", "surface_id": browser_surface}),
    );
    assert_eq!(selected_default["selected"], true);
    assert_eq!(selected_default["current_profile_id"], default_profile_id);
    assert_eq!(selected_default["surface_changed"], true);
    assert_eq!(selected_default["previous_surface_profile_id"], created_id);
    let default_identity = rpc(
        &server.socket,
        "browser.identify",
        json!({"surface_id": browser_surface}),
    );
    assert_eq!(default_identity["profile_id"], default_profile_id);
    let default_cookies = rpc(
        &server.socket,
        "browser.cookies.get",
        json!({"surface_id": browser_surface}),
    );
    assert!(!default_cookies["cookies"]
        .as_array()
        .unwrap()
        .iter()
        .any(|cookie| cookie["name"] == "profile_only"));

    let selected_default_again = rpc(
        &server.socket,
        "browser.profiles.select",
        json!({"profile": "default", "surface_id": browser_surface}),
    );
    assert_eq!(selected_default_again["surface_changed"], false);

    let selected_created_again = rpc(
        &server.socket,
        "browser.profiles.select",
        json!({"profile": created_id, "surface_id": browser_surface}),
    );
    assert_eq!(selected_created_again["surface_changed"], true);
    let selected_snapshot = rpc(&server.socket, "renderer.snapshot", json!({}));
    let selected_browser_view = selected_snapshot["surface_views"]
        .as_array()
        .unwrap()
        .iter()
        .find(|view| view["surface_id"] == browser_surface)
        .expect("selected browser view");
    assert!(selected_browser_view["browser"]["runtime_actions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|action| action["cookie"]["name"] == "profile_only"));
    let _ = rpc(
        &server.socket,
        "browser.profiles.select",
        json!({"profile": "default", "surface_id": browser_surface}),
    );

    let invalid_surface = rpc_response(
        &server.socket,
        "browser.profiles.select",
        json!({"profile": created_id, "surface_id": "surface:9999"}),
    );
    assert_eq!(invalid_surface["ok"], false);
    let profiles_after_invalid = rpc(&server.socket, "browser.profiles.list", json!({}));
    assert_eq!(
        profiles_after_invalid["current_profile_id"],
        default_profile_id
    );

    let imported = rpc(
        &server.socket,
        "browser.import.cookies",
        json!({
            "browser": "Fixture Browser",
            "source_profile": "Chrome Default",
            "destination_profile": "default",
            "domain": "example.test",
            "cookies": [
                {"name": "session", "value": "abc123", "domain": ".example.test"},
                {"name": "other", "value": "ignored", "domain": "elsewhere.test"},
                {"name": "", "value": "ignored", "domain": "example.test"}
            ]
        }),
    );
    assert_eq!(imported["browser"], "Fixture Browser");
    assert_eq!(imported["scope"], "cookiesOnly");
    assert_eq!(imported["domain_filters"], json!(["example.test"]));
    assert_eq!(imported["created_destination_profiles"], json!([]));
    assert_eq!(imported["imported_cookies"], 1);
    assert_eq!(imported["skipped_cookies"], 2);
    assert_eq!(imported["imported_history_entries"], 0);
    assert_eq!(
        imported["entries"][0]["source_profiles"],
        json!(["Chrome Default"])
    );
    assert_eq!(imported["entries"][0]["destination_profile"], "Default");
    assert_eq!(imported["entries"][0]["scope"], "cookiesOnly");
    assert_eq!(imported["entries"][0]["imported_cookies"], 1);

    let scoped_import = rpc(
        &server.socket,
        "browser.import.cookies",
        json!({
            "browser": "Fixture Browser",
            "source_profile": "Chrome Default",
            "destination_profile": "default",
            "scope": "cookies-and-history",
            "domain": "example.test",
            "cookies": [{"name": "scoped", "value": "yes", "domain": "example.test"}],
            "history": [
                {
                    "url": "https://example.test/docs#old",
                    "title": "Older Docs",
                    "lastVisitedMs": 1000,
                    "visitCount": 2
                },
                {
                    "url": "https://example.test/docs#new",
                    "title": "Current Docs",
                    "lastVisitedMs": 2000,
                    "visitCount": 5
                },
                {
                    "url": "https://elsewhere.test/ignored",
                    "title": "Wrong Domain",
                    "lastVisitedMs": 3000,
                    "visitCount": 1
                }
            ]
        }),
    );
    assert_eq!(scoped_import["scope"], "cookiesAndHistory");
    assert_eq!(scoped_import["entries"][0]["scope"], "cookiesAndHistory");
    assert_eq!(scoped_import["imported_history_entries"], 2);
    assert_eq!(scoped_import["skipped_history_entries"], 1);

    let history = rpc(
        &server.socket,
        "browser.history.list",
        json!({"profile": "default"}),
    );
    let imported_history = history["entries"]
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["url"] == "https://example.test/docs")
        .expect("imported history entry");
    assert_eq!(imported_history["title"], "Current Docs");
    assert_eq!(imported_history["visitCount"], 5);
    let history_id = imported_history["id"].as_str().expect("history id");
    uuid::Uuid::parse_str(history_id).expect("history id should be uuid");

    let cli_history = cli_json_with_env(
        &server.socket,
        &[
            "browser",
            "history",
            "search",
            "current",
            "--profile",
            "default",
            "--limit",
            "1",
        ],
        &[],
    );
    assert_eq!(cli_history["query"], "current");
    assert_eq!(cli_history["limit"], 1);
    assert_eq!(cli_history["entries"].as_array().unwrap().len(), 1);
    assert_eq!(cli_history["entries"][0]["title"], "Current Docs");

    let cookies = rpc(
        &server.socket,
        "browser.cookies.get",
        json!({"surface_id": browser_surface}),
    );
    assert!(
        cookies["cookies"]
            .as_array()
            .unwrap()
            .iter()
            .any(|cookie| { cookie["name"] == "session" && cookie["value"] == "abc123" }),
        "imported cookie was not visible on default browser surface: {cookies}"
    );

    let cleared = rpc(
        &server.socket,
        "browser.profiles.clear",
        json!({"profile": "default", "force": true}),
    );
    assert_eq!(cleared["cleared"], true);
    assert_eq!(cleared["count"], 1);
    assert_eq!(cleared["profiles"][0]["id"], default_profile_id);
    assert_eq!(cleared["profiles"][0]["slug"], "default");
    assert_eq!(cleared["profiles"][0]["cleared_history"], true);
    assert!(cleared["profiles"][0]["cleared_website_data_types"]
        .as_array()
        .unwrap()
        .iter()
        .any(|data_type| data_type == "WKWebsiteDataTypeCookies"));
    let history_after_clear = rpc(
        &server.socket,
        "browser.history.list",
        json!({"profile": "default"}),
    );
    assert_eq!(history_after_clear["total"], 0);
    assert!(history_after_clear["entries"]
        .as_array()
        .unwrap()
        .is_empty());

    let cookies_after_clear = rpc(
        &server.socket,
        "browser.cookies.get",
        json!({"surface_id": browser_surface}),
    );
    assert_eq!(cookies_after_clear["cookies"].as_array().unwrap().len(), 0);

    let tmp = tempfile::tempdir().expect("tempdir");
    let cookies_file = tmp.path().join("cookies.txt");
    std::fs::write(
        &cookies_file,
        "# Netscape HTTP Cookie File\n.example.test\tTRUE\t/\tFALSE\t1893456000\tfile_session\tfrom_file\n#HttpOnly_.example.test\tTRUE\t/\tFALSE\t1893456000\thttp_only\tsecret\nelsewhere.test\tFALSE\t/\tFALSE\t1893456000\tignored\tnope\n",
    )
    .expect("write cookies file");
    let cookies_file_text = cookies_file.display().to_string();
    let imported_from_file = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "browser",
            "import",
            "--cookies-file",
            cookies_file_text.as_str(),
            "--from",
            "Firefox",
            "--profile",
            "default",
            "--to-profile",
            "default",
            "--domain",
            "example.test",
        ],
        &[],
    );
    assert_eq!(imported_from_file["browser"], "Firefox");
    assert_eq!(imported_from_file["scope"], "cookiesOnly");
    assert_eq!(imported_from_file["imported_cookies"], 2);
    assert_eq!(imported_from_file["skipped_cookies"], 1);
    assert_eq!(
        imported_from_file["entries"][0]["source_profiles"],
        json!(["default"])
    );
    let file_cookies = rpc(
        &server.socket,
        "browser.cookies.get",
        json!({"surface_id": browser_surface}),
    );
    assert!(file_cookies["cookies"]
        .as_array()
        .unwrap()
        .iter()
        .any(|cookie| cookie["name"] == "file_session" && cookie["value"] == "from_file"));
    assert!(file_cookies["cookies"]
        .as_array()
        .unwrap()
        .iter()
        .any(|cookie| cookie["name"] == "http_only" && cookie["value"] == "secret"));

    let bookmarks_file = tmp.path().join("bookmarks.json");
    std::fs::write(
        &bookmarks_file,
        serde_json::to_vec_pretty(&json!({
            "bookmarks": [{
                "url": "https://bookmarks.example.test/linux",
                "title": "Linux Bookmark",
                "folderPath": ["Ports"]
            }]
        }))
        .expect("bookmark JSON"),
    )
    .expect("bookmark file");
    let settings_file = tmp.path().join("browser-settings.json");
    std::fs::write(
        &settings_file,
        serde_json::to_vec_pretty(&json!({
            "homepage": "https://bookmarks.example.test/home",
            "defaultSearchEngine": "kagi"
        }))
        .expect("settings JSON"),
    )
    .expect("settings file");
    let imported_additional = cli_json_with_env(
        &server.socket,
        &[
            "browser",
            "import",
            "--scope",
            "additional",
            "--bookmarks-file",
            bookmarks_file.to_str().unwrap(),
            "--settings-file",
            settings_file.to_str().unwrap(),
            "--from",
            "Fixture",
            "--to-profile",
            "default",
        ],
        &[],
    );
    assert_eq!(imported_additional["imported_bookmark_entries"], 1);
    assert_eq!(imported_additional["imported_setting_values"], 2);
    let cli_bookmarks = cli_json_with_env(
        &server.socket,
        &["browser", "bookmarks", "search", "linux"],
        &[],
    );
    assert_eq!(cli_bookmarks["entries"][0]["title"], "Linux Bookmark");
    let imported_resolution = rpc(
        &server.socket,
        "browser.omnibar.resolve",
        json!({"profile": "default", "input": "cmux import"}),
    );
    assert_eq!(imported_resolution["search_engine"], "kagi");

    let delete_default = rpc_response(
        &server.socket,
        "browser.profiles.delete",
        json!({"id": default_profile_id}),
    );
    assert_eq!(delete_default["ok"], false, "response was {delete_default}");
    assert_eq!(delete_default["error"]["code"], "invalid_state");

    let deleted = rpc(
        &server.socket,
        "browser.profiles.delete",
        json!({"id": created_id}),
    );
    assert_eq!(deleted["deleted"], true);
    assert_eq!(deleted["profile"]["name"], "Renamed Profile");
    let after_delete = rpc(&server.socket, "browser.profiles.list", json!({}));
    assert_eq!(after_delete["current_profile_id"], default_profile_id);
    assert_eq!(after_delete["profiles"].as_array().unwrap().len(), 1);

    let unsupported = rpc_response(
        &server.socket,
        "browser.import.cookies",
        json!({"browser": "Fixture Browser Without Linux Store"}),
    );
    assert_eq!(unsupported["ok"], false, "response was {unsupported}");
    assert_eq!(unsupported["error"]["code"], "not_supported");
}

#[test]
fn browser_omnibar_resolves_smart_input_and_profile_history() {
    let tmp = tempfile::tempdir().expect("browser omnibar config root");
    let xdg_config = tmp.path().join("config");
    let cmux_config = xdg_config.join("cmux/cmux.json");
    std::fs::create_dir_all(cmux_config.parent().unwrap()).expect("cmux config dir");
    std::fs::write(
        &cmux_config,
        r#"{"browser":{"defaultSearchEngine":"duckduckgo"}}"#,
    )
    .expect("cmux browser config");
    let xdg_config_text = xdg_config.display().to_string();
    let server = start_server_with_env(&[("XDG_CONFIG_HOME", xdg_config_text.as_str())]);
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert_eq!(capabilities["features"]["browser_omnibar"], true);
    for method in [
        "browser.omnibar.resolve",
        "browser.omnibar.suggestions",
        "settings.browser.status",
        "settings.browser.set",
    ] {
        assert!(capabilities["methods"]
            .as_array()
            .unwrap()
            .iter()
            .any(|candidate| candidate == method));
    }

    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "https://docs.example.test/start"}),
    );
    let surface_id = opened["surface_id"].as_str().unwrap();
    let _ = rpc(
        &server.socket,
        "browser.runtime.sync",
        json!({"surface_id": surface_id, "title": "Linux Port Docs"}),
    );
    let other_workspace = rpc(
        &server.socket,
        "workspace.create",
        json!({"name": "Open Browser Tab"}),
    );
    let other_workspace_id = other_workspace["workspace_id"].as_str().unwrap();
    let other_browser = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "workspace_id": other_workspace_id,
            "url": "https://guide.example.test/linux"
        }),
    );
    let other_surface_id = other_browser["surface_id"].as_str().unwrap();
    let _ = rpc(
        &server.socket,
        "browser.runtime.sync",
        json!({"surface_id": other_surface_id, "title": "Linux Guide"}),
    );

    let host = rpc(
        &server.socket,
        "browser.omnibar.resolve",
        json!({"input": "example.com:8443/docs"}),
    );
    assert_eq!(host["kind"], "url");
    assert_eq!(host["url"], "https://example.com:8443/docs");

    let localhost = rpc(
        &server.socket,
        "browser.omnibar.resolve",
        json!({"input": "localhost:3000"}),
    );
    assert_eq!(localhost["url"], "http://localhost:3000/");

    let search = rpc(
        &server.socket,
        "browser.omnibar.resolve",
        json!({"input": "cmux linux port"}),
    );
    assert_eq!(search["kind"], "search");
    assert_eq!(search["search_engine"], "duckduckgo");
    assert_eq!(
        search["url"],
        "https://duckduckgo.com/?q=cmux%20linux%20port"
    );

    let suggestions = rpc(
        &server.socket,
        "browser.omnibar.suggestions",
        json!({"surface_id": surface_id, "query": "docs", "limit": 8}),
    );
    assert_eq!(suggestions["search_engine"], "duckduckgo");
    assert_eq!(suggestions["suggestions"][0]["kind"], "search");
    assert!(suggestions["suggestions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|suggestion| {
            suggestion["kind"] == "history"
                && suggestion["url"] == "https://docs.example.test/start"
                && suggestion["title"] == "Linux Port Docs"
        }));
    let cross_tab = rpc(
        &server.socket,
        "browser.omnibar.suggestions",
        json!({
            "surface_id": surface_id,
            "query": "guide",
            "limit": 8,
            "remote_suggestions": ["guide install", "guide install", "guide config"]
        }),
    );
    assert!(cross_tab["remote_suggestions_enabled"].as_bool().unwrap());
    assert!(cross_tab["remote_suggestions_supported"].as_bool().unwrap());
    assert!(cross_tab["suggestions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|suggestion| {
            suggestion["kind"] == "switch_tab"
                && suggestion["surface_id"] == other_surface_id
                && suggestion["workspace_id"] == other_workspace_id
                && suggestion["badge"] == "Switch to tab"
        }));
    assert_eq!(
        cross_tab["suggestions"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|suggestion| suggestion["kind"] == "remote")
            .count(),
        2
    );
    let single_character = rpc(
        &server.socket,
        "browser.omnibar.suggestions",
        json!({"surface_id": surface_id, "query": "l", "limit": 8}),
    );
    assert!(single_character["suggestions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|suggestion| suggestion["kind"] == "switch_tab"));
    assert!(!single_character["suggestions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|suggestion| suggestion["kind"] == "search"));
    let _ = rpc(
        &server.socket,
        "surface.focus",
        json!({"surface_id": other_surface_id}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.current", json!({}))["surface_id"],
        other_surface_id
    );

    let recent = rpc(
        &server.socket,
        "browser.omnibar.suggestions",
        json!({"surface_id": surface_id, "query": "", "limit": 8}),
    );
    assert_eq!(recent["suggestions"][0]["kind"], "history");

    let status = rpc(&server.socket, "settings.browser.status", json!({}));
    assert_eq!(status["defaultSearchEngine"], "duckduckgo");
    let _ = rpc(
        &server.socket,
        "settings.browser.set",
        json!({"key": "customSearchEngineName", "value": "Internal Docs"}),
    );
    let _ = rpc(
        &server.socket,
        "settings.browser.set",
        json!({
            "key": "customSearchEngineURLTemplate",
            "value": "https://search.example.test/find/{query}"
        }),
    );
    let custom = rpc(
        &server.socket,
        "settings.browser.set",
        json!({"key": "defaultSearchEngine", "value": "custom"}),
    );
    assert_eq!(custom["searchEngineName"], "Internal Docs");
    let custom_search = rpc(
        &server.socket,
        "browser.omnibar.resolve",
        json!({"input": "profile storage"}),
    );
    assert_eq!(
        custom_search["url"],
        "https://search.example.test/find/profile%20storage"
    );
    let invalid_template = rpc_response(
        &server.socket,
        "settings.browser.set",
        json!({
            "key": "customSearchEngineURLTemplate",
            "value": "javascript:{query}"
        }),
    );
    assert_eq!(invalid_template["ok"], false);
    assert_eq!(invalid_template["error"]["code"], "invalid_params");
}

#[test]
fn workspace_color_settings_persist_palette_and_advertise_contract() {
    let tmp = tempfile::tempdir().expect("workspace color settings root");
    let config_home = tmp.path().join("config");
    let config_path = config_home.join("cmux/cmux.json");
    std::fs::create_dir_all(config_path.parent().unwrap()).expect("config directory");
    std::fs::write(&config_path, r#"{"keep":{"value":true}}"#).expect("seed config");
    let config_home_text = config_home.display().to_string();
    let server = start_server_with_env(&[("XDG_CONFIG_HOME", config_home_text.as_str())]);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().expect("methods");
    for method in [
        "settings.workspace_colors.status",
        "settings.workspace_colors.set",
        "settings.workspace_colors.color.set",
        "settings.workspace_colors.color.remove",
        "settings.workspace_colors.palette.reset",
    ] {
        assert!(
            methods.iter().any(|value| value == method),
            "missing {method} from capabilities"
        );
    }
    assert_eq!(capabilities["features"]["workspace_color_settings"], true);

    let defaults = rpc(
        &server.socket,
        "settings.workspace_colors.status",
        json!({}),
    );
    assert_eq!(defaults["indicatorStyle"], "leftRail");
    assert_eq!(defaults["colors"].as_array().unwrap().len(), 16);
    assert_eq!(defaults["colors"][0]["name"], "Red");

    let style = rpc(
        &server.socket,
        "settings.workspace_colors.set",
        json!({"key": "indicatorStyle", "value": "solidFill"}),
    );
    assert_eq!(style["indicatorStyle"], "solidFill");
    let selection = rpc(
        &server.socket,
        "settings.workspace_colors.set",
        json!({"key": "selectionColor", "value": "#12abef"}),
    );
    assert_eq!(selection["selectionColor"], "#12ABEF");

    let custom = rpc(
        &server.socket,
        "settings.workspace_colors.color.set",
        json!({"name": "Team Blue", "color": "#0102fe"}),
    );
    assert!(custom["colors"]
        .as_array()
        .unwrap()
        .iter()
        .any(|entry| entry["name"] == "Team Blue" && entry["color"] == "#0102FE"));

    let invalid = rpc_response(
        &server.socket,
        "settings.workspace_colors.color.set",
        json!({"name": "Broken", "color": "blue"}),
    );
    assert_eq!(invalid["ok"], false);
    assert_eq!(invalid["error"]["code"], "invalid_params");

    let removed = rpc(
        &server.socket,
        "settings.workspace_colors.color.remove",
        json!({"name": "Team Blue"}),
    );
    assert!(!removed["colors"]
        .as_array()
        .unwrap()
        .iter()
        .any(|entry| entry["name"] == "Team Blue"));

    let reset = rpc(
        &server.socket,
        "settings.workspace_colors.palette.reset",
        json!({}),
    );
    assert_eq!(reset["colors"].as_array().unwrap().len(), 16);
    assert_eq!(reset["colors"][8]["name"], "Blue");
    let written: Value = serde_json::from_str(
        &std::fs::read_to_string(&config_path).expect("workspace colors config"),
    )
    .expect("workspace colors JSON");
    assert_eq!(written["keep"]["value"], true);
    assert_eq!(written["workspaceColors"]["indicatorStyle"], "solidFill");
    assert_eq!(written["workspaceColors"]["selectionColor"], "#12ABEF");
    assert_eq!(written["workspaceColors"]["colors"]["Charcoal"], "#3E4B5E");
}

#[test]
fn sidebar_settings_persist_and_renderer_rows_expose_detail_sources() {
    let tmp = tempfile::tempdir().expect("sidebar settings root");
    let config_home = tmp.path().join("config");
    let config_path = config_home.join("cmux/cmux.json");
    std::fs::create_dir_all(config_path.parent().unwrap()).expect("config directory");
    std::fs::write(&config_path, r#"{"keep":{"value":true}}"#).expect("seed config");
    let config_home_text = config_home.display().to_string();
    let server = start_server_with_env(&[("XDG_CONFIG_HOME", config_home_text.as_str())]);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert_eq!(
        capabilities["features"]["sidebar_appearance_settings"],
        true
    );
    for method in ["settings.sidebar.status", "settings.sidebar.set"] {
        assert!(capabilities["methods"]
            .as_array()
            .unwrap()
            .iter()
            .any(|value| value == method));
    }

    let defaults = rpc(&server.socket, "settings.sidebar.status", json!({}));
    assert_eq!(defaults["hideAllDetails"], false);
    assert_eq!(defaults["branchLayout"], "vertical");
    assert_eq!(defaults["showPorts"], true);
    assert!(defaults["rightMaxWidth"].is_null());

    let compact = rpc(
        &server.socket,
        "settings.sidebar.set",
        json!({"key": "hideAllDetails", "value": true}),
    );
    assert_eq!(compact["hideAllDetails"], true);
    let inline = rpc(
        &server.socket,
        "settings.sidebar.set",
        json!({"key": "sidebar.branchLayout", "value": "inline"}),
    );
    assert_eq!(inline["branchLayout"], "inline");
    let width = rpc(
        &server.socket,
        "settings.sidebar.set",
        json!({"key": "rightMaxWidth", "value": 5000}),
    );
    assert_eq!(width["rightMaxWidth"], 4096.0);
    let invalid = rpc_response(
        &server.socket,
        "settings.sidebar.set",
        json!({"key": "branchLayout", "value": "diagonal"}),
    );
    assert_eq!(invalid["ok"], false);
    assert_eq!(invalid["error"]["code"], "invalid_params");

    let identify = rpc(&server.socket, "system.identify", json!({}));
    let workspace = identify["workspace_ref"].as_str().expect("workspace ref");
    rpc(
        &server.socket,
        "workspace.action",
        json!({
            "workspace_id": workspace,
            "action": "set-description",
            "description": "Ship the Linux sidebar"
        }),
    );
    rpc(
        &server.socket,
        "sidebar.status.set",
        json!({
            "workspace_id": workspace,
            "key": "ci",
            "value": "passing",
            "priority": 5,
            "color": "#22AA66"
        }),
    );
    rpc(
        &server.socket,
        "sidebar.progress.set",
        json!({"workspace_id": workspace, "value": 0.75, "label": "Porting"}),
    );
    rpc(
        &server.socket,
        "sidebar.log.append",
        json!({
            "workspace_id": workspace,
            "level": "info",
            "source": "linux",
            "message": "sidebar refreshed"
        }),
    );
    let snapshot = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "core"}),
    );
    let row = snapshot["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_ref"] == workspace)
        .expect("workspace renderer row");
    assert_eq!(row["description"], "Ship the Linux sidebar");
    assert_eq!(row["status_entries"][0]["value"], "passing");
    assert_eq!(row["progress"]["value"], 0.75);
    assert_eq!(row["latest_log"]["source"], "linux");
    assert_eq!(row["latest_log"]["message"], "sidebar refreshed");

    let written: Value =
        serde_json::from_str(&std::fs::read_to_string(&config_path).expect("sidebar config"))
            .expect("sidebar JSON");
    assert_eq!(written["keep"]["value"], true);
    assert_eq!(written["sidebar"]["hideAllDetails"], true);
    assert_eq!(written["sidebar"]["branchLayout"], "inline");
    assert_eq!(written["sidebar"]["rightMaxWidth"], 4096.0);
}

#[test]
fn browser_cookie_import_reads_linux_host_cookie_stores() {
    let tmp = tempfile::tempdir().expect("host cookie import root");
    let home = tmp.path().join("home");
    let xdg_config = tmp.path().join("config");
    let chrome_root = xdg_config.join("google-chrome/Default");
    let chrome_profile = chrome_root.join("Network");
    let firefox_profile = home.join(".mozilla/firefox/abc.default-release");
    std::fs::create_dir_all(&chrome_profile).expect("chrome profile dir");
    std::fs::create_dir_all(&firefox_profile).expect("firefox profile dir");

    let chrome_db = chrome_profile.join("Cookies");
    let chrome = Connection::open(&chrome_db).expect("chrome cookie db");
    chrome
        .execute(
            "CREATE TABLE cookies (host_key TEXT, name TEXT, value TEXT, encrypted_value BLOB)",
            [],
        )
        .expect("chrome cookies schema");
    chrome
        .execute(
            "INSERT INTO cookies (host_key, name, value, encrypted_value) VALUES (?1, ?2, ?3, ?4)",
            params![
                ".example.test",
                "chrome_session",
                "from_chrome",
                Option::<Vec<u8>>::None
            ],
        )
        .expect("chrome plaintext cookie");
    chrome
        .execute(
            "INSERT INTO cookies (host_key, name, value, encrypted_value) VALUES (?1, ?2, ?3, ?4)",
            params![
                ".example.test",
                "chrome_encrypted",
                "",
                Some(vec![1_u8, 2, 3])
            ],
        )
        .expect("chrome encrypted cookie");
    let chrome_history = Connection::open(chrome_root.join("History")).expect("chrome history db");
    chrome_history
        .execute(
            "CREATE TABLE urls (url TEXT, title TEXT, visit_count INTEGER, last_visit_time INTEGER)",
            [],
        )
        .expect("chrome history schema");
    let chromium_last_visit_time = (1_700_000_000_000_i64 + 11_644_473_600_000) * 1_000;
    chrome_history
        .execute(
            "INSERT INTO urls (url, title, visit_count, last_visit_time) VALUES (?1, ?2, ?3, ?4)",
            params![
                "https://example.test/chrome-history#fragment",
                "Chrome History",
                7_i64,
                chromium_last_visit_time
            ],
        )
        .expect("chrome history row");
    chrome_history
        .execute(
            "INSERT INTO urls (url, title, visit_count, last_visit_time) VALUES (?1, ?2, ?3, ?4)",
            params![
                "https://elsewhere.test/chrome-history",
                "Filtered Chrome History",
                3_i64,
                chromium_last_visit_time
            ],
        )
        .expect("filtered chrome history row");
    std::fs::write(
        chrome_root.join("Bookmarks"),
        serde_json::to_vec_pretty(&json!({
            "roots": {
                "bookmark_bar": {
                    "type": "folder",
                    "name": "Bookmarks Bar",
                    "children": [{
                        "type": "folder",
                        "name": "Engineering",
                        "children": [{
                            "type": "url",
                            "name": "Chrome Bookmark",
                            "url": "https://example.test/chrome-bookmark#guide",
                            "date_added": "13344473600000000"
                        }]
                    }, {
                        "type": "url",
                        "name": "Filtered Bookmark",
                        "url": "https://elsewhere.test/bookmark",
                        "date_added": "13344473600000000"
                    }]
                }
            }
        }))
        .expect("chrome bookmarks JSON"),
    )
    .expect("chrome bookmarks");
    std::fs::write(
        chrome_root.join("Preferences"),
        serde_json::to_vec_pretty(&json!({
            "homepage": "https://example.test/chrome-home",
            "bookmark_bar": {"show_on_all_tabs": true},
            "default_search_provider_data": {
                "template_url_data": {
                    "short_name": "Google",
                    "url": "https://www.google.com/search?q={searchTerms}"
                }
            }
        }))
        .expect("chrome preferences JSON"),
    )
    .expect("chrome preferences");

    let firefox_db = firefox_profile.join("cookies.sqlite");
    let firefox = Connection::open(&firefox_db).expect("firefox cookie db");
    firefox
        .execute(
            "CREATE TABLE moz_cookies (host TEXT, name TEXT, value TEXT)",
            [],
        )
        .expect("firefox cookies schema");
    firefox
        .execute(
            "INSERT INTO moz_cookies (host, name, value) VALUES (?1, ?2, ?3)",
            params![".example.test", "firefox_session", "from_firefox"],
        )
        .expect("firefox cookie");
    let firefox_history =
        Connection::open(firefox_profile.join("places.sqlite")).expect("firefox history db");
    firefox_history
        .execute(
            "CREATE TABLE moz_places (id INTEGER PRIMARY KEY, url TEXT, title TEXT, visit_count INTEGER, last_visit_date INTEGER)",
            [],
        )
        .expect("firefox history schema");
    firefox_history
        .execute(
            "INSERT INTO moz_places (id, url, title, visit_count, last_visit_date) VALUES (?1, ?2, ?3, ?4, ?5)",
            params![
                1_i64,
                "https://example.test/firefox-history",
                "Firefox History",
                4_i64,
                1_700_000_100_000_000_i64
            ],
        )
        .expect("firefox history row");
    firefox_history
        .execute(
            "CREATE TABLE moz_bookmarks (id INTEGER PRIMARY KEY, parent INTEGER, type INTEGER, title TEXT, dateAdded INTEGER, fk INTEGER)",
            [],
        )
        .expect("firefox bookmarks schema");
    firefox_history
        .execute(
            "INSERT INTO moz_bookmarks (id, parent, type, title, dateAdded, fk) VALUES (10, 0, 2, 'Bookmarks Menu', 0, NULL)",
            [],
        )
        .expect("firefox bookmark root");
    firefox_history
        .execute(
            "INSERT INTO moz_bookmarks (id, parent, type, title, dateAdded, fk) VALUES (11, 10, 2, 'Linux', 0, NULL)",
            [],
        )
        .expect("firefox bookmark folder");
    firefox_history
        .execute(
            "INSERT INTO moz_bookmarks (id, parent, type, title, dateAdded, fk) VALUES (12, 11, 1, 'Firefox Bookmark', 1700000200000000, 1)",
            [],
        )
        .expect("firefox bookmark");
    std::fs::write(
        firefox_profile.join("prefs.js"),
        "user_pref(\"browser.startup.homepage\", \"https://example.test/firefox-home\");\nuser_pref(\"browser.search.defaultenginename\", \"DuckDuckGo\");\nuser_pref(\"browser.toolbars.bookmarks.visibility\", \"always\");\n",
    )
    .expect("firefox preferences");
    drop(chrome);
    drop(chrome_history);
    drop(firefox);
    drop(firefox_history);

    let home_text = home.display().to_string();
    let xdg_config_text = xdg_config.display().to_string();
    let server = start_server_with_env(&[
        ("HOME", home_text.as_str()),
        ("XDG_CONFIG_HOME", xdg_config_text.as_str()),
    ]);
    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "about:blank"}),
    );
    let browser_surface = opened["surface_id"].as_str().unwrap();
    let sources = rpc(&server.socket, "browser.import.sources", json!({}));
    assert!(sources["sources"].as_array().unwrap().iter().any(|source| {
        source["browser"] == "Chrome"
            && source["profile"] == "Default"
            && source["cookies"] == true
            && source["history"] == true
            && source["bookmarks"] == true
            && source["settings"] == true
    }));
    assert!(sources["sources"].as_array().unwrap().iter().any(|source| {
        source["browser"] == "Firefox"
            && source["profile"] == "abc.default-release"
            && source["cookies"] == true
            && source["history"] == true
            && source["bookmarks"] == true
            && source["settings"] == true
    }));
    assert_eq!(sources["profiles"][0]["name"], "Default");

    let chrome_import = rpc(
        &server.socket,
        "browser.import.cookies",
        json!({
            "browser": "Chrome",
            "source_profile": "Default",
            "destination_profile": "default",
            "domain": "example.test",
            "scope": "all"
        }),
    );
    assert_eq!(chrome_import["browser"], "Chrome");
    assert_eq!(chrome_import["scope"], "everything");
    assert_eq!(chrome_import["imported_cookies"], 1);
    assert_eq!(chrome_import["skipped_cookies"], 0);
    assert_eq!(chrome_import["imported_history_entries"], 1);
    assert_eq!(chrome_import["imported_bookmark_entries"], 1);
    assert_eq!(chrome_import["skipped_bookmark_entries"], 1);
    assert_eq!(chrome_import["imported_settings"]["searchEngine"], "google");
    assert_eq!(
        chrome_import["imported_settings"]["homepageURL"],
        "https://example.test/chrome-home"
    );
    assert_eq!(
        chrome_import["entries"][0]["source_profiles"],
        json!(["Default"])
    );
    assert!(
        chrome_import["warnings"]
            .as_array()
            .unwrap()
            .iter()
            .any(|warning| warning
                .as_str()
                .unwrap_or_default()
                .contains("encrypted Chromium cookie")),
        "chrome import was {chrome_import}"
    );

    let firefox_import = rpc(
        &server.socket,
        "browser.import.cookies",
        json!({
            "browser": "Firefox",
            "source_profile": "abc.default-release",
            "destination_profile": "default",
            "domain": "example.test",
            "scope": "all"
        }),
    );
    assert_eq!(firefox_import["browser"], "Firefox");
    assert_eq!(firefox_import["imported_cookies"], 1);
    assert_eq!(firefox_import["imported_history_entries"], 1);
    assert_eq!(firefox_import["imported_bookmark_entries"], 1);
    assert_eq!(
        firefox_import["imported_settings"]["searchEngine"],
        "duckduckgo"
    );
    assert_eq!(
        firefox_import["imported_settings"]["homepageURL"],
        "https://example.test/firefox-home"
    );
    assert_eq!(
        firefox_import["entries"][0]["source_profiles"],
        json!(["abc.default-release"])
    );

    let cookies = rpc(
        &server.socket,
        "browser.cookies.get",
        json!({"surface_id": browser_surface}),
    );
    let rows = cookies["cookies"].as_array().expect("cookies array");
    assert!(rows
        .iter()
        .any(|cookie| cookie["name"] == "chrome_session" && cookie["value"] == "from_chrome"));
    assert!(rows
        .iter()
        .any(|cookie| cookie["name"] == "firefox_session" && cookie["value"] == "from_firefox"));
    assert!(
        !rows
            .iter()
            .any(|cookie| cookie["name"] == "chrome_encrypted"),
        "encrypted cookie should not be imported without keyring support: {cookies}"
    );

    let history = rpc(
        &server.socket,
        "browser.history.list",
        json!({"profile": "default"}),
    );
    assert_eq!(history["total"], 2);
    let rows = history["entries"].as_array().expect("history array");
    assert!(rows.iter().any(|entry| {
        entry["url"] == "https://example.test/chrome-history"
            && entry["title"] == "Chrome History"
            && entry["visitCount"] == 7
            && entry["lastVisitedMs"] == 1_700_000_000_000_i64
    }));
    assert!(rows.iter().any(|entry| {
        entry["url"] == "https://example.test/firefox-history"
            && entry["title"] == "Firefox History"
            && entry["visitCount"] == 4
            && entry["lastVisitedMs"] == 1_700_000_100_000_i64
    }));
    assert!(!rows
        .iter()
        .any(|entry| entry["title"] == "Filtered Chrome History"));

    let bookmarks = rpc(
        &server.socket,
        "browser.bookmarks.list",
        json!({"profile": "default"}),
    );
    assert_eq!(bookmarks["total"], 2);
    let rows = bookmarks["entries"].as_array().expect("bookmarks array");
    assert!(rows.iter().any(|entry| {
        entry["url"] == "https://example.test/chrome-bookmark#guide"
            && entry["title"] == "Chrome Bookmark"
            && entry["folderPath"] == json!(["Bookmarks Bar", "Engineering"])
    }));
    assert!(rows.iter().any(|entry| {
        entry["url"] == "https://example.test/firefox-history"
            && entry["title"] == "Firefox Bookmark"
            && entry["folderPath"] == json!(["Bookmarks Menu", "Linux"])
    }));
    let cli_bookmarks = cli_json_with_env(
        &server.socket,
        &[
            "browser",
            "bookmarks",
            "search",
            "firefox",
            "--profile",
            "default",
            "--limit",
            "1",
        ],
        &[],
    );
    assert_eq!(cli_bookmarks["query"], "firefox");
    assert_eq!(cli_bookmarks["entries"][0]["title"], "Firefox Bookmark");

    let suggestions = rpc(
        &server.socket,
        "browser.omnibar.suggestions",
        json!({"profile": "default", "query": "engineering"}),
    );
    assert!(suggestions["suggestions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|suggestion| {
            suggestion["kind"] == "bookmark"
                && suggestion["title"] == "Chrome Bookmark"
                && suggestion["badge"] == "Bookmark"
        }));
    let resolved = rpc(
        &server.socket,
        "browser.omnibar.resolve",
        json!({"profile": "default", "input": "cmux linux port"}),
    );
    assert_eq!(resolved["search_engine"], "duckduckgo");
    assert!(resolved["url"]
        .as_str()
        .unwrap_or_default()
        .starts_with("https://duckduckgo.com/"));
}

#[test]
fn browser_profiles_and_history_persist_across_server_restarts() {
    let tmp = tempfile::tempdir().expect("browser profile persistence root");
    let profile_store = tmp.path().join("browser-profiles.json");
    let profile_store_text = profile_store.display().to_string();

    let persisted_profile_id = {
        let server =
            start_server_with_env(&[("CMUX_BROWSER_PROFILES_PATH", profile_store_text.as_str())]);
        let created = rpc(
            &server.socket,
            "browser.profiles.create",
            json!({"name": "Persistent Profile"}),
        );
        let profile_id = created["profile"]["id"]
            .as_str()
            .expect("profile id")
            .to_string();
        let imported = rpc(
            &server.socket,
            "browser.import.cookies",
            json!({
                "browser": "Persistence Fixture",
                "source_profile": "Fixture",
                "destination_profile": profile_id,
                "scope": "history",
                "history": [{
                    "url": "https://persist.example.test/docs#section",
                    "title": "Persistent Docs",
                    "lastVisitedMs": 1700000000000_i64,
                    "visitCount": 6
                }]
            }),
        );
        assert_eq!(imported["imported_cookies"], 0);
        assert_eq!(imported["imported_history_entries"], 1);
        let additional = rpc(
            &server.socket,
            "browser.import.data",
            json!({
                "browser": "Persistence Fixture",
                "source_profile": "Fixture",
                "destination_profile": profile_id,
                "scope": "additional",
                "bookmarks": [{
                    "url": "https://persist.example.test/bookmark",
                    "title": "Persistent Bookmark",
                    "folderPath": ["Imported"]
                }],
                "settings": {
                    "homepage": "https://persist.example.test/home",
                    "defaultSearchEngine": "brave"
                }
            }),
        );
        assert_eq!(additional["imported_bookmark_entries"], 1);
        assert_eq!(
            additional["imported_setting_values"], 2,
            "additional import was {additional}"
        );
        assert!(profile_store.exists(), "profile store was not written");
        assert_eq!(
            std::fs::metadata(&profile_store)
                .expect("profile store metadata")
                .permissions()
                .mode()
                & 0o777,
            0o600
        );
        profile_id
    };

    {
        let server =
            start_server_with_env(&[("CMUX_BROWSER_PROFILES_PATH", profile_store_text.as_str())]);
        let profiles = rpc(&server.socket, "browser.profiles.list", json!({}));
        assert_eq!(profiles["current_profile_id"], persisted_profile_id);
        let profile = profiles["profiles"]
            .as_array()
            .unwrap()
            .iter()
            .find(|profile| profile["id"] == persisted_profile_id)
            .expect("persisted profile");
        assert_eq!(profile["name"], "Persistent Profile");
        assert_eq!(profile["history_entry_count"], 1);
        assert_eq!(profile["bookmark_entry_count"], 1);
        assert_eq!(
            profile["imported_settings"]["homepageURL"],
            "https://persist.example.test/home"
        );
        assert_eq!(profile["imported_settings"]["searchEngine"], "brave");

        let history = rpc(
            &server.socket,
            "browser.history.list",
            json!({"profile": persisted_profile_id}),
        );
        assert_eq!(history["total"], 1);
        assert_eq!(
            history["entries"][0]["url"],
            "https://persist.example.test/docs"
        );
        assert_eq!(history["entries"][0]["title"], "Persistent Docs");
        assert_eq!(history["entries"][0]["visitCount"], 6);
        let bookmarks = rpc(
            &server.socket,
            "browser.bookmarks.list",
            json!({"profile": persisted_profile_id}),
        );
        assert_eq!(bookmarks["total"], 1);
        assert_eq!(
            bookmarks["entries"][0]["url"],
            "https://persist.example.test/bookmark"
        );
        let resolved = rpc(
            &server.socket,
            "browser.omnibar.resolve",
            json!({"profile": persisted_profile_id, "input": "persistent search"}),
        );
        assert_eq!(resolved["search_engine"], "brave");

        let cleared = rpc(
            &server.socket,
            "browser.history.clear",
            json!({"profile": persisted_profile_id, "force": true}),
        );
        assert_eq!(cleared["cleared_history_entries"], 1);
        let cleared_bookmarks = rpc(
            &server.socket,
            "browser.bookmarks.clear",
            json!({"profile": persisted_profile_id, "force": true}),
        );
        assert_eq!(cleared_bookmarks["cleared_bookmark_entries"], 1);
    }

    let server =
        start_server_with_env(&[("CMUX_BROWSER_PROFILES_PATH", profile_store_text.as_str())]);
    let history = rpc(
        &server.socket,
        "browser.history.list",
        json!({"profile": persisted_profile_id}),
    );
    assert_eq!(history["total"], 0);
    let bookmarks = rpc(
        &server.socket,
        "browser.bookmarks.list",
        json!({"profile": persisted_profile_id}),
    );
    assert_eq!(bookmarks["total"], 0);
}

#[test]
fn browser_surfaces_scope_state_and_history_to_their_profiles() {
    let server = start_server();
    let alpha = rpc(
        &server.socket,
        "browser.profiles.create",
        json!({"name": "Alpha Profile"}),
    );
    let alpha_id = alpha["profile"]["id"].as_str().unwrap().to_string();
    assert_eq!(alpha["profile"]["data_generation"], 0);

    let alpha_first = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "url": "https://alpha.example.test/first",
            "profile": "alpha-profile"
        }),
    );
    let alpha_first_id = alpha_first["surface_id"].as_str().unwrap().to_string();
    assert_eq!(alpha_first["profile_id"], alpha_id);

    let alpha_second = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "browser",
            "open",
            "https://alpha.example.test/second",
            "--profile",
            "alpha-profile",
        ],
        &[],
    );
    assert_eq!(alpha_second["profile_id"], alpha_id);
    assert!(alpha_second["surface_ref"]
        .as_str()
        .is_some_and(|surface_ref| surface_ref.starts_with("surface:")));
    let tabs = rpc(&server.socket, "browser.tab.list", json!({}));
    let alpha_second_id = tabs["tabs"]
        .as_array()
        .unwrap()
        .iter()
        .find(|tab| tab["url"] == "https://alpha.example.test/second")
        .and_then(|tab| tab["surface_id"].as_str())
        .expect("CLI-created alpha surface")
        .to_string();
    assert_eq!(
        rpc(
            &server.socket,
            "browser.identify",
            json!({"surface_id": alpha_second_id})
        )["profile_id"],
        alpha_id
    );

    let beta = rpc(
        &server.socket,
        "browser.profiles.create",
        json!({"name": "Beta Profile"}),
    );
    let beta_id = beta["profile"]["id"].as_str().unwrap().to_string();
    let beta_surface = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "url": "https://beta.example.test/home",
            "profile_id": beta_id
        }),
    );
    let beta_surface_id = beta_surface["surface_id"].as_str().unwrap().to_string();
    assert_eq!(beta_surface["profile_id"], beta_id);

    rpc(
        &server.socket,
        "browser.cookies.set",
        json!({
            "surface_id": alpha_first_id,
            "name": "profile-cookie",
            "value": "alpha"
        }),
    );
    rpc(
        &server.socket,
        "browser.storage.set",
        json!({
            "surface_id": alpha_first_id,
            "type": "local",
            "key": "profile-storage",
            "value": "alpha"
        }),
    );

    let alpha_cookies = rpc(
        &server.socket,
        "browser.cookies.get",
        json!({"surface_id": alpha_second_id}),
    );
    assert!(alpha_cookies["cookies"]
        .as_array()
        .unwrap()
        .iter()
        .any(|cookie| cookie["name"] == "profile-cookie" && cookie["value"] == "alpha"));
    let alpha_storage = rpc(
        &server.socket,
        "browser.storage.get",
        json!({
            "surface_id": alpha_second_id,
            "type": "local",
            "key": "profile-storage"
        }),
    );
    assert_eq!(alpha_storage["value"], "alpha");

    let beta_cookies = rpc(
        &server.socket,
        "browser.cookies.get",
        json!({"surface_id": beta_surface_id}),
    );
    assert!(beta_cookies["cookies"].as_array().unwrap().is_empty());
    let beta_storage = rpc(
        &server.socket,
        "browser.storage.get",
        json!({
            "surface_id": beta_surface_id,
            "type": "local",
            "key": "profile-storage"
        }),
    );
    assert!(beta_storage["value"].is_null());

    let alpha_history = rpc(
        &server.socket,
        "browser.history.list",
        json!({"surface_id": alpha_first_id}),
    );
    assert_eq!(alpha_history["profile"]["id"], alpha_id);
    assert!(alpha_history["entries"]
        .as_array()
        .unwrap()
        .iter()
        .all(|entry| entry["url"]
            .as_str()
            .unwrap()
            .contains("alpha.example.test")));

    let beta_history = rpc(
        &server.socket,
        "browser.history.list",
        json!({"surface_id": beta_surface_id}),
    );
    assert_eq!(beta_history["profile"]["id"], beta_id);
    assert!(beta_history["entries"]
        .as_array()
        .unwrap()
        .iter()
        .all(|entry| entry["url"].as_str().unwrap().contains("beta.example.test")));

    let cleared = rpc(
        &server.socket,
        "browser.profiles.clear",
        json!({"profile": alpha_id, "force": true}),
    );
    assert_eq!(cleared["profiles"][0]["data_generation"], 1);
    let alpha_identify = rpc(
        &server.socket,
        "browser.identify",
        json!({"surface_id": alpha_first_id}),
    );
    assert_eq!(alpha_identify["profile_id"], alpha_id);
    let alpha_after_clear = rpc(
        &server.socket,
        "browser.cookies.get",
        json!({"surface_id": alpha_second_id}),
    );
    assert!(alpha_after_clear["cookies"].as_array().unwrap().is_empty());

    let deleted = rpc(
        &server.socket,
        "browser.profiles.delete",
        json!({"profile": beta_id}),
    );
    assert_eq!(deleted["deleted"], true);
    let beta_after_delete = rpc(
        &server.socket,
        "browser.identify",
        json!({"surface_id": beta_surface_id}),
    );
    assert_eq!(
        beta_after_delete["profile_id"],
        "52B43C05-4A1D-45D3-8FD5-9EF94952E445"
    );
}

#[test]
fn browser_surface_profile_and_data_generation_survive_restart() {
    let tmp = tempfile::tempdir().expect("browser profile surface restart root");
    let profile_store = tmp.path().join("browser-profiles.json");
    let session_store = tmp.path().join("session.json");
    let profile_store_text = profile_store.display().to_string();
    let session_store_text = session_store.display().to_string();

    let profile_id = {
        let server = start_server_with_env(&[
            ("CMUX_BROWSER_PROFILES_PATH", profile_store_text.as_str()),
            ("CMUX_SESSION_SNAPSHOT_PATH", session_store_text.as_str()),
        ]);
        let profile = rpc(
            &server.socket,
            "browser.profiles.create",
            json!({"name": "Restart Profile"}),
        );
        let profile_id = profile["profile"]["id"].as_str().unwrap().to_string();
        let opened = rpc(
            &server.socket,
            "browser.open_split",
            json!({
                "url": "https://restart-profile.example.test",
                "profile_id": profile_id
            }),
        );
        assert_eq!(opened["profile_id"], profile_id);
        let cleared = rpc(
            &server.socket,
            "browser.profiles.clear",
            json!({"profile": profile_id, "force": true}),
        );
        assert_eq!(cleared["profiles"][0]["data_generation"], 1);
        profile_id
    };

    let server = start_server_with_env(&[
        ("CMUX_BROWSER_PROFILES_PATH", profile_store_text.as_str()),
        ("CMUX_SESSION_SNAPSHOT_PATH", session_store_text.as_str()),
    ]);
    let tabs = rpc(&server.socket, "browser.tab.list", json!({}));
    let surface_id = tabs["tabs"]
        .as_array()
        .unwrap()
        .iter()
        .find(|tab| tab["url"] == "https://restart-profile.example.test")
        .and_then(|tab| tab["surface_id"].as_str())
        .expect("restored browser surface")
        .to_string();
    let identified = rpc(
        &server.socket,
        "browser.identify",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(identified["profile_id"], profile_id);
    let workspace_id = identified["workspace_id"]
        .as_str()
        .expect("restored workspace id");
    let workspaces = rpc(&server.socket, "workspace.list", json!({}));
    let restored_workspace = workspaces["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|workspace| workspace["workspace_id"] == workspace_id)
        .expect("restored workspace");
    assert_eq!(
        restored_workspace["preferred_browser_profile_id"],
        profile_id
    );
    let inherited = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "workspace_id": workspace_id,
            "url": "https://restart-profile.example.test/inherited"
        }),
    );
    assert_eq!(inherited["profile_id"], profile_id);
    let profiles = rpc(&server.socket, "browser.profiles.list", json!({}));
    let profile = profiles["profiles"]
        .as_array()
        .unwrap()
        .iter()
        .find(|profile| profile["id"] == profile_id)
        .expect("restored profile");
    assert_eq!(profile["data_generation"], 1);
}

#[test]
fn browser_workspace_profile_preferences_are_isolated() {
    let server = start_server();
    let workspaces = rpc(&server.socket, "workspace.list", json!({}));
    let first_workspace_id = workspaces["workspaces"][0]["workspace_id"]
        .as_str()
        .expect("first workspace id")
        .to_string();
    let created = rpc(
        &server.socket,
        "browser.profiles.create",
        json!({"name": "Workspace Profile"}),
    );
    let profile_id = created["profile"]["id"].as_str().unwrap().to_string();
    let _ = rpc(
        &server.socket,
        "browser.profiles.select",
        json!({"profile": "default"}),
    );
    let second = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Profile Workspace", "focus": false}),
    );
    let second_workspace_id = second["workspace_id"].as_str().unwrap().to_string();

    let explicit = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "workspace_id": second_workspace_id,
            "profile_id": profile_id,
            "url": "https://workspace-profile.example.test/explicit"
        }),
    );
    assert_eq!(explicit["profile_id"], profile_id);
    let inherited_second = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "workspace_id": second_workspace_id,
            "url": "https://workspace-profile.example.test/inherited"
        }),
    );
    assert_eq!(inherited_second["profile_id"], profile_id);

    let inherited_first = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "workspace_id": first_workspace_id,
            "url": "https://default-profile.example.test"
        }),
    );
    assert_eq!(
        inherited_first["profile_id"],
        "52B43C05-4A1D-45D3-8FD5-9EF94952E445"
    );

    let workspaces = rpc(&server.socket, "workspace.list", json!({}));
    let first = workspaces["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|workspace| workspace["workspace_id"] == first_workspace_id)
        .expect("first workspace");
    let second = workspaces["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|workspace| workspace["workspace_id"] == second_workspace_id)
        .expect("second workspace");
    assert_eq!(
        first["preferred_browser_profile_id"],
        "52B43C05-4A1D-45D3-8FD5-9EF94952E445"
    );
    assert_eq!(second["preferred_browser_profile_id"], profile_id);
}

#[test]
fn browser_profile_startup_cleanup_removes_only_stale_native_stores() {
    let tmp = tempfile::tempdir().expect("browser native cleanup root");
    let profile_store = tmp.path().join("browser-profiles.json");
    let webkit_data = tmp.path().join("webkit-data");
    let webkit_cache = tmp.path().join("webkit-cache");
    let profile_store_text = profile_store.display().to_string();
    let webkit_data_text = webkit_data.display().to_string();
    let webkit_cache_text = webkit_cache.display().to_string();

    let profile_id = {
        let server = start_server_with_env(&[
            ("CMUX_BROWSER_PROFILES_PATH", profile_store_text.as_str()),
            ("CMUX_BROWSER_WEBKIT_DATA_DIR", webkit_data_text.as_str()),
            ("CMUX_BROWSER_WEBKIT_CACHE_DIR", webkit_cache_text.as_str()),
        ]);
        let profile = rpc(
            &server.socket,
            "browser.profiles.create",
            json!({"name": "Cleanup Profile"}),
        );
        let profile_id = profile["profile"]["id"].as_str().unwrap().to_string();
        let cleared = rpc(
            &server.socket,
            "browser.profiles.clear",
            json!({"profile": profile_id, "force": true}),
        );
        assert_eq!(cleared["profiles"][0]["data_generation"], 1);
        profile_id
    };
    let profile_key = profile_id.to_ascii_lowercase();
    for root in [&webkit_data, &webkit_cache] {
        std::fs::create_dir_all(root.join(&profile_key).join("generation-0/data"))
            .expect("stale generation");
        std::fs::create_dir_all(root.join(&profile_key).join("generation-1/data"))
            .expect("current generation");
        std::fs::create_dir_all(root.join("orphan/generation-7/data")).expect("orphan profile");
    }

    let _server = start_server_with_env(&[
        ("CMUX_BROWSER_PROFILES_PATH", profile_store_text.as_str()),
        ("CMUX_BROWSER_WEBKIT_DATA_DIR", webkit_data_text.as_str()),
        ("CMUX_BROWSER_WEBKIT_CACHE_DIR", webkit_cache_text.as_str()),
    ]);
    for root in [&webkit_data, &webkit_cache] {
        assert!(!root.join(&profile_key).join("generation-0").exists());
        assert!(root.join(&profile_key).join("generation-1").is_dir());
        assert!(!root.join("orphan").exists());
    }
}

#[test]
fn malformed_browser_profile_store_does_not_delete_native_data() {
    let tmp = tempfile::tempdir().expect("malformed browser profile root");
    let profile_store = tmp.path().join("browser-profiles.json");
    let webkit_data = tmp.path().join("webkit-data");
    let webkit_cache = tmp.path().join("webkit-cache");
    std::fs::write(&profile_store, "{not-json").expect("malformed profile store");
    for root in [&webkit_data, &webkit_cache] {
        std::fs::create_dir_all(root.join("preserve-me/generation-4/data"))
            .expect("native profile fixture");
    }
    let profile_store_text = profile_store.display().to_string();
    let webkit_data_text = webkit_data.display().to_string();
    let webkit_cache_text = webkit_cache.display().to_string();
    let _server = start_server_with_env(&[
        ("CMUX_BROWSER_PROFILES_PATH", profile_store_text.as_str()),
        ("CMUX_BROWSER_WEBKIT_DATA_DIR", webkit_data_text.as_str()),
        ("CMUX_BROWSER_WEBKIT_CACHE_DIR", webkit_cache_text.as_str()),
    ]);
    assert!(webkit_data.join("preserve-me/generation-4/data").is_dir());
    assert!(webkit_cache.join("preserve-me/generation-4/data").is_dir());
}

#[test]
fn browser_panel_controls_match_macos_contract() {
    let server = start_server();
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().unwrap();
    for method in [
        "browser.react_grab.toggle",
        "browser.devtools.toggle",
        "browser.console.show",
        "browser.focus_mode.set",
        "browser.zoom.set",
        "browser.history.list",
        "browser.history.clear",
        "browser.import.dialog",
    ] {
        assert!(
            methods.iter().any(|advertised| advertised == method),
            "{method} was not advertised: {capabilities}"
        );
    }
    assert_eq!(capabilities["features"]["browser_model"], true);
    assert_eq!(capabilities["features"]["browser_automation"], true);
    assert_eq!(capabilities["features"]["browser_stub"], false);
    assert_eq!(capabilities["features"]["browser_panel_controls"], true);

    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "data:text/html,<title>panel-controls</title>"}),
    );
    let surface_id = opened["surface_id"].as_str().unwrap();
    let workspace_id = opened["workspace_id"].as_str().unwrap();
    let window_id = rpc(&server.socket, "system.identify", json!({}))["focused"]["window_id"]
        .as_str()
        .unwrap()
        .to_string();

    let react_grab = rpc(
        &server.socket,
        "browser.react_grab.toggle",
        json!({"workspace_id": workspace_id, "surface_id": surface_id}),
    );
    assert_eq!(react_grab["workspace_id"], workspace_id);
    assert_eq!(react_grab["workspace_ref"], opened["workspace_ref"]);
    assert_eq!(react_grab["surface_id"], surface_id);
    assert_eq!(react_grab["surface_ref"], opened["surface_ref"]);
    assert_eq!(react_grab["window_id"], window_id);
    assert_eq!(react_grab["toggled"], true);
    assert_eq!(react_grab["react_grab_active"], true);

    let devtools = rpc(
        &server.socket,
        "browser.devtools.toggle",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(devtools["handled"], true);
    assert_eq!(devtools["developer_tools_visible"], true);
    let surfaces = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    );
    let browser_row = surfaces["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["surface_id"] == surface_id)
        .expect("browser surface row");
    assert_eq!(browser_row["developer_tools_visible"], true);

    let console = rpc(
        &server.socket,
        "browser.console.show",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(console["handled"], true);
    assert_eq!(console["developer_tools_visible"], true);

    let cli_devtools = cli_json_with_env(&server.socket, &["browser", surface_id, "devtools"], &[]);
    assert_eq!(cli_devtools["handled"], true);
    assert_eq!(cli_devtools["developer_tools_visible"], false);
    let cli_console = cli_json_with_env(
        &server.socket,
        &["browser", surface_id, "console", "show"],
        &[],
    );
    assert_eq!(cli_console["handled"], true);
    assert_eq!(cli_console["developer_tools_visible"], true);
    let cli_react_grab =
        cli_json_with_env(&server.socket, &["browser", surface_id, "react-grab"], &[]);
    assert_eq!(cli_react_grab["toggled"], true);
    assert_eq!(cli_react_grab["react_grab_active"], false);

    let invalid_focus = rpc_response(
        &server.socket,
        "browser.focus_mode.set",
        json!({"surface_id": surface_id, "mode": "sideways"}),
    );
    assert_eq!(invalid_focus["ok"], false, "response was {invalid_focus}");
    assert_eq!(invalid_focus["error"]["code"], "invalid_params");
    let focus = rpc(
        &server.socket,
        "browser.focus_mode.set",
        json!({"surface_id": surface_id, "mode": "enter"}),
    );
    assert_eq!(focus["handled"], true);
    assert_eq!(focus["mode"], "enter");
    assert_eq!(focus["focus_mode_active"], true);

    let invalid_zoom = rpc_response(
        &server.socket,
        "browser.zoom.set",
        json!({"surface_id": surface_id, "direction": "sideways"}),
    );
    assert_eq!(invalid_zoom["ok"], false, "response was {invalid_zoom}");
    assert_eq!(invalid_zoom["error"]["code"], "invalid_params");
    let zoom_in = rpc(
        &server.socket,
        "browser.zoom.set",
        json!({"surface_id": surface_id, "direction": "in"}),
    );
    assert_eq!(zoom_in["handled"], true);
    assert_eq!(zoom_in["direction"], "in");
    assert!(
        zoom_in["page_zoom"].as_f64().unwrap_or_default() > 1.0,
        "zoom payload was {zoom_in}"
    );
    let zoom_reset = rpc(
        &server.socket,
        "browser.zoom.set",
        json!({"surface_id": surface_id, "direction": "reset"}),
    );
    assert_eq!(zoom_reset["page_zoom"], 1.0);
    let cli_focus = cli_json_with_env(
        &server.socket,
        &["browser", surface_id, "focus-mode", "--mode", "exit"],
        &[],
    );
    assert_eq!(cli_focus["handled"], true);
    assert_eq!(cli_focus["mode"], "exit");
    assert_eq!(cli_focus["focus_mode_active"], false);
    let cli_zoom = cli_json_with_env(&server.socket, &["browser", surface_id, "zoom", "in"], &[]);
    assert_eq!(cli_zoom["handled"], true);
    assert_eq!(cli_zoom["direction"], "in");
    assert!(
        cli_zoom["page_zoom"].as_f64().unwrap_or_default() > 1.0,
        "cli zoom payload was {cli_zoom}"
    );

    let clear_without_force = rpc_response(&server.socket, "browser.history.clear", json!({}));
    assert_eq!(
        clear_without_force["ok"], false,
        "response was {clear_without_force}"
    );
    assert_eq!(clear_without_force["error"]["code"], "invalid_params");
    let cleared = rpc(
        &server.socket,
        "browser.history.clear",
        json!({"force": true}),
    );
    assert_eq!(cleared["cleared"], true);
    assert_eq!(cleared["scope"], "default_profile");
    let cli_clear_without_force = cli_failure(&server.socket, &["browser", "history", "clear"]);
    assert!(
        cli_clear_without_force.contains("browser.history.clear requires force=true"),
        "unexpected cli failure: {cli_clear_without_force}"
    );
    let cli_cleared = cli_json_with_env(
        &server.socket,
        &["browser", "history", "clear", "--force"],
        &[],
    );
    assert_eq!(cli_cleared["cleared"], true);
    assert_eq!(cli_cleared["scope"], "default_profile");

    let dialog = rpc(
        &server.socket,
        "browser.import.dialog",
        json!({"scope": "cookies-and-history", "destination_profile": "Import Profile", "create_profile": true}),
    );
    assert_eq!(dialog["opened"], true);
    assert_eq!(dialog["scope"], "cookiesAndHistory");
    let profiles = rpc(&server.socket, "browser.profiles.list", json!({}));
    assert!(profiles["profiles"]
        .as_array()
        .unwrap()
        .iter()
        .any(|profile| profile["name"] == "Import Profile"));

    let invalid_dialog = rpc_response(
        &server.socket,
        "browser.import.dialog",
        json!({"scope": "invalid"}),
    );
    assert_eq!(invalid_dialog["ok"], false, "response was {invalid_dialog}");
    assert_eq!(invalid_dialog["error"]["code"], "invalid_params");
}

#[test]
fn browser_import_dialog_creates_visible_browser_when_needed() {
    let server = start_server();
    let before = rpc(&server.socket, "surface.list", json!({}));
    assert!(
        before["surfaces"]
            .as_array()
            .unwrap()
            .iter()
            .all(|surface| { surface["type"] != "browser" && surface["kind"] != "browser" }),
        "test expects no initial browser surfaces: {before}"
    );

    let dialog = rpc(
        &server.socket,
        "browser.import.dialog",
        json!({
            "scope": "cookies-and-history",
            "destination_profile": "Imported Linux Profile",
            "create_profile": true
        }),
    );
    assert_eq!(dialog["opened"], true);
    assert_eq!(dialog["scope"], "cookiesAndHistory");
    let destination_profile_id = dialog["destination_profile_id"]
        .as_str()
        .expect("destination profile id");
    let surface_ids = dialog["surface_ids"].as_array().expect("surface ids");
    assert_eq!(surface_ids.len(), 1, "dialog response was {dialog}");
    let surface_id = surface_ids[0].as_str().expect("surface id");

    let snapshot = rpc(&server.socket, "renderer.snapshot", json!({}));
    let browser_view = snapshot["surface_views"]
        .as_array()
        .unwrap()
        .iter()
        .find(|surface| surface["surface_id"] == surface_id)
        .expect("created browser surface in snapshot");
    assert_eq!(browser_view["kind"], "browser");
    assert_eq!(browser_view["url"], "about:blank");
    assert_eq!(browser_view["browser"]["import_dialog_opened"], true);
    assert_eq!(
        browser_view["browser"]["import_dialog_scope"],
        "cookiesAndHistory"
    );
    assert_eq!(
        browser_view["browser"]["import_dialog_destination_profile_id"],
        destination_profile_id
    );

    let profiles = rpc(&server.socket, "browser.profiles.list", json!({}));
    assert!(profiles["profiles"]
        .as_array()
        .unwrap()
        .iter()
        .any(|profile| {
            profile["id"] == destination_profile_id && profile["name"] == "Imported Linux Profile"
        }));
}

