    assert!(root_stdout.contains("diff"), "root help was {root_stdout}");
    assert!(
        root_stdout.contains("events"),
        "root help was {root_stdout}"
    );
    assert!(
        root_stdout.contains("feedback"),
        "root help was {root_stdout}"
    );
    assert!(
        root_stdout.contains("mobile"),
        "root help was {root_stdout}"
    );
    assert!(
        root_stdout.contains("vm, cloud"),
        "root help was {root_stdout}"
    );
