#[test]
fn browser_cmd_shift_h_flashes_focused_browser_twice() {
    let server = start_server();
    let terminal_surface = rpc(&server.socket, "surface.current", json!({}))["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "about:blank", "focus": true}),
    );
    let browser_surface = opened["surface_id"].as_str().unwrap().to_string();

    rpc(&server.socket, "debug.flash.reset", json!({}));
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "cmd+shift+h"}),
    );

    let browser_count = rpc(
        &server.socket,
        "debug.flash.count",
        json!({"surface_id": browser_surface}),
    )["count"]
        .as_u64()
        .unwrap();
    let terminal_count = rpc(
        &server.socket,
        "debug.flash.count",
        json!({"surface_id": terminal_surface}),
    )["count"]
        .as_u64()
        .unwrap();
    assert_eq!(browser_count, 2);
    assert_eq!(terminal_count, 0);
}

#[test]
fn browser_viewport_set_controls_eval_snapshot_and_screenshot_size() {
    let server = start_server();
    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "about:blank"}),
    );
    let surface_id = opened["surface_id"].as_str().unwrap();

    let viewport = rpc(
        &server.socket,
        "browser.viewport.set",
        json!({
            "surface_id": surface_id,
            "width": 320,
            "height": 180,
            "device_scale_factor": 2.0
        }),
    );
    assert_eq!(viewport["viewport"]["width"], 320);
    assert_eq!(viewport["viewport"]["height"], 180);
    assert_eq!(viewport["viewport"]["device_scale_factor"], 2.0);

    let eval = rpc(
        &server.socket,
        "browser.eval",
        json!({
            "surface_id": surface_id,
            "script": "({width: window.innerWidth, height: window.innerHeight, dpr: window.devicePixelRatio})"
        }),
    );
    assert_eq!(eval["value"]["width"], 320);
    assert_eq!(eval["value"]["height"], 180);
    assert_eq!(eval["value"]["dpr"], 2.0);

    rpc(
        &server.socket,
        "browser.navigate",
        json!({"surface_id": surface_id, "url": "data:text/html,<title>viewport</title>"}),
    );
    let snapshot = rpc(
        &server.socket,
        "browser.snapshot",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(snapshot["viewport"]["width"], 320);
    assert_eq!(snapshot["viewport"]["height"], 180);

    let screenshot = rpc(
        &server.socket,
        "browser.screenshot",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(screenshot["width"], 320);
    assert_eq!(screenshot["height"], 180);
    assert!(
        screenshot["png_base64"]
            .as_str()
            .is_some_and(|value| value.len() > 1000),
        "screenshot was {screenshot}"
    );

    let tmp = tempfile::tempdir().expect("tempdir");
    let cli_path = tmp.path().join("cli-screenshot.png");
    let cli_path_text = cli_path.display().to_string();
    let output = cli(
        &server.socket,
        &[
            "browser",
            "screenshot",
            "--surface",
            surface_id,
            cli_path_text.as_str(),
        ],
    );
    assert_eq!(output.trim(), format!("OK {cli_path_text}"));
    let cli_written = std::fs::read(&cli_path).expect("cli screenshot written");
    assert!(
        cli_written.starts_with(b"\x89PNG\r\n\x1a\n"),
        "cli screenshot was not a PNG"
    );
}

#[test]
fn browser_cli_default_artifacts_use_xdg_cache_home() {
    let cache_tmp = tempfile::tempdir().expect("cache tempdir");
    let cache_home = cache_tmp.path().join("cache");
    let cache_home_text = cache_home.display().to_string();
    let server = start_server();
    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "about:blank"}),
    );
    let surface_id = opened["surface_id"].as_str().unwrap();

    let screenshot_output = cli_with_env(
        &server.socket,
        &["browser", "screenshot", "--surface", surface_id],
        &[("XDG_CACHE_HOME", cache_home_text.as_str())],
    );
    let screenshot_path = screenshot_output
        .trim()
        .strip_prefix("OK ")
        .expect("screenshot OK");
    assert!(
        Path::new(screenshot_path).starts_with(cache_home.join("cmux/browser/screenshots")),
        "screenshot path did not use XDG cache home: {screenshot_path}"
    );
    let screenshot_bytes = std::fs::read(screenshot_path).expect("default screenshot written");
    assert!(
        screenshot_bytes.starts_with(b"\x89PNG\r\n\x1a\n"),
        "default screenshot was not a PNG"
    );

    rpc(
        &server.socket,
        "browser.setcontent",
        json!({
            "surface_id": surface_id,
            "url": "data:text/html,<title>Default PDF</title>",
            "html": "<!doctype html><title>Default PDF</title><main><h1>Default PDF</h1></main>"
        }),
    );
    let pdf_output = cli_with_env(
        &server.socket,
        &["browser", "pdf", "--surface", surface_id],
        &[("XDG_CACHE_HOME", cache_home_text.as_str())],
    );
    let pdf_path = pdf_output.trim().strip_prefix("OK ").expect("pdf OK");
    assert!(
        Path::new(pdf_path).starts_with(cache_home.join("cmux/browser/pdf")),
        "PDF path did not use XDG cache home: {pdf_path}"
    );
    let pdf_bytes = std::fs::read(pdf_path).expect("default PDF written");
    assert!(
        pdf_bytes.starts_with(b"%PDF-1.4"),
        "default PDF was not a PDF"
    );
}

#[test]
fn browser_pdf_export_writes_valid_linux_artifact() {
    let server = start_server();
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert!(
        capabilities["methods"]
            .as_array()
            .unwrap()
            .iter()
            .any(|method| method == "browser.pdf"),
        "browser.pdf was not advertised: {capabilities}"
    );
    assert_eq!(capabilities["features"]["browser_pdf"], true);

    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"url": "about:blank"}),
    );
    let surface_id = opened["surface_id"].as_str().unwrap();
    rpc(
        &server.socket,
        "browser.setcontent",
        json!({
            "surface_id": surface_id,
            "url": "data:text/html,<title>PDF Source</title>",
            "html": "<!doctype html><title>PDF Source</title><main><h1>Linux PDF export</h1><p id='summary'>portable artifact</p></main>"
        }),
    );

    let tmp = tempfile::tempdir().expect("tempdir");
    let rpc_path = tmp.path().join("rpc-export.pdf");
    let rpc_path_text = rpc_path.display().to_string();
    let exported = rpc(
        &server.socket,
        "browser.pdf",
        json!({"surface_id": surface_id, "path": rpc_path_text}),
    );
    assert_eq!(exported["mime_type"], "application/pdf");
    assert_eq!(exported["page_count"], 1);
    assert_eq!(exported["title"], "PDF Source");
    assert!(exported["bytes"].as_u64().unwrap_or(0) > 500);
    let decoded = base64::engine::general_purpose::STANDARD
        .decode(exported["pdf_base64"].as_str().unwrap())
        .expect("decode pdf");
    assert!(decoded.starts_with(b"%PDF-1.4"), "pdf bytes were invalid");
    let written = std::fs::read(&rpc_path).expect("rpc pdf written");
    assert!(written.starts_with(b"%PDF-1.4"), "written pdf was invalid");

    let cli_path = tmp.path().join("cli-export.pdf");
    let cli_path_text = cli_path.display().to_string();
    let output = cli(
        &server.socket,
        &[
            "browser",
            "pdf",
            "--surface",
            surface_id,
            "--out",
            cli_path_text.as_str(),
        ],
    );
    assert!(output.contains("OK"), "cli output was {output}");
    let cli_written = std::fs::read(&cli_path).expect("cli pdf written");
    assert!(cli_written.starts_with(b"%PDF-1.4"), "cli pdf was invalid");
}

#[test]
fn browser_unknown_subcommand_points_to_linux_browser_help() {
    let server = start_server();
    let error = cli_failure(&server.socket, &["browser", "frobnicate"]);
    assert!(
        error.contains("unsupported browser subcommand: frobnicate")
            && error.contains("cmux help browser")
            && error.contains("cmux docs browser")
            && !error.contains("Linux port"),
        "unknown browser subcommand should point to Linux browser help: {error}"
    );
}

