                | "missing_header"
                | "missing_linux_platform"
                | "embedding_header_abi_version_mismatch"
                | "linux_platform_value_mismatch"
                | "env_var_limit_mismatch"
                | "input_keycode_native_mask_mismatch"
                | "input_keycode_physical_key_flag_mismatch"
