#[test]
fn shortcut_overrides_drive_dispatch_unbinding_reset_and_canvas_actions() {
    let server = start_server();
    let initial = rpc(&server.socket, "system.identify", json!({}));
    let workspace_id = initial["focused"]["workspace_id"].as_str().unwrap();
    let origin_surface = initial["focused"]["surface_id"].as_str().unwrap();
    let initial_surface_count = rpc(&server.socket, "surface.list", json!({}))["surfaces"]
        .as_array()
        .unwrap()
        .len();

    let customized = rpc(
        &server.socket,
        "debug.shortcut.set",
        json!({"name": "new_terminal", "combo": "Alt+Super+X"}),
    );
    assert_eq!(customized["mode"], "custom");
    assert_eq!(customized["shortcut_hint"], "⌥⌘X");
    assert_eq!(customized["shortcut_label"], "Alt+Super+X");

    let old_default = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "cmd+t"}),
    );
    assert_eq!(old_default["handled"], false);
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surface_count
    );

    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "SUPER+ALT+X"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surface_count + 1
    );

    let cleared = rpc(
        &server.socket,
        "debug.shortcut.set",
        json!({"name": "new_terminal", "combo": "clear"}),
    );
    assert_eq!(cleared["mode"], "unbound");
    assert_eq!(cleared["shortcut_hint"], "");
    assert_eq!(cleared["shortcut_label"], "");
    let cleared_key = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "alt+super+x"}),
    );
    assert_eq!(cleared_key["handled"], false);

    let reset = rpc(
        &server.socket,
        "debug.shortcut.set",
        json!({"name": "new_terminal", "combo": "reset"}),
    );
    assert_eq!(reset["mode"], "default");
    assert_eq!(reset["shortcut_hint"], "⌘T");
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "cmd+t"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surface_count + 2
    );

    rpc(
        &server.socket,
        "debug.shortcut.set",
        json!({"name": "focus_left", "combo": "clear"}),
    );
    let disabled_alias = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "cmd+ctrl+h"}),
    );
    assert_eq!(disabled_alias["handled"], false);
    let disabled_linux_alias = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+shift+h"}),
    );
    assert_eq!(disabled_linux_alias["handled"], false);
    rpc(
        &server.socket,
        "debug.shortcut.set",
        json!({"name": "focus_left", "combo": "reset"}),
    );

    let copy_mode = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+shift+m"}),
    );
    assert_eq!(copy_mode["terminal_shortcut_action"], "toggle_copy_mode");
    assert_eq!(copy_mode["terminal_copy_mode_active"], true);
    let copy_mode_exit = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+shift+m"}),
    );
    assert_eq!(copy_mode_exit["terminal_copy_mode_active"], false);
    rpc(
        &server.socket,
        "debug.shortcut.set",
        json!({"name": "toggle_terminal_copy_mode", "combo": "clear"}),
    );
    let disabled_copy_mode_alias = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+shift+m"}),
    );
    assert_eq!(disabled_copy_mode_alias["handled"], false);
    rpc(
        &server.socket,
        "debug.shortcut.set",
        json!({"name": "toggle_terminal_copy_mode", "combo": "reset"}),
    );

    let rename_workspace = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "cmd+shift+r"}),
    );
    assert_eq!(rename_workspace["visible"], true);
    assert_eq!(rename_workspace["mode"], "rename_input");
    rpc(
        &server.socket,
        "debug.type",
        json!({"text": "Shortcut Workspace"}),
    );
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "enter"}),
    );
    let workspace_rows = rpc(&server.socket, "workspace.list", json!({}));
    let current_workspace = workspace_rows["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["workspace_id"] == workspace_id)
        .unwrap();
    assert_eq!(current_workspace["title"], "Shortcut Workspace");

    let rename_tab = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "cmd+r"}),
    );
    assert_eq!(rename_tab["mode"], "rename_input");
    rpc(
        &server.socket,
        "debug.type",
        json!({"text": "Shortcut Tab"}),
    );
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "enter"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.current", json!({}))["title"],
        "Shortcut Tab"
    );

    rpc(
        &server.socket,
        "canvas.set_mode",
        json!({"workspace_id": workspace_id, "mode": "canvas"}),
    );
    rpc(
        &server.socket,
        "canvas.set_frame",
        json!({"surface_id": origin_surface, "x": 100, "y": 100, "width": 200, "height": 120}),
    );
    let distant_surface = rpc(
        &server.socket,
        "canvas.new_pane",
        json!({"workspace_id": workspace_id, "type": "terminal"}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    rpc(
        &server.socket,
        "canvas.set_frame",
        json!({"surface_id": distant_surface, "x": 500, "y": 300, "width": 300, "height": 200}),
    );
    rpc(
        &server.socket,
        "surface.focus",
        json!({"surface_id": origin_surface}),
    );
    rpc(
        &server.socket,
        "debug.shortcut.set",
        json!({"name": "canvas_align_left", "combo": "ctrl+super+1"}),
    );
    let aligned = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "Super+Ctrl+1"}),
    );
    assert_eq!(aligned["action"], "align_left");
    assert_eq!(aligned["applied"], true);
    let info = rpc(&server.socket, "canvas.info", json!({}));
    assert!(info["panes"]
        .as_array()
        .unwrap()
        .iter()
        .all(|pane| pane["x"] == 100.0));

    rpc(&server.socket, "debug.command_palette.toggle", json!({}));
    let catalog = rpc(
        &server.socket,
        "debug.command_palette.results",
        json!({"limit": 256}),
    );
    let align_row = catalog["results"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["command_id"] == "palette.canvasAlignLeft")
        .unwrap();
    assert_eq!(align_row["shortcut_hint"], "⌃⌘1");
    assert_eq!(align_row["shortcut_label"], "Ctrl+Super+1");
}

#[test]
fn linux_terminal_shortcut_aliases_create_split_and_close_surfaces() {
    let server = start_server();
    let initial = rpc(&server.socket, "system.identify", json!({}));
    let workspace_id = initial["focused"]["workspace_id"].as_str().unwrap();
    let initial_surface_count = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    )["surfaces"]
        .as_array()
        .unwrap()
        .len();

    let terminal = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+shift+t"}),
    );
    assert!(
        terminal["surface_id"].is_string(),
        "response was {terminal}"
    );

    let right = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+shift+o"}),
    );
    assert!(right["pane_id"].is_string(), "response was {right}");

    let down = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+shift+e"}),
    );
    assert!(down["pane_id"].is_string(), "response was {down}");

    let closed = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+shift+w"}),
    );
    assert!(closed["surface_id"].is_string(), "response was {closed}");
    assert_eq!(
        rpc(
            &server.socket,
            "surface.list",
            json!({"workspace_id": workspace_id}),
        )["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surface_count + 2
    );

    for (name, combo) in [
        ("new_terminal", "ctrl+shift+t"),
        ("close_surface", "ctrl+shift+w"),
        ("split_right", "ctrl+shift+o"),
        ("split_down", "ctrl+shift+e"),
    ] {
        rpc(
            &server.socket,
            "debug.shortcut.set",
            json!({"name": name, "combo": "clear"}),
        );
        let disabled = rpc(
            &server.socket,
            "debug.shortcut.simulate",
            json!({"combo": combo}),
        );
        assert_eq!(disabled["handled"], false, "response was {disabled}");
        rpc(
            &server.socket,
            "debug.shortcut.set",
            json!({"name": name, "combo": "reset"}),
        );
    }
}

#[test]
fn shortcut_bindings_load_reload_and_persist_through_cmux_json() {
    let tmp = tempfile::tempdir().expect("config tempdir");
    let xdg_config = tmp.path().join("config");
    let config_path = xdg_config.join("cmux/cmux.json");
    std::fs::create_dir_all(config_path.parent().unwrap()).unwrap();
    std::fs::write(
        &config_path,
        r#"{
            "shortcuts": {
                "bindings": {
                    "newSurface": "alt+super+x",
                    "diffViewerScrollDown": "n",
                    "canvasAlignLeft": null
                }
            }
        }"#,
    )
    .unwrap();
    let xdg_config_text = xdg_config.display().to_string();
    let server = start_server_with_env(&[("XDG_CONFIG_HOME", xdg_config_text.as_str())]);
    let initial_count = rpc(&server.socket, "surface.list", json!({}))["surfaces"]
        .as_array()
        .unwrap()
        .len();

    let settings = rpc(&server.socket, "settings.shortcuts", json!({}));
    let terminal_row = settings["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["name"] == "new_terminal")
        .unwrap();
    assert_eq!(terminal_row["config_id"], "newSurface");
    assert_eq!(terminal_row["mode"], "custom");
    assert_eq!(terminal_row["combo"], "cmd+opt+x");
    let align_row = settings["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["name"] == "canvas_align_left")
        .unwrap();
    assert_eq!(align_row["mode"], "unbound");
    let diff_row = settings["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["name"] == "diff_viewer_scroll_down")
        .expect("bare diff shortcut row");
    assert_eq!(diff_row["mode"], "custom");
    assert_eq!(diff_row["combo"], "n");
    let persisted_bare = rpc(
        &server.socket,
        "settings.shortcut.set",
        json!({"name": "diff_viewer_scroll_down", "combo": "m"}),
    );
    assert_eq!(persisted_bare["persisted"], true);
    assert_eq!(persisted_bare["config_id"], "diffViewerScrollDown");
    let written: Value = serde_json::from_str(&std::fs::read_to_string(&config_path).unwrap())
        .expect("bare diff shortcut config");
    assert_eq!(
        written["shortcuts"]["bindings"]["diffViewerScrollDown"],
        "m"
    );

    assert_eq!(
        rpc(
            &server.socket,
            "debug.shortcut.simulate",
            json!({"combo": "cmd+t"})
        )["handled"],
        false
    );
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "super+alt+x"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_count + 1
    );

    std::fs::write(
        &config_path,
        r#"{"shortcuts":{"bindings":{"newSurface":"ctrl+super+y"}}}"#,
    )
    .unwrap();
    let reloaded = rpc(&server.socket, "config.reload", json!({}));
    assert_eq!(reloaded["reload_generation"], 2);
    assert_eq!(
        rpc(
            &server.socket,
            "debug.shortcut.simulate",
            json!({"combo": "super+alt+x"})
        )["handled"],
        false
    );
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "super+ctrl+y"}),
    );

    let unbound = rpc(
        &server.socket,
        "settings.shortcut.set",
        json!({"name": "new_terminal", "combo": "clear"}),
    );
    assert_eq!(unbound["persisted"], true);
    assert_eq!(unbound["config_id"], "newSurface");
    assert_eq!(unbound["mode"], "unbound");
    let written: Value = serde_json::from_str(&std::fs::read_to_string(&config_path).unwrap())
        .expect("written shortcut config");
    assert!(written["shortcuts"]["bindings"]["newSurface"].is_null());
    assert_eq!(
        rpc(
            &server.socket,
            "debug.shortcut.simulate",
            json!({"combo": "super+ctrl+y"})
        )["handled"],
        false
    );

    let reset = rpc(
        &server.socket,
        "settings.shortcut.set",
        json!({"name": "new_terminal", "combo": "reset"}),
    );
    assert_eq!(reset["mode"], "default");
    let written: Value = serde_json::from_str(&std::fs::read_to_string(&config_path).unwrap())
        .expect("reset shortcut config");
    assert!(written["shortcuts"]["bindings"].get("newSurface").is_none());
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "cmd+t"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_count + 3
    );
}

#[test]
fn global_shortcut_settings_status_and_debug_activation_use_stable_contracts() {
    let tmp = tempfile::tempdir().expect("config tempdir");
    let xdg_config = tmp.path().join("config");
    let config_path = xdg_config.join("cmux/cmux.json");
    std::fs::create_dir_all(config_path.parent().unwrap()).unwrap();
    std::fs::write(&config_path, r#"{"app":{"systemWideHotkeyEnabled":true}}"#).unwrap();
    let xdg_config_text = xdg_config.display().to_string();
    let server = start_server_with_env(&[("XDG_CONFIG_HOME", xdg_config_text.as_str())]);

    let status = rpc(&server.socket, "global_shortcuts.status", json!({}));
    assert_eq!(status["system_wide_hotkey_enabled"], true);
    assert_eq!(status["backend"], "inactive");
    assert_eq!(status["effective_registrations"][0]["id"], "globalSearch");
    assert_eq!(
        status["effective_registrations"][1]["id"],
        "showHideAllWindows"
    );

    let rows = rpc(&server.socket, "settings.shortcuts", json!({}));
    let show_hide = rows["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["config_id"] == "showHideAllWindows")
        .expect("show/hide shortcut row");
    assert_eq!(show_hide["combo"], "cmd+ctrl+opt+.");

    let fired = rpc(
        &server.socket,
        "debug.global_shortcuts.fire",
        json!({"action": "showHideAllWindows"}),
    );
    assert_eq!(fired["action"], "showHideAllWindows");
    assert_eq!(
        fired["status"]["activation_counts"]["showHideAllWindows"],
        1
    );

    let disabled = rpc(
        &server.socket,
        "settings.global_hotkey.set_enabled",
        json!({"enabled": false}),
    );
    assert_eq!(disabled["system_wide_hotkey_enabled"], false);
    assert_eq!(
        disabled["effective_registrations"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    let written: Value = serde_json::from_str(&std::fs::read_to_string(&config_path).unwrap())
        .expect("global hotkey config");
    assert_eq!(written["app"]["systemWideHotkeyEnabled"], false);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert_eq!(capabilities["features"]["global_shortcuts"], true);
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "settings.global_hotkey.status"));
}

#[test]
fn shortcut_when_clauses_route_shared_keys_and_gate_chords_by_live_context() {
    let tmp = tempfile::tempdir().expect("config tempdir");
    let xdg_config = tmp.path().join("config");
    let config_path = xdg_config.join("cmux/cmux.json");
    std::fs::create_dir_all(config_path.parent().unwrap()).unwrap();
    std::fs::write(
        &config_path,
        r#"{
            "shortcuts": {
                "bindings": {
                    "newSurface": "ctrl+super+y",
                    "openBrowser": "ctrl+super+y",
                    "toggleSidebar": ["ctrl+b", "s"]
                },
                "when": {
                    "newSurface": "terminalFocus && paneCount == 1 && workspaceCount in [1, 2] && sidebarMode =~ /files|find/ && !commandPaletteVisible && !terminalFindVisible",
                    "openBrowser": "browserFocus",
                    "toggleSidebar": "sidebarFocus"
                }
            }
        }"#,
    )
    .unwrap();
    let xdg_config_text = xdg_config.display().to_string();
    let server = start_server_with_env(&[("XDG_CONFIG_HOME", xdg_config_text.as_str())]);

    let settings = rpc(&server.socket, "settings.shortcuts", json!({}));
    let terminal_row = settings["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["name"] == "new_terminal")
        .expect("new terminal settings row");
    assert_eq!(terminal_row["when_configured"], true);
    assert!(terminal_row["when"]
        .as_str()
        .unwrap()
        .contains("paneCount == 1"));

    let initial_surfaces = rpc(&server.socket, "surface.list", json!({}))["surfaces"]
        .as_array()
        .unwrap()
        .len();
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+super+y"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surfaces + 1
    );

    let blocked = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({
            "combo": "ctrl+super+y",
            "context": {
                "terminalFocus": false,
                "browserFocus": false,
                "sidebarFocus": true,
                "markdownFocus": false
            }
        }),
    );
    assert_eq!(blocked["handled"], false);

    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({
            "combo": "ctrl+super+y",
            "context": {
                "terminalFocus": false,
                "browserFocus": true,
                "sidebarFocus": false,
                "markdownFocus": false
            }
        }),
    );
    assert_eq!(
        rpc(&server.socket, "surface.current", json!({}))["type"],
        "browser"
    );

    let terminal_prefix = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+b"}),
    );
    assert_eq!(terminal_prefix["handled"], false);
    let sidebar_prefix = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({
            "combo": "ctrl+b",
            "context": {
                "sidebarFocus": true,
                "browserFocus": false,
                "markdownFocus": false,
                "terminalFocus": false
            }
        }),
    );
    assert_eq!(sidebar_prefix["chord_pending"], true);
    let wrong_completion_context = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({
            "combo": "s",
            "context": {
                "sidebarFocus": false,
                "browserFocus": false,
                "markdownFocus": false,
                "terminalFocus": true
            }
        }),
    );
    assert_eq!(wrong_completion_context["handled"], false);
    assert_eq!(wrong_completion_context["chord_cancelled"], true);

    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({
            "combo": "ctrl+b",
            "context": {
                "sidebarFocus": true,
                "browserFocus": false,
                "markdownFocus": false,
                "terminalFocus": false
            }
        }),
    );
    let completed = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({
            "combo": "s",
            "context": {
                "sidebarFocus": true,
                "browserFocus": false,
                "markdownFocus": false,
                "terminalFocus": false
            }
        }),
    );
    assert_eq!(completed["chord_completed"], true);

    std::fs::write(
        &config_path,
        r#"{
            "shortcuts": {
                "bindings": {"newSurface": "ctrl+super+y"},
                "when": {"newSurface": "paneCount >"}
            }
        }"#,
    )
    .unwrap();
    rpc(&server.socket, "config.reload", json!({}));
    let reloaded_settings = rpc(&server.socket, "settings.shortcuts", json!({}));
    let terminal_row = reloaded_settings["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["name"] == "new_terminal")
        .expect("reloaded new terminal settings row");
    assert_eq!(terminal_row["when_configured"], false);
    let fallback = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({
            "combo": "ctrl+super+y",
            "context": {
                "sidebarFocus": true,
                "browserFocus": false,
                "markdownFocus": false,
                "terminalFocus": false
            }
        }),
    );
    assert!(fallback["surface_id"].as_str().is_some());
}

#[test]
fn shortcut_chords_consume_prefix_complete_once_cancel_and_persist() {
    let tmp = tempfile::tempdir().expect("config tempdir");
    let xdg_config = tmp.path().join("config");
    let config_path = xdg_config.join("cmux/cmux.json");
    std::fs::create_dir_all(config_path.parent().unwrap()).unwrap();
    std::fs::write(
        &config_path,
        r#"{
            "shortcuts": {
                "bindings": {
                    "newSurface": ["ctrl+b", "c"],
                    "toggleSidebar": ["ctrl+b", "s"]
                }
            }
        }"#,
    )
    .unwrap();
    let xdg_config_text = xdg_config.display().to_string();
    let server = start_server_with_env(&[("XDG_CONFIG_HOME", xdg_config_text.as_str())]);
    let initial_surfaces = rpc(&server.socket, "surface.list", json!({}))["surfaces"]
        .as_array()
        .unwrap()
        .len();

    let settings = rpc(&server.socket, "settings.shortcuts", json!({}));
    let row = settings["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["name"] == "new_terminal")
        .unwrap();
    assert_eq!(row["combo"], "ctrl+b c");
    assert_eq!(row["strokes"], json!(["ctrl+b", "c"]));
    assert_eq!(row["shortcut_hint"], "⌃B C");
    assert_eq!(row["shortcut_label"], "Ctrl+B C");

    let prefix = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+b"}),
    );
    assert_eq!(prefix["handled"], true);
    assert_eq!(prefix["chord_pending"], true);
    assert_eq!(prefix["chord_prefix"], "ctrl+b");
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surfaces
    );

    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "x"}),
    );
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "c"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surfaces
    );

    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+b"}),
    );
    let completed = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "c"}),
    );
    assert_eq!(completed["handled"], true);
    assert_eq!(completed["chord_completed"], true);
    assert_eq!(completed["chord_prefix"], "ctrl+b");
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surfaces + 1
    );

    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+b"}),
    );
    let opened = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "s"}),
    );
    assert_eq!(opened["visible"], false);
    assert_eq!(opened["chord_completed"], true);

    let persisted = rpc(
        &server.socket,
        "settings.shortcut.set",
        json!({"name": "new_terminal", "combo": "ctrl+k n"}),
    );
    assert_eq!(persisted["strokes"], json!(["ctrl+k", "n"]));
    let written: Value = serde_json::from_str(&std::fs::read_to_string(&config_path).unwrap())
        .expect("written chord config");
    assert_eq!(
        written["shortcuts"]["bindings"]["newSurface"],
        json!(["ctrl+k", "n"])
    );
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+k"}),
    );
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "n"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surfaces + 2
    );

    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "ctrl+k"}),
    );
    rpc(&server.socket, "config.reload", json!({}));
    rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "n"}),
    );
    assert_eq!(
        rpc(&server.socket, "surface.list", json!({}))["surfaces"]
            .as_array()
            .unwrap()
            .len(),
        initial_surfaces + 2
    );
}

#[test]
fn renderer_snapshot_ghostty_vt_embeds_render_state_for_terminal_views() {
    let server = start_server();
    let scroll_lines = (0..36)
        .map(|index| format!("CMUX_SCROLL_{index:02}"))
        .collect::<Vec<_>>()
        .join(" ");
    let command = format!(
        "for i in {scroll_lines}; do printf 'CMUX_SCROLL_%s\\n' \"$i\"; done; printf 'CMUX_GHOSTTY_FRAME\\n'\n"
    );
    rpc(
        &server.socket,
        "surface.send_text",
        json!({"text": command}),
    );
    let deadline = Instant::now() + Duration::from_secs(4);
    while Instant::now() < deadline {
        let text = rpc(&server.socket, "surface.read_text", json!({}));
        if text["text"]
            .as_str()
            .unwrap_or_default()
            .contains("CMUX_GHOSTTY_FRAME")
        {
            break;
        }
        thread::sleep(Duration::from_millis(50));
    }

    let snapshot = rpc(
        &server.socket,
        "renderer.snapshot",
        json!({"backend": "ghostty-vt"}),
    );
    let view = snapshot["surface_views"]
        .as_array()
        .unwrap()
        .iter()
        .find(|view| view["kind"] == "terminal")
        .expect("terminal view");
    let fallback_text = view["render_grid"]["row_spans"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|span| span["text"].as_str())
        .collect::<String>();
    assert!(
        fallback_text.contains("CMUX_GHOSTTY_FRAME"),
        "fallback render grid was missing terminal output: {snapshot}"
    );
    let fallback_scrollback = view["render_grid"]["scrollback_spans"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|span| span["text"].as_str())
        .collect::<String>();
    assert!(
        fallback_scrollback.contains("CMUX_SCROLL"),
        "fallback render grid was missing bounded scrollback: {snapshot}"
    );
    if view.get("ghostty_vt_error").is_some() {
        assert!(
            view["ghostty_vt_error"]["message"]
                .as_str()
                .unwrap_or_default()
                .contains("libghostty-vt was not found"),
            "snapshot was {snapshot}"
        );
        eprintln!("SKIP: libghostty-vt is not available");
        return;
    }

    let render = &view["ghostty_vt"];
    assert_eq!(render["parser"], "ghostty-vt");
    assert_eq!(render["cols"], 80);
    assert_eq!(render["rows"], 30);
    assert_eq!(render["row_count"], 30);
    let rendered_text = render["rows_data"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|row| row["cells"].as_array().into_iter().flatten())
        .filter_map(|cell| cell["text"].as_str().map(str::to_string))
        .collect::<String>();
    assert!(
        rendered_text.contains("CMUX_GHOSTTY_FRAME"),
        "snapshot was {snapshot}"
    );
}

#[test]
fn ghostty_vt_formatter_reports_unavailable_without_library() {
    let ghostty_root = tempfile::tempdir().expect("ghostty root");
    let root_path = ghostty_root.path().display().to_string();
    let missing_library = ghostty_root.path().join("missing.so").display().to_string();
    let server = start_server_with_env(&[
        ("CMUX_GHOSTTY_ROOT", root_path.as_str()),
        ("CMUX_GHOSTTY_VT_LIBRARY", missing_library.as_str()),
    ]);

    let response = rpc_response(
        &server.socket,
        "renderer.ghostty_vt.format",
        json!({"text": "hello", "cols": 20, "rows": 4}),
    );
    assert_eq!(response["ok"], false, "response was {response}");
    assert_eq!(response["error"]["code"], "not_supported");
    assert!(
        response["error"]["message"]
            .as_str()
            .unwrap_or_default()
            .contains("libghostty-vt was not found"),
        "response was {response}"
    );
}

#[test]
fn ghostty_vt_formatter_formats_vt_stream_when_library_is_available() {
    let server = start_server();
    let response = rpc_response(
        &server.socket,
        "renderer.ghostty_vt.format",
        json!({"text": "old value\r\u{1b}[2Knew value\n", "cols": 80, "rows": 5}),
    );
    if response["ok"] == false
        && response["error"]["code"] == "not_supported"
        && response["error"]["message"]
            .as_str()
            .unwrap_or_default()
            .contains("libghostty-vt was not found")
    {
        eprintln!("SKIP: libghostty-vt is not available");
        return;
    }
    assert_eq!(response["ok"], true, "response was {response}");
    let result = &response["result"];
    let text = result["text"].as_str().unwrap_or_default();
    assert!(text.contains("new value"), "response was {response}");
    assert!(!text.contains("old value"), "response was {response}");
    assert_eq!(result["parser"], "ghostty-vt");
    assert!(
        result["library"]
            .as_str()
            .unwrap_or_default()
            .contains("libghostty-vt"),
        "response was {response}"
    );
}

#[test]
fn renderer_apply_size_resizes_backing_terminal_pty() {
    let server = start_server();
    let ident = rpc(&server.socket, "system.identify", json!({}));
    let pane_id = ident["focused"]["pane_id"].as_str().unwrap();
    let surface_id = ident["focused"]["surface_id"].as_str().unwrap();

    let resized = rpc(
        &server.socket,
        "renderer.apply_size",
        json!({
            "pane_id": pane_id,
            "cols": 91,
            "rows": 27,
            "pixel_width": 910,
            "pixel_height": 540
        }),
    );
    assert_eq!(resized["terminal_size"]["cols"], 91);
    assert_eq!(resized["terminal_size"]["rows"], 27);
    assert_eq!(resized["frame"]["width"], 800.0);
    assert_eq!(resized["frame"]["height"], 600.0);

    let terminals = rpc(&server.socket, "debug.terminals", json!({}));
    let terminal = terminals["terminals"]
        .as_array()
        .unwrap()
        .iter()
        .find(|terminal| terminal["surface_id"] == surface_id)
        .expect("terminal row");
    assert_eq!(terminal["terminal_size"]["cols"], 91);
    assert_eq!(terminal["terminal_size"]["rows"], 27);
    assert_eq!(terminal["terminal_size"]["pixel_width"], 910);
    assert_eq!(terminal["terminal_size"]["pixel_height"], 540);

    let cli_resized: Value = serde_json::from_str(&cli(
        &server.socket,
        &[
            "--json",
            "renderer",
            "apply-size",
            "--pane",
            pane_id,
            "--cols",
            "92",
            "--rows",
            "28",
            "--pixel-width",
            "920",
            "--pixel-height",
            "560",
        ],
    ))
    .expect("renderer apply-size json");
    assert_eq!(cli_resized["terminal_size"]["cols"], 92);
    assert_eq!(cli_resized["terminal_size"]["rows"], 28);

    let missing_pixel_height = cli_failure(
        &server.socket,
        &[
            "renderer",
            "apply-size",
            "--pane",
            pane_id,
            "--cols",
            "92",
            "--rows",
            "28",
            "--pixel-width",
            "920",
        ],
    );
    assert!(
        missing_pixel_height.contains("renderer apply-size requires --pixel-height"),
        "stderr was {missing_pixel_height}"
    );

    let unknown_flag = cli_failure(
        &server.socket,
        &[
            "renderer",
            "apply-size",
            "--pane",
            pane_id,
            "--cols",
            "92",
            "--rows",
            "28",
            "--pixel-width",
            "920",
            "--pixel-height",
            "560",
            "--bogus",
            "value",
        ],
    );
    assert!(
        unknown_flag.contains("renderer apply-size: unknown argument '--bogus'"),
        "stderr was {unknown_flag}"
    );
}

#[test]
fn cmuxd_remote_binary_embeds_app_version_marker() {
    let marker = format!("cmux-linux-{}", env!("CARGO_PKG_VERSION"));
    let output = Command::new(env!("CARGO_BIN_EXE_cmuxd-remote"))
        .arg("version")
        .output()
        .expect("run cmuxd-remote version");
    assert!(
        output.status.success(),
        "version command failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains(&marker), "stdout was {stdout}");

    let binary = std::fs::read(env!("CARGO_BIN_EXE_cmuxd-remote")).expect("read cmuxd-remote");
    assert!(
        binary
            .windows(marker.len())
            .any(|window| window == marker.as_bytes()),
        "cmuxd-remote binary did not contain {marker}"
    );
}

#[test]
fn cli_remote_daemon_status_reports_local_binary_and_cache() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let output = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("--json")
        .arg("remote-daemon-status")
        .env("TMPDIR", tmp.path())
        .output()
        .expect("run remote-daemon-status");
    assert!(
        output.status.success(),
        "remote-daemon-status failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let payload: Value = serde_json::from_slice(&output.stdout).expect("status json");
    let expected_arch = match std::env::consts::ARCH {
        "x86_64" => "amd64",
        "aarch64" => "arm64",
        other => other,
    };
    assert_eq!(payload["app_version"], env!("CARGO_PKG_VERSION"));
    assert_eq!(
        payload["remote_daemon_version"],
        format!("cmux-linux-{}", env!("CARGO_PKG_VERSION"))
    );
    assert_eq!(payload["manifest_present"], false);
    assert_eq!(payload["target_goos"], "linux");
    assert_eq!(payload["target_goarch"], expected_arch);
    assert_eq!(payload["local_binary_exists"], true);
    assert!(
        payload["local_binary_path"]
            .as_str()
            .unwrap_or_default()
            .ends_with("cmuxd-remote"),
        "payload was {payload}"
    );
    assert_eq!(
        payload["local_binary_sha256"]
            .as_str()
            .unwrap_or_default()
            .len(),
        64
    );
    assert_eq!(payload["cache_exists"], false);
    assert_eq!(payload["cache_verified"], false);
    assert!(
        payload["cache_path"]
            .as_str()
            .unwrap_or_default()
            .starts_with(tmp.path().to_str().unwrap()),
        "payload was {payload}"
    );
    assert!(
        payload["download_command"]
            .as_str()
            .unwrap_or_default()
            .contains(payload["asset_name"].as_str().unwrap()),
        "payload was {payload}"
    );

    let text = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("remote-daemon-status")
        .arg("--os")
        .arg("linux")
        .arg("--arch")
        .arg("arm64")
        .env("TMPDIR", tmp.path())
        .output()
        .expect("run remote-daemon-status text");
    assert!(
        text.status.success(),
        "remote-daemon-status text failed: stdout={} stderr={}",
        String::from_utf8_lossy(&text.stdout),
        String::from_utf8_lossy(&text.stderr)
    );
    let stdout = String::from_utf8(text.stdout).expect("status text utf8");
    assert!(
        stdout.contains("platform: linux/arm64"),
        "stdout was {stdout}"
    );
    assert!(
        stdout.contains("cache platform: linux-aarch64"),
        "stdout was {stdout}"
    );
    assert!(stdout.contains("manifest: missing"), "stdout was {stdout}");

    let invalid = Command::new(env!("CARGO_BIN_EXE_cmux"))
        .arg("remote-daemon-status")
        .arg("--arch")
        .arg("mips")
        .output()
        .expect("run invalid remote-daemon-status");
    assert!(
        !invalid.status.success(),
        "invalid arch unexpectedly succeeded: stdout={} stderr={}",
        String::from_utf8_lossy(&invalid.stdout),
        String::from_utf8_lossy(&invalid.stderr)
    );
    let stderr = String::from_utf8(invalid.stderr).expect("stderr utf8");
    assert!(
        stderr.contains("unsupported remote daemon arch"),
        "stderr was {stderr}"
    );
}

#[test]
fn cmuxd_remote_stdio_proxy_stream_round_trips_tcp() {
    let listener = TcpListener::bind(("127.0.0.1", 0)).expect("bind upstream");
    let port = listener.local_addr().expect("upstream addr").port();
    let (done_tx, done_rx) = mpsc::channel();
    thread::spawn(move || {
        let (mut conn, _) = listener.accept().expect("accept upstream");
        let mut payload = [0_u8; 4];
        conn.read_exact(&mut payload)
            .expect("read upstream payload");
        assert_eq!(&payload, b"ping");
        conn.write_all(b"pong").expect("write upstream payload");
        done_tx.send(()).expect("upstream done");
    });

    let mut child = Command::new(env!("CARGO_BIN_EXE_cmuxd-remote"))
        .args(["serve", "--stdio"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn cmuxd-remote");
    let mut stdin = child.stdin.take().expect("daemon stdin");
    let stdout = child.stdout.take().expect("daemon stdout");
    let (frame_tx, frame_rx) = mpsc::channel();
    thread::spawn(move || {
        let reader = BufReader::new(stdout);
        for line in reader.lines().map_while(Result::ok) {
            if line.trim().is_empty() {
                continue;
            }
            if let Ok(frame) = serde_json::from_str::<Value>(&line) {
                let _ = frame_tx.send(frame);
            }
        }
    });

    let hello = daemon_rpc(&mut stdin, &frame_rx, 1, "hello", json!({}));
    let capabilities = hello["capabilities"].as_array().expect("capabilities");
    assert!(capabilities.iter().any(|value| value == "proxy.stream"));
    assert!(capabilities.iter().any(|value| value == "proxy.socks5"));
    assert!(capabilities
        .iter()
        .any(|value| value == "proxy.http_connect"));

    let opened = daemon_rpc(
        &mut stdin,
        &frame_rx,
        2,
        "proxy.open",
        json!({"host": "127.0.0.1", "port": port, "timeout_ms": 1000}),
    );
    let stream_id = opened["stream_id"].as_str().expect("stream id");
    let written = daemon_rpc(
        &mut stdin,
        &frame_rx,
        3,
        "proxy.write",
        json!({
            "stream_id": stream_id,
            "data_base64": base64::engine::general_purpose::STANDARD.encode(b"ping")
        }),
    );
    assert_eq!(written["written"], 4);

    let subscribed = daemon_rpc(
        &mut stdin,
        &frame_rx,
        4,
        "proxy.stream.subscribe",
        json!({"stream_id": stream_id}),
    );
    assert_eq!(subscribed["subscribed"], true);
    let event = daemon_event(&frame_rx, "proxy.stream.data", stream_id);
    let data = base64::engine::general_purpose::STANDARD
        .decode(event["data_base64"].as_str().expect("event data"))
        .expect("decode event data");
    assert_eq!(data, b"pong");

    let closed = daemon_rpc(
        &mut stdin,
        &frame_rx,
        5,
        "proxy.close",
        json!({"stream_id": stream_id}),
    );
    assert_eq!(closed["closed"], true);
    done_rx
        .recv_timeout(Duration::from_secs(2))
        .expect("upstream server finished");

    drop(stdin);
    let _ = child.kill();
    let _ = child.wait();
}

#[test]
fn cmuxd_remote_session_lifecycle_tracks_detachable_resize_state() {
    let mut child = Command::new(env!("CARGO_BIN_EXE_cmuxd-remote"))
        .args(["serve", "--stdio"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn cmuxd-remote");
    let mut stdin = child.stdin.take().expect("daemon stdin");
    let stdout = child.stdout.take().expect("daemon stdout");
    let (frame_tx, frame_rx) = mpsc::channel();
    thread::spawn(move || {
        let reader = BufReader::new(stdout);
        for line in reader.lines().map_while(Result::ok) {
            if line.trim().is_empty() {
                continue;
            }
            if let Ok(frame) = serde_json::from_str::<Value>(&line) {
                let _ = frame_tx.send(frame);
            }
        }
    });

    let hello = daemon_rpc(&mut stdin, &frame_rx, 1, "hello", json!({}));
    let capabilities = hello["capabilities"].as_array().expect("capabilities");
    for capability in [
        "session.lifecycle",
        "session.attach",
        "session.detach",
        "session.status",
        "session.close",
        "session.resize.min",
        "pty.session.persistent_daemon",
    ] {
        assert!(
            capabilities.iter().any(|value| value == capability),
            "missing capability {capability}: {hello}"
        );
    }

    let opened = daemon_rpc(
        &mut stdin,
        &frame_rx,
        2,
        "session.open",
        json!({
            "session_id": "ssh-pty-1",
            "command": "exec $SHELL -i",
            "attachment_id": "desktop",
            "cols": 120,
            "rows": 40
        }),
    );
    assert_eq!(opened["session_id"], "ssh-pty-1");
    assert_eq!(opened["cols"], 120);
    assert_eq!(opened["rows"], 40);
    assert_eq!(opened["attachment_count"], 1);

    let phone = daemon_rpc(
        &mut stdin,
        &frame_rx,
        3,
        "session.attach",
        json!({
            "session_id": "ssh-pty-1",
            "attachment_id": "phone",
            "cols": 82,
            "rows": 20
        }),
    );
    assert_eq!(phone["attachment_id"], "phone");
    assert_eq!(phone["cols"], 82);
    assert_eq!(phone["rows"], 20);
    assert_eq!(phone["attachment_count"], 2);

    let phone_grew = daemon_rpc(
        &mut stdin,
        &frame_rx,
        4,
        "session.resize",
        json!({
            "session_id": "ssh-pty-1",
            "attachment_id": "phone",
            "cols": 90,
            "rows": 22
        }),
    );
    assert_eq!(phone_grew["cols"], 90);
    assert_eq!(phone_grew["rows"], 22);

    let detached_phone = daemon_rpc(
        &mut stdin,
        &frame_rx,
        5,
        "session.detach",
        json!({
            "session_id": "ssh-pty-1",
            "attachment_id": "phone"
        }),
    );
    assert_eq!(detached_phone["detached"], true);
    assert_eq!(detached_phone["cols"], 120);
    assert_eq!(detached_phone["rows"], 40);
    assert_eq!(detached_phone["attachment_count"], 1);

    let detached_desktop = daemon_rpc(
        &mut stdin,
        &frame_rx,
        6,
        "session.detach",
        json!({
            "session_id": "ssh-pty-1",
            "attachment_id": "desktop"
        }),
    );
    assert_eq!(detached_desktop["detached"], true);
    assert_eq!(detached_desktop["cols"], 120);
    assert_eq!(detached_desktop["rows"], 40);
    assert_eq!(detached_desktop["attachment_count"], 0);

    let status = daemon_rpc(
        &mut stdin,
        &frame_rx,
        7,
        "session.status",
        json!({"session_id": "ssh-pty-1"}),
    );
    assert_eq!(status["session_id"], "ssh-pty-1");
    assert_eq!(status["attachment_count"], 0);

    let closed = daemon_rpc(
        &mut stdin,
        &frame_rx,
        8,
        "session.close",
        json!({"session_id": "ssh-pty-1"}),
    );
    assert_eq!(closed["closed"], true);
    assert_eq!(closed["session_id"], "ssh-pty-1");

    let listed = daemon_rpc(&mut stdin, &frame_rx, 9, "session.status", json!({}));
    assert_eq!(listed["session_count"], 0);
    assert_eq!(listed["sessions"], json!([]));

    drop(stdin);
    let _ = child.kill();
    let _ = child.wait();
}

#[test]
fn new_split_direction_flag_builds_nested_t_layout() {
    let server = start_server();
    let initial = rpc(&server.socket, "system.identify", json!({}));
    let initial_surface = initial["focused"]["surface_ref"].as_str().unwrap();

    let right = cli(
        &server.socket,
        &[
            "new-split",
            "--surface",
            initial_surface,
            "--direction",
            "right",
        ],
    );
    assert!(
        right.contains("surface:2"),
        "unexpected split output: {right}"
    );
    let down = cli(
        &server.socket,
        &["new-split", "--surface", "surface:2", "--direction", "down"],
    );
    assert!(
        down.contains("surface:3"),
        "unexpected split output: {down}"
    );

    let panes = rpc(&server.socket, "pane.list", json!({}));
    let frames = panes["panes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|pane| pane["frame"].clone())
        .collect::<Vec<_>>();
    assert!(frames.contains(&json!({
        "x": 0.0, "y": 0.0, "width": 400.0, "height": 600.0
    })));
    assert!(frames.contains(&json!({
        "x": 400.0, "y": 0.0, "width": 400.0, "height": 300.0
    })));
    assert!(frames.contains(&json!({
        "x": 400.0, "y": 300.0, "width": 400.0, "height": 300.0
    })));
}

#[test]
fn session_resize_tracks_smallest_attachment_and_detach_transitions() {
    let server = start_server();
    let ident = rpc(&server.socket, "system.identify", json!({}));
    let pane_id = ident["focused"]["pane_id"].as_str().unwrap();
    let surface_id = ident["focused"]["surface_id"].as_str().unwrap();

    rpc(
        &server.socket,
        "renderer.apply_size",
        json!({
            "pane_id": pane_id,
            "cols": 120,
            "rows": 40,
            "pixel_width": 1200,
            "pixel_height": 800
        }),
    );
    let desktop = rpc(
        &server.socket,
        "session.resize.set",
        json!({
            "pane_id": pane_id,
            "attachment_id": "desktop",
            "cols": 120,
            "rows": 40
        }),
    );
    assert_eq!(desktop["terminal_size"]["cols"], 120);
    assert_eq!(desktop["terminal_size"]["rows"], 40);

    let phone = rpc(
        &server.socket,
        "session.resize.set",
        json!({
            "pane_id": pane_id,
            "attachment_id": "phone",
            "cols": 82,
            "rows": 20
        }),
    );
    assert_eq!(phone["terminal_size"]["cols"], 82);
    assert_eq!(phone["terminal_size"]["rows"], 20);

    let terminals = rpc(&server.socket, "debug.terminals", json!({}));
    let terminal = terminals["terminals"]
        .as_array()
        .unwrap()
        .iter()
        .find(|terminal| terminal["surface_id"] == surface_id)
        .expect("terminal row");
    assert_eq!(terminal["terminal_size"]["cols"], 82);
    assert_eq!(terminal["terminal_size"]["rows"], 20);

    let phone_reconnect = rpc(
        &server.socket,
        "session.resize.set",
        json!({
            "pane_id": pane_id,
            "attachment_id": "phone",
            "cols": 90,
            "rows": 22
        }),
    );
    assert_eq!(phone_reconnect["terminal_size"]["cols"], 90);
    assert_eq!(phone_reconnect["terminal_size"]["rows"], 22);

    let after_phone_detach = rpc(
        &server.socket,
        "session.resize.clear",
        json!({
            "pane_id": pane_id,
            "attachment_id": "phone"
        }),
    );
    assert_eq!(after_phone_detach["terminal_size"]["cols"], 120);
    assert_eq!(after_phone_detach["terminal_size"]["rows"], 40);

    let min = rpc(
        &server.socket,
        "session.resize.min",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(min["terminal_size"]["cols"], 120);
    assert_eq!(min["terminal_size"]["rows"], 40);

    let after_desktop_detach = rpc(
        &server.socket,
        "session.resize.clear",
        json!({
            "pane_id": pane_id,
            "attachment_id": "desktop"
        }),
    );
    assert_eq!(after_desktop_detach["terminal_size"]["cols"], 120);
    assert_eq!(after_desktop_detach["terminal_size"]["rows"], 40);
}

#[test]
fn remote_workspace_lifecycle_methods_match_macos_contract() {
    let fake = fake_ssh();
    let server = start_server_with_env(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().expect("methods");
    for method in [
        "workspace.remote.foreground_auth_ready",
        "workspace.remote.pty_bridge",
        "workspace.remote.pty_close",
        "workspace.remote.pty_detach",
        "workspace.remote.pty_resize",
        "workspace.remote.pty_sessions",
        "workspace.remote.pty_attach_end",
        "workspace.remote.terminal_session_end",
        "ssh.session.snapshot",
        "ssh.session.restore_snapshot",
    ] {
        assert!(
            methods.iter().any(|value| value == method),
            "missing method {method} from capabilities"
        );
    }
    assert_eq!(capabilities["features"]["ssh_remote_lifecycle"], true);

    let created = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote lifecycle",
            "destination": "lifecycle.example",
            "identity_file": "/tmp/cmux-fake-key"
        }),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    let current_surface = rpc(&server.socket, "surface.current", json!({}));
    assert_eq!(current_surface["workspace_id"], workspace_id);
    let surface_id = current_surface["surface_id"].as_str().unwrap();
    let session_id = created["ssh_pty_session_id"].as_str().unwrap();
    let relay_port = created["remote_relay_port"].as_u64().unwrap();
    assert_eq!(created["remote"]["active_terminal_sessions"], 1);
    let startup_command = created["ssh_startup_command"]
        .as_str()
        .expect("ssh startup command");
    let terminal_command = created["ssh_terminal_command"]
        .as_str()
        .expect("ssh terminal command");
    assert!(
        terminal_command.starts_with("ssh -tt "),
        "terminal command was {terminal_command}"
    );
    assert!(
        terminal_command.contains("cat > \"$cmux_tmp\";"),
        "terminal command was {terminal_command}"
    );
    assert!(
        terminal_command.contains("sh \"$cmux_tmp\" </dev/tty"),
        "terminal command was {terminal_command}"
    );
    assert!(
        terminal_command.contains(startup_command),
        "terminal command {terminal_command} did not reference startup script {startup_command}"
    );

    let wrapper_path = std::path::Path::new(&fake.remote_home)
        .join(".cmux")
        .join("bin")
        .join("cmux");
    assert!(
        wrapper_path.is_file(),
        "fake remote cmux wrapper was not uploaded to {}",
        wrapper_path.display()
    );
    let bridge_port = start_tcp_socket_bridge(&server.socket);
    let remote_new_workspace = Command::new(&wrapper_path)
        .arg("--json")
        .arg("new-workspace")
        .arg("--name")
        .arg("remote relay workspace")
        .env("CMUX_SOCKET_PATH", format!("127.0.0.1:{bridge_port}"))
        .output()
        .expect("run uploaded remote cmux wrapper");
    assert!(
        remote_new_workspace.status.success(),
        "remote new-workspace failed: stdout={} stderr={}",
        String::from_utf8_lossy(&remote_new_workspace.stdout),
        String::from_utf8_lossy(&remote_new_workspace.stderr)
    );
    let remote_created_workspace: Value =
        serde_json::from_slice(&remote_new_workspace.stdout).expect("remote workspace json");
    let remote_created_workspace_id = remote_created_workspace["workspace_id"].as_str().unwrap();
    let listed_after_remote_wrapper = rpc(&server.socket, "workspace.list", json!({}));
    assert!(
        listed_after_remote_wrapper["workspaces"]
            .as_array()
            .unwrap()
            .iter()
            .any(|workspace| {
                workspace["workspace_id"] == remote_created_workspace_id
                    && workspace["title"] == "remote relay workspace"
            }),
        "remote wrapper new-workspace did not create expected workspace: {listed_after_remote_wrapper}"
    );

    let auth_ready = rpc(
        &server.socket,
        "workspace.remote.foreground_auth_ready",
        json!({
            "workspace_id": workspace_id,
            "foreground_auth_token": "  ready-token  "
        }),
    );
    assert_eq!(auth_ready["workspace_id"], workspace_id);
    assert_eq!(auth_ready["workspace_ref"], "workspace:2");
    assert_eq!(auth_ready["remote"]["state"], "connected");
    assert_eq!(auth_ready["remote"]["active_terminal_sessions"], 1);

    let pty_sessions = rpc(
        &server.socket,
        "workspace.remote.pty_sessions",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(pty_sessions["workspace_id"], workspace_id);
    assert_eq!(pty_sessions["sessions"].as_array().unwrap().len(), 1);
    assert_eq!(pty_sessions["sessions"][0]["session_id"], session_id);
    assert_eq!(pty_sessions["sessions"][0]["surface_id"], surface_id);

    let all_pty_sessions = rpc(
        &server.socket,
        "workspace.remote.pty_sessions",
        json!({"all_workspaces": true}),
    );
    assert_eq!(all_pty_sessions["all_workspaces"], true);
    assert!(all_pty_sessions["sessions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|session| session["session_id"] == session_id));

    let detach_target = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote detach",
            "destination": "detach.example",
            "identity_file": "/tmp/cmux-fake-key"
        }),
    );
    let detach_workspace_id = detach_target["workspace_id"].as_str().unwrap();
    let detach_surface_id = detach_target["surface_id"].as_str().unwrap();
    let detach_session_id = detach_target["ssh_pty_session_id"].as_str().unwrap();
    let cli_list_attached = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "ssh-session-list",
            "--workspace",
            detach_workspace_id,
        ],
        &[],
    );
    assert_eq!(
        cli_list_attached["sessions"][0]["session_id"],
        detach_session_id
    );
    assert_eq!(
        cli_list_attached["sessions"][0]["attachments"][0]["surface_id"],
        detach_surface_id
    );

    let detach_probe_command = "CMUX_DETACH_MARK=keep-ssh-session; printf 'CMUX_DETACH_PROBE:START'; printf 'pid=%s marker=%s socket=%s\\n' \"$$\" \"$CMUX_DETACH_MARK\" \"$CMUX_SOCKET_PATH\"; printf 'CMUX_DETACH_PROBE:END'\n";
    rpc(
        &server.socket,
        "surface.send_text",
        json!({"surface_id": detach_surface_id, "text": detach_probe_command}),
    );
    let attached_probe = rpc(
        &server.socket,
        "surface.read_text",
        json!({"surface_id": detach_surface_id}),
    );
    let attached_probe_line = attached_probe["text"]
        .as_str()
        .unwrap_or_default()
        .lines()
        .find(|line| line.starts_with("pid="))
        .expect("attached detachable probe line")
        .to_string();
    assert!(
        attached_probe_line.contains("marker=keep-ssh-session")
            && attached_probe_line.contains("socket=127.0.0.1:"),
        "attached probe was {attached_probe}"
    );

    rpc(
        &server.socket,
        "surface.create",
        json!({
            "workspace_id": detach_workspace_id,
            "type": "terminal",
            "focus": false
        }),
    );
    let cli_closed_surface = cli_json_with_env(
        &server.socket,
        &["--id-format", "both", "close-surface", detach_surface_id],
        &[],
    );
    assert_eq!(cli_closed_surface["surface_id"], detach_surface_id);
    let cli_list_detached = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "ssh-session-list",
            "--workspace-id",
            detach_workspace_id,
        ],
        &[],
    );
    assert_eq!(
        cli_list_detached["sessions"][0]["session_id"],
        detach_session_id
    );
    assert_eq!(cli_list_detached["sessions"][0]["attachments"], json!([]));
    assert!(cli_list_detached["sessions"][0]["scrollback_bytes"]
        .as_u64()
        .is_some());

    let all_detached = rpc(
        &server.socket,
        "ssh.session.list",
        json!({"all_workspaces": true}),
    );
    assert_eq!(all_detached["all_workspaces"], true);
    assert!(all_detached["session_count"].as_u64().unwrap() >= 2);
    assert!(all_detached["workspace_count"].as_u64().unwrap() >= 2);
    assert!(all_detached["sessions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|session| session["session_id"] == detach_session_id
            && session["workspace_id"] == detach_workspace_id
            && session["attachments"] == json!([])));

    let cli_all_detached = cli_json_with_env(&server.socket, &["ssh-session-list", "--all"], &[]);
    assert_eq!(cli_all_detached["all_workspaces"], true);
    assert!(cli_all_detached["sessions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|session| session["session_id"] == detach_session_id));

    let invalid_all_with_workspace = rpc_response(
        &server.socket,
        "ssh.session.list",
        json!({"all_workspaces": true, "workspace_id": detach_workspace_id}),
    );
    assert_eq!(invalid_all_with_workspace["ok"], false);
    assert_eq!(
        invalid_all_with_workspace["error"]["code"],
        "invalid_params"
    );

    let detached_snapshot = rpc(
        &server.socket,
        "ssh.session.snapshot",
        json!({"workspace_id": detach_workspace_id}),
    );
    assert_eq!(detached_snapshot["version"], 1);
    assert_eq!(detached_snapshot["session_count"], 1);
    assert_eq!(
        detached_snapshot["sessions"][0]["session_id"],
        detach_session_id
    );
    assert_eq!(
        detached_snapshot["sessions"][0]["persistent_daemon_slot"],
        detach_target["persistent_daemon_slot"]
    );
    assert_eq!(
        detached_snapshot["sessions"][0]["remote"]["persistent_daemon_slot"],
        detach_target["persistent_daemon_slot"]
    );
    let cli_snapshot = cli_json_with_env(
        &server.socket,
        &["ssh-session-snapshot", "--workspace", detach_workspace_id],
        &[],
    );
    assert_eq!(cli_snapshot["session_count"], 1);
    assert_eq!(cli_snapshot["sessions"][0]["session_id"], detach_session_id);

    let cli_attached = cli_json_with_env(
        &server.socket,
        &[
            "--id-format",
            "both",
            "ssh-session-attach",
            detach_session_id,
            "--workspace-id",
            detach_workspace_id,
        ],
        &[],
    );
    assert_eq!(cli_attached["workspace_id"], detach_workspace_id);
    assert_eq!(cli_attached["session_id"], detach_session_id);
    assert_ne!(cli_attached["surface_id"], detach_surface_id);
    let reattached_surface_id = cli_attached["surface_id"].as_str().unwrap();
    let reattach_probe_command = "printf 'CMUX_DETACH_PROBE:START'; printf 'pid=%s marker=%s socket=%s\\n' \"$$\" \"$CMUX_DETACH_MARK\" \"$CMUX_SOCKET_PATH\"; printf 'CMUX_DETACH_PROBE:END'\n";
    rpc(
        &server.socket,
        "surface.send_text",
        json!({"surface_id": reattached_surface_id, "text": reattach_probe_command}),
    );
    let reattached_probe = rpc(
        &server.socket,
        "surface.read_text",
        json!({"surface_id": reattached_surface_id}),
    );
    let reattached_probe_line = reattached_probe["text"]
        .as_str()
        .unwrap_or_default()
        .lines()
        .find(|line| line.starts_with("pid="))
        .expect("reattached detachable probe line")
        .to_string();
    assert_eq!(
        reattached_probe_line, attached_probe_line,
        "reattach should preserve remote shell identity and env"
    );

    let cli_cleaned = cli_json_with_env(
        &server.socket,
        &[
            "ssh-session-cleanup",
            detach_session_id,
            "--workspace",
            detach_workspace_id,
        ],
        &[],
    );
    assert_eq!(cli_cleaned["session_id"], detach_session_id);
    assert_eq!(cli_cleaned["removed"], true);
    let cli_list_cleaned = cli_json_with_env(
        &server.socket,
        &["ssh-session-list", "--workspace", detach_workspace_id],
        &[],
    );
    assert_eq!(cli_list_cleaned["sessions"], json!([]));

    let mut restore_snapshot = detached_snapshot.clone();
    let mut missing_slot = restore_snapshot["sessions"][0].clone();
    missing_slot["session_id"] = json!("missing-persistent-slot");
    missing_slot["persistent_daemon_slot"] = Value::Null;
    restore_snapshot["sessions"]
        .as_array_mut()
        .unwrap()
        .push(missing_slot);
    let restore_path = server._tmp.path().join("ssh-session-snapshot.json");
    std::fs::write(
        &restore_path,
        serde_json::to_string(&restore_snapshot).expect("restore snapshot json"),
    )
    .expect("write restore snapshot");
    let restore_path_text = restore_path.display().to_string();
    let restored = cli_json_with_env(
        &server.socket,
        &["ssh-session-restore", "--file", restore_path_text.as_str()],
        &[],
    );
    assert_eq!(restored["restored_count"], 1);
    assert_eq!(restored["skipped_count"], 1);
    assert_eq!(restored["restored"][0]["session_id"], detach_session_id);
    assert_eq!(
        restored["skipped"][0]["reason"],
        "missing_persistent_daemon_slot"
    );
    let restored_sessions = rpc(
        &server.socket,
        "ssh.session.list",
        json!({"workspace_id": detach_workspace_id}),
    );
    assert_eq!(
        restored_sessions["sessions"][0]["session_id"],
        detach_session_id
    );
    assert_eq!(restored_sessions["sessions"][0]["attachments"], json!([]));

    let bridge = rpc(
        &server.socket,
        "workspace.remote.pty_bridge",
        json!({
            "workspace_id": workspace_id,
            "session_id": session_id,
            "attachment_id": "desktop",
            "require_existing": true
        }),
    );
    assert_eq!(bridge["workspace_id"], workspace_id);
    assert_eq!(bridge["host"], "127.0.0.1");
    assert_eq!(bridge["port"], relay_port);
    assert_eq!(bridge["session_id"], session_id);
    assert_eq!(bridge["attachment_id"], "desktop");
    let attachment_token = bridge["token"].as_str().unwrap();
    assert!(!attachment_token.is_empty());

    let resized = rpc(
        &server.socket,
        "workspace.remote.pty_resize",
        json!({
            "workspace_id": workspace_id,
            "session_id": session_id,
            "attachment_id": "desktop",
            "attachment_token": attachment_token,
            "cols": 100,
            "rows": 33
        }),
    );
    assert_eq!(resized["resized"], true);
    assert_eq!(resized["cols"], 100);
    assert_eq!(resized["rows"], 33);

    let detached = rpc(
        &server.socket,
        "workspace.remote.pty_detach",
        json!({
            "workspace_id": workspace_id,
            "session_id": session_id,
            "attachment_id": "desktop",
            "attachment_token": attachment_token
        }),
    );
    assert_eq!(detached["detached"], true);
    assert_eq!(detached["attachment_id"], "desktop");

    let attach_end = rpc(
        &server.socket,
        "workspace.remote.pty_attach_end",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "session_id": session_id
        }),
    );
    assert_eq!(attach_end["workspace_id"], workspace_id);
    assert_eq!(attach_end["surface_id"], surface_id);
    assert_eq!(attach_end["session_id"], session_id);
    assert_eq!(attach_end["workspace_found"], true);
    assert_eq!(attach_end["cleared_remote_pty_session"], true);
    assert_eq!(attach_end["untracked_remote_terminal"], false);
    assert_eq!(attach_end["remote"]["active_terminal_sessions"], 1);

    let sessions = rpc(
        &server.socket,
        "ssh.session.list",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(sessions["sessions"], json!([]));

    let attach_end_again = rpc(
        &server.socket,
        "workspace.remote.pty_attach_end",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "session_id": session_id
        }),
    );
    assert_eq!(attach_end_again["workspace_found"], true);
    assert_eq!(attach_end_again["cleared_remote_pty_session"], false);
    assert_eq!(attach_end_again["untracked_remote_terminal"], false);
    assert_eq!(attach_end_again["remote"]["active_terminal_sessions"], 1);

    let terminal_end = rpc(
        &server.socket,
        "workspace.remote.terminal_session_end",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "relay_port": relay_port
        }),
    );
    assert_eq!(terminal_end["workspace_id"], workspace_id);
    assert_eq!(terminal_end["surface_id"], surface_id);
    assert_eq!(terminal_end["relay_port"], relay_port);
    assert_eq!(terminal_end["remote"]["active_terminal_sessions"], 0);
    assert_eq!(terminal_end["remote"]["state"], "disconnected");

    let missing_workspace_pty = rpc(
        &server.socket,
        "workspace.remote.pty_attach_end",
        json!({
            "workspace_id": "00000000-0000-0000-0000-000000000000",
            "surface_id": "11111111-1111-1111-1111-111111111111",
            "session_id": "detached-1"
        }),
    );
    assert_eq!(missing_workspace_pty["workspace_found"], false);
    assert_eq!(missing_workspace_pty["cleared_remote_pty_session"], false);
    assert_eq!(missing_workspace_pty["untracked_remote_terminal"], false);

    let missing_auth_workspace = rpc_response(
        &server.socket,
        "workspace.remote.foreground_auth_ready",
        json!({}),
    );
    assert_eq!(missing_auth_workspace["ok"], false);
    assert_eq!(missing_auth_workspace["error"]["code"], "invalid_params");
    assert_eq!(
        missing_auth_workspace["error"]["message"],
        "Missing workspace_id"
    );

    let missing_session = rpc_response(
        &server.socket,
        "workspace.remote.pty_attach_end",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id
        }),
    );
    assert_eq!(missing_session["ok"], false);
    assert_eq!(missing_session["error"]["code"], "invalid_params");
    assert_eq!(missing_session["error"]["message"], "Missing session_id");

    let invalid_relay = rpc_response(
        &server.socket,
        "workspace.remote.terminal_session_end",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "relay_port": 0
        }),
    );
    assert_eq!(invalid_relay["ok"], false);
    assert_eq!(invalid_relay["error"]["code"], "invalid_params");
    assert_eq!(
        invalid_relay["error"]["message"],
        "Missing or invalid relay_port"
    );

    let close_target = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote close",
            "destination": "close.example",
            "identity_file": "/tmp/cmux-fake-key"
        }),
    );
    let close_workspace_id = close_target["workspace_id"].as_str().unwrap();
    let close_session_id = close_target["ssh_pty_session_id"].as_str().unwrap();
    let closed = rpc(
        &server.socket,
        "workspace.remote.pty_close",
        json!({
            "workspace_id": close_workspace_id,
            "session_id": close_session_id
        }),
    );
    assert_eq!(closed["workspace_id"], close_workspace_id);
    assert_eq!(closed["session_id"], close_session_id);
    assert_eq!(closed["closed"], true);
    let closed_sessions = rpc(
        &server.socket,
        "workspace.remote.pty_sessions",
        json!({"workspace_id": close_workspace_id}),
    );
    assert_eq!(closed_sessions["sessions"], json!([]));

    let missing_terminal_workspace = rpc_response(
        &server.socket,
        "workspace.remote.terminal_session_end",
        json!({
            "workspace_id": "00000000-0000-0000-0000-000000000000",
            "surface_id": surface_id,
            "relay_port": relay_port
        }),
    );
    assert_eq!(missing_terminal_workspace["ok"], false);
    assert_eq!(missing_terminal_workspace["error"]["code"], "not_found");
    assert_eq!(
        missing_terminal_workspace["error"]["message"],
        "Workspace not found"
    );
}

#[test]
fn remote_tmux_socket_methods_match_macos_contract() {
    let server = start_server_with_beta_features(&[]);

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    let methods = capabilities["methods"].as_array().expect("methods");
    for method in [
        "remote.tmux.attach",
        "remote.tmux.detach",
        "remote.tmux.mirror",
        "remote.tmux.sessions",
        "remote.tmux.state",
        "remote.tmux.window",
    ] {
        assert!(
            methods.iter().any(|value| value == method),
            "missing method {method} from capabilities"
        );
    }
    assert_eq!(capabilities["features"]["remote_tmux"], true);

    let missing_host = rpc_response(&server.socket, "remote.tmux.sessions", json!({}));
    assert_eq!(missing_host["ok"], false);
    assert_eq!(missing_host["error"]["code"], "invalid_params");
    assert_eq!(missing_host["error"]["message"], "host is required");

    let invalid_host = rpc_response(
        &server.socket,
        "remote.tmux.sessions",
        json!({"host": "-oProxyCommand=x"}),
    );
    assert_eq!(invalid_host["ok"], false);
    assert_eq!(invalid_host["error"]["code"], "invalid_params");
    assert_eq!(invalid_host["error"]["message"], "host is required");

    let invalid_port = rpc_response(
        &server.socket,
        "remote.tmux.sessions",
        json!({"host": "dev.example", "port": 0}),
    );
    assert_eq!(invalid_port["ok"], false);
    assert_eq!(invalid_port["error"]["code"], "invalid_params");
    assert_eq!(invalid_port["error"]["message"], "host is required");

    let missing_session = rpc_response(
        &server.socket,
        "remote.tmux.attach",
        json!({"host": "dev.example"}),
    );
    assert_eq!(missing_session["ok"], false);
    assert_eq!(missing_session["error"]["code"], "invalid_params");
    assert_eq!(missing_session["error"]["message"], "session is required");

    let initial = rpc(
        &server.socket,
        "remote.tmux.sessions",
        json!({"host": "dev.example"}),
    );
    assert_eq!(initial["host"], "dev.example");
    assert_eq!(initial["sessions"], json!([]));

    let missing_attach = rpc_response(
        &server.socket,
        "remote.tmux.attach",
        json!({"host": "dev.example", "session": "work"}),
    );
    assert_eq!(missing_attach["ok"], false);
    assert_eq!(missing_attach["error"]["code"], "not_found");
    assert_eq!(missing_attach["error"]["message"], "tmux session not found");

    let attached = rpc(
        &server.socket,
        "remote.tmux.attach",
        json!({"host": "dev.example", "session": "work", "create": true}),
    );
    assert_eq!(attached["host"], "dev.example");
    assert_eq!(attached["session"], "work");
    assert_eq!(attached["attached"], true);

    let listed = rpc(
        &server.socket,
        "remote.tmux.sessions",
        json!({"host": "dev.example"}),
    );
    let sessions = listed["sessions"].as_array().expect("tmux sessions");
    assert_eq!(sessions.len(), 1);
    assert_eq!(sessions[0]["id"], "$0");
    assert_eq!(sessions[0]["name"], "work");
    assert_eq!(sessions[0]["windows"], 1);
    assert_eq!(sessions[0]["attached"], true);
    assert!(sessions[0]["created"].as_u64().is_some());

    let state = rpc(
        &server.socket,
        "remote.tmux.state",
        json!({"host": "dev.example", "session": "work"}),
    );
    assert_eq!(state["host"], "dev.example");
    assert_eq!(state["session"], "work");
    assert_eq!(state["session_id"], "$0");
    assert_eq!(state["attached"], true);
    assert_eq!(state["started"], true);
    assert_eq!(state["enter_received"], true);
    assert_eq!(state["exited"], false);
    assert_eq!(state["window_count"], 1);
    assert_eq!(state["window_ids"], json!([0]));
    assert_eq!(state["total_output_bytes"], 0);
    assert_eq!(state["pane_output_bytes"]["%0"], 0);
    assert!(state["recent_events"]
        .as_array()
        .unwrap()
        .iter()
        .any(|event| event == "attached"));

    let mirror = rpc(
        &server.socket,
        "remote.tmux.mirror",
        json!({"host": "dev.example"}),
    );
    assert_eq!(mirror["host"], "dev.example");
    assert_eq!(mirror["mirrored"], true);
    assert_eq!(mirror["workspace_count"], 1);
    let mirrored_workspace_id = mirror["workspaces"][0]["workspace_id"].as_str().unwrap();
    assert!(!mirrored_workspace_id.is_empty());
    assert_eq!(mirror["workspaces"][0]["session"], "work");

    let mirrored_state = rpc(
        &server.socket,
        "remote.tmux.state",
        json!({"host": "dev.example", "session": "work"}),
    );
    assert_eq!(mirrored_state["attached"], true);
    assert_eq!(mirrored_state["workspace_id"], mirrored_workspace_id);
    assert!(mirrored_state["recent_events"]
        .as_array()
        .unwrap()
        .iter()
        .any(|event| event == "mirrored"));

    let detached = rpc(
        &server.socket,
        "remote.tmux.detach",
        json!({"host": "dev.example", "session": "work"}),
    );
    assert_eq!(detached["host"], "dev.example");
    assert_eq!(detached["session"], "work");
    assert_eq!(detached["detached"], true);

    let detached_state = rpc(
        &server.socket,
        "remote.tmux.state",
        json!({"host": "dev.example", "session": "work"}),
    );
    assert_eq!(detached_state["attached"], false);
    let listed_after_detach = rpc(
        &server.socket,
        "remote.tmux.sessions",
        json!({"host": "dev.example"}),
    );
    assert_eq!(listed_after_detach["sessions"][0]["attached"], false);

    let missing_detach_args = rpc_response(&server.socket, "remote.tmux.detach", json!({}));
    assert_eq!(missing_detach_args["ok"], false);
    assert_eq!(missing_detach_args["error"]["code"], "invalid_params");
    assert_eq!(
        missing_detach_args["error"]["message"],
        "host and session are required"
    );

    let current_window = rpc(&server.socket, "window.current", json!({}))["window_id"]
        .as_str()
        .unwrap()
        .to_string();
    let dedicated = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "uuids",
            "ssh-tmux",
            "empty.example",
            "--port",
            "2222",
            "--identity",
            "/tmp/cmux-empty-key",
            "--no-focus",
        ],
        &[],
    );
    assert_eq!(dedicated["host"], "empty.example");
    assert_eq!(dedicated["mirrored"], true);
    assert_eq!(dedicated["workspace_count"], 1);
    assert_eq!(dedicated["workspaces"][0]["session"], "default");
    let dedicated_window_id = dedicated["window_id"].as_str().unwrap();
    assert!(!dedicated_window_id.is_empty());
    let after_window = rpc(&server.socket, "window.current", json!({}));
    assert_eq!(after_window["window_id"], current_window);
    let windows = rpc(&server.socket, "window.list", json!({}));
    assert!(windows["windows"]
        .as_array()
        .unwrap()
        .iter()
        .any(|window| window["id"] == dedicated_window_id));

    let dedicated_state = rpc(
        &server.socket,
        "remote.tmux.state",
        json!({
            "host": "empty.example",
            "port": 2222,
            "identity_file": "/tmp/cmux-empty-key",
            "session": "default"
        }),
    );
    assert_eq!(dedicated_state["attached"], true);
    assert_eq!(dedicated_state["window_id"], dedicated_window_id);

    let text_output = cli(&server.socket, &["ssh-tmux", "text.example", "--no-focus"]);
    assert!(
        text_output.starts_with("OK host=text.example window=window:"),
        "unexpected ssh-tmux text output: {text_output}"
    );
    let text_state = rpc(
        &server.socket,
        "remote.tmux.state",
        json!({"host": "text.example", "session": "default"}),
    );
    assert_eq!(text_state["attached"], true);
}

#[test]
fn remote_tmux_live_discovery_uses_ssh_and_classifies_auth() {
    let fake = fake_ssh();
    let server = start_server_with_beta_features(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let sessions = rpc(
        &server.socket,
        "remote.tmux.sessions",
        json!({"host": "live.example", "live": true}),
    );
    assert_eq!(sessions["host"], "live.example");
    assert_eq!(sessions["live"], true);
    let rows = sessions["sessions"].as_array().expect("live sessions");
    assert_eq!(rows.len(), 2);
    assert_eq!(rows[0]["id"], "$0");
    assert_eq!(rows[0]["name"], "work");
    assert_eq!(rows[0]["windows"], 2);
    assert_eq!(rows[0]["attached"], false);
    assert_eq!(rows[1]["name"], "ops");
    assert_eq!(rows[1]["attached"], true);

    let dedicated = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "uuids",
            "ssh-tmux",
            "live-cli.example",
            "--live",
            "--no-focus",
        ],
        &[],
    );
    assert_eq!(dedicated["host"], "live-cli.example");
    assert_eq!(dedicated["live"], true);
    assert_eq!(dedicated["mirrored"], true);
    assert_eq!(dedicated["workspace_count"], 2);
    assert_eq!(dedicated["workspaces"][0]["session"], "ops");
    assert_eq!(dedicated["workspaces"][1]["session"], "work");

    let empty = rpc(
        &server.socket,
        "remote.tmux.window",
        json!({"host": "empty-live.example", "live": true, "activate": false}),
    );
    assert_eq!(empty["host"], "empty-live.example");
    assert_eq!(empty["live"], true);
    assert_eq!(empty["mirrored"], true);
    assert_eq!(empty["workspace_count"], 1);
    assert_eq!(empty["workspaces"][0]["session"], "default");

    let auth = rpc(
        &server.socket,
        "remote.tmux.window",
        json!({"host": "auth-required.example", "live": true}),
    );
    assert_eq!(auth["host"], "auth-required.example");
    assert_eq!(auth["auth_required"], true);
    let argv = auth["ssh_argv"].as_array().expect("ssh argv");
    assert_eq!(argv[0], "/usr/bin/ssh");
    assert!(argv.iter().any(|arg| arg == "BatchMode=no"));
    assert!(argv.iter().any(|arg| arg == "auth-required.example"));
    assert!(
        argv.iter()
            .filter_map(Value::as_str)
            .any(|arg| arg.starts_with("ControlPath=") && arg.contains("cmux-tmux-")),
        "ssh argv did not include cmux tmux ControlPath: {argv:?}"
    );
    assert!(
        !argv
            .iter()
            .filter_map(Value::as_str)
            .any(|arg| arg.starts_with("ControlPath=/tmp/cmux-tmux-")),
        "ssh argv used legacy /tmp tmux ControlPath: {argv:?}"
    );

    let ssh_log = std::fs::read_to_string(&fake.log_path).expect("fake ssh log");
    assert!(
        ssh_log.contains("BatchMode=yes") && ssh_log.contains("tmux list-sessions"),
        "live discovery did not use batch-mode tmux probing:\n{ssh_log}"
    );
    assert!(
        ssh_log.contains("tmux new-session -d"),
        "empty live host did not create default session:\n{ssh_log}"
    );
}

#[test]
fn remote_tmux_live_control_stream_seeds_output_and_routes_input() {
    let fake = fake_ssh();
    let server = start_server_with_beta_features(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let mirrored = rpc(
        &server.socket,
        "remote.tmux.window",
        json!({
            "host": "live-control.example",
            "live": true,
            "activate": false
        }),
    );
    let workspace = mirrored["workspaces"]
        .as_array()
        .expect("mirrored workspaces")
        .iter()
        .find(|workspace| workspace["session"] == "ops")
        .expect("ops workspace");
    let surface_id = workspace["surface_id"]
        .as_str()
        .expect("remote tmux surface")
        .to_string();
    let work_workspace_id = mirrored["workspaces"]
        .as_array()
        .expect("mirrored workspaces")
        .iter()
        .find(|workspace| workspace["session"] == "work")
        .and_then(|workspace| workspace["workspace_id"].as_str())
        .expect("work workspace")
        .to_string();

    let deadline = Instant::now() + Duration::from_secs(5);
    let connected = loop {
        let state = rpc(
            &server.socket,
            "remote.tmux.state",
            json!({"host": "live-control.example", "session": "ops"}),
        );
        if state["enter_received"] == true
            && state["windows"]
                .as_array()
                .is_some_and(|windows| !windows.is_empty())
        {
            break state;
        }
        assert!(
            Instant::now() < deadline,
            "remote tmux control stream did not connect: {state}"
        );
        thread::sleep(Duration::from_millis(20));
    };
    assert_eq!(connected["windows"][0]["id"], "@0");
    assert_eq!(connected["windows"][0]["name"], "main");
    assert_eq!(connected["windows"][0]["active_pane_id"], "%2");
    assert_eq!(connected["windows"][0]["pane_ids"], json!(["%0", "%2"]));
    assert_eq!(connected["projected_window_id"], "@0");
    let second_surface_id = connected["windows"][0]["pane_surfaces"]["%2"]
        .as_str()
        .expect("second remote tmux pane surface")
        .to_string();
    let ops_workspace_id = workspace["workspace_id"]
        .as_str()
        .expect("ops workspace")
        .to_string();
    let ops_panes = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": &ops_workspace_id}),
    );
    assert_eq!(
        ops_panes["panes"].as_array().expect("ops panes").len(),
        2,
        "tmux split layout was not projected into cmux panes: {ops_panes}"
    );

    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let state = rpc(
            &server.socket,
            "remote.tmux.state",
            json!({"host": "live-control.example", "session": "work"}),
        );
        if state["windows"]
            .as_array()
            .is_some_and(|windows| windows.len() == 2)
        {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "multi-window remote tmux topology did not arrive: {state}"
        );
        thread::sleep(Duration::from_millis(20));
    }
    let work_surfaces = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": work_workspace_id}),
    );
    let work_titles = work_surfaces["surfaces"]
        .as_array()
        .expect("work surfaces")
        .iter()
        .filter_map(|surface| surface["title"].as_str())
        .collect::<HashSet<_>>();
    assert!(work_titles.contains("main"));
    assert!(work_titles.contains("logs"));
    assert!(work_titles.contains("main [%3]"));
    let main_surface_id = work_surfaces["surfaces"]
        .as_array()
        .expect("work surfaces")
        .iter()
        .find(|surface| surface["title"] == "main")
        .and_then(|surface| surface["surface_id"].as_str())
        .expect("main surface")
        .to_string();
    let logs_surface_id = work_surfaces["surfaces"]
        .as_array()
        .expect("work surfaces")
        .iter()
        .find(|surface| surface["title"] == "logs")
        .and_then(|surface| surface["surface_id"].as_str())
        .expect("logs surface")
        .to_string();
    let work_panes = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": &work_workspace_id}),
    );
    assert_eq!(work_panes["panes"].as_array().expect("work panes").len(), 2);
    rpc(
        &server.socket,
        "surface.focus",
        json!({"surface_id": &logs_surface_id}),
    );
    let work_panes_logs = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": &work_workspace_id}),
    );
    assert_eq!(
        work_panes_logs["panes"]
            .as_array()
            .expect("work panes after logs switch")
            .len(),
        1
    );
    rpc(
        &server.socket,
        "surface.focus",
        json!({"surface_id": &main_surface_id}),
    );
    let work_panes_main = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": &work_workspace_id}),
    );
    assert_eq!(
        work_panes_main["panes"]
            .as_array()
            .expect("work panes after main switch")
            .len(),
        2
    );

    let split = rpc(
        &server.socket,
        "surface.split",
        json!({
            "workspace_id": workspace["workspace_id"],
            "surface_id": &surface_id,
            "type": "terminal",
            "direction": "right"
        }),
    );
    assert_eq!(split["routed_to_remote_tmux"], true);

    let new_window = rpc(
        &server.socket,
        "surface.create",
        json!({
            "workspace_id": workspace["workspace_id"],
            "type": "terminal"
        }),
    );
    assert_eq!(new_window["routed_to_remote_tmux"], true);

    let renamed = rpc(
        &server.socket,
        "surface.action",
        json!({
            "surface_id": &surface_id,
            "action": "rename",
            "title": "renamed main"
        }),
    );
    assert_eq!(renamed["title"], "renamed main");

    rpc(
        &server.socket,
        "surface.close",
        json!({"surface_id": &logs_surface_id}),
    );
    let work_surfaces_after_close = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": &work_workspace_id}),
    );
    assert!(!work_surfaces_after_close["surfaces"]
        .as_array()
        .expect("work surfaces after close")
        .iter()
        .any(|surface| surface["surface_id"] == logs_surface_id));

    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let screen = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": &surface_id, "raw": true}),
        );
        if screen["text"]
            .as_str()
            .is_some_and(|text| text.contains("seed-pane-0"))
        {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "remote tmux capture did not seed the surface: {screen}"
        );
        thread::sleep(Duration::from_millis(20));
    }

    rpc(
        &server.socket,
        "surface.send_text",
        json!({"surface_id": &surface_id, "text": "x"}),
    );
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let screen = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": &surface_id, "raw": true}),
        );
        if screen["text"]
            .as_str()
            .is_some_and(|text| text.contains("remote-live-output"))
        {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "remote tmux output did not reach the surface: {screen}"
        );
        thread::sleep(Duration::from_millis(20));
    }

    let second_seed = rpc(
        &server.socket,
        "surface.read_text",
        json!({"surface_id": &second_surface_id, "raw": true}),
    );
    assert!(
        second_seed["text"]
            .as_str()
            .is_some_and(|text| text.contains("seed-pane-2")),
        "second remote pane was not captured: {second_seed}"
    );
    rpc(
        &server.socket,
        "surface.focus",
        json!({"surface_id": &surface_id}),
    );
    rpc(
        &server.socket,
        "surface.focus",
        json!({"surface_id": &second_surface_id}),
    );
    rpc(
        &server.socket,
        "surface.send_text",
        json!({"surface_id": &second_surface_id, "text": "y"}),
    );
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let screen = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": &second_surface_id, "raw": true}),
        );
        if screen["text"]
            .as_str()
            .is_some_and(|text| text.contains("remote-live-output"))
        {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "second remote tmux pane output did not reach its surface: {screen}"
        );
        thread::sleep(Duration::from_millis(20));
    }
    rpc(
        &server.socket,
        "surface.close",
        json!({"surface_id": &second_surface_id}),
    );
    let ops_panes_after_close = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": &ops_workspace_id}),
    );
    assert_eq!(
        ops_panes_after_close["panes"]
            .as_array()
            .expect("ops panes after close")
            .len(),
        1
    );

    let ssh_log = std::fs::read_to_string(&fake.log_path).expect("fake ssh log");
    assert!(ssh_log.contains("control: list-windows -t"));
    assert!(ssh_log.contains("control: capture-pane -e -p -S -5000 -t %0"));
    assert!(ssh_log.contains("control: capture-pane -e -p -S -5000 -t %2"));
    assert!(ssh_log.contains("control: send-keys -t %0 -H 78"));
    assert!(ssh_log.contains("control: select-pane -t %2"));
    assert!(ssh_log.contains("control: send-keys -t %2 -H 79"));
    assert!(ssh_log.contains("control: kill-pane -t %2"));
    assert!(ssh_log.contains("control: select-window -t @1"));
    assert!(ssh_log.contains("control: select-window -t @0"));
    assert!(ssh_log.contains("control: split-window -h -t @0.%0"));
    assert!(ssh_log.contains("control: new-window -t ops"));
    assert!(ssh_log.contains("control: rename-window -t @0 'renamed main'"));
    assert!(ssh_log.contains("control: kill-window -t @1"));
}

#[test]
fn remote_tmux_live_control_stream_reconnects_after_transport_exit() {
    let fake = fake_ssh();
    let server = start_server_with_beta_features(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let attached = rpc(
        &server.socket,
        "remote.tmux.attach",
        json!({
            "host": "reconnect-control.example",
            "session": "ops",
            "live": true
        }),
    );
    assert_eq!(attached["attached"], true);

    let deadline = Instant::now() + Duration::from_secs(8);
    let state = loop {
        let state = rpc(
            &server.socket,
            "remote.tmux.state",
            json!({
                "host": "reconnect-control.example",
                "session": "ops"
            }),
        );
        let reconnected = state["enter_received"] == true
            && state["reconnecting"] == false
            && state["exited"] == false
            && state["recent_events"]
                .as_array()
                .is_some_and(|events| events.iter().any(|event| event == "reconnect-attempt"));
        if reconnected {
            break state;
        }
        assert!(
            Instant::now() < deadline,
            "remote tmux control stream did not reconnect: {state}"
        );
        thread::sleep(Duration::from_millis(20));
    };
    assert_eq!(state["reconnect_attempt_count"], 0);

    let ssh_log = std::fs::read_to_string(&fake.log_path).expect("fake ssh log");
    let control_attaches = ssh_log
        .lines()
        .filter(|line| {
            line.contains("reconnect-control.example") && line.contains("tmux -CC attach-session")
        })
        .count();
    assert!(
        control_attaches >= 2,
        "remote tmux control process was not relaunched:\n{ssh_log}"
    );
}

#[test]
fn remote_detected_ports_are_not_auto_mirrored_with_ssh_l_forwards() {
    let fake = fake_ssh();
    let server = start_server_with_env(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let created = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote no mirror",
            "destination": "fake.example",
            "identity_file": "/tmp/cmux-fake-key"
        }),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    let surface_id = created["surface_id"].as_str().unwrap();
    assert_eq!(created["remote"]["state"], "connected");
    assert_eq!(created["remote"]["forwarded_ports"], json!([]));

    rpc(
        &server.socket,
        "surface.send_text",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "text": "python3 -m http.server 8123\n"
        }),
    );
    let status = rpc(
        &server.socket,
        "workspace.remote.status",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(status["remote"]["detected_ports"], json!([8123]));
    assert_eq!(status["remote"]["forwarded_ports"], json!([]));

    let workspaces = rpc(&server.socket, "workspace.list", json!({}));
    let workspace = workspaces["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|workspace| workspace["workspace_id"] == workspace_id)
        .expect("workspace row");
    assert_eq!(workspace["listening_ports"], json!([8123]));

    let ssh_log = std::fs::read_to_string(&fake.log_path).expect("fake ssh log");
    assert!(
        !ssh_log.split_whitespace().any(|arg| arg == "-L"),
        "unexpected ssh -L in fake ssh log:\n{ssh_log}"
    );
}

#[test]
fn remote_proxy_broker_reuses_transport_for_matching_ssh_options() {
    let fake = fake_ssh();
    let server = start_server_with_env(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let first = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote proxy one",
            "destination": "same.example",
            "identity_file": "/tmp/cmux-fake-key",
            "ssh_options": ["UserKnownHostsFile=/tmp/cmux-known-hosts"]
        }),
    );
    let second = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote proxy two",
            "destination": "same.example",
            "identity_file": "/tmp/cmux-fake-key",
            "ssh_options": ["UserKnownHostsFile=/tmp/cmux-known-hosts"]
        }),
    );

    assert_eq!(first["remote"]["state"], "connected");
    assert_eq!(second["remote"]["state"], "connected");
    assert_eq!(first["remote"]["proxy"]["state"], "ready");
    assert_eq!(second["remote"]["proxy"]["state"], "ready");
    assert_eq!(
        first["remote"]["local_proxy_port"],
        second["remote"]["local_proxy_port"]
    );
    assert_eq!(
        first["remote"]["proxy"]["port"],
        second["remote"]["proxy"]["port"]
    );
    let capabilities = first["remote"]["daemon"]["capabilities"]
        .as_array()
        .expect("daemon capabilities");
    assert!(capabilities.iter().any(|value| value == "proxy.socks5"));
    assert!(capabilities
        .iter()
        .any(|value| value == "proxy.http_connect"));
}

#[test]
fn ssh_agent_forwarding_flags_round_trip_through_cli_and_socket() {
    let server = start_server();

    let enabled = cli_json_with_env(
        &server.socket,
        &["--json", "ssh", "--forward-agent", "agent.example"],
        &[],
    );
    assert_eq!(enabled["remote"]["destination"], "agent.example");
    assert_eq!(enabled["remote"]["forward_agent"], true);
    assert!(enabled["ssh_command"]
        .as_str()
        .unwrap_or_default()
        .split_whitespace()
        .any(|arg| arg == "-A"));
    let enabled_ssh_command = enabled["ssh_command"].as_str().unwrap_or_default();
    assert!(
        enabled_ssh_command.contains("ControlPath="),
        "ssh command did not include ControlPath: {enabled_ssh_command}"
    );
    assert!(
        !enabled_ssh_command.contains("ControlPath=/tmp/cmux-ssh-"),
        "ssh command used legacy /tmp ControlPath: {enabled_ssh_command}"
    );

    let disabled = cli_json_with_env(
        &server.socket,
        &["--json", "ssh", "-a", "no-agent.example"],
        &[],
    );
    assert_eq!(disabled["remote"]["destination"], "no-agent.example");
    assert_eq!(disabled["remote"]["forward_agent"], false);
    assert!(disabled["ssh_command"]
        .as_str()
        .unwrap_or_default()
        .split_whitespace()
        .any(|arg| arg == "-a"));

    let inherited = cli_json_with_env(
        &server.socket,
        &["--json", "ssh", "inherit-agent.example"],
        &[],
    );
    assert_eq!(inherited["remote"]["destination"], "inherit-agent.example");
    assert_eq!(inherited["remote"]["forward_agent"], Value::Null);

    let ident = rpc(&server.socket, "system.identify", json!({}));
    let configured = rpc(
        &server.socket,
        "workspace.remote.configure",
        json!({
            "workspace_id": ident["focused"]["workspace_id"],
            "destination": "configured-no-agent.example",
            "forward_agent": "false",
            "auto_connect": false
        }),
    );
    assert_eq!(configured["remote"]["forward_agent"], false);

    let invalid = rpc_response(
        &server.socket,
        "workspace.remote.configure",
        json!({
            "workspace_id": ident["focused"]["workspace_id"],
            "destination": "invalid-agent.example",
            "forward_agent": "maybe",
            "auto_connect": false
        }),
    );
    assert_eq!(invalid["ok"], false);
    assert_eq!(invalid["error"]["code"], "invalid_params");
    assert!(invalid["error"]["message"]
        .as_str()
        .unwrap_or_default()
        .contains("forward_agent must be true or false"));
}

#[test]
fn remote_proxy_transport_key_separates_agent_forwarding_modes() {
    let fake = fake_ssh();
    let server = start_server_with_env(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let first = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote proxy forward agent",
            "destination": "agent-mode.example",
            "identity_file": "/tmp/cmux-fake-key",
            "ssh_options": ["UserKnownHostsFile=/tmp/cmux-known-hosts"],
            "forward_agent": true
        }),
    );
    let second = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote proxy no agent",
            "destination": "agent-mode.example",
            "identity_file": "/tmp/cmux-fake-key",
            "ssh_options": ["UserKnownHostsFile=/tmp/cmux-known-hosts"],
            "forward_agent": false
        }),
    );

    assert_eq!(first["remote"]["state"], "connected");
    assert_eq!(second["remote"]["state"], "connected");
    assert_eq!(first["remote"]["forward_agent"], true);
    assert_eq!(second["remote"]["forward_agent"], false);
    assert_ne!(
        first["remote"]["local_proxy_port"], second["remote"]["local_proxy_port"],
        "opposite agent-forwarding modes must not reuse an SSH proxy transport"
    );

    let ssh_log = std::fs::read_to_string(&fake.log_path).expect("fake ssh log");
    assert!(
        ssh_log.split_whitespace().any(|arg| arg == "-A"),
        "fake ssh log did not include -A:\n{ssh_log}"
    );
    assert!(
        ssh_log.split_whitespace().any(|arg| arg == "-a"),
        "fake ssh log did not include -a:\n{ssh_log}"
    );
}

#[test]
fn remote_workspace_browser_surfaces_are_auto_wired_to_proxy() {
    let fake = fake_ssh();
    let server = start_server_with_env(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let local_ident = rpc(&server.socket, "system.identify", json!({}));
    let local_browser = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "workspace_id": local_ident["focused"]["workspace_id"],
            "surface_id": local_ident["focused"]["surface_id"],
            "url": "about:blank"
        }),
    );
    let local_snapshot = rpc(
        &server.socket,
        "browser.snapshot",
        json!({"surface_id": local_browser["surface_id"]}),
    );
    assert_eq!(local_snapshot["proxy"]["enabled"], false);
    assert_eq!(local_snapshot["proxy"]["state"], "unavailable");

    let remote = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote browser proxy",
            "destination": "browser.example",
            "identity_file": "/tmp/cmux-fake-key"
        }),
    );
    let proxy_port = remote["remote"]["local_proxy_port"]
        .as_u64()
        .expect("proxy port");
    let remote_browser = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "workspace_id": remote["workspace_id"],
            "surface_id": remote["surface_id"],
            "url": "about:blank"
        }),
    );
    let remote_snapshot = rpc(
        &server.socket,
        "browser.snapshot",
        json!({"surface_id": remote_browser["surface_id"]}),
    );
    assert_eq!(remote_snapshot["proxy"]["enabled"], true);
    assert_eq!(remote_snapshot["proxy"]["state"], "ready");
    assert_eq!(remote_snapshot["proxy"]["host"], "127.0.0.1");
    assert_eq!(remote_snapshot["proxy"]["port"], proxy_port);
    assert_eq!(
        remote_snapshot["proxy"]["socks5"],
        format!("socks5://127.0.0.1:{proxy_port}")
    );
    assert_eq!(
        remote_snapshot["proxy"]["http_connect"],
        format!("http://127.0.0.1:{proxy_port}")
    );

    rpc(
        &server.socket,
        "workspace.remote.disconnect",
        json!({"workspace_id": remote["workspace_id"]}),
    );
    let disconnected_snapshot = rpc(
        &server.socket,
        "browser.snapshot",
        json!({"surface_id": remote_browser["surface_id"]}),
    );
    assert_eq!(disconnected_snapshot["proxy"]["enabled"], false);
    assert_eq!(disconnected_snapshot["proxy"]["state"], "unavailable");
}

#[test]
fn remote_browser_proxy_observability_reports_http_metadata_per_browser_surface() {
    let fake = fake_ssh();
    let (probe_port, probe_done) = start_proxy_probe_server(1);
    let server = start_server_with_env(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let remote = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote proxy inspection",
            "destination": "proxy-inspection.example",
            "identity_file": "/tmp/cmux-fake-key"
        }),
    );
    let proxy_port = remote["remote"]["local_proxy_port"]
        .as_u64()
        .expect("proxy port");
    let browser = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "workspace_id": remote["workspace_id"],
            "surface_id": remote["surface_id"],
            "url": "about:blank"
        }),
    );
    let surface_id = browser["surface_id"].as_str().unwrap();

    let body = "cmux-proxy-body=hello";
    let response = http_post_via_socks(
        proxy_port,
        "127.0.0.1",
        probe_port,
        "/inspect?case=proxy",
        body,
    );
    assert!(
        response.contains("HTTP/1.1 200 OK") && response.contains("request_body=cmux-proxy-body"),
        "probe response was {response:?}"
    );

    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let requests = rpc(
            &server.socket,
            "browser.network.requests",
            json!({"surface_id": surface_id}),
        );
        let rows = requests["requests"].as_array().expect("requests array");
        if let Some(row) = rows.iter().find(|row| {
            row["source"] == "proxy"
                && row["url"].as_str().is_some_and(|url| {
                    url.contains(&format!("127.0.0.1:{probe_port}/inspect?case=proxy"))
                })
        }) {
            assert_eq!(row["method"], "POST");
            assert_eq!(row["status"], 200);
            assert_eq!(row["proxy_port"], proxy_port);
            assert_eq!(row["protocol"], "socks5");
            assert_eq!(row["target"]["host"], "127.0.0.1");
            assert_eq!(row["target"]["port"], probe_port as u64);
            assert_eq!(
                row["request_headers"]["Host"],
                format!("127.0.0.1:{probe_port}")
            );
            assert_eq!(row["request_headers"]["X-Cmux-Trace"], "proxy-observed");
            assert_eq!(row["response_headers"]["X-Cmux-Probe"], "observed");
            assert!(
                row["request_body_preview"]
                    .as_str()
                    .is_some_and(|preview| preview.contains(body)),
                "request body preview missing body: {row}"
            );
            assert!(
                row["response_body_preview"]
                    .as_str()
                    .is_some_and(|preview| preview.contains("path=/inspect?case=proxy")),
                "response body preview missing path: {row}"
            );
            assert!(
                row["duration_ms"].as_u64().is_some(),
                "duration missing from proxy row: {row}"
            );
            assert!(
                row["bytes_sent"].as_u64().unwrap_or(0) > body.len() as u64
                    && row["bytes_received"].as_u64().unwrap_or(0) > 0,
                "byte counters missing from proxy row: {row}"
            );

            let cleared = rpc(
                &server.socket,
                "browser.network.requests",
                json!({"surface_id": surface_id, "clear": true}),
            );
            assert!(
                cleared["requests"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|row| row["source"] == "proxy"),
                "clear call should return rows before clearing: {cleared}"
            );
            let after_clear = rpc(
                &server.socket,
                "browser.network.requests",
                json!({"surface_id": surface_id}),
            );
            assert!(
                after_clear["requests"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .all(|row| row["source"] != "proxy"),
                "proxy rows should be cleared for this surface proxy: {after_clear}"
            );
            probe_done
                .recv_timeout(Duration::from_secs(5))
                .expect("proxy probe server saw inspection request");
            return;
        }
        thread::sleep(Duration::from_millis(100));
    }
    panic!("proxy inspection row did not appear in browser.network.requests");
}

#[test]
fn remote_browser_proxy_e2e_covers_http_websocket_and_reconnect_continuity() {
    let fake = fake_ssh();
    let (probe_port, probe_done) = start_proxy_probe_server(3);
    let server = start_server_with_env(&[
        ("PATH", fake.path.as_str()),
        ("CMUX_FAKE_SSH_LOG", fake.log_path.as_str()),
        ("CMUX_FAKE_REMOTE_HOME", fake.remote_home.as_str()),
    ]);

    let remote = rpc(
        &server.socket,
        "workspace.remote.create",
        json!({
            "title": "remote proxy e2e",
            "destination": "proxy-e2e.example",
            "identity_file": "/tmp/cmux-fake-key"
        }),
    );
    let workspace_id = remote["workspace_id"].as_str().unwrap();
    let proxy_port = remote["remote"]["local_proxy_port"]
        .as_u64()
        .expect("proxy port");
    assert_eq!(remote["remote"]["state"], "connected");
    assert_eq!(remote["remote"]["proxy"]["state"], "ready");
    assert_eq!(remote["remote"]["proxy"]["port"], proxy_port);

    let first_response = http_get_via_socks(proxy_port, "127.0.0.1", probe_port, "/egress");
    assert!(
        first_response.contains("HTTP/1.1 200 OK"),
        "first response was {first_response:?}"
    );
    assert!(
        first_response.contains("egress_ip=127.0.0.1"),
        "first response was {first_response:?}"
    );
    assert!(
        first_response.contains("path=/egress"),
        "first response was {first_response:?}"
    );

    let websocket_echo =
        websocket_echo_via_connect(proxy_port, "127.0.0.1", probe_port, "cmux-ws-before");
    assert_eq!(websocket_echo, "cmux-ws-before");

    rpc(
        &server.socket,
        "workspace.remote.reconnect",
        json!({"workspace_id": workspace_id}),
    );
    let status = rpc(
        &server.socket,
        "workspace.remote.status",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(status["remote"]["state"], "connected");
    assert_eq!(status["remote"]["proxy"]["state"], "ready");
    assert_eq!(status["remote"]["local_proxy_port"], proxy_port);

    let after_reconnect =
        http_get_via_socks(proxy_port, "127.0.0.1", probe_port, "/after-reconnect");
    assert!(
        after_reconnect.contains("HTTP/1.1 200 OK"),
        "after reconnect response was {after_reconnect:?}"
    );
    assert!(
        after_reconnect.contains("path=/after-reconnect"),
        "after reconnect response was {after_reconnect:?}"
    );

    probe_done
        .recv_timeout(Duration::from_secs(5))
        .expect("proxy probe server saw all expected connections");
    let ssh_log = std::fs::read_to_string(&fake.log_path).expect("fake ssh log");
    assert!(
        ssh_log.contains("-W") && ssh_log.contains(&format!("127.0.0.1:{probe_port}")),
        "proxy traffic did not use ssh -W to reach probe server:\n{ssh_log}"
    );
}

#[test]
fn split_resizes_existing_and_new_terminal_ptys_evenly() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "split size"}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    rpc(
        &server.socket,
        "workspace.select",
        json!({"workspace_id": workspace_id}),
    );
    rpc(
        &server.socket,
        "surface.split",
        json!({"workspace_id": workspace_id, "direction": "right"}),
    );

    let panes = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    let pane_columns = panes["panes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|pane| pane["columns"].as_u64().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(pane_columns, vec![40, 40]);

    let terminals = rpc(&server.socket, "debug.terminals", json!({}));
    let mut terminal_columns = terminals["terminals"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|terminal| terminal["workspace_id"] == workspace_id)
        .map(|terminal| terminal["terminal_size"]["cols"].as_u64().unwrap())
        .collect::<Vec<_>>();
    terminal_columns.sort_unstable();
    assert_eq!(terminal_columns, vec![40, 40]);
}

#[test]
fn surface_send_key_ctrl_d_plus_alias_closes_split_pane() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "ctrl d alias", "focus": true}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    let split = rpc(
        &server.socket,
        "surface.split",
        json!({"workspace_id": workspace_id, "direction": "right"}),
    );
    let right_surface = split["surface_id"].as_str().unwrap();

    let before = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(before["panes"].as_array().unwrap().len(), 2);

    rpc(
        &server.socket,
        "surface.send_key",
        json!({"workspace_id": workspace_id, "surface_id": right_surface, "key": "ctrl+d"}),
    );

    let after = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(after["panes"].as_array().unwrap().len(), 1);
}

#[test]
fn surface_send_key_accepts_linux_super_aliases_for_pty_fallback() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "super key aliases", "focus": true}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    let current_surface = rpc(&server.socket, "surface.current", json!({}));
    assert_eq!(current_surface["workspace_id"], workspace_id);
    let surface_id = current_surface["surface_id"].as_str().unwrap();

    for key in [
        "cmd-enter",
        "command-enter",
        "super-shift-p",
        "win-left",
        "windows-alt-right",
    ] {
        rpc(
            &server.socket,
            "surface.send_key",
            json!({"workspace_id": workspace_id, "surface_id": surface_id, "key": key}),
        );
    }

    let rejected = rpc_response(
        &server.socket,
        "surface.send_key",
        json!({"workspace_id": workspace_id, "surface_id": surface_id, "key": "cmd"}),
    );
    assert_eq!(rejected["ok"], false, "response was {rejected}");
    assert!(
        rejected["error"]["message"]
            .as_str()
            .unwrap_or_default()
            .contains("unsupported key: cmd"),
        "response was {rejected}"
    );
}

#[test]
fn workspace_equalize_splits_resets_pane_frames_and_terminal_sizes() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "equalize size", "focus": true}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap().to_string();
    rpc(
        &server.socket,
        "surface.split",
        json!({"workspace_id": workspace_id, "direction": "right"}),
    );

    let panes_before = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    let pane_ids = panes_before["panes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|pane| pane["pane_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(pane_ids.len(), 2);

    rpc(
        &server.socket,
        "pane.resize",
        json!({"pane_id": &pane_ids[0], "direction": "right", "amount": 80}),
    );
    let resized = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    let resized_columns = resized["panes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|pane| pane["columns"].as_u64().unwrap())
        .collect::<Vec<_>>();
    assert_ne!(resized_columns, vec![40, 40]);

    let equalized = rpc(
        &server.socket,
        "workspace.equalize_splits",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(equalized["workspace_id"], workspace_id);
    assert_eq!(equalized["equalized"], true);
    assert_eq!(equalized["orientation"], Value::Null);
    assert_eq!(equalized["panes"].as_array().unwrap().len(), 2);
    for pane in equalized["panes"].as_array().unwrap() {
        assert_eq!(pane["frame"]["width"], 400.0);
        assert_eq!(pane["terminal_size"]["cols"], 40);
        assert_eq!(pane["terminal_size"]["rows"], 30);
    }

    let panes_after = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    let columns_after = panes_after["panes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|pane| pane["columns"].as_u64().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(columns_after, vec![40, 40]);

    let terminals = rpc(&server.socket, "debug.terminals", json!({}));
    let mut terminal_columns = terminals["terminals"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|terminal| terminal["workspace_id"] == workspace_id)
        .map(|terminal| terminal["terminal_size"]["cols"].as_u64().unwrap())
        .collect::<Vec<_>>();
    terminal_columns.sort_unstable();
    assert_eq!(terminal_columns, vec![40, 40]);

    rpc(
        &server.socket,
        "pane.resize",
        json!({"pane_id": &pane_ids[1], "direction": "right", "amount": 80}),
    );
    let cli_equalized: Value = serde_json::from_str(&cli(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "equalize-splits",
            "--workspace",
            &workspace_id,
        ],
    ))
    .expect("cmux equalize-splits json");
    assert_eq!(cli_equalized["workspace_id"], workspace_id);
    assert_eq!(cli_equalized["equalized"], true);

    let single = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "single equalize", "focus": false}),
    );
    let single_id = single["workspace_id"].as_str().unwrap();
    let single_equalized = rpc(
        &server.socket,
        "workspace.equalize_splits",
        json!({"workspace_id": single_id}),
    );
    assert_eq!(single_equalized["equalized"], false);

    let invalid = rpc_response(
        &server.socket,
        "workspace.equalize_splits",
        json!({"workspace_id": workspace_id, "orientation": "diagonal"}),
    );
    assert_eq!(invalid["ok"], false, "response was {invalid}");
    assert_eq!(invalid["error"]["code"], "invalid_params");

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "workspace.equalize_splits"));
    assert_eq!(capabilities["features"]["workspace_equalize_splits"], true);
}

#[test]
fn renderer_snapshot_includes_app_chrome_state() {
    let server = start_server();
    let ident = rpc(&server.socket, "system.identify", json!({}));
    let workspace_id = ident["focused"]["workspace_id"].as_str().unwrap();

    rpc(
        &server.socket,
        "sidebar.status.set",
        json!({
            "workspace_id": workspace_id,
            "key": "build",
            "value": "passing",
            "priority": 20,
            "icon": "ok"
        }),
    );
    rpc(
        &server.socket,
        "sidebar.progress.set",
        json!({"workspace_id": workspace_id, "value": 0.25, "label": "Indexing"}),
    );
    rpc(
        &server.socket,
        "sidebar.log.append",
        json!({
            "workspace_id": workspace_id,
            "level": "info",
            "source": "tests",
            "message": "snapshot chrome"
        }),
    );
    rpc(
        &server.socket,
        "app.focus_override.set",
        json!({"state": "inactive"}),
    );
    rpc(
        &server.socket,
        "notification.create",
        json!({
            "workspace_id": workspace_id,
            "title": "Build done",
            "body": "snapshot notification"
        }),
    );
    rpc(&server.socket, "debug.command_palette.toggle", json!({}));

    let snapshot = rpc(&server.socket, "renderer.snapshot", json!({}));
    assert_eq!(snapshot["sidebar"]["workspace_id"], workspace_id);
    assert_eq!(snapshot["sidebar"]["progress"], "0.25 Indexing");
    assert!(
        snapshot["sidebar"]["statuses"]
            .as_array()
            .unwrap()
            .iter()
            .any(|status| status["key"] == "build" && status["value"] == "passing"),
        "snapshot was {snapshot}"
    );
    assert!(
        snapshot["sidebar"]["logs"]
            .as_array()
            .unwrap()
            .iter()
            .any(|entry| entry["message"] == "snapshot chrome"),
        "snapshot was {snapshot}"
    );
    assert!(
        snapshot["notifications"]
            .as_array()
            .unwrap()
            .iter()
            .any(|notification| notification["title"] == "Build done"
                && notification["read"] == false),
        "snapshot was {snapshot}"
    );
    assert_eq!(snapshot["command_palette"]["visible"], true);
    assert_eq!(snapshot["command_palette"]["mode"], "commands");
}

