#[test]
fn claude_warm_pool_shortcut_claims_prestarted_terminal_and_refills() {
    let token = format!("CMUX_CLAUDE_WARM_READY_{}", std::process::id());
    let command = format!("printf '{}\\n'", token);
    let env = [("CMUX_CLAUDE_COMMAND", command.as_str())];
    let server = start_server_with_env(&env);
    let initial_workspace = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    let ensured = rpc(
        &server.socket,
        "agent.claude.warm_pool.ensure",
        json!({"target_size": 2}),
    );
    assert_eq!(ensured["provider"], "claude");
    assert_eq!(ensured["target_size"], 2);
    assert_eq!(ensured["available"], 2);
    let warm_rows = ensured["workspaces"].as_array().unwrap();
    assert_eq!(warm_rows.len(), 2);
    assert!(warm_rows.iter().all(|row| {
        row["title"] == "Claude Code"
            && row["provider"] == "claude"
            && row["runtime_surface_ready"] == true
            && row["selected"] == false
    }));
    assert_eq!(
        rpc(&server.socket, "workspace.current", json!({}))["workspace_id"],
        initial_workspace
    );
    let first_warm_workspace = warm_rows[0]["workspace_id"].as_str().unwrap().to_string();

    let help = rpc(&server.socket, "help.shortcuts", json!({}));
    assert!(help["rows"]
        .as_array()
        .unwrap()
        .iter()
        .any(|row| { row["title"] == "Claude Code" && row["shortcut_hint"] == "⇧⌘C" }));

    let claimed = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "cmd+shift+c"}),
    );
    let claimed_workspace = claimed["workspace_id"].as_str().unwrap();
    let claimed_surface = claimed["surface_id"].as_str().unwrap();
    assert_eq!(claimed_workspace, first_warm_workspace);
    assert_eq!(
        rpc(&server.socket, "workspace.current", json!({}))["workspace_id"],
        claimed_workspace
    );

    let refilled = rpc(
        &server.socket,
        "agent.claude.warm_pool.status",
        json!({"target_size": 2}),
    );
    assert_eq!(refilled["available"], 2);
    assert!(refilled["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .all(|row| row["workspace_id"].as_str() != Some(claimed_workspace)));

    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let read = rpc(
            &server.socket,
            "surface.read_text",
            json!({"surface_id": claimed_surface}),
        );
        if read["text"].as_str().unwrap_or_default().contains(&token) {
            return;
        }
        thread::sleep(Duration::from_millis(100));
    }
    panic!("claimed Claude Code warm terminal did not produce readiness token");
}

#[test]
fn cli_reports_refs_by_default_and_uuids_on_request() {
    let server = start_server();

    let default_ident: Value =
        serde_json::from_str(&cli(&server.socket, &["--json", "identify"])).unwrap();
    assert!(default_ident["workspace_ref"]
        .as_str()
        .unwrap()
        .starts_with("workspace:"));
    assert!(default_ident.get("workspace_id").is_none());

    let both_ident: Value = serde_json::from_str(&cli(
        &server.socket,
        &["--json", "--id-format", "both", "identify"],
    ))
    .unwrap();
    assert!(both_ident["workspace_ref"]
        .as_str()
        .unwrap()
        .starts_with("workspace:"));
    assert!(uuid::Uuid::parse_str(both_ident["workspace_id"].as_str().unwrap()).is_ok());

    let uuid_ident: Value = serde_json::from_str(&cli(
        &server.socket,
        &["--json", "--id-format", "uuids", "identify"],
    ))
    .unwrap();
    assert!(uuid::Uuid::parse_str(uuid_ident["workspace_id"].as_str().unwrap()).is_ok());
    assert!(uuid_ident.get("workspace_ref").is_none());
}

