#[test]
fn malformed_layout_is_rejected_without_creating_workspace() {
    let server = start_server();
    let before = rpc(&server.socket, "workspace.list", json!({}));
    let before_len = before["workspaces"].as_array().unwrap().len();

    let mut stream = UnixStream::connect(&server.socket).expect("connect socket");
    serde_json::to_writer(
        &mut stream,
        &json!({
            "id": 1,
            "method": "workspace.create",
            "params": {
                "title": "bad",
                "layout": {
                    "direction": "horizontal",
                    "children": [{"pane": {"surfaces": [{"type": "terminal"}]}}]
                }
            }
        }),
    )
    .expect("write json");
    stream.write_all(b"\n").expect("write newline");
    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    reader.read_line(&mut line).expect("read response");
    let response: Value = serde_json::from_str(&line).expect("response json");
    assert_eq!(response["ok"], false);
    assert_eq!(response["error"]["code"], "invalid_params");

    let after = rpc(&server.socket, "workspace.list", json!({}));
    assert_eq!(after["workspaces"].as_array().unwrap().len(), before_len);
}

#[test]
fn surface_current_and_tab_rename_update_listed_title() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "rename"}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    rpc(
        &server.socket,
        "workspace.select",
        json!({"workspace_id": workspace_id}),
    );

    let current = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": workspace_id}),
    );
    let surface_id = current["surface_id"].as_str().unwrap();
    let title = "renamed from rust test";
    let renamed = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": surface_id,
            "action": "rename",
            "title": title
        }),
    );
    assert_eq!(renamed["title"], title);

    let listed = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    );
    let row = listed["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == surface_id)
        .unwrap();
    assert_eq!(row["title"], title);

    let stdout = cli(
        &server.socket,
        &[
            "rename-tab",
            "--workspace",
            workspace_id,
            "--tab",
            surface_id,
            "cli title",
        ],
    );
    assert!(stdout.contains("action=rename"));
    assert!(stdout.contains("tab="));

    let panel_title = "renamed from panel env";
    let panel_stdout = cli_with_env(
        &server.socket,
        &["rename-tab", panel_title],
        &[
            ("CMUX_WORKSPACE_ID", workspace_id),
            ("CMUX_PANEL_ID", surface_id),
        ],
    );
    assert!(panel_stdout.contains("action=rename"));
    let panel_listed = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    );
    let panel_row = panel_listed["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == surface_id)
        .unwrap();
    assert_eq!(panel_row["title"], panel_title);
}

#[test]
fn tab_action_close_neighbors_skips_pinned_and_keeps_anchor() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "close neighbors", "focus": true}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    rpc(
        &server.socket,
        "workspace.select",
        json!({"workspace_id": workspace_id}),
    );
    let pane_id = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    )["panes"][0]["pane_id"]
        .as_str()
        .unwrap()
        .to_string();
    let first_surface = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": workspace_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let second_surface = rpc(
        &server.socket,
        "surface.create",
        json!({"workspace_id": workspace_id, "pane_id": pane_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let anchor_surface = rpc(
        &server.socket,
        "surface.create",
        json!({"workspace_id": workspace_id, "pane_id": pane_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let right_surface = rpc(
        &server.socket,
        "surface.create",
        json!({"workspace_id": workspace_id, "pane_id": pane_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();

    let pinned = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": first_surface,
            "action": "pin"
        }),
    );
    assert_eq!(pinned["pinned"], true);

    let closed_left = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": anchor_surface,
            "action": "close-left"
        }),
    );
    assert_eq!(closed_left["closed"], 1);
    assert_eq!(closed_left["skipped_pinned"], 1);
    let after_left = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    );
    let after_left_ids = after_left["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|surface| surface["surface_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert!(after_left_ids.contains(&first_surface));
    assert!(!after_left_ids.contains(&second_surface));
    assert!(after_left_ids.contains(&anchor_surface));
    assert!(after_left_ids.contains(&right_surface));

    let cli_output = cli(
        &server.socket,
        &[
            "tab-action",
            "--workspace",
            workspace_id,
            "--surface",
            anchor_surface.as_str(),
            "--action",
            "close-right",
        ],
    );
    assert!(cli_output.contains("action=close_right"));
    assert!(cli_output.contains("closed=1"));
    let after_right = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    );
    let after_right_ids = after_right["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|surface| surface["surface_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert!(after_right_ids.contains(&first_surface));
    assert!(after_right_ids.contains(&anchor_surface));
    assert!(!after_right_ids.contains(&right_surface));

    let unpinned = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": first_surface,
            "action": "unpin"
        }),
    );
    assert_eq!(unpinned["pinned"], false);
    let close_others = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": anchor_surface,
            "action": "close-others"
        }),
    );
    assert_eq!(close_others["closed"], 1);
    assert_eq!(close_others["skipped_pinned"], 0);
    let after_others = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": workspace_id}),
    );
    let after_others_surfaces = after_others["surfaces"].as_array().unwrap();
    assert_eq!(after_others_surfaces.len(), 1);
    assert_eq!(after_others_surfaces[0]["surface_id"], anchor_surface);
}

#[test]
fn tab_action_new_right_inserts_in_same_pane_and_honors_focus() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "new right tabs", "focus": true}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    let pane_id = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    )["panes"][0]["pane_id"]
        .as_str()
        .unwrap()
        .to_string();
    let source_surface = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": workspace_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let tail_surface = rpc(
        &server.socket,
        "surface.create",
        json!({"workspace_id": workspace_id, "pane_id": pane_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();

    let terminal = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": source_surface,
            "action": "new-terminal-right"
        }),
    );
    let terminal_surface = terminal["created_surface_id"].as_str().unwrap().to_string();
    assert_eq!(terminal["surface_id"], source_surface);
    assert_eq!(terminal["created_tab_id"], terminal_surface);

    let browser = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": terminal_surface,
            "action": "new-browser-right",
            "url": "data:text/html,<title>Adjacent</title>",
            "focus": true
        }),
    );
    let browser_surface = browser["created_surface_id"].as_str().unwrap().to_string();

    let panes = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(panes["panes"].as_array().unwrap().len(), 1);
    let pane_surfaces = rpc(&server.socket, "pane.surfaces", json!({"pane_id": pane_id}));
    let surface_ids = pane_surfaces["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|surface| surface["surface_id"].as_str().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(
        surface_ids,
        vec![
            source_surface.as_str(),
            terminal_surface.as_str(),
            browser_surface.as_str(),
            tail_surface.as_str()
        ]
    );
    let current = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": workspace_id}),
    );
    assert_eq!(current["surface_id"], browser_surface);
    assert_eq!(current["pane_id"], pane_id);
    let browser_url = rpc(
        &server.socket,
        "browser.url.get",
        json!({"surface_id": browser_surface}),
    );
    assert_eq!(browser_url["url"], "data:text/html,<title>Adjacent</title>");
}

#[test]
fn browser_tab_new_creates_a_same_pane_tab_without_splitting() {
    let server = start_server();
    let terminal = rpc(&server.socket, "surface.current", json!({}));
    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({
            "surface_id": terminal["surface_id"],
            "url": "https://example.test/first",
            "focus": true
        }),
    );
    let browser_id = opened["surface_id"].as_str().unwrap();
    let pane_id = opened["pane_id"].as_str().unwrap();
    let panes_before = rpc(&server.socket, "pane.list", json!({}));
    let tabs_before = rpc(&server.socket, "pane.surfaces", json!({"pane_id": pane_id}));

    let created = rpc(
        &server.socket,
        "browser.tab.new",
        json!({
            "surface_id": browser_id,
            "url": "https://example.test/second",
            "focus": true
        }),
    );
    let new_browser_id = created["surface_id"].as_str().unwrap();
    assert_eq!(created["pane_id"], pane_id);
    assert_eq!(created["created_split"], false);
    assert_eq!(
        rpc(&server.socket, "pane.list", json!({}))["panes"]
            .as_array()
            .unwrap()
            .len(),
        panes_before["panes"].as_array().unwrap().len()
    );
    let tabs_after = rpc(&server.socket, "pane.surfaces", json!({"pane_id": pane_id}));
    assert_eq!(
        tabs_after["surfaces"].as_array().unwrap().len(),
        tabs_before["surfaces"].as_array().unwrap().len() + 1
    );
    assert_eq!(
        rpc(&server.socket, "surface.current", json!({}))["surface_id"],
        new_browser_id
    );
}

#[test]
fn tab_action_reload_and_duplicate_browser_tabs() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "browser tab actions", "focus": true}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    rpc(
        &server.socket,
        "workspace.select",
        json!({"workspace_id": workspace_id}),
    );
    let terminal_surface = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": workspace_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let url = "data:text/html,<title>Duplicate Me</title><main>copy</main>";
    let opened = rpc(
        &server.socket,
        "browser.open_split",
        json!({"workspace_id": workspace_id, "surface_id": terminal_surface, "url": url}),
    );
    let browser_surface = opened["surface_id"].as_str().unwrap().to_string();
    let browser_pane = opened["pane_id"].as_str().unwrap().to_string();

    let reloaded = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": browser_surface,
            "action": "reload"
        }),
    );
    assert_eq!(reloaded["action"], "reload");
    assert_eq!(reloaded["surface_id"], browser_surface);
    assert_eq!(reloaded["url"], url);
    assert_eq!(reloaded["title"], "Duplicate Me");

    let terminal_reload = rpc_response(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": terminal_surface,
            "action": "reload"
        }),
    );
    assert_eq!(terminal_reload["ok"], false);
    assert_eq!(terminal_reload["error"]["code"], "invalid_state");

    let duplicated = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": browser_surface,
            "action": "duplicate"
        }),
    );
    let created_surface = duplicated["created_surface_id"].as_str().unwrap();
    assert_eq!(duplicated["action"], "duplicate");
    assert_eq!(duplicated["surface_id"], browser_surface);
    assert_eq!(duplicated["created_tab_id"], created_surface);
    let pane_after_duplicate = rpc(
        &server.socket,
        "pane.surfaces",
        json!({"pane_id": browser_pane}),
    );
    let pane_surface_ids = pane_after_duplicate["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|surface| surface["surface_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    let browser_index = pane_surface_ids
        .iter()
        .position(|surface| surface == &browser_surface)
        .unwrap();
    assert_eq!(
        pane_surface_ids.get(browser_index + 1).map(String::as_str),
        Some(created_surface)
    );
    let duplicated_url = rpc(
        &server.socket,
        "browser.url.get",
        json!({"surface_id": created_surface}),
    );
    assert_eq!(duplicated_url["url"], url);

    let terminal_duplicate = rpc_response(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": workspace_id,
            "surface_id": terminal_surface,
            "action": "duplicate"
        }),
    );
    assert_eq!(terminal_duplicate["ok"], false);
    assert_eq!(terminal_duplicate["error"]["code"], "invalid_state");

    let cli_output = cli(
        &server.socket,
        &[
            "tab-action",
            "--workspace",
            workspace_id,
            "--surface",
            browser_surface.as_str(),
            "--action",
            "duplicate",
        ],
    );
    assert!(cli_output.contains("action=duplicate"));
    assert!(cli_output.contains("created=tab:"));
}

#[test]
fn tab_action_move_to_new_workspace_rehomes_surface() {
    let server = start_server();
    let source_workspace = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "move tab source", "focus": true}),
    );
    let source_workspace_id = source_workspace["workspace_id"].as_str().unwrap();
    rpc(
        &server.socket,
        "workspace.select",
        json!({"workspace_id": source_workspace_id}),
    );
    let panes = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": source_workspace_id}),
    );
    let source_pane_id = panes["panes"][0]["pane_id"].as_str().unwrap();
    let first_surface = rpc(
        &server.socket,
        "surface.current",
        json!({"workspace_id": source_workspace_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let moved_surface = rpc(
        &server.socket,
        "surface.create",
        json!({"workspace_id": source_workspace_id, "pane_id": source_pane_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();

    let moved = rpc(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": source_workspace_id,
            "surface_id": moved_surface,
            "action": "move-to-new-workspace",
            "title": "Detached logs",
            "focus": false
        }),
    );
    let destination_workspace_id = moved["created_workspace_id"].as_str().unwrap();
    assert_eq!(moved["action"], "move_to_new_workspace");
    assert_eq!(moved["source_workspace_id"], source_workspace_id);
    assert_eq!(moved["workspace_id"], destination_workspace_id);
    assert_eq!(moved["surface_id"], moved_surface);
    assert_eq!(moved["tab_id"], moved_surface);

    let source_after = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": source_workspace_id}),
    );
    assert!(source_after["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .all(|surface| surface["surface_id"].as_str() != Some(moved_surface.as_str())));
    let destination_after = rpc(
        &server.socket,
        "surface.list",
        json!({"workspace_id": destination_workspace_id}),
    );
    let destination_surfaces = destination_after["surfaces"].as_array().unwrap();
    assert_eq!(destination_surfaces.len(), 1);
    assert_eq!(destination_surfaces[0]["surface_id"], moved_surface);
    let workspaces = rpc(&server.socket, "workspace.list", json!({}));
    let destination_row = workspaces["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .find(|workspace| workspace["workspace_id"].as_str() == Some(destination_workspace_id))
        .unwrap();
    assert_eq!(destination_row["title"], "Detached logs");

    let only_tab_move = rpc_response(
        &server.socket,
        "tab.action",
        json!({
            "workspace_id": source_workspace_id,
            "surface_id": first_surface,
            "action": "move-to-new-workspace"
        }),
    );
    assert_eq!(only_tab_move["ok"], false);
    assert_eq!(only_tab_move["error"]["code"], "invalid_state");

    let cli_surface = rpc(
        &server.socket,
        "surface.create",
        json!({"workspace_id": source_workspace_id, "pane_id": source_pane_id}),
    )["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let cli_moved = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "move-tab-to-new-workspace",
            "--surface",
            cli_surface.as_str(),
            "--title",
            "CLI detached",
            "--focus",
            "true",
        ],
        &[],
    );
    let cli_workspace_id = cli_moved["created_workspace_id"].as_str().unwrap();
    assert_eq!(cli_moved["action"], "move_to_new_workspace");
    assert_eq!(cli_moved["source_workspace_id"], source_workspace_id);
    assert_eq!(cli_moved["workspace_id"], cli_workspace_id);
    assert_eq!(cli_moved["surface_id"], cli_surface);
    let current_workspace = rpc(&server.socket, "workspace.current", json!({}));
    assert_eq!(current_workspace["workspace_id"], cli_workspace_id);

    rpc(
        &server.socket,
        "surface.create",
        json!({"workspace_id": source_workspace_id, "pane_id": source_pane_id}),
    );
    let text_output = cli(
        &server.socket,
        &[
            "detach-tab",
            "--surface",
            first_surface.as_str(),
            "--title",
            "Detached text",
        ],
    );
    assert!(text_output.contains("action=move_to_new_workspace"));
    assert!(text_output.contains("created_workspace="));
}

#[test]
fn surface_reorder_before_self_is_stable_noop_after_move() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "surface reorder"}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    rpc(
        &server.socket,
        "workspace.select",
        json!({"workspace_id": workspace_id}),
    );

    let split = rpc(
        &server.socket,
        "surface.split",
        json!({"direction": "right"}),
    );
    let moved_surface = split["surface_id"].as_str().unwrap();
    let panes = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    let destination_pane = panes["panes"]
        .as_array()
        .unwrap()
        .iter()
        .find_map(|pane| {
            let pane_id = pane["pane_id"].as_str()?;
            (pane["surface_count"].as_u64() == Some(1)).then_some(pane_id)
        })
        .expect("destination pane");

    rpc(
        &server.socket,
        "surface.move",
        json!({
            "surface_id": moved_surface,
            "pane_id": destination_pane,
            "focus": false
        }),
    );
    let before_reorder = rpc(
        &server.socket,
        "pane.surfaces",
        json!({"pane_id": destination_pane}),
    );
    let before_surface_ids = before_reorder["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|surface| surface["surface_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert!(before_surface_ids.iter().any(|id| id == moved_surface));

    let reordered = rpc(
        &server.socket,
        "surface.reorder",
        json!({
            "surface_id": moved_surface,
            "before_surface_id": moved_surface
        }),
    );
    assert_eq!(reordered["surface_id"], moved_surface);

    let pane_surfaces = rpc(
        &server.socket,
        "pane.surfaces",
        json!({"pane_id": destination_pane}),
    );
    let surface_ids = pane_surfaces["surfaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|surface| surface["surface_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(surface_ids, before_surface_ids);
}

#[test]
fn cli_surface_and_workspace_move_aliases_route_to_v2_methods() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "cli move aliases"}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();
    rpc(
        &server.socket,
        "workspace.select",
        json!({"workspace_id": workspace_id}),
    );
    let initial_panes = rpc(
        &server.socket,
        "pane.list",
        json!({"workspace_id": workspace_id}),
    );
    let source_pane = initial_panes["panes"][0]["pane_id"].as_str().unwrap();
    let extra = rpc(
        &server.socket,
        "surface.create",
        json!({"workspace_id": workspace_id, "pane_id": source_pane}),
    );
    let extra_surface = extra["surface_id"].as_str().unwrap();

    let reordered = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "reorder-surface",
            "--surface",
            extra_surface,
            "--index",
            "0",
        ],
        &[],
    );
    assert_eq!(reordered["surface_id"], extra_surface);
    let source_surfaces = rpc(
        &server.socket,
        "pane.surfaces",
        json!({"pane_id": source_pane}),
    );
    assert_eq!(source_surfaces["surfaces"][0]["surface_id"], extra_surface);

    let split = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "split-off",
            "--surface",
            extra_surface,
            "right",
            "--focus",
            "false",
        ],
        &[],
    );
    let split_pane = split["pane_id"].as_str().unwrap();
    assert_eq!(split["surface_id"], extra_surface);
    assert_ne!(split_pane, source_pane);

    let moved = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "move-surface",
            "--surface",
            extra_surface,
            "--pane",
            source_pane,
            "--index",
            "0",
            "--focus",
            "false",
        ],
        &[],
    );
    assert_eq!(moved["surface_id"], extra_surface);
    assert_eq!(moved["pane_id"], source_pane);
    let moved_surfaces = rpc(
        &server.socket,
        "pane.surfaces",
        json!({"pane_id": source_pane}),
    );
    assert_eq!(moved_surfaces["surfaces"][0]["surface_id"], extra_surface);

    let current_window_id = rpc(&server.socket, "window.current", json!({}))["window_id"]
        .as_str()
        .unwrap()
        .to_string();
    let reorder_a = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "CLI reorder A", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let reorder_b = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "CLI reorder B", "focus": false}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let dry_run = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "reorder-workspace",
            "--workspace",
            reorder_a.as_str(),
            "--after",
            reorder_b.as_str(),
            "--dry-run",
        ],
        &[],
    );
    assert_eq!(dry_run["workspace_id"], reorder_a);
    assert_eq!(dry_run["dry_run"], true);
    assert_eq!(dry_run["events"].as_array().unwrap().len(), 0);
    let after_dry_run = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": current_window_id.clone()}),
    );
    let dry_order = after_dry_run["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|workspace| workspace["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert!(
        dry_order
            .windows(2)
            .any(|pair| pair[0] == reorder_a && pair[1] == reorder_b),
        "dry-run should not reorder workspaces: {after_dry_run}"
    );

    let reordered_workspace = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "reorder-workspace",
            reorder_a.as_str(),
            "--after",
            reorder_b.as_str(),
        ],
        &[],
    );
    assert_eq!(reordered_workspace["workspace_id"], reorder_a);
    assert_eq!(reordered_workspace["dry_run"], false);
    let after_reorder = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": current_window_id.clone()}),
    );
    let reordered_order = after_reorder["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|workspace| workspace["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert!(
        reordered_order
            .windows(2)
            .any(|pair| pair[0] == reorder_b && pair[1] == reorder_a),
        "workspace should move after target: {after_reorder}"
    );

    let bulk_order = format!("{workspace_id},{reorder_a}");
    let reordered_many = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "reorder-workspaces",
            "--order",
            bulk_order.as_str(),
            "--window",
            current_window_id.as_str(),
        ],
        &[],
    );
    assert_eq!(reordered_many["window_id"], current_window_id);
    assert_eq!(reordered_many["dry_run"], false);
    assert_eq!(reordered_many["plan"].as_array().unwrap().len(), 2);
    let after_many = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": current_window_id.clone()}),
    );
    let many_order = after_many["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|workspace| workspace["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(many_order[0], workspace_id);
    assert_eq!(many_order[1], reorder_a);

    let window = rpc(&server.socket, "window.create", json!({}));
    let window_id = window["window_id"].as_str().unwrap();
    let moved_workspace = cli_json_with_env(
        &server.socket,
        &[
            "--json",
            "--id-format",
            "both",
            "move-workspace-to-window",
            "--workspace",
            workspace_id,
            "--window",
            window_id,
        ],
        &[],
    );
    assert_eq!(moved_workspace["workspace_id"], workspace_id);
}

#[test]
fn sidebar_simulated_drag_clears_drag_state_without_committing_reorder() {
    let server = start_server();
    let window_id = rpc(&server.socket, "window.current", json!({}))["window_id"]
        .as_str()
        .unwrap()
        .to_string();
    rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "drag target 1"}),
    );
    rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "drag target 2"}),
    );
    let before = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": window_id.clone()}),
    )["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|workspace| workspace["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert!(before.len() >= 3);

    let simulated = rpc(
        &server.socket,
        "debug.sidebar.simulate_drag",
        json!({
            "window_id": window_id.clone(),
            "from_tab_id": before[0].clone(),
            "to_tab_id": before[2].clone(),
            "duration_ms": 1,
            "steps": 5
        }),
    );
    assert_eq!(simulated["edge"], "bottom");
    assert_eq!(simulated["steps"], 5);
    assert_eq!(
        simulated["path"]
            .as_array()
            .unwrap()
            .last()
            .unwrap()
            .as_str(),
        Some(before[2].as_str())
    );

    let state = rpc(
        &server.socket,
        "debug.sidebar.drag_state",
        json!({"window_id": window_id.clone()}),
    );
    assert!(state["dragged_tab_id"].is_null(), "state was {state}");
    assert!(state["dragged_workspace_id"].is_null(), "state was {state}");
    assert!(state["drop_indicator"].is_null(), "state was {state}");
    assert_eq!(state["is_simulated"], false);
    assert_eq!(simulated["state"], state);

    let after = rpc(
        &server.socket,
        "workspace.list",
        json!({"window_id": window_id}),
    )["workspaces"]
        .as_array()
        .unwrap()
        .iter()
        .map(|workspace| workspace["workspace_id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>();
    assert_eq!(after, before);
}

#[test]
fn sidebar_metadata_cli_updates_workspace_state() {
    let server = start_server();
    let created = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "metadata"}),
    );
    let workspace_id = created["workspace_id"].as_str().unwrap();

    let out = cli(
        &server.socket,
        &[
            "set-status",
            "build",
            "compiling",
            "--workspace",
            workspace_id,
            "--priority",
            "80",
        ],
    );
    assert!(out.starts_with("OK"));
    cli(
        &server.socket,
        &[
            "set-progress",
            "0.5",
            "--workspace",
            workspace_id,
            "--label",
            "Building",
        ],
    );
    cli(
        &server.socket,
        &["log", "--workspace", workspace_id, "--", "ship it"],
    );

    let status = cli(
        &server.socket,
        &["list-status", "--workspace", workspace_id],
    );
    assert!(status.contains("build=compiling"));
    assert!(status.contains("priority=80"));
    cli(
        &server.socket,
        &[
            "report-meta",
            "docs",
            "ready",
            "--workspace",
            workspace_id,
            "--icon",
            "book",
            "--color",
            "#336699",
            "--url",
            "https://example.test/docs",
            "--format",
            "markdown",
            "--priority",
            "25",
        ],
    );
    cli(
        &server.socket,
        &[
            "report-meta-block",
            "summary",
            "--workspace",
            workspace_id,
            "--priority",
            "10",
            "--",
            "## Done\nAll green",
        ],
    );

    let meta = cli(&server.socket, &["list-meta", "--workspace", workspace_id]);
    assert!(meta.contains("docs=ready"));
    assert!(meta.contains("icon=book"));
    assert!(meta.contains("color=#336699"));
    assert!(meta.contains("url=https://example.test/docs"));
    assert!(meta.contains("format=markdown"));
    let blocks = cli(
        &server.socket,
        &["list-meta-blocks", "--workspace", workspace_id],
    );
    assert!(blocks.contains("summary=## Done\\nAll green"));
    assert!(blocks.contains("priority=10"));

    let state = cli(
        &server.socket,
        &["sidebar-state", "--workspace", workspace_id],
    );
    assert!(state.contains("status_count=2"));
    assert!(state.contains("meta_block_count=1"));
    assert!(state.contains("summary=## Done\\nAll green"));
    assert!(state.contains("progress=0.50 Building"));
    assert!(state.contains("[info] ship it"));
    let methods = rpc(&server.socket, "system.capabilities", json!({}));
    let method_names = methods["methods"].as_array().unwrap();
    assert!(method_names
        .iter()
        .any(|method| method.as_str() == Some("sidebar.meta.set")));
    assert!(method_names
        .iter()
        .any(|method| method.as_str() == Some("sidebar.meta_block.set")));

    cli(
        &server.socket,
        &["clear-meta", "docs", "--workspace", workspace_id],
    );
    cli(
        &server.socket,
        &["clear-meta-block", "summary", "--workspace", workspace_id],
    );
    cli(
        &server.socket,
        &["clear-status", "build", "--workspace", workspace_id],
    );
    cli(
        &server.socket,
        &["clear-progress", "--workspace", workspace_id],
    );
    cli(&server.socket, &["clear-log", "--workspace", workspace_id]);
    let cleared = cli(
        &server.socket,
        &["sidebar-state", "--workspace", workspace_id],
    );
    assert!(cleared.contains("status_count=0"));
    assert!(cleared.contains("meta_block_count=0"));
    assert!(cleared.contains("progress=none"));
    assert!(cleared.contains("log_count=0"));
}

#[test]
fn sidebar_multiselect_groups_selected_workspaces_over_public_socket_contract() {
    let server = start_server();
    let first = rpc(&server.socket, "workspace.current", json!({}))["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let second = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Second"}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();
    let third = rpc(
        &server.socket,
        "workspace.create",
        json!({"title": "Third"}),
    )["workspace_id"]
        .as_str()
        .unwrap()
        .to_string();

    rpc(
        &server.socket,
        "workspace.sidebar_select",
        json!({"workspace_id": first}),
    );
    rpc(
        &server.socket,
        "workspace.sidebar_select",
        json!({"workspace_id": second, "toggle": true}),
    );
    let selection = rpc(
        &server.socket,
        "workspace.sidebar_select",
        json!({"workspace_id": third, "toggle": true}),
    );
    assert_eq!(
        selection["selected_workspace_ids"],
        json!([first, second, third])
    );
    assert_eq!(selection["selected_count"], 3);
    assert!(
        rpc(&server.socket, "workspace.list", json!({}))["workspaces"]
            .as_array()
            .unwrap()
            .iter()
            .all(|workspace| workspace["multi_selected"] == true)
    );

    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert_eq!(
        capabilities["features"]["workspace_sidebar_multiselect"],
        true
    );
    assert!(capabilities["methods"]
        .as_array()
        .unwrap()
        .iter()
        .any(|method| method == "workspace.sidebar_select"));
    let settings = rpc(&server.socket, "settings.shortcuts", json!({}));
    let shortcut = settings["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["name"] == "group_selected_workspaces")
        .expect("group selected shortcut row");
    assert_eq!(shortcut["config_id"], "groupSelectedWorkspaces");
    assert_eq!(shortcut["default_combo"], "cmd+shift+g");

    let grouped = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "super+shift+g"}),
    );
    assert_eq!(grouped["handled"], true);
    assert_eq!(grouped["action"], "groupSelectedWorkspaces");
    assert_eq!(
        grouped["selected_workspace_ids"].as_array().unwrap().len(),
        3
    );
    let groups = rpc(&server.socket, "workspace.group.list", json!({}));
    assert_eq!(groups["groups"].as_array().unwrap().len(), 1);
    assert_eq!(groups["groups"][0]["member_count"], 4);
}

#[test]
fn terminal_text_box_is_available_over_public_socket_contract() {
    let server = start_server();
    let surface_id = rpc(&server.socket, "surface.current", json!({}))["surface_id"]
        .as_str()
        .unwrap()
        .to_string();
    let capabilities = rpc(&server.socket, "system.capabilities", json!({}));
    assert_eq!(capabilities["features"]["terminal_text_box"], true);
    for method in [
        "terminal.textbox.state",
        "terminal.textbox.set_text",
        "terminal.textbox.attach",
        "terminal.textbox.submit",
    ] {
        assert!(capabilities["methods"]
            .as_array()
            .unwrap()
            .iter()
            .any(|entry| entry == method));
    }

    let focused = rpc(
        &server.socket,
        "debug.shortcut.simulate",
        json!({"combo": "super+shift+a"}),
    );
    assert_eq!(focused["text_box"]["active"], true);
    assert_eq!(focused["text_box"]["focus"], "textBox");
    let edited = rpc(
        &server.socket,
        "terminal.textbox.set_text",
        json!({"surface_id": surface_id, "text": "socket draft"}),
    );
    assert_eq!(edited["text_box"]["can_submit"], true);
    let escaped = rpc(
        &server.socket,
        "terminal.textbox.escape",
        json!({"surface_id": surface_id}),
    );
    assert_eq!(escaped["text_box"]["focus"], "terminal");
    assert_eq!(escaped["text_box"]["hide_escape_armed"], true);

    let rows = rpc(&server.socket, "settings.shortcuts", json!({}));
    let shortcuts = rows["rows"].as_array().unwrap();
    let focus = shortcuts
        .iter()
        .find(|row| row["config_id"] == "focusTextBoxInput")
        .expect("focus TextBox shortcut");
    assert_eq!(focus["default_combo"], "cmd+shift+a");
    let attach = shortcuts
        .iter()
        .find(|row| row["config_id"] == "attachTextBoxFile")
        .expect("attach TextBox shortcut");
    assert_eq!(attach["default_combo"], "cmd+opt+shift+a");
}
